#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned long timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_length;
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager, size_t initial_capacity) {
    manager->packets = (NetworkPacket *)malloc(initial_capacity * sizeof(NetworkPacket));
    if (!manager->packets) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_packet(PacketManager *manager, NetworkPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkPacket *new_packets = (NetworkPacket *)realloc(manager->packets, new_capacity * sizeof(NetworkPacket));
        if (!new_packets) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&manager->lock);
            exit(EXIT_FAILURE);
        }
        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
}

void update_packet(PacketManager *manager, size_t index, NetworkPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (index < manager->count) {
        manager->packets[index] = packet;
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t calculate_total_data_transferred(PacketManager *manager) {
    size_t total = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        total += manager->packets[i].payload_length;
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}

void cleanup_packets(PacketManager *manager, unsigned long cutoff_timestamp) {
    pthread_mutex_lock(&manager->lock);
    size_t new_count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].timestamp >= cutoff_timestamp) {
            manager->packets[new_count++] = manager->packets[i];
        }
    }
    manager->count = new_count;
    pthread_mutex_unlock(&manager->lock);
}

void destroy_packet_manager(PacketManager *manager) {
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
}
