typedef struct {
    int value;
} record;

int allocate_and_initialize(long **offsets, int **keys, record ***records, size_t size, size_t alignment) {
    *offsets = aligned_alloc(alignment, sizeof(long) * size);
    if (*offsets == NULL) return -1;

    *keys = aligned_alloc(alignment, sizeof(int) * size);
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = aligned_alloc(alignment, sizeof(record *) * size);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = aligned_alloc(alignment, sizeof(record));
        if ((*records)[i] == NULL) {
            for (size_t j = 0; j < i; ++j) free((*records)[j]);
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
    }

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = i * alignment;
        (*keys)[i] = i;
        (*records)[i]->value = rand() % 1000; // Random value between 0 and 999
    }

    return 0;
}

void free_resources(long *offsets, int *keys, record **records, size_t size) {
    for (size_t i = 0; i < size; ++i) free(records[i]);
    free(offsets);
    free(keys);
    free(records);
}
