#define DEFAULT_CHUNK_SIZE 1024

typedef struct {
    char *filename;
    int chunk_size;
    pthread_t thread_id;
} FileTask;

int process_file(const char *filename, int chunk_size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    int total_lines = 0;
    char buffer[chunk_size];
    while (fgets(buffer, sizeof(buffer), file)) {
        total_lines++;
    }
    fclose(file);

    printf("Processed %s: %d lines\n", filename, total_lines);
    return total_lines;
}

void *thread_function(void *arg) {
    FileTask *task = (FileTask *)arg;
    int result = process_file(task->filename, task->chunk_size);
    // Update shared resource with result
    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <output_file> <input_files...>\n", argv[0]);
        return 1;
    }

    const char *output_file = argv[1];
    int num_files = argc - 2;
    FileTask tasks[num_files];

    for (int i = 0; i < num_files; i++) {
        tasks[i].filename = argv[i + 2];
        tasks[i].chunk_size = DEFAULT_CHUNK_SIZE;
        pthread_create(&tasks[i].thread_id, NULL, thread_function, &tasks[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_files; i++) {
        pthread_join(tasks[i].thread_id, NULL);
    }

    // Write summary report to output file
    FILE *summary_file = fopen(output_file, "w");
    if (!summary_file) {
        perror("Error opening output file");
        return 1;
    }

    int total_lines = 0;
    for (int i = 0; i < num_files; i++) {
        // Retrieve result from shared resource
        total_lines += /* retrieve result */;
    }
    fprintf(summary_file, "Total lines across all files: %d\n", total_lines);
    fclose(summary_file);

    return 0;
}
