#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define NUM_THREADS 4

typedef struct {
    char *filename;
    pthread_mutex_t lock;
} FileData;

void* process_file(void* arg) {
    FileData *data = (FileData*)arg;
    FILE *file = fopen(data->filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        pthread_mutex_lock(&data->lock);
        // Process each line here
        printf("%s", line);
        pthread_mutex_unlock(&data->lock);
    }

    fclose(file);
    return NULL;
}

int resolve_dns(const char *hostname, char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy(ip_address, ipstr);
    }

    freeaddrinfo(res); // all done with this structure
    return 0;
}

int main() {
    FileData file_data = {"large_dataset.txt", PTHREAD_MUTEX_INITIALIZER};
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, process_file, &file_data) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Example DNS resolution
    char ip_address[INET6_ADDRSTRLEN];
    if (resolve_dns("example.com", ip_address) == 0) {
        printf("IP address of example.com: %s\n", ip_address);
    }

    return EXIT_SUCCESS;
}
