#define MAX_SIZE 10000

int* read_integers_from_csv(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    int* array = (int*)malloc(MAX_SIZE * sizeof(int));
    if (!array) {
        perror("Memory allocation failed");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        int num;
        if (sscanf(buffer, "%d", &num) == 1) {
            array[*count] = num;
            (*count)++;
            if (*count >= MAX_SIZE) {
                fprintf(stderr, "Input exceeds maximum size\n");
                free(array);
                fclose(file);
                exit(EXIT_FAILURE);
            }
        }
    }

    fclose(file);
    return array;
}

void* find_largest_integer(void* arg) {
    int* array = (int*)arg;
    int max_value = array[0];
    for (int i = 1; i < *count; i++) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    printf("Largest integer: %d\n", max_value);
    return NULL;
}

int main() {
    int count = 0;
    int* array = read_integers_from_csv("input.csv", &count);

    pthread_t thread;
    if (pthread_create(&thread, NULL, find_largest_integer, array) != 0) {
        perror("Failed to create thread");
        free(array);
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);
    free(array);
    return 0;
}
