#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>

// Define a structure to hold log information
typedef struct {
    char *buffer;
    size_t buffer_size;
    pthread_mutex_t mutex;
} LogContext;

// Initialize the log context
void init_log_context(LogContext *ctx, size_t initial_size) {
    ctx->buffer = (char *)malloc(initial_size);
    if (!ctx->buffer) {
        fprintf(stderr, "Failed to allocate memory for log buffer\n");
        exit(1);
    }
    ctx->buffer_size = initial_size;
    pthread_mutex_init(&ctx->mutex, NULL);
}

// Function to safely format and log a message
void log_warning(LogContext *ctx, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&ctx->mutex);

    // Check if the buffer needs resizing
    size_t required_size = vsnprintf(NULL, 0, format, args) + 1;
    if (required_size > ctx->buffer_size) {
        char *new_buffer = realloc(ctx->buffer, required_size);
        if (!new_buffer) {
            fprintf(stderr, "Failed to reallocate memory for log buffer\n");
            exit(1);
        }
        ctx->buffer = new_buffer;
        ctx->buffer_size = required_size;
    }

    // Format the message into the buffer
    vsnprintf(ctx->buffer, ctx->buffer_size, format, args);

    // Log the message (this part would typically interact with your logging framework)
    printf("WARNING: %s\n", ctx->buffer);

    // Unlock the mutex
    pthread_mutex_unlock(&ctx->mutex);

    va_end(args);
}

// Clean up the log context
void cleanup_log_context(LogContext *ctx) {
    free(ctx->buffer);
    pthread_mutex_destroy(&ctx->mutex);
}
```

This code snippet provides a basic implementation of a thread-safe logging function for warning messages in a C environment. It includes dynamic memory management, thread safety using mutexes, and a simple mechanism to format variable arguments into a log message. The `log_warning` function can be integrated into an existing logging framework by replacing the placeholder for actual logging with appropriate calls to that framework.']

