#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>

typedef struct {
    const EVP_CIPHER *cipher;
    int mode;
} CipherConfig;

EVP_CIPHER_CTX* create_cipher_context(const char* algorithm, int mode) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL; // Handle error
    }

    CipherConfig config;
    if (strcmp(algorithm, "AES") == 0) {
        switch (mode) {
            case ECB: config.cipher = EVP_aes_256_ecb(); break;
            case CBC: config.cipher = EVP_aes_256_cbc(); break;
            case CFB: config.cipher = EVP_aes_256_cfb128(); break;
            case OFB: config.cipher = EVP_aes_256_ofb(); break;
            default: EVP_CIPHER_CTX_free(ctx); return NULL; // Handle error
        }
    } else if (strcmp(algorithm, "DES") == 0) {
        switch (mode) {
            case ECB: config.cipher = EVP_des_ecb(); break;
            case CBC: config.cipher = EVP_des_cbc(); break;
            default: EVP_CIPHER_CTX_free(ctx); return NULL; // Handle error
        }
    } else if (strcmp(algorithm, "3DES") == 0) {
        switch (mode) {
            case ECB: config.cipher = EVP_des_ede_ecb(); break;
            case CBC: config.cipher = EVP_des_ede_cbc(); break;
            default: EVP_CIPHER_CTX_free(ctx); return NULL; // Handle error
        }
    } else {
        EVP_CIPHER_CTX_free(ctx); return NULL; // Handle error
    }

    if (EVP_EncryptInit_ex(ctx, config.cipher, NULL, NULL, NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle error
    }

    return ctx;
}

void free_cipher_context(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

int encrypt_data(EVP_CIPHER_CTX *ctx, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len) {
    if (EVP_EncryptUpdate(ctx, ciphertext, ciphertext_len, plaintext, plaintext_len) != 1) {
        return -1; // Handle error
    }

    int final_len;
    if (EVP_EncryptFinal_ex(ctx, ciphertext + *ciphertext_len, &final_len) != 1) {
        return -1; // Handle error
    }

    *ciphertext_len += final_len;
    return 0;
}

int decrypt_data(EVP_CIPHER_CTX *ctx, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len) {
    if (EVP_DecryptUpdate(ctx, plaintext, plaintext_len, ciphertext, ciphertext_len) != 1) {
        return -1; // Handle error
    }

    int final_len;
    if (EVP_DecryptFinal_ex(ctx, plaintext + *plaintext_len, &final_len) != 1) {
        return -1; // Handle error
    }

    *plaintext_len += final_len;
    return 0;
}
