import java.util.*;
import java.io.IOException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class PokemonReportGenerator {

    private static final Logger logger = LoggerFactory.getLogger(PokemonReportGenerator.class);
    private Map<String, List<String>> typeWeaknessMap;

    public PokemonReportGenerator(Map<String, List<String>> typeWeaknessMap) {
        this.typeWeaknessMap = typeWeaknessMap;
    }

    public String generateReport(Pokemon pokemon) {
        try {
            StringBuilder report = new StringBuilder();
            report.append("Pokemon Name: ").append(pokemon.getName()).append("\n");
            report.append("Type(s): ").append(String.join(", ", pokemon.getTypes())).append("\n");

            List<String> weaknesses = getWeaknesses(pokemon);
            if (weaknesses.isEmpty()) {
                report.append("No known weaknesses.\n");
            } else {
                report.append("Weaknesses:\n");
                for (String weakness : weaknesses) {
                    report.append("- ").append(weakness).append("\n");
                }
            }

            return report.toString();
        } catch (Exception e) {
            logger.error("Error generating Pokemon report", e);
            return "Failed to generate report.";
        }
    }

    private List<String> getWeaknesses(Pokemon pokemon) {
        List<String> weaknesses = new ArrayList<>();
        for (String type : pokemon.getTypes()) {
            if (typeWeaknessMap.containsKey(type)) {
                weaknesses.addAll(typeWeaknessMap.get(type));
            } else {
                logger.warn("Unknown type: " + type);
            }
        }
        return weaknesses;
    }

    public static void main(String[] args) {
        // Example usage
        Map<String, List<String>> typeWeaknessMap = new HashMap<>();
        typeWeaknessMap.put("Fire", Arrays.asList("Water", "Ground"));
        typeWeaknessMap.put("Water", Arrays.asList("Electric"));

        PokemonReportGenerator generator = new PokemonReportGenerator(typeWeaknessMap);
        Pokemon pokemon = new Pokemon("Pikachu", Arrays.asList("Electric"));
        System.out.println(generator.generateReport(pokemon));
    }
}

class Pokemon {
    private String name;
    private List<String> types;

    public Pokemon(String name, List<String> types) {
        this.name = name;
        this.types = types;
    }

    public String getName() {
        return name;
    }

    public List<String> getTypes() {
        return types;
    }
}
