    FILE *config_file = fopen(config->config_path, "r");
    if (!config_file) {
        perror("Failed to open config file");
        EVP_CIPHER_CTX_free(ctx);
        return -2;
    }

    char line[256];
    while (fgets(line, sizeof(line), config_file)) {
        // Parse algorithm and priority from line
        // Select algorithm based on priority
    }
    fclose(config_file);

    // Allocate buffer for intermediate data storage
    unsigned char *buffer = malloc(config->buffer_size);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        EVP_CIPHER_CTX_free(ctx);
        return -3;
    }

    // Perform encryption or decryption based on operation
    int result;
    if (config->operation == ENCRYPT) {
        result = EVP_EncryptInit_ex(ctx, selected_cipher, NULL, key, iv);
    } else {
        result = EVP_DecryptInit_ex(ctx, selected_cipher, NULL, key, iv);
    }

    if (!result) {
        fprintf(stderr, "Failed to initialize cipher\n");
        free(buffer);
        EVP_CIPHER_CTX_free(ctx);
        return -4;
    }

    // Process data in chunks
    while (data_to_process > 0) {
        int len;
        result = EVP_EncryptUpdate(ctx, buffer, &len, input_data, data_to_process);
        if (!result) {
            fprintf(stderr, "Failed to update cipher\n");
            free(buffer);
            EVP_CIPHER_CTX_free(ctx);
            return -5;
        }
        // Handle output buffer
    }

    // Finalize encryption or decryption
    int final_len;
    result = EVP_EncryptFinal_ex(ctx, buffer + len, &final_len);
    if (!result) {
        fprintf(stderr, "Failed to finalize cipher\n");
        free(buffer);
        EVP_CIPHER_CTX_free(ctx);
        return -6;
    }

    // Free resources
    free(buffer);
    EVP_CIPHER_CTX_free(ctx);

