#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>
#include <time.h>

#define MAX_SEMAPHORES 10000
#define LOG_FILE "semaphore_log.txt"
#define LOG_ROTATE_INTERVAL (24 * 60 * 60) // Daily rotation

typedef struct {
    sem_t *sems[MAX_SEMAPHORES];
    char names[MAX_SEMAPHORES][32];
    int count;
    pthread_mutex_t mutex;
} SemaphoreManager;

SemaphoreManager manager = { .mutex = PTHREAD_MUTEX_INITIALIZER };

void log_action(const char *action, const char *name, int value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s %02d:%02d:%02d: %s semaphore '%s' with value %d\n",
                asctime(tm_info), tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                action, name, value);
        fclose(log_file);
    }
}

void rotate_and_compress_log() {
    time_t now = time(NULL);
    char old_log[256];
    snprintf(old_log, sizeof(old_log), "%s.%ld", LOG_FILE, now);
    rename(LOG_FILE, old_log);
    // Compress the log file using a system command or library function
}

void init_semaphore_manager() {
    pthread_mutex_lock(&manager.mutex);
    manager.count = 0;
    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        manager.sems[i] = NULL;
        snprintf(manager.names[i], sizeof(manager.names[i]), "sem%d", i);
    }
    pthread_mutex_unlock(&manager.mutex);
}

void add_semaphore(int index) {
    if (index >= MAX_SEMAPHORES || manager.count >= MAX_SEMAPHORES) return;
    pthread_mutex_lock(&manager.mutex);
    if (manager.sems[index] != NULL) {
        pthread_mutex_unlock(&manager.mutex);
        return; // Semaphore already exists
    }
    manager.sems[index] = sem_open(manager.names[index], O_CREAT, 0644, 1);
    if (manager.sems[index] == SEM_FAILED) {
        perror("Failed to create semaphore");
        pthread_mutex_unlock(&manager.mutex);
        return;
    }
    manager.count++;
    log_action("Added", manager.names[index], 1);
    pthread_mutex_unlock(&manager.mutex);
}

void remove_semaphore(int index) {
    if (index >= MAX_SEMAPHORES || manager.sems[index] == NULL) return;
    pthread_mutex_lock(&manager.mutex);
    sem_close(manager.sems[index]);
    sem_unlink(manager.names[index]);
    manager.sems[index] = NULL;
    manager.count--;
    log_action("Removed", manager.names[index], 0);
    pthread_mutex_unlock(&manager.mutex);
}

int get_semaphore_value(int index) {
    if (index >= MAX_SEMAPHORES || manager.sems[index] == NULL) return -1;
    int value;
    sem_getvalue(manager.sems[index], &value);
    log_action("Retrieved", manager.names[index], value);
    return value;
}

void *log_rotation_thread(void *arg) {
    while (1) {
        sleep(LOG_ROTATE_INTERVAL);
        rotate_and_compress_log();
    }
    return NULL;
}

int main() {
    init_semaphore_manager();
    pthread_t log_thread;
    pthread_create(&log_thread, NULL, log_rotation_thread, NULL);

    // Example usage
    add_semaphore(0);
    printf("Semaphore value: %d\n", get_semaphore_value(0));
    remove_semaphore(0);

    pthread_join(log_thread, NULL);
    return 0;
}
