void updateMapEntry(int key, int increment, const std::string& element, std::unordered_map<int, std::vector<std::string>>& map) {
    static const size_t MAX_MAP_SIZE = 1000; // Define a maximum size limit for the map
    static std::mutex mapMutex;

    if (increment < 0 || element.empty()) {
        throw std::invalid_argument("Invalid input parameters: increment must be non-negative and element cannot be empty.");
    }

    std::lock_guard<std::mutex> lock(mapMutex);

    if (map.size() >= MAX_MAP_SIZE) {
        throw std::runtime_error("Map has reached its maximum size limit.");
    }

    auto it = map.find(key);
    if (it != map.end()) {
        it->second.push_back(element);
        it->first += increment;
    } else {
        map[key] = {element};
        map[key].front() += increment; // Assuming the increment is meant to be applied to the first element
    }
}
