#include <nlohmann/json.hpp>

enum class LogLevel { DEBUG, INFO, WARNING, ERROR };
enum class LogFormat { PLAIN_TEXT, JSON };

class Logger {
public:
    static void init(LogLevel level = LogLevel::INFO, LogFormat format = LogFormat::PLAIN_TEXT) {
        config.level = level;
        config.format = format;
    }

    static void log(LogLevel level, const std::string& message) {
        if (level >= config.level) {
            std::string formattedMessage = formatMessage(level, message);
            output(formattedMessage);
        }
    }

private:
    struct Config {
        LogLevel level = LogLevel::INFO;
        LogFormat format = LogFormat::PLAIN_TEXT;
    };

    static Config config;

    static std::string formatMessage(LogLevel level, const std::string& message) {
        switch (config.format) {
            case LogFormat::JSON:
                return nlohmann::json{{"level", level}, {"message", message}}.dump();
            case LogFormat::PLAIN_TEXT:
                return "[" + getLevelString(level) + "] " + message;
        }
        return "";
    }

    static std::string getLevelString(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO: return "INFO";
            case LogLevel::WARNING: return "WARNING";
            case LogLevel::ERROR: return "ERROR";
        }
        return "";
    }

    static void output(const std::string& message) {
        if (config.format == LogFormat::JSON) {
            std::cout << message << std::endl;
        } else {
            std::ofstream logFile("log.txt", std::ios_base::app);
            logFile << message << std::endl;
            logFile.close();
        }
    }
};

Logger::Config Logger::config;

int main() {
    Logger::init(Logger::DEBUG, Logger::JSON);
    Logger::log(Logger::INFO, "This is an info message.");
    Logger::log(Logger::ERROR, "This is an error message.");
    return 0;
}
