using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;

public class BatchInsertOptimizer
{
    public async Task<bool> ExecuteBatchInsertsAsync(List<Tuple<string, object[]>> data, string connectionString, string tableSchema)
    {
        bool allBatchesSuccessful = true;
        int batchSize = 100; // Initial batch size

        while (data.Any())
        {
            var currentBatch = data.Take(batchSize).ToList();
            data = data.Skip(batchSize).ToList();

            try
            {
                await InsertBatchAsync(currentBatch, connectionString, tableSchema);
                Debug.WriteLine($"Batch of {currentBatch.Count} inserted successfully.");
            }
            catch (SqlException ex)
            {
                if (ex.Number == -2) // Network-related errors
                {
                    Debug.WriteLine("Network error encountered. Retrying...");
                    await Task.Delay(1000); // Wait before retrying
                    batchSize = Math.Max(batchSize / 2, 1); // Reduce batch size on failure
                }
                else if (ex.Number == 1205) // Deadlock detected
                {
                    Debug.WriteLine("Deadlock detected. Retrying...");
                    await Task.Delay(1000); // Wait before retrying
                }
                else
                {
                    Debug.WriteLine($"SQL error: {ex.Message}");
                    allBatchesSuccessful = false;
                    break;
                }
            }
        }

        return allBatchesSuccessful;
    }

    private async Task InsertBatchAsync(List<Tuple<string, object[]>> batch, string connectionString, string tableSchema)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();

            var parameters = batch.Select(t => t.Item2).SelectMany(x => x).ToArray();
            var parameterNames = batch.Select(t => t.Item1).Select((name, index) => $"@Param{index}").ToArray();

            string sql = $"INSERT INTO {tableSchema} VALUES ({string.Join(", ", parameterNames)})";

            using (var command = new SqlCommand(sql, connection))
            {
                for (int i = 0; i < parameters.Length; i++)
                {
                    command.Parameters.AddWithValue(parameterNames[i], parameters[i]);
                }

                await command.ExecuteNonQueryAsync();
            }
        }
    }
}
