    public static XPathNavigator FindFirstXPathElement(string xmlContent, string elementName)
    {
        using (var reader = new StringReader(xmlContent))
        {
            var navigator = new XPathDocument(reader).CreateNavigator();
            var node = navigator.SelectSingleNode($"//{elementName}");
            if (node == null)
                throw new InvalidOperationException("No element found.");
            if (navigator.SelectNodes($"//{elementName}").Count > 1)
                throw new InvalidOperationException("Multiple elements found.");
            return node;
        }
    }

    public static void CreateDirectoryAndSetEnvironmentVariable(string path, string directoryName)
    {
        var fullPath = Path.Combine(path, directoryName);
        if (!Directory.Exists(fullPath))
        {
            Directory.CreateDirectory(fullPath);
        }
        Environment.SetEnvironmentVariable(directoryName, fullPath, EnvironmentVariableTarget.Process);
    }
}
