import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MD5Hasher {

    private static final Logger LOGGER = Logger.getLogger(MD5Hasher.class.getName());
    private static final int MAX_STRING_LENGTH = 10_000;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public static String processStrings(String... strings) throws InterruptedException {
        long startTime = System.currentTimeMillis();
        StringBuilder resultBuilder = new StringBuilder();

        for (String str : strings) {
            if (str == null || str.isEmpty()) {
                throw new IllegalArgumentException("Input string cannot be null or empty");
            }
            if (str.length() > MAX_STRING_LENGTH) {
                LOGGER.warning("String exceeds maximum length of " + MAX_STRING_LENGTH + " characters");
            }

            executorService.submit(() -> {
                try {
                    String md5Hash = computeMD5(str);
                    resultBuilder.append(md5Hash);
                } catch (NoSuchAlgorithmException e) {
                    LOGGER.log(Level.SEVERE, "Error computing MD5 hash", e);
                }
            });
        }

        executorService.shutdown();
        if (!executorService.awaitTermination(1, TimeUnit.MINUTES)) {
            executorService.shutdownNow();
        }

        long endTime = System.currentTimeMillis();
        LOGGER.info("Total processing time: " + (endTime - startTime) + " ms");
        return resultBuilder.toString();
    }

    private static String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) {
        try {
            String result = processStrings("Hello, World!", "Java Programming", "Concurrency");
            System.out.println(result);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            LOGGER.log(Level.SEVERE, "Thread interrupted", e);
        }
    }
}
