using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class PageService : IPageService
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<PageService> _logger;
    private const int MaxContentLength = 1024 * 10; // 10 KB
    private static readonly string[] DisallowedTags = { "<script>", "</script>", "<iframe>", "</iframe>" };

    public PageService(HttpClient httpClient, ILogger<PageService> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task UpdateElementContentAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
        {
            throw new ArgumentException("Page section ID and element ID cannot be null or empty.");
        }

        if (htmlContent.Length > MaxContentLength)
        {
            _logger.LogWarning("HTML content exceeds maximum allowed length. Truncating...");
            htmlContent = htmlContent.Substring(0, MaxContentLength);
        }

        foreach (var tag in DisallowedTags)
        {
            if (htmlContent.Contains(tag))
            {
                _logger.LogError($"Disallowed tag '{tag}' detected in HTML content.");
                throw new InvalidOperationException("HTML content contains disallowed tags.");
            }
        }

        var url = $"https://cms.example.com/api/updateElement?sectionId={pageSectionId}&elementId={elementId}";
        var content = new StringContent(htmlContent, Encoding.UTF8, "application/json");

        int retryCount = 0;
        while (retryCount < 5)
        {
            try
            {
                var response = await _httpClient.PostAsync(url, content);
                response.EnsureSuccessStatusCode();
                break;
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Failed to update element content. Retrying...");
                retryCount++;
                await Task.Delay((int)Math.Pow(2, retryCount) * 100); // Exponential backoff
            }
        }

        if (retryCount == 5)
        {
            throw new InvalidOperationException("Failed to update element content after multiple retries.");
        }
    }
}

public interface IPageService
{
    Task UpdateElementContentAsync(string pageSectionId, string elementId, string htmlContent);
}
