["```javascript
const fs = require('fs').promises;
const path = require('path');

async function readFileContents(directoryPath, allowedExtensions) {
  try {
    const files = await fs.readdir(directoryPath);
    let totalFilesProcessed = 0;
    let successfulReads = 0;

    const processFile = async (file) => {
      if (allowedExtensions.includes(path.extname(file))) {
        try {
          const content = await fs.readFile(path.join(directoryPath, file), 'utf8');
          console.log(`Successfully read ${file}`);
          successfulReads++;
        } catch (error) {
          console.error(`Failed to read ${file}:`, error);
        }
      }
      totalFilesProcessed++;
    };

    const concurrentOperations = 10; // Balance this number based on system capabilities
    let fileIndex = 0;

    while (fileIndex < files.length) {
      const promises = [];
      for (let i = 0; i < concurrentOperations && fileIndex < files.length; i++) {
        promises.push(processFile(files[fileIndex]));
        fileIndex++;
      }
      await Promise.all(promises);
    }

    console.log(`Total files processed: ${totalFilesProcessed}`);
    console.log(`Successful reads: ${successfulReads}`);

  } catch (error) {
    console.error('Error reading directory:', error);
  }
}

// Example usage:
const directoryPath = './your-directory-path';
const allowedExtensions = ['.txt', '.json']; // Add more extensions as needed
readFileContents(directoryPath, allowedExtensions);
```

This code snippet demonstrates how to asynchronously read files from a specified directory, filter them based on their extension, and handle potential performance bottlenecks. It also includes error handling for cases where the directory path is invalid or inaccessible, and efficiently manages memory usage by processing file contents in parallel with a controlled number of concurrent operations."]

["```javascript
const blueslip = require('blueslip');
const retry = require('retry');

function runTests(modulePath, testCases) {
  const module = require(modulePath);
  let successCount = 0;
  let failureCount = 0;
  let failureReasons = {};

  function executeTest(testCase) {
    return new Promise((resolve, reject) => {
      const operation = retry.operation({ retries: 3 });
      operation.attempt(async (currentAttempt) => {
        try {
          await testCase(module);
          resolve();
        } catch (error) {
          if (operation.retry(error)) {
            console.log(`Test failed on attempt ${currentAttempt}, retrying...`);
            return;
          }
          reject(error);
        }
      });
    });
  }

  async function runBatch(testCases, batchSize = 100) {
    const batchPromises = [];
    for (let i = 0; i < testCases.length; i += batchSize) {
      const batch = testCases.slice(i, i + batchSize);
      batch.forEach((testCase) => {
        batchPromises.push(executeTest(testCase));
      });
      await Promise.all(batchPromises);
      batchPromises.length = 0;
    }
  }

  async function runAllTests() {
    for (const testCase of testCases) {
      try {
        await executeTest(testCase);
        successCount++;
      } catch (error) {
        failureCount++;
        const reason = error.message || 'Unknown reason';
        if (!failureReasons[reason]) {
          failureReasons[reason] = 0;
        }
        failureReasons[reason]++;
      } finally {
        blueslip.reset();
      }
    }
  }

  async function main() {
    await runAllTests();
    console.log(`Tests completed. Success: ${successCount}, Failure: ${failureCount}`);
    for (const [reason, count] of Object.entries(failureReasons)) {
      console.log(`${count} tests failed due to: ${reason}`);
    }
  }

  main();
}

// Example usage:
const testCases = [
  async (module) => module.testFunction1(),
  async (module) => module.testFunction2(),
  // Add more test cases as needed
];

runTests('./path/to/module', testCases);
```

This code snippet provides a basic structure for managing a suite of tests in a modular, scalable testing framework. It dynamically loads the module using `require`, executes the tests in sequence with retries, and resets the mocking library after each test execution. The function also includes batching to reduce console output overhead and tracks success rates and failure reasons."]

