            // Set up timeout to handle potential network latency
            setTimeout(function() {
                // Simulate fetching updated field value
                var updatedValue = fetchUpdatedFieldValue(field.id);
                updatedFields[field.name] = updatedValue;

                // Check if insertString should be inserted or appended
                if (field.name === insertString) {
                    modifiedArray = insertAtFirstOccurrence($scope.fieldNames, appendString);
                } else {
                    modifiedArray = appendToArray($scope.fieldNames, appendString);
                }
            }, 100); // Adjust timeout duration as needed
        }
    });

    return { updatedFields: updatedFields, modifiedArray: modifiedArray };
}

function fetchUpdatedFieldValue(fieldId) {
    // Simulate asynchronous data fetching
