class DataStreamManager {
  constructor(maxBufferLength = 1000) {
    this.buffer = [];
    this.maxBufferLength = maxBufferLength;
    this.isPaused = false;
    this.loggingServiceUrl = 'https://example.com/log';
    this.retryAttempts = 3;
    this.delayMin = 500;
    this.delayMax = 2000;
  }

  async logData(data) {
    if (this.isPaused) return;

    try {
      for (let attempt = 0; attempt <= this.retryAttempts; attempt++) {
        const response = await fetch(this.loggingServiceUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data)
        });

        if (response.ok) {
          return;
        } else {
          console.error(`Logging failed. Attempt ${attempt + 1} of ${this.retryAttempts}`);
          await this.delay();
        }
      }

      throw new Error('Failed to log data after multiple attempts');
    } catch (error) {
      console.error('Error logging data:', error);
      // Fallback mechanism: store data locally if logging fails
      this.buffer.push(data);
      if (this.buffer.length > this.maxBufferLength) {
        this.buffer.shift();
      }
    }
  }

  async delay() {
    const delay = Math.floor(Math.random() * (this.delayMax - this.delayMin + 1)) + this.delayMin;
    return new Promise(resolve => setTimeout(resolve, delay));
  }

  pause() {
    this.isPaused = true;
    console.log('Data collection paused');
  }

  resume() {
    this.isPaused = false;
    console.log('Data collection resumed');
    // Process any buffered data
    while (this.buffer.length > 0) {
      const data = this.buffer.shift();
      this.logData(data);
    }
  }

  async simulateService() {
    setInterval(async () => {
      if (Math.random() < 0.5) {
        console.log('Starting service');
        await this.delay();
        console.log('Stopping service');
      } else {
        console.log('Service running normally');
      }
    }, Math.floor(Math.random() * (this.delayMax - this.delayMin + 1)) + this.delayMin);
  }
}

// Usage
const manager = new DataStreamManager();
manager.simulateService();

setInterval(() => {
  const data = { timestamp: new Date(), value: Math.random() };
  manager.logData(data);
}, 1000);

manager.pause();
setTimeout(() => manager.resume(), 5000);
