// Define the JavaScript module
const DynamicScriptLoader = (function() {
    const loadedScripts = new Set();
    const scriptQueue = [];
    let isProcessing = false;

    function loadScript(url) {
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = url;
            script.onload = resolve;
            script.onerror = reject;
            document.head.appendChild(script);
        });
    }

    function processQueue() {
        if (isProcessing || scriptQueue.length === 0) return;

        isProcessing = true;
        const nextScriptUrl = scriptQueue.shift();

        loadScript(nextScriptUrl)
            .then(() => {
                loadedScripts.add(nextScriptUrl);
                console.log(`Script ${nextScriptUrl} loaded successfully.`);
            })
            .catch((error) => {
                console.error(`Failed to load script ${nextScriptUrl}:`, error);
            })
            .finally(() => {
                isProcessing = false;
                processQueue();
            });
    }

    function enqueueScript(url) {
        if (!loadedScripts.has(url)) {
            scriptQueue.push(url);
            processQueue();
        }
    }

    return {
        load: (url) => enqueueScript(url)
    };
})();

// Example usage
DynamicScriptLoader.load('https://example.com/script1.js');
DynamicScriptLoader.load('https://example.com/script2.js');
```

This code snippet defines a JavaScript module named `DynamicScriptLoader` that dynamically loads and executes JavaScript files from a server endpoint. It uses a queue to manage the loading process, ensuring scripts are loaded in the correct order and handles errors gracefully. The module provides a simple interface for enqueuing script URLs and automatically processes them asynchronously."]

