public class SocialMediaSessionTracker {
    private final long sessionTimeoutMillis = 30 * 60 * 1000; // 30 minutes
    private final BlockingQueue<UserActivity> activityQueue;
    private final ExecutorService executorService;

    public SocialMediaSessionTracker(int queueCapacity) {
        this.activityQueue = new ArrayBlockingQueue<>(queueCapacity);
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        startProcessing();
    }

    public void submitActivity(UserActivity activity) throws InterruptedException {
        activityQueue.put(activity);
    }

    private void startProcessing() {
        executorService.submit(() -> {
            while (true) {
                try {
                    UserActivity activity = activityQueue.take();
                    processActivity(activity);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
    }

    private void processActivity(UserActivity activity) {
        // Simulate session metadata retrieval
        SessionMetadata metadata = fetchSessionMetadata(activity.getUserId());
        if (metadata == null) {
            metadata = new SessionMetadata(activity.getUserId(), System.currentTimeMillis());
        }

        long currentTime = System.currentTimeMillis();
        if (currentTime - metadata.getLastActivityTime() > sessionTimeoutMillis) {
            printSessionDuration(metadata);
            metadata.reset(currentTime);
        }
        metadata.updateLastActivityTime(currentTime);

        // Simulate backpressure handling
        try {
            Thread.sleep(1); // Simulate processing time
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private SessionMetadata fetchSessionMetadata(String userId) {
        // Placeholder for actual metadata retrieval logic
        return new SessionMetadata(userId, System.currentTimeMillis());
    }

    private void printSessionDuration(SessionMetadata metadata) {
        long sessionDuration = System.currentTimeMillis() - metadata.getSessionStartTime();
        System.out.println("User " + metadata.getUserId() + " spent " + sessionDuration + " ms in a session.");
    }

    public static class UserActivity {
        private final String userId;
        private final long timestamp;

        public UserActivity(String userId, long timestamp) {
            this.userId = userId;
            this.timestamp = timestamp;
        }

        public String getUserId() {
            return userId;
        }

        public long getTimestamp() {
            return timestamp;
        }
    }

    public static class SessionMetadata {
        private final String userId;
        private long sessionStartTime;
        private long lastActivityTime;

        public SessionMetadata(String userId, long startTime) {
            this.userId = userId;
            this.sessionStartTime = startTime;
            this.lastActivityTime = startTime;
        }

        public String getUserId() {
            return userId;
        }

        public long getSessionStartTime() {
            return sessionStartTime;
        }

        public long getLastActivityTime() {
            return lastActivityTime;
        }

        public void reset(long newStartTime) {
            this.sessionStartTime = newStartTime;
            this.lastActivityTime = newStartTime;
        }

        public void updateLastActivityTime(long newTime) {
            this.lastActivityTime = newTime;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        SocialMediaSessionTracker tracker = new SocialMediaSessionTracker(1000);
        for (int i = 0; i < 1000; i++) {
            String userId = "user" + (i % 10);
            long timestamp = System.currentTimeMillis() - (i * 60 * 1000); // Simulate past activities
            tracker.submitActivity(new UserActivity(userId, timestamp));
        }
    }
}
