public class ServiceManager {
    private Map<String, Service> servicePool;
    private List<Service> activeServices;
    private int currentLoad;
    private long systemUptime;
    private ConfigManager configManager;

    public ServiceManager(ConfigManager configManager) {
        this.servicePool = new HashMap<>();
        this.activeServices = new ArrayList<>();
        this.currentLoad = 0;
        this.systemUptime = System.currentTimeMillis();
        this.configManager = configManager;
        loadServiceConfigurations();
    }

    private void loadServiceConfigurations() {
        // Load service configurations from external management system
        List<ServiceConfig> configs = configManager.getServiceConfigs();
        for (ServiceConfig config : configs) {
            Service service = new Service(config.getId(), config.isActive());
            servicePool.put(config.getId(), service);
            if (config.isActive()) {
                activeServices.add(service);
            }
        }
    }

    public void startService(String id) {
        Service service = servicePool.get(id);
        if (service != null && !service.isActive()) {
            service.start();
            activeServices.add(service);
            logEvent("START", id, currentLoad, systemUptime);
        }
    }

    public void stopService(String id) {
        Service service = servicePool.get(id);
        if (service != null && service.isActive()) {
            service.stop();
            activeServices.remove(service);
            logEvent("STOP", id, currentLoad, systemUptime);
        }
    }

