['```rust
use reqwest::{Client, Error, Method, RequestBuilder};
use std::time::Duration;
use tokio::sync::Mutex;

pub struct HttpClient {
    client: Client,
    base_url: String,
    timeout: Duration,
    ssl_verify: bool,
    headers: Option<Vec<(String, String)>>,
    cookies: Mutex<Vec<String>>,
}

impl HttpClient {
    pub fn new(base_url: &str, timeout: Duration, ssl_verify: bool) -> Self {
        let client = Client::builder()
            .timeout(timeout)
            .danger_accept_invalid_certs(!ssl_verify)
            .build()
            .unwrap();
        HttpClient {
            client,
            base_url: base_url.to_string(),
            timeout,
            ssl_verify,
            headers: None,
            cookies: Mutex::new(Vec::new()),
        }
    }

    pub fn with_headers(mut self, headers: Vec<(String, String)>) -> Self {
        self.headers = Some(headers);
        self
    }

    pub async fn get(&self, endpoint: &str) -> Result<String, Error> {
        let request = self.build_request(Method::GET, endpoint).await?;
        self.send_request(request).await
    }

    pub async fn post(&self, endpoint: &str, body: String) -> Result<String, Error> {
        let request = self.build_request(Method::POST, endpoint).await?;
        let mut builder = request.body(body);
        if let Some(headers) = &self.headers {
            for (key, value) in headers {
                builder = builder.header(key, value);
            }
        }
        self.send_request(builder.build()?).await
    }

    async fn build_request(&self, method: Method, endpoint: &str) -> Result<RequestBuilder, Error> {
        let url = format!("{}{}", self.base_url, endpoint);
        Ok(self.client.request(method, url))
    }

    async fn send_request(&self, request: RequestBuilder) -> Result<String, Error> {
        let response = request.send().await?;
        if response.status().is_success() {
            response.text().await
        } else {
            Err(Error::new(reqwest::ErrorKind::InvalidResponse, "Non-success status code"))
        }
    }

    pub async fn add_cookie(&self, cookie: String) {
        let mut cookies = self.cookies.lock().unwrap();
        cookies.push(cookie);
    }

    pub async fn remove_cookie(&self, cookie: &str) {
        let mut cookies = self.cookies.lock().unwrap();
        cookies.retain(|c| !c.contains(cookie));
    }
}
