import requests
from ratelimiter import RateLimiter
from retrying import retry
import logging

# Setup logging configuration
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# External API endpoint
API_URL = "https://api.example.com/user/update"

# Rate limiter for external API calls
rate_limiter = RateLimiter(max_calls=10, period=60)  # Allow 10 calls per minute

@retry(stop_max_attempt_number=3, wait_fixed=2000)
def fetch_user_data(user_id):
    """Fetch user data from the external API."""
    with rate_limiter:
        response = requests.get(f"{API_URL}/{user_id}")
        if response.status_code == 200:
            return response.json()
        else:
            logger.error(f"Failed to fetch user data for {user_id}: {response.status_code}")
            raise Exception("Failed to fetch user data")

def update_user_profile(user_id, new_contact_info, last_login_time, last_login_ip):
    """Update a user profile with new contact information and login details."""
    try:
        user_data = fetch_user_data(user_id)
        # Update user data with new information
        user_data.update({
            "contact_info": new_contact_info,
            "last_login_time": last_login_time,
            "last_login_ip": last_login_ip
        })

        # Simulate updating the database or external storage
        response = requests.put(f"{API_URL}/{user_id}", json=user_data)
        if response.status_code == 200:
            return {
                "success": True,
                "message": "User profile updated successfully",
                "metrics": {
                    "retries": 0,
                    "logged_errors": [],
                    "api_status": "Success"
                }
            }
        else:
            logger.error(f"Failed to update user profile for {user_id}: {response.status_code}")
            raise Exception("Failed to update user profile")
    except Exception as e:
        logger.error(f"Error updating user profile for {user_id}: {e}")
        return {
            "success": False,
            "message": str(e),
            "metrics": {
                "retries": 3,  # Number of retries attempted
                "logged_errors": [str(e)],
                "api_status": "Failed"
            }
        }

# Example usage
result = update_user_profile("12345", {"email": "newemail@example.com"}, "2023-04-01T12:00:00Z", "192.168.1.1")
print(result)
