    try {
      const response = await axios.get('https://api.example.com/certificate', {
        headers: {
          'Authorization': `Bearer ${await getAccessToken()}`
        }
      });

      if (response.status === 200) {
        return response.data.pem;
      } else {
        throw new Error(`Failed to fetch certificate: ${response.statusText}`);
      }
    } catch (error) {
      retryCount++;
      const backoffTime = Math.pow(2, retryCount) * 100; // Exponential backoff
      await new Promise(resolve => setTimeout(resolve, backoffTime));
    }
  }

  throw new Error('Failed to fetch certificate after multiple retries');
}

