u_char* resolve_hostname(const char *hostname) {
    struct addrinfo hints, *res;
    u_char ip[INET6_ADDRSTRLEN];
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), ip, INET_ADDRSTRLEN);
    freeaddrinfo(res);

    return strdup(ip); // Return the IP address as a u_char array
}

int authResolve(AuthRequest *request) {
    pthread_mutex_lock(&session_manager.lock);
    int auth_result = authenticate_user(request->client_id, request->session_id);
    if (auth_result != 0) {
        pthread_mutex_unlock(&session_manager.lock);
        return -1; // Authentication failure
    }

    u_char *ip_address = resolve_hostname(request->hostname);
    pthread_mutex_unlock(&session_manager.lock);

    if (ip_address == NULL) {
        return -2; // DNS resolution error
    }

    free(ip_address); // Free the allocated memory for IP address
    return 0; // Success
}

void* thread_function(void *arg) {
    AuthRequest request = *(AuthRequest *)arg;
    int result = authResolve(&request);
    if (result == 0) {
        printf("Authentication and DNS resolution successful.\n");
    } else {
        printf("Error: %d\n", result);
    }
    return NULL;
}

int main() {
    init_session_manager();

    pthread_t threads[10];
    AuthRequest requests[10];

    for (int i = 0; i < 10; i++) {
        requests[i].hostname = "example.com";
        requests[i].client_id = "client123";
        requests[i].session_id = "session456";

        pthread_create(&threads[i], NULL, thread_function, &requests[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
