<?php

class UserPasswordUpdater {
    private $databases;
    private $authService;
    private $logger;

    public function __construct($databases, $authService, $logger) {
        $this->databases = $databases;
        $this->authService = $authService;
        $this->logger = $logger;
    }

    public function updatePassword($userId, $newPassword) {
        $startTime = microtime(true);
        $transactionId = uniqid();

        try {
            // Validate password strength
            if (!$this->validatePasswordStrength($newPassword)) {
                throw new Exception("Invalid password strength");
            }

            // Update user data in multiple databases
            foreach ($this->databases as $db) {
                $db->beginTransaction();
                $db->updateUserPassword($userId, $newPassword);
                $db->commit();
            }

            // Update password in external authentication service
            $authServiceResponse = $this->authService->updatePassword($userId, $newPassword);

            if ($authServiceResponse['status'] !== 'success') {
                throw new Exception("Failed to update password in external service");
            }

            // Log successful operation
            $this->logger->logSuccess($transactionId, "Password updated successfully for user {$userId}");

        } catch (Exception $e) {
            // Rollback any partially applied changes
            foreach ($this->databases as $db) {
                if ($db->inTransaction()) {
                    $db->rollBack();
                }
            }

            // Log failure
            $this->logger->logFailure($transactionId, "Failed to update password for user {$userId}: " . $e->getMessage());

            throw $e;
        } finally {
            // Calculate and log operation time
            $endTime = microtime(true);
            $operationTime = $endTime - $startTime;
            $this->logger->logOperationTime($transactionId, $operationTime);
        }
    }

    private function validatePasswordStrength($password) {
        // Implement password strength validation logic here
        return strlen($password) >= 8 && preg_match('/[a-z]/', $password) && preg_match('/[A-Z]/', $password) && preg_match('/\d/', $password);
    }
}

