$databases = [new Database(), new Database()]; // Initialize your database instances
$authService = new AuthService(); // Initialize your authentication service instance
$logger = new Logger(); // Initialize your logger instance

$userPasswordUpdater = new UserPasswordUpdater($databases, $authService, $logger);
$userPasswordUpdater->updatePassword(12345, "NewSecurePass123");
?>
