#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct FSA {
    State** states;
    int numStates;
    pthread_mutex_t mutex;
} FSA;

State* create_state_list(int* states, int numStates, FSA* fsa, int lastState) {
    if (numStates == 0 || states == NULL || fsa == NULL) {
        return NULL;
    }

    State* head = NULL;
    State** current = &head;

    for (int i = 0; i < numStates; i++) {
        State* newState = (State*)malloc(sizeof(State));
        if (newState == NULL) {
            // Handle memory allocation failure
            return NULL;
        }
        newState->id = states[i];
        newState->next = NULL;

        *current = newState;
        current = &(*current)->next;
    }

    pthread_mutex_lock(&fsa->mutex);
    fsa->states[lastState]->next = head;
    pthread_mutex_unlock(&fsa->mutex);

    return head;
}
