#include <iostream>
#include <vector>
#include <stdexcept>

class MemoryPool {
public:
    MemoryPool(size_t initialSize) : pool(initialSize), nextFree(0) {}

    void* allocate(size_t size) {
        if (nextFree + size > pool.size()) {
            throw std::bad_alloc();
        }
        void* ptr = &pool[nextFree];
        nextFree += size;
        return ptr;
    }

private:
    std::vector<char> pool;
    size_t nextFree;
};

class OctreeNode {
public:
    OctreeNode(size_t featureSize, MemoryPool& pool) : data(pool.allocate(featureSize)), children(nullptr) {}

    ~OctreeNode() {
        if (children != nullptr) {
            delete[] children;
        }
    }

private:
    void* data;
    OctreeNode** children;
};

class Octree {
public:
    Octree(size_t featureSize, size_t numLeafNodes, size_t dataCapacity)
        : featureSize(featureSize), pool(dataCapacity * featureSize) {
        if (featureSize <= 0 || numLeafNodes <= 0 || dataCapacity <= 0) {
            throw std::invalid_argument("Invalid input values");
        }
        root = new OctreeNode(featureSize, pool);
    }

    ~Octree() {
        delete root;
    }

private:
    size_t featureSize;
    MemoryPool pool;
    OctreeNode* root;
};

int main() {
    try {
        Octree octree(32, 1000, 10000);
        // Perform operations on the octree
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
