#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000
#define SLIDING_WINDOW_SIZE 10

typedef struct {
    uint32_t size;
    time_t timestamp;
    uint32_t checksum;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int head, tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} PacketQueue;

PacketQueue packet_queue;

void init_packet_queue() {
    pthread_mutex_init(&packet_queue.lock, NULL);
    pthread_cond_init(&packet_queue.not_full, NULL);
    pthread_cond_init(&packet_queue.not_empty, NULL);
    packet_queue.head = packet_queue.tail = 0;
}

int enqueue_packet(Packet *packet) {
    pthread_mutex_lock(&packet_queue.lock);
    while ((packet_queue.tail + 1) % MAX_PACKETS == packet_queue.head) {
        pthread_cond_wait(&packet_queue.not_full, &packet_queue.lock);
    }
    packet_queue.packets[packet_queue.tail] = *packet;
    packet_queue.tail = (packet_queue.tail + 1) % MAX_PACKETS;
    pthread_cond_signal(&packet_queue.not_empty);
    pthread_mutex_unlock(&packet_queue.lock);
    return 0;
}

int dequeue_packet(Packet *packet) {
    pthread_mutex_lock(&packet_queue.lock);
    while (packet_queue.head == packet_queue.tail) {
        pthread_cond_wait(&packet_queue.not_empty, &packet_queue.lock);
    }
    *packet = packet_queue.packets[packet_queue.head];
    packet_queue.head = (packet_queue.head + 1) % MAX_PACKETS;
    pthread_cond_signal(&packet_queue.not_full);
    pthread_mutex_unlock(&packet_queue.lock);
    return 0;
}

Packet process_packets() {
    Packet highest_checksum_packet;
    uint32_t total_checksum = 0;
    int packet_count = 0;

    while (1) {
        Packet packet;
        dequeue_packet(&packet);

        if (time(NULL) - packet.timestamp > 1) {
            // Handle packet frequency within the last second
            continue;
        }

        if (packet.size < 1024 || packet.size > 65536) {
            // Filter packets based on size
            continue;
        }

        total_checksum += packet.checksum;
        packet_count++;

        if (packet.checksum > highest_checksum_packet.checksum) {
            highest_checksum_packet = packet;
        }
    }

    // Calculate metrics
    uint32_t average_checksum = total_checksum / packet_count;

    return highest_checksum_packet;
}

void *network_thread(void *arg) {
    while (1) {
        Packet packet;
        // Simulate receiving a packet
        packet.size = rand() % 65536 + 1024;
        packet.timestamp = time(NULL);
        packet.checksum = rand();

        enqueue_packet(&packet);
    }
}

int main() {
    init_packet_queue();
    pthread_t network_tid;

    pthread_create(&network_tid, NULL, network_thread, NULL);

    Packet highest_checksum_packet = process_packets();

    printf("Highest checksum packet: Size=%d, Timestamp=%ld, Checksum=%u\n",
           highest_checksum_packet.size,
           highest_checksum_packet.timestamp,
           highest_checksum_packet.checksum);

    pthread_join(network_tid, NULL);
    return 0;
}
