#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <random>

class AttackSelector {
public:
    AttackSelector() : last_attack_time(0), total_attacks(0) {}

    void selectAttack() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return canSelectAttack(); });

        int selectedAttack = chooseAttack();
        std::cout << "Selected Attack: " << selectedAttack << std::endl;

        updateFrequency(selectedAttack);
    }

private:
    std::mutex mutex;
    std::condition_variable cv;
    std::queue<std::chrono::time_point<std::chrono::system_clock>> attack_times;
    int last_attack_time;
    std::vector<int> attack_frequencies = {0, 0, 0};
    const int cooldown = 9;
    const int frequency_window = 60;

    bool canSelectAttack() {
        auto now = std::chrono::system_clock::now();
        if (attack_times.empty()) {
            last_attack_time = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();
            return true;
        }
        int current_time = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();
        if (current_time - last_attack_time >= cooldown) {
            last_attack_time = current_time;
            return true;
        }
        return false;
    }

    int chooseAttack() {
        updateFrequencies();
        std::random_device rd;
        std::mt19937 gen(rd());
        std::discrete_distribution<> dist(attack_frequencies.begin(), attack_frequencies.end());
        return dist(gen);
    }

    void updateFrequency(int selectedAttack) {
        total_attacks++;
        if (total_attacks % frequency_window == 0) {
            resetFrequencies();
        }
        attack_frequencies[selectedAttack]++;
    }

    void updateFrequencies() {
        auto now = std::chrono::system_clock::now();
        while (!attack_times.empty()) {
            int time_since_last_attack = std::chrono::duration_cast<std::chrono::seconds>(now - attack_times.front()).count();
            if (time_since_last_attack >= frequency_window) {
                attack_frequencies[0] -= 1;
                attack_frequencies[1] -= 1;
                attack_frequencies[2] -= 1;
                attack_times.pop();
            } else {
                break;
            }
        }
    }

    void resetFrequencies() {
        for (auto& freq : attack_frequencies) {
            freq = 0;
        }
    }
};

int main() {
    AttackSelector selector;

    std::vector<std::thread> threads;
    for (int i = 0; i < 100; ++i) {
        threads.emplace_back([&selector] { selector.selectAttack(); });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
