async function asyncReduce(numbers, initialValue, callback, config) {
  const { timeoutInterval, loggingStrategy } = config;
  let total = initialValue;

  try {
    for (const number of numbers) {
      if (loggingStrategy === 'verbose') {
        console.log(`Processing number: ${number}`);
      }
      total = await callback(number, total);
      if (Date.now() - startTime > timeoutInterval) {
        throw new Error('Timeout reached');
      }
    }

    return total;
  } catch (error) {
    if (loggingStrategy === 'verbose') {
      console.error(`Error processing number: ${error.message}`);
    }
    throw error;
  }
}

// Example usage:
const numbers = [1, 2, 3, 4, 5, 6];
const initialValue = 0;
const callback = async (number, total) => {
  if (number % 3 === 0) {
    return total + number;
  } else {
    return total;
  }
};
const config = {
  timeoutInterval: 1000,
  loggingStrategy: 'verbose'
};

