#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *key;
    char *value;
} ConfigEntry;

typedef struct {
    ConfigEntry **entries;
    size_t count;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager* config_manager_init() {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    manager->entries = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void config_manager_free(ConfigManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->key);
        free(manager->entries[i]->value);
        free(manager->entries[i]);
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int config_manager_load(ConfigManager *manager, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    ConfigEntry **new_entries = (ConfigEntry**)realloc(manager->entries, sizeof(ConfigEntry*) * 2 * manager->count);
    if (!new_entries) {
        fclose(file);
        return -1;
    }
    manager->entries = new_entries;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (key && value) {
            ConfigEntry *entry = (ConfigEntry*)malloc(sizeof(ConfigEntry));
            entry->key = strdup(key);
            entry->value = strdup(value);
            pthread_mutex_lock(&manager->lock);
            manager->entries[manager->count++] = entry;
            pthread_mutex_unlock(&manager->lock);
        }
    }

    fclose(file);
    return 0;
}

int config_manager_get(ConfigManager *manager, const char *key, char **value) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i]->key, key) == 0) {
            *value = strdup(manager->entries[i]->value);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int config_manager_set(ConfigManager *manager, const char *key, const char *value) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i]->key, key) == 0) {
            free(manager->entries[i]->value);
            manager->entries[i]->value = strdup(value);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    ConfigEntry *entry = (ConfigEntry*)malloc(sizeof(ConfigEntry));
    entry->key = strdup(key);
    entry->value = strdup(value);
    manager->entries[manager->count++] = entry;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int config_manager_save(ConfigManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return -1;

    for (size_t i = 0; i < manager->count; ++i) {
        fprintf(file, "%s=%s\n", manager->entries[i]->key, manager->entries[i]->value);
    }

    fclose(file);
    return 0;
}
