char* appendSlashOrReturnNull(const char* str, size_t sizeLimit, size_t maxBufferSize) {
    if (str == NULL || *str == '\0' || strlen(str) > sizeLimit) {
        return NULL;
    }

    size_t newLength = strlen(str) + 2; // +1 for '/', +1 for null terminator
    if (newLength > maxBufferSize) {
        return NULL;
    }

    char* result = (char*)realloc((void*)str, newLength);
    if (result == NULL) {
        return NULL;
    }

    strcat(result, "/");
    return result;
}
