function getElementList(doc, selector, callback) {
    let elements = [];
    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE && callback(node)) {
            elements.push(node);
        }
        for (let child of node.childNodes) {
            traverse(child);
        }
    }
    traverse(doc.querySelector(selector));
    return elements;
}
