#define MAX_COMMANDS 20

typedef struct {
    char command[1024];
    int timeout;
    int priority;
} Command;

void handle_sigint(int sig) {
    // Handle user interrupt
}

void execute_command(Command *cmd, pid_t *pid) {
    *pid = fork();
    if (*pid == 0) {
        execl("/bin/sh", "sh", "-c", cmd->command, NULL);
        exit(127); // Command not found
    } else if (*pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }
}

int wait_for_command(pid_t pid, int timeout) {
    int status;
    time_t start = time(NULL);
    while (time(NULL) - start < timeout && waitpid(pid, &status, WNOHANG) == 0) {
        sleep(1); // Check every second
    }
    if (waitpid(pid, &status, 0) != pid) {
        return -1; // Error waiting for process
    }
    if (WIFEXITED(status)) {
        return WEXITSTATUS(status);
    } else if (WIFSIGNALED(status)) {
        return -2; // Process terminated by signal
    }
    return 0;
}

int execute_commands(Command commands[], int num_commands) {
    pid_t pids[MAX_COMMANDS];
    for (int i = 0; i < num_commands; i++) {
        execute_command(&commands[i], &pids[i]);
    }

    int result = 1;
    for (int i = 0; i < num_commands; i++) {
        int status = wait_for_command(pids[i], commands[i].timeout);
        if (status != 0) {
            result = 0;
        }
    }

    return result;
}

int main() {
    Command commands[MAX_COMMANDS] = {
        {"sleep 5", 10, 1},
        {"echo Hello", 5, 2},
        // Add more commands as needed
    };

    int num_commands = sizeof(commands) / sizeof(commands[0]);

    signal(SIGINT, handle_sigint);

    int result = execute_commands(commands, num_commands);
    printf("All commands executed successfully: %d\n", result);

    return 0;
}
