    public DirectoryManager(String targetDirectory, String metadataServiceUrl) {
        this.targetDirectory = targetDirectory;
        this.metadataServiceUrl = metadataServiceUrl;
    }

    public void manageDirectory() throws IOException {
        Path dirPath = Paths.get(targetDirectory);
        if (Files.exists(dirPath)) {
            deleteDirectory(dirPath);
        }
        // Additional operations can be added here
    }

    private void deleteDirectory(Path dirPath) throws IOException {
        if (!isDirectoryEmpty(dirPath)) {
            logger.severe("Directory is not empty. Cannot delete.");
            return;
        }
        Files.walk(dirPath)
             .sorted(java.util.Comparator.reverseOrder())
             .map(Path::toFile)
             .forEach(File::delete);
        logger.info("Directory deleted successfully: " + dirPath);
    }

    private boolean isDirectoryEmpty(Path dirPath) throws IOException {
        try (var stream = Files.list(dirPath)) {
            return !stream.findAny().isPresent();
        }
    }

    public void executeCommand(String command) {
        // Execute system command logic here
        logger.info("Executing command: " + command);
    }

