bool isValidPhoneNumber(const char* phoneNumber) {
    // Example: 10-digit number with optional country code
    int len = strlen(phoneNumber);
    if (len < 10 || len > 15) return false;
    for (int i = 0; i < len; i++) {
        if (!isdigit(phoneNumber[i])) return false;
    }
    return true;
}

// Function to validate address format
bool isValidAddress(const char* address) {
    // Example: Alphanumeric characters and spaces only
    int len = strlen(address);
    for (int i = 0; i < len; i++) {
        if (!isalnum(address[i]) && address[i] != ' ') return false;
