using System.Collections.Generic;
using System.Data.SqlClient;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class EncryptionService
{
    private readonly string _connectionString;
    private readonly Dictionary<string, ICryptoTransform> _encryptionTransforms = new Dictionary<string, ICryptoTransform>();

    public EncryptionService(string connectionString)
    {
        _connectionString = connectionString;
        LoadEncryptionConfigurations();
    }

    private void LoadEncryptionConfigurations()
    {
        // Load encryption configurations from a configuration file
        var config = GetEncryptionConfigurationsFromConfigFile();

        foreach (var configItem in config)
        {
            switch (configItem.Algorithm)
            {
                case "AES":
                    _encryptionTransforms[configItem.Key] = CreateAesTransform(configItem);
                    break;
                case "Camellia":
                    _encryptionTransforms[configItem.Key] = CreateCamelliaTransform(configItem);
                    break;
                case "RSA":
                    _encryptionTransforms[configItem.Key] = CreateRsAEncryptor(configItem);
                    break;
            }
        }
    }

    private ICryptoTransform CreateAesTransform(EncryptionConfig config)
    {
        using (var aes = Aes.Create())
        {
            aes.KeySize = config.KeySize;
            aes.IV = config.InitializationVector;
            return aes.CreateEncryptor(aes.Key, aes.IV);
        }
    }

    private ICryptoTransform CreateCamelliaTransform(EncryptionConfig config)
    {
        using (var camellia = Camellia.Create())
        {
            camellia.KeySize = config.KeySize;
            camellia.IV = config.InitializationVector;
            return camellia.CreateEncryptor(camellia.Key, camellia.IV);
        }
    }

    private ICryptoTransform CreateRsAEncryptor(EncryptionConfig config)
    {
        using (var rsa = RSA.Create())
        {
            rsa.ImportFromPem(config.PublicKey);
            return rsa.CreateEncryptor();
        }
    }

    public async Task<byte[]> EncryptDataAsync(string key, byte[] data)
    {
        if (!_encryptionTransforms.ContainsKey(key))
        {
            throw new ArgumentException("Invalid encryption key");
        }

        using (var memoryStream = new MemoryStream())
        using (var cryptoStream = new CryptoStream(memoryStream, _encryptionTransforms[key], CryptoStreamMode.Write))
        {
            await cryptoStream.WriteAsync(data, 0, data.Length);
        }

        return memoryStream.ToArray();
    }

    public async Task<byte[]> DecryptDataAsync(string key, byte[] encryptedData)
    {
        if (!_encryptionTransforms.ContainsKey(key))
        {
            throw new ArgumentException("Invalid encryption key");
        }

        using (var memoryStream = new MemoryStream(encryptedData))
        using (var cryptoStream = new CryptoStream(memoryStream, _encryptionTransforms[key], CryptoStreamMode.Read))
        using (var resultStream = new MemoryStream())
        {
            await cryptoStream.CopyToAsync(resultStream);
        }

        return resultStream.ToArray();
    }

    public async Task StoreEncryptedDataAsync(string key, byte[] encryptedData)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand("INSERT INTO EncryptedData (Key, Data) VALUES (@Key, @Data)", connection);
            command.Parameters.AddWithValue("@Key", key);
            command.Parameters.AddWithValue("@Data", encryptedData);
            await command.ExecuteNonQueryAsync();
        }
    }

    public async Task<byte[]> RetrieveEncryptedDataAsync(string key)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand("SELECT Data FROM EncryptedData WHERE Key = @Key", connection);
            command.Parameters.AddWithValue("@Key", key);
            using (var reader = await command.ExecuteReaderAsync())
            {
                if (await reader.ReadAsync())
                {
                    return (byte[])reader["Data"];
                }
            }
        }

        throw new InvalidOperationException("Encrypted data not found");
    }
}

public class EncryptionConfig
{
    public string Algorithm { get; set; }
    public int KeySize { get; set; }
    public byte[] InitializationVector { get; set; }
    public string PublicKey { get; set; }
}

private List<EncryptionConfig> GetEncryptionConfigurationsFromConfigFile()
{
