using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DecryptionService
{
    private readonly HttpClient _httpClient;
    private const int MaxRetries = 3;

    public DecryptionService(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<string> DecryptMessageAsync(string base64EncryptedMessage, byte[] key, byte[] iv, string hmacKey)
    {
        if (string.IsNullOrEmpty(base64EncryptedMessage))
            throw new ArgumentException("Base64 encrypted message cannot be null or empty.", nameof(base64EncryptedMessage));
        if (key == null || key.Length != 24)
            throw new ArgumentException("Encryption key must be 24 bytes long.", nameof(key));
        if (iv == null || iv.Length != 8)
            throw new ArgumentException("Initialization vector must be 8 bytes long.", nameof(iv));
        if (string.IsNullOrEmpty(hmacKey))
            throw new ArgumentException("HMAC key cannot be null or empty.", nameof(hmacKey));

        for (int attempt = 0; attempt <= MaxRetries; attempt++)
        {
            try
            {
                var encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
                using (var tripleDES = new TripleDESCryptoServiceProvider { Key = key, IV = iv })
                {
                    tripleDES.Mode = CipherMode.CBC;
                    tripleDES.Padding = PaddingMode.PKCS7;

                    using (var msDecrypt = new MemoryStream(encryptedBytes))
                    using (var csDecrypt = new CryptoStream(msDecrypt, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
                    using (var srDecrypt = new StreamReader(csDecrypt))
                    {
                        var decryptedMessage = await srDecrypt.ReadToEndAsync();
                        if (!VerifyHmac(decryptedMessage, hmacKey))
                            throw new InvalidOperationException("HMAC verification failed.");

                        return decryptedMessage;
                    }
                }
            }
            catch (Exception ex)
            {
                LogAttempt(attempt, false, ex.Message);
                if (attempt == MaxRetries) throw;
                await Task.Delay(100 * attempt); // Exponential backoff
            }
        }

        throw new InvalidOperationException("Decryption failed after maximum retries.");
    }

    private bool VerifyHmac(string message, string hmacKey)
    {
        using (var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(hmacKey)))
        {
            var computedHash = hmac.ComputeHash(Encoding.UTF8.GetBytes(message));
            var providedHash = Convert.FromBase64String(message.Substring(0, 64)); // Assuming the first 64 characters are the HMAC
            return computedHash.SequenceEqual(providedHash);
        }
    }

    private void LogAttempt(int attempt, bool success, string message)
    {
        Console.WriteLine($"Attempt {attempt}: {message} - Success: {success}");
    }
}
```

This code snippet defines a `DecryptionService` class that handles the decryption of messages encrypted with Triple DES and verifies their integrity using HMAC-SHA256. It includes error handling, retries, and logging for monitoring purposes. The `DecryptMessageAsync` method is designed to be asynchronous and can handle both small and large messages efficiently.']

