        foreach (var str in strings)
        {
            await HashAndStoreStringAsync(str);
        }
    }

    private async Task HashAndStoreStringAsync(string str)
    {
        if (!_hashCache.TryGetValue(str, out var hash))
        {
            hash = ComputeSHA256Hash(str);
            _hashCache.TryAdd(str, hash);
        }

        // Simulate disk I/O and network latency
        await Task.Delay(10); // Adjust delay as needed

        // Store in cache or persist to disk if necessary
        using (var fileStream = new FileStream(_cacheFilePath, FileMode.Append, FileAccess.Write, FileShare.None))
        {
            await fileStream.WriteAsync(hash, 0, hash.Length);
        }
    }

    private byte[] ComputeSHA256Hash(string str)
    {
        using (var sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(str));
        }
    }

    public async Task<byte[]> GetHashAsync(string str)
    {
        if (_hashCache.TryGetValue(str, out var hash))
        {
            return hash;
        }

        // Simulate disk I/O and network latency
        await Task.Delay(10); // Adjust delay as needed

        using (var fileStream = new FileStream(_cacheFilePath, FileMode.Open, FileAccess.Read, FileShare.Read))
        {
            byte[] buffer = new byte[32]; // SHA-256 hash size
            int bytesRead = await fileStream.ReadAsync(buffer, 0, buffer.Length);
            if (bytesRead == buffer.Length)
            {
                return buffer;
            }
        }

        throw new InvalidOperationException("Hash not found in cache or file.");
    }

    public async Task ReportProgressAsync()
    {
        // Simulate progress reporting
        await Task.Delay(100); // Adjust delay as needed

        Console.WriteLine($"Processed {GetNumberOfProcessedStrings()} strings.");
    }

    private int GetNumberOfProcessedStrings()
    {
        return _hashCache.Count;
    }
}
