    private readonly ConcurrentDictionary<int, Aes> _aesSessions = new ConcurrentDictionary<int, Aes>();
    private readonly ILogger _logger;
    private TcpListener _listener;

    public SecureClientServer(int port, ILogger logger)
    {
        _logger = logger;
        _listener = new TcpListener(System.Net.IPAddress.Any, port);
        _listener.Start();
    }

    public async Task StartAsync()
    {
        while (true)
        {
            var client = await _listener.AcceptTcpClientAsync();
            _ = HandleClientAsync(client);
        }
    }

    private async Task HandleClientAsync(TcpClient client)
    {
        try
        {
            using (var networkStream = client.GetStream())
            {
                // Establish secure session
                var aesSession = GenerateAesSession();
                _aesSessions.TryAdd(client.GetHashCode(), aesSession);

                while (client.Connected)
                {
                    var data = await ReadDataAsync(networkStream);
                    if (data == null) break;

                    // Decrypt and process data
                    var decryptedData = Decrypt(data, aesSession);
                    ProcessData(decryptedData);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error handling client connection.");
        }
        finally
        {
            client.Close();
            _aesSessions.TryRemove(client.GetHashCode(), out _);
        }
    }

    private Aes GenerateAesSession()
    {
        var aes = Aes.Create("AES-CBC");
        aes.KeySize = 256;
