using System;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;

public class DataDeserializer
{
    public static T DeserializeFromCompressedFile<T>(string filePath) where T : new()
    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The specified file does not exist.");
        }

        using (FileStream fileStream = File.OpenRead(filePath))
        {
            // Read the header to get the checksum and compression type
            byte[] header = new byte[16];
            fileStream.Read(header, 0, header.Length);

            byte[] checksumBytes = new byte[8];
            Array.Copy(header, checksumBytes, checksumBytes.Length);
            ulong expectedChecksum = BitConverter.ToUInt64(checksumBytes, 0);

            CompressionMode compressionMode = (CompressionMode)header[12];

            // Calculate the actual checksum of the file content
            using (SHA512 sha512 = SHA512.Create())
            {
                byte[] fileContentHash = new byte[fileStream.Length - header.Length];
                fileStream.Read(fileContentHash, 0, fileContentHash.Length);
                ulong actualChecksum = BitConverter.ToUInt64(sha512.ComputeHash(fileContentHash), 0);

                if (actualChecksum != expectedChecksum)
                {
                    throw new InvalidOperationException("Checksum mismatch detected.");
                }
            }

            // Decompress the data
            using (Stream decompressionStream = compressionMode == CompressionMode.Deflate ? 
                new DeflateStream(fileStream, CompressionMode.Decompress) : 
                new GZipStream(fileStream, CompressionMode.Decompress))
            {
                using (BinaryReader reader = new BinaryReader(decompressionStream))
                {
                    return DeserializeObject<T>(reader);
                }
            }
        }
    }

    private static T DeserializeObject<T>(BinaryReader reader)
