    this.logger.log('Packet added:', packet);
  }

  updatePacket(index, updatedFields) {
    if (index >= 0 && index < this.packets.length) {
      Object.assign(this.packets[index], updatedFields);
      this.logger.log('Packet updated:', this.packets[index]);
    } else {
      this.logger.error('Invalid packet index');
    }
  }

  iteratePackets() {
    let totalDataTransferred = 0;
    for (const packet of this.packets) {
      if (packet.status === 'processed') {
        totalDataTransferred += packet.payloadLength;
      }
    }
    return totalDataTransferred;
  }

  cleanupUnusedPackets() {
    const currentTime = Date.now();
    this.packets = this.packets.filter(packet => {
      if ((currentTime - packet.timestamp) > 60000) { // Example: Remove packets older than 1 minute
        this.logger.log('Packet cleaned up:', packet);
        return false;
      }
      return true;
    });
