use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::{Duration, SystemTime};
use tokio::task;
use tokio::time::sleep;

const BASE_DIR_ENV: &str = "WORKSPACE_BASE_DIR";
const MAX_RETRIES: u32 = 5;
const RETRY_DELAY: Duration = Duration::from_secs(1);
const ARCHIVE_AGE: Duration = Duration::from_secs(7 * 24 * 60 * 60);
const LOG_ROTATE_SIZE: u64 = 1_000_000_000; // 1 GB
const CLEANUP_AGE: Duration = Duration::from_secs(30 * 24 * 60 * 60);

struct WorkspaceManager {
    base_dir: PathBuf,
    log_file: File,
}

impl WorkspaceManager {
    fn new() -> Result<Self, io::Error> {
        let base_dir = env::var(BASE_DIR_ENV).unwrap_or_else(|_| "~/workspaces".to_string());
        let base_path = shellexpand::tilde(&base_dir).into_owned();
        fs::create_dir_all(&base_path)?;
        let log_file = File::options().append(true).create(true).open(base_path.join("workspace.log"))?;
        Ok(Self { base_dir: PathBuf::from(base_path), log_file })
    }

    async fn create_workspace(&self, name: &str) -> Result<(), io::Error> {
        for _ in 0..MAX_RETRIES {
            if let Err(e) = fs::create_dir_all(self.base_dir.join(name)) {
                if e.kind() == io::ErrorKind::AlreadyExists {
                    return Ok(());
                }
                sleep(RETRY_DELAY).await;
            } else {
                return Ok(());
            }
        }
        Err(io::Error::new(io::ErrorKind::Other, "Failed to create workspace after retries"))
    }

    async fn archive_old_workspaces(&self) -> Result<(), io::Error> {
        let now = SystemTime::now();
        for entry in fs::read_dir(self.base_dir.join("archive"))? {
            let entry = entry?;
            if let Ok(metadata) = entry.metadata() {
                if metadata.created().unwrap_or(now).elapsed()? > ARCHIVE_AGE {
                    fs::remove_dir_all(entry.path())?;
                }
            }
        }
        Ok(())
    }

    async fn rotate_logs(&self) -> Result<(), io::Error> {
        let mut log_file = File::options().append(true).create(true).open(self.base_dir.join("workspace.log"))?;
        if self.log_file.metadata()?.len() > LOG_ROTATE_SIZE {
            fs::rename(self.base_dir.join("workspace.log"), self.base_dir.join("workspace.log.old"))?;
            log_file = File::create(self.base_dir.join("workspace.log"))?;
        }
        Ok(())
    }

    async fn cleanup_old_entries(&self) -> Result<(), io::Error> {
        let now = SystemTime::now();
        for entry in fs::read_dir(self.base_dir)? {
            let entry = entry?;
            if let Ok(metadata) = entry.metadata() {
                if metadata.created().unwrap_or(now).elapsed()? > CLEANUP_AGE {
                    fs::remove_dir_all(entry.path())?;
                }
            }
        }
        Ok(())
    }

    async fn run_background_tasks(&self) {
        task::spawn(async move {
            loop {
                self.archive_old_workspaces().await.unwrap();
                self.rotate_logs().await.unwrap();
                sleep(Duration::from_secs(60 * 60 * 24)).await;
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<(), io::Error> {
    let manager = Arc::new(Mutex::new(WorkspaceManager::new()?));
    manager.lock().unwrap().run_background_tasks();
    // Example usage
    manager.lock().unwrap().create_workspace("my_workspace").await?;
    Ok(())
}
```']

