#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INPUT_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int findLargestInteger(int* array, int size) {
    if (size == 0) return -1; // Handle empty input
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

void populateNFAPIStructures(int* array, int size, NFAPI_CRC_INDICATION_PDU_T** output, int seed) {
    *output = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*output == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    srand(seed);
    for (int i = 0; i < size; i++) {
        int rnti = array[i];
        if (rnti < 0 || rnti > 65535) { // Assuming RNTI is a 16-bit unsigned integer
            fprintf(stderr, "Invalid RNTI value: %d\n", rnti);
            continue;
        }
        (*output)[i].RX_UE_INFORMATION_TAG = i + 1; // Example tag assignment
        (*output)[i].RNTI = rnti;
        (*output)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Pseudo-random CRC flag
    }
}

void processInputAndPopulateStructures() {
    int input[MAX_INPUT_SIZE];
    int size;

    printf("Enter the number of integers: ");
    scanf("%d", &size);
    if (size > MAX_INPUT_SIZE) {
        fprintf(stderr, "Input size exceeds limit\n");
        exit(1);
    }

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &input[i]);
    }

    int largestInteger = findLargestInteger(input, size);
    if (largestInteger != -1) {
        printf("Largest integer: %d\n", largestInteger);
    } else {
        printf("No integers provided.\n");
    }

    NFAPI_CRC_INDICATION_PDU_T* output;
    populateNFAPIStructures(input, size, &output, 42); // Example seed value

    // Free allocated memory
    free(output);

    printf("Processing complete.\n");
}

int main() {
    processInputAndPopulateStructures();
    return 0;
