typedef struct {
    int value;
} record;

int process_records(int num_records, int range_start, int range_end, const char* ciphers[], int cipher_count) {
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) return -1; // Memory allocation failed

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1; // Memory allocation failed
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
    }

    EVP_CIPHER_CTX* ctx = NULL;
    for (int i = 0; i < cipher_count; i++) {
        if (strcmp(ciphers[i], "AES") == 0) {
            ctx = EVP_CIPHER_CTX_new();
            if (!ctx || !EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
                free(offsets);
                free(keys);
                free(records);
                EVP_CIPHER_CTX_free(ctx);
                return -1; // Cryptographic operation failed
            }
        } else if (strcmp(ciphers[i], "Camellia") == 0) {
            ctx = EVP_CIPHER_CTX_new();
            if (!ctx || !EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, iv)) {
                free(offsets);
                free(keys);
                free(records);
                EVP_CIPHER_CTX_free(ctx);
                return -1; // Cryptographic operation failed
            }
        } else if (strcmp(ciphers[i], "MD5") == 0) {
            unsigned char md_value[EVP_MAX_MD_SIZE];
            int md_len;
            if (!EVP_DigestInit_ex(md_ctx, EVP_md5(), NULL) ||
                !EVP_DigestUpdate(md_ctx, records, num_records * sizeof(record)) ||
                !EVP_DigestFinal_ex(md_ctx, md_value, &md_len)) {
                free(offsets);
                free(keys);
                free(records);
                return -1; // Cryptographic operation failed
            }
        } else if (strcmp(ciphers[i], "SHA") == 0) {
            unsigned char sha_value[EVP_MAX_MD_SIZE];
            int sha_len;
            if (!EVP_DigestInit_ex(sha_ctx, EVP_sha256(), NULL) ||
                !EVP_DigestUpdate(sha_ctx, records, num_records * sizeof(record)) ||
                !EVP_DigestFinal_ex(sha_ctx, sha_value, &sha_len)) {
                free(offsets);
                free(keys);
                free(records);
                return -1; // Cryptographic operation failed
            }
        } else if (strcmp(ciphers[i], "RSA") == 0) {
            RSA* rsa = RSA_new();
            if (!rsa || !RSA_generate_key_ex(rsa, 2048, BN_value_one(), NULL)) {
                free(offsets);
                free(keys);
                free(records);
                RSA_free(rsa);
                return -1; // Cryptographic operation failed
            }
            unsigned char* signature = (unsigned char*)malloc(RSA_size(rsa));
            if (!signature) {
                free(offsets);
                free(keys);
                free(records);
                RSA_free(rsa);
                return -1; // Memory allocation failed
            }
            int sig_len;
            if (!RSA_sign(NID_sha1, (unsigned char*)&records, num_records * sizeof(record), signature, &sig_len, rsa)) {
                free(offsets);
                free(keys);
                free(records);
                RSA_free(rsa);
                free(signature);
                return -1; // Cryptographic operation failed
            }
            free(signature);
            RSA_free(rsa);
        }
    }

    EVP_CIPHER_CTX_free(ctx);

    free(offsets);
    free(keys);
    free(records);

    return 0; // Success
}
