#include <openssl/evp.h>
#include <openssl/rand.h>
#include <iostream>
#include <string>
#include <random>
#include <memory>

namespace CryptoLib {
    class EncryptionManager {
    public:
        enum class CipherMode { ECB, EDE, EDE3, CFB };
        enum class KeyLength { DES = 56, DES_EDE = 112, DES_EDE3 = 168 };

        EncryptionManager(CipherMode mode, KeyLength keyLen) : mode_(mode), keyLen_(keyLen) {
            // Initialize OpenSSL
            if (OpenSSL_add_all_algorithms() != 1 || ERR_load_crypto_strings() != 1) {
                throw std::runtime_error("Failed to initialize OpenSSL");
            }
        }

        ~EncryptionManager() {
            EVP_cleanup();
            ERR_free_strings();
        }

        void setKey(const std::string& key) {
            if (key.size() * 8 != static_cast<int>(keyLen_)) {
                throw std::invalid_argument("Invalid key length");
            }
            key_ = key;
        }

        void setIV(const std::string& iv) {
            if (iv.size() != EVP_CIPHER_block_size(getCipher())) {
                throw std::invalid_argument("Invalid IV size");
            }
            iv_ = iv;
        }

        std::string encrypt(const std::string& plaintext) const {
            EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
            if (!ctx) {
                throw std::runtime_error("Failed to create cipher context");
            }
            try {
                if (EVP_EncryptInit_ex(ctx, getCipher(), nullptr, reinterpret_cast<const unsigned char*>(key_.c_str()), reinterpret_cast<const unsigned char*>(iv_.c_str())) != 1) {
                    throw std::runtime_error("Failed to initialize encryption");
                }

                int len;
                std::string ciphertext(plaintext.size() + EVP_CIPHER_block_size(getCipher()), '\0');
                if (EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]), &len, reinterpret_cast<const unsigned char*>(plaintext.c_str()), plaintext.size()) != 1) {
                    throw std::runtime_error("Failed to encrypt data");
                }
                ciphertext.resize(len);

                int final_len;
                if (EVP_EncryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]) + len, &final_len) != 1) {
                    throw std::runtime_error("Failed to finalize encryption");
                }
                ciphertext.append(final_len, '\0');

                return ciphertext;
            } catch (...) {
                EVP_CIPHER_CTX_free(ctx);
                throw;
            }
        }

    private:
        CipherMode mode_;
        KeyLength keyLen_;
        std::string key_;
        std::string iv_;

        const EVP_CIPHER* getCipher() const {
            switch (mode_) {
                case CipherMode::ECB: return EVP_des_ecb();
                case CipherMode::EDE: return EVP_des_ede3_cbc();
                case CipherMode::EDE3: return EVP_des_ede3_cbc();
                case CipherMode::CFB: return EVP_des_cfb8();
            }
            throw std::invalid_argument("Unsupported cipher mode");
        }

        static std::string generateRandomIV(size_t size) {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 255);
            std::string iv(size, '\0');
            for (size_t i = 0; i < size; ++i) {
                iv[i] = static_cast<char>(dis(gen));
            }
            return iv;
        }

        friend class EncryptionManagerTest;
    };

    // Example usage
    void exampleUsage() {
        try {
            EncryptionManager manager(EncryptionManager::CipherMode::ECB, EncryptionManager::KeyLength::DES);
            manager.setKey("01234567");
            manager.setIV(EncryptionManager::generateRandomIV(EVP_CIPHER_block_size(EVP_des_ecb())));
            std::string plaintext = "Hello, World!";
            std::string ciphertext = manager.encrypt(plaintext);
            std::cout << "Ciphertext: " << ciphertext << std::endl;
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }
}
```

