#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int user_id;
    time_t start_time;
    time_t last_activity;
    char state[20];
    size_t data_transferred;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t count;
    size_t capacity;
} SessionManager;

void init_session_manager(SessionManager *manager, size_t initial_capacity) {
    manager->sessions = (UserSession *)malloc(initial_capacity * sizeof(UserSession));
    if (!manager->sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
}

void add_session(SessionManager *manager, UserSession session) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        manager->sessions = (UserSession *)realloc(manager->sessions, new_capacity * sizeof(UserSession));
        if (!manager->sessions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->capacity = new_capacity;
    }
    manager->sessions[manager->count++] = session;
}

void update_session(SessionManager *manager, int user_id, UserSession updated_session) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].user_id == user_id) {
            manager->sessions[i] = updated_session;
            return;
        }
    }
}

void calculate_metrics(SessionManager *manager, size_t *active_users, double *average_duration) {
    time_t current_time = time(NULL);
    *active_users = 0;
    time_t total_duration = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].state, "active") == 0) {
            (*active_users)++;
            total_duration += current_time - manager->sessions[i].start_time;
        }
    }

    *average_duration = total_duration / *active_users;
}

void cleanup_inactive_sessions(SessionManager *manager, time_t expiration_threshold) {
    size_t new_count = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (time(NULL) - manager->sessions[i].last_activity > expiration_threshold) {
            continue;
        }
        manager->sessions[new_count++] = manager->sessions[i];
    }

    manager->count = new_count;
}

void free_session_manager(SessionManager *manager) {
    free(manager->sessions);
}
