#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char name[256];
    void (*implementation)(void);
    void *context;
    void *init_params;
} CryptoAlgorithm;

typedef struct {
    CryptoAlgorithm **algorithms;
    size_t count;
    pthread_mutex_t lock;
} CryptoRegistry;

CryptoRegistry* create_registry() {
    CryptoRegistry *registry = (CryptoRegistry*)malloc(sizeof(CryptoRegistry));
    if (!registry) return NULL;
    registry->algorithms = NULL;
    registry->count = 0;
    pthread_mutex_init(&registry->lock, NULL);
    return registry;
}

void destroy_registry(CryptoRegistry *registry) {
    for (size_t i = 0; i < registry->count; ++i) {
        free(registry->algorithms[i]);
    }
    free(registry->algorithms);
    pthread_mutex_destroy(&registry->lock);
    free(registry);
}

int add_algorithm(CryptoRegistry *registry, const char *name, void (*implementation)(void), void *context, void *init_params) {
    pthread_mutex_lock(&registry->lock);
    CryptoAlgorithm *new_algo = (CryptoAlgorithm*)malloc(sizeof(CryptoAlgorithm));
    if (!new_algo) {
        pthread_mutex_unlock(&registry->lock);
        return -1;
    }
    strncpy(new_algo->name, name, sizeof(new_algo->name) - 1);
    new_algo->implementation = implementation;
    new_algo->context = context;
    new_algo->init_params = init_params;

    CryptoAlgorithm **new_algorithms = (CryptoAlgorithm**)realloc(registry->algorithms, (registry->count + 1) * sizeof(CryptoAlgorithm*));
    if (!new_algorithms) {
        free(new_algo);
        pthread_mutex_unlock(&registry->lock);
        return -1;
    }
    registry->algorithms = new_algorithms;
    registry->algorithms[registry->count++] = new_algo;
    pthread_mutex_unlock(&registry->lock);
    return 0;
}

int get_algorithm(CryptoRegistry *registry, const char *name, CryptoAlgorithm **algo) {
    pthread_mutex_lock(&registry->lock);
    for (size_t i = 0; i < registry->count; ++i) {
        if (strcmp(registry->algorithms[i]->name, name) == 0) {
            *algo = registry->algorithms[i];
            pthread_mutex_unlock(&registry->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&registry->lock);
    return -1;
}

void example_hash_function(void) {
    // Example hash function implementation
}

int main() {
    CryptoRegistry *registry = create_registry();
    if (!registry) {
        fprintf(stderr, "Failed to create registry\n");
        return 1;
    }

    if (add_algorithm(registry, "SHA256", example_hash_function, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to add algorithm\n");
        destroy_registry(registry);
        return 1;
    }

    CryptoAlgorithm *algo;
    if (get_algorithm(registry, "SHA256", &algo) == 0) {
        printf("Found algorithm: %s\n", algo->name);
        algo->implementation();
    } else {
        fprintf(stderr, "Algorithm not found\n");
    }

    destroy_registry(registry);
    return 0;
}
