import java.util.Arrays;

public class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public boolean areDisjoint(int x, int y) {
        return find(x) != find(y);
    }
}

public class DisjointPairsCounter {
    public static int countDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);
        long startTime = System.currentTimeMillis();

        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (uf.areDisjoint(i, j)) {
                    uf.union(i, j);
                }
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " ms");

        return uf.rank[0]; // Assuming the root of the union-find structure represents the count of disjoint pairs
    }

    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5};
        System.out.println("Count of disjoint pairs: " + countDisjointPairs(array));
    }
}
