typedef struct {
    int UE_ID;
    int MME_ID;
    int TAC;
    char SUCI[16];
} LTE_MME_CONNECTION_INFO;

typedef struct {
    LTE_MME_CONNECTION_INFO* connections;
    size_t capacity;
    size_t size;
} ConnectionArray;

void initConnectionArray(ConnectionArray* array, size_t initialCapacity) {
    array->connections = (LTE_MME_CONNECTION_INFO*)malloc(initialCapacity * sizeof(LTE_MME_CONNECTION_INFO));
    if (array->connections == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    array->capacity = initialCapacity;
    array->size = 0;
}

void freeConnectionArray(ConnectionArray* array) {
    free(array->connections);
    array->connections = NULL;
    array->capacity = 0;
    array->size = 0;
}

int insertConnection(ConnectionArray* array, LTE_MME_CONNECTION_INFO newConnection) {
    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity == 0 ? 1 : array->capacity * 2;
        LTE_MME_CONNECTION_INFO* newConnections = (LTE_MME_CONNECTION_INFO*)realloc(array->connections, newCapacity * sizeof(LTE_MME_CONNECTION_INFO));
        if (newConnections == NULL) {
            // Handle memory allocation failure
            return -1;
        }
        array->connections = newConnections;
        array->capacity = newCapacity;
    }

    array->connections[array->size++] = newConnection;
    return 0;
}

int validateConnection(LTE_MME_CONNECTION_INFO connection) {
    if (connection.UE_ID <= 0 || connection.MME_ID <= 0 || connection.TAC < 0 || strlen(connection.SUCI) != 15) {
        return -1; // Invalid fields
    }
    return 0;
}

void logConnection(ConnectionArray* array, int index) {
    if (index >= 0 && index < array->size) {
        // Log the connection details
        printf("Logging connection: UE_ID=%d, MME_ID=%d, TAC=%d, SUCI=%s\n", 
               array->connections[index].UE_ID,
               array->connections[index].MME_ID,
               array->connections[index].TAC,
               array->connections[index].SUCI);
    }
}

int main() {
    ConnectionArray connectionArray;
    initConnectionArray(&connectionArray, 10);

    LTE_MME_CONNECTION_INFO newConnection = {12345, 67890, 123, "1234567890abcdef"};
    if (validateConnection(newConnection) == 0) {
        insertConnection(&connectionArray, newConnection);
        logConnection(&connectionArray, connectionArray.size - 1);
    }

    freeConnectionArray(&connectionArray);
    return 0;
}
