int findLargestInteger(int* arr, int size) {
    if (size == 0) return -1; // Handle empty input
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void populateNFAPICRCIndicationPDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int* inputArray, int size, int seed) {
    srand(seed);
    for (int i = 0; i < size; i++) {
        if (inputArray[i] >= 1 && inputArray[i] <= 65535) { // Valid RNTI range
            pdus[i].RX_UE_INFORMATION_TAG = i + 1;
            pdus[i].RNTI = inputArray[i];
            pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Pseudo-random CRC flag
        } else {
            printf("Warning: Invalid RNTI value encountered and excluded.\n");
        }
    }
}

int executeBackgroundCommand(const char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        wait(&status);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    }
}

int main() {
    int inputArray[MAX_INPUT_SIZE];
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_INPUT_SIZE];

    // Read input
    int size = 0;
    while (scanf("%d", &inputArray[size]) == 1 && size < MAX_INPUT_SIZE) {
        size++;
    }
    if (size >= MAX_INPUT_SIZE) {
        fprintf(stderr, "Error: Input exceeds maximum allowed size.\n");
        return 1;
    }

    // Find largest integer
    int largest = findLargestInteger(inputArray, size);
    printf("Largest Integer: %d\n", largest);

    // Populate NFAPICRCIndicationPDUs
    populateNFAPICRCIndicationPDUs(pdus, inputArray, size, 42); // Example seed

    // Execute background command
    const char* command = "your_command_here";
    int success = executeBackgroundCommand(command);
    printf("Command execution %s\n", success ? "successful" : "failed");

    return 0;
}
