#define MAX_TRANSACTIONS 10000
#define ROLLING_WINDOW_SECONDS 5

typedef struct {
    int id;
    time_t timestamp;
    double amount;
    char type[20];
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    pthread_mutex_t lock;
} TransactionQueue;

TransactionQueue transaction_queue;

void init_transaction_queue() {
    pthread_mutex_init(&transaction_queue.lock, NULL);
}

void enqueue_transaction(Transaction transaction) {
    pthread_mutex_lock(&transaction_queue.lock);
    if (transaction_queue.count < MAX_TRANSACTIONS) {
        transaction_queue.transactions[transaction_queue.count++] = transaction;
    }
    pthread_mutex_unlock(&transaction_queue.lock);
}

Transaction dequeue_transaction() {
    Transaction transaction;
    pthread_mutex_lock(&transaction_queue.lock);
    if (transaction_queue.count > 0) {
        transaction = transaction_queue.transactions[--transaction_queue.count];
    } else {
        // Handle empty queue case
        transaction.id = -1; // Invalid ID to indicate no transaction
    }
    pthread_mutex_unlock(&transaction_queue.lock);
    return transaction;
}

double calculate_max_weighted_sum() {
    double max_weighted_sum = 0.0;
    int max_id = -1;
    for (int i = 0; i < transaction_queue.count; i++) {
        if (transaction_queue.transactions[i].timestamp > time(NULL) - ROLLING_WINDOW_SECONDS) {
            double weighted_sum = transaction_queue.transactions[i].amount * transaction_queue.transactions[i].id;
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_id = transaction_queue.transactions[i].id;
            }
        }
    }
    return max_weighted_sum;
}

int count_transaction_types() {
    int type_counts[10] = {0}; // Assuming up to 10 different types
    for (int i = 0; i < transaction_queue.count; i++) {
        if (transaction_queue.transactions[i].timestamp > time(NULL) - ROLLING_WINDOW_SECONDS) {
            int type_index = hash_type(transaction_queue.transactions[i].type); // Implement hash function
            type_counts[type_index]++;
        }
    }
    return sum_array(type_counts, 10);
}

double calculate_average_amount() {
    double total_amount = 0.0;
    for (int i = 0; i < transaction_queue.count; i++) {
        if (transaction_queue.transactions[i].timestamp > time(NULL) - ROLLING_WINDOW_SECONDS) {
            total_amount += transaction_queue.transactions[i].amount;
        }
    }
    return total_amount / transaction_queue.count;
}

void* process_transactions(void* arg) {
    while (1) {
        Transaction transaction = dequeue_transaction();
        if (transaction.id == -1) {
            break; // No more transactions to process
        }
        if (validate_transaction(transaction)) {
            log_transaction(transaction);
            update_metrics(transaction);
        } else {
            log_error(transaction);
        }
    }
    return NULL;
}

int main() {
    init_transaction_queue();
    pthread_t threads[10]; // Assuming 10 worker threads
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_transactions, NULL);
    }

    // Simulate transaction stream
    for (int i = 0; i < MAX_TRANSACTIONS * ROLLING_WINDOW_SECONDS; i++) {
        Transaction transaction;
        generate_transaction(&transaction); // Implement function to generate transactions
        enqueue_transaction(transaction);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    double max_weighted_sum = calculate_max_weighted_sum();
    int type_count = count_transaction_types();
    double average_amount = calculate_average_amount();

    printf("Max Weighted Sum: %f\n", max_weighted_sum);
    printf("Type Count: %d\n", type_count);
    printf("Average Amount: %f\n", average_amount);

    return 0;
}
