using System;
using System.Collections.Concurrent;
using System.Threading;

public class DynamicRandomNumberManager
{
    private ConcurrentDictionary<int, Random> _randomGenerators;
    private ConcurrentDictionary<int, (double min, double max)> _ranges;
    private object _lockObject = new object();

    public DynamicRandomNumberManager(int initialCapacity)
    {
        _randomGenerators = new ConcurrentDictionary<int, Random>(initialCapacity);
        _ranges = new ConcurrentDictionary<int, (double min, double max)>(initialCapacity);
    }

    public void AddGenerator(int id, int seed, double minRange, double maxRange)
    {
        _randomGenerators.TryAdd(id, new Random(seed));
        _ranges.TryAdd(id, (minRange, maxRange));
    }

    public double GetRandomNumber(int id)
    {
        if (_randomGenerators.TryGetValue(id, out var random) && _ranges.TryGetValue(id, out var range))
        {
            return random.NextDouble() * (range.max - range.min) + range.min;
        }
        throw new ArgumentException("Generator not found.");
    }

    public void UpdateRange(int id, double minRange, double maxRange)
    {
        if (_ranges.TryUpdate(id, (minRange, maxRange), out _))
        {
            // Optionally, reseed the generator to ensure independence
            _randomGenerators[id] = new Random();
        }
        else
        {
            throw new ArgumentException("Generator not found.");
        }
    }

    public void SummarizeState()
    {
        foreach (var kvp in _ranges)
        {
            Console.WriteLine($"Generator {kvp.Key}: Range ({kvp.Value.min}, {kvp.Value.max})");
        }
    }
}
