} CryptoContext;

int initialize_crypto(CryptoContext *ctx, CryptoAlgorithm alg) {
    switch (alg) {
        case ALG_AES:
            ctx->cipher_ctx = EVP_CIPHER_CTX_new();
            if (!ctx->cipher_ctx) return -1;
            break;
        case ALG_CAMELLIA:
            ctx->cipher_ctx = EVP_CIPHER_CTX_new();
            if (!ctx->cipher_ctx) return -1;
            break;
        case ALG_MD5:
            ctx->md_ctx = EVP_MD_CTX_new();
            if (!ctx->md_ctx) return -1;
            break;
        case ALG_SHA:
            ctx->md_ctx = EVP_MD_CTX_new();
            if (!ctx->md_ctx) return -1;
            break;
        case ALG_RSA:
            ctx->rsa_key = RSA_new();
            if (!ctx->rsa_key) return -1;
            break;
        default:
            return -1;
    }
    return 0;
}

void cleanup_crypto(CryptoContext *ctx, CryptoAlgorithm alg) {
    switch (alg) {
        case ALG_AES:
            EVP_CIPHER_CTX_free(ctx->cipher_ctx);
            break;
        case ALG_CAMELLIA:
            EVP_CIPHER_CTX_free(ctx->cipher_ctx);
            break;
        case ALG_MD5:
            EVP_MD_CTX_free(ctx->md_ctx);
            break;
        case ALG_SHA:
            EVP_MD_CTX_free(ctx->md_ctx);
            break;
        case ALG_RSA:
            RSA_free(ctx->rsa_key);
            break;
    }
}

