    switch (alg) {
        case ALG_AES:
            return EVP_EncryptUpdate(ctx->cipher_ctx, out, out_len, in, in_len);
        case ALG_CAMELLIA:
            return Camellia_EncryptUpdate(ctx->cipher_ctx, out, out_len, in, in_len);
        default:
            return -1;
    }
