    switch (alg) {
        case ALG_AES:
            return EVP_DecryptUpdate(ctx->cipher_ctx, out, out_len, in, in_len);
        case ALG_CAMELLIA:
            return Camellia_DecryptUpdate(ctx->cipher_ctx, out, out_len, in, in_len);
        default:
            return -1;
    }
}

int sign_data(CryptoContext *ctx, CryptoAlgorithm alg, const unsigned char *in, size_t in_len, unsigned char *out, size_t *out_len) {
