    switch (alg) {
        case ALG_RSA:
            return RSA_verify(NID_sha1, in, in_len, signature, signature_len, ctx->rsa_key);
        default:
            return -1;
    }
}

int hash_data(CryptoContext *ctx, CryptoAlgorithm alg, const unsigned char *in, size_t in_len, unsigned char *out, size_t *out_len) {
    switch (alg) {
        case ALG_MD5:
            EVP_DigestInit_ex(ctx->md_ctx, EVP_md5(), NULL);
            break;
        case ALG_SHA:
            EVP_DigestInit_ex(ctx->md_ctx, EVP_sha1(), NULL);
            break;
        default:
            return -1;
    }
