#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdlib.h>
#include <string.h>

#define DEFAULT_ITERATIONS 10000

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} AESCipher;

int derive_key(const char *password, size_t password_len, const unsigned char *salt, size_t salt_len, int iterations, unsigned char *key, size_t key_len) {
    return PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iterations, EVP_sha256(), key_len, key);
}

AESCipher* aes_init(const char *password, size_t password_len, const unsigned char *salt, size_t salt_len, int iterations) {
    AESCipher *cipher = (AESCipher*)malloc(sizeof(AESCipher));
    if (!cipher) return NULL;

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        free(cipher);
        return NULL;
    }

    unsigned char key[32];
    if (!derive_key(password, password_len, salt, salt_len, iterations, key, sizeof(key))) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    memcpy(cipher->key, key, sizeof(key));
    memset(cipher->iv, 0, sizeof(cipher->iv)); // Initialize IV to zero for simplicity

    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv) != 1) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void aes_cleanup(AESCipher *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
    }
}
