#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 10000

typedef struct Node {
    int id;
    float weight;
    time_t timestamp;
    struct Node* next[MAX_NODES];
} Node;

Node* graph[MAX_NODES] = {NULL};

void* process_node(void* arg) {
    int node_id = *(int*)arg;
    FILE* file = fopen("node_properties.txt", "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    Node* new_node = malloc(sizeof(Node));
    new_node->id = node_id;
    new_node->weight = 0.0;
    new_node->timestamp = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d %f %ld", &new_node->id, &new_node->weight, &new_node->timestamp) == 3) {
            break;
        }
    }

    fclose(file);

    graph[new_node->id] = new_node;

    return NULL;
}

void process_nodes(int start_id, int end_id) {
    pthread_t threads[MAX_NODES];
    int ids[MAX_NODES];

    for (int i = start_id; i <= end_id; i++) {
        ids[i - start_id] = i;
        pthread_create(&threads[i - start_id], NULL, process_node, &ids[i - start_id]);
    }

    for (int i = 0; i < end_id - start_id + 1; i++) {
        pthread_join(threads[i], NULL);
    }
}

void print_highest_weight_node() {
    float max_weight = 0.0;
    int max_id = -1;

    for (int i = 0; i < MAX_NODES; i++) {
        if (graph[i] != NULL && graph[i]->weight > max_weight) {
            max_weight = graph[i]->weight;
            max_id = graph[i]->id;
        }
    }

    printf("Node with highest weight: %d, Weight: %.2f\n", max_id, max_weight);
}

