#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    int UE_ID;
    int MME_ID;
    int TAC;
    char SUCI[256];
    time_t timestamp;
} LTE_MME_CONNECTION_INFO;

typedef struct {
    LTE_MME_CONNECTION_INFO *connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    time_t timeout;
} ConnectionManager;

void init_connection_manager(ConnectionManager *manager, time_t initial_timeout) {
    manager->connections = (LTE_MME_CONNECTION_INFO *)malloc(MAX_CONNECTIONS * sizeof(LTE_MME_CONNECTION_INFO));
    if (!manager->connections) {
        // Handle memory allocation failure
        return;
    }
    manager->count = 0;
    manager->capacity = MAX_CONNECTIONS;
    pthread_mutex_init(&manager->lock, NULL);
    manager->timeout = initial_timeout;
}

void destroy_connection_manager(ConnectionManager *manager) {
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
}

int add_connection(ConnectionManager *manager, LTE_MME_CONNECTION_INFO *info) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        // Handle capacity exceeded
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->connections[manager->count++] = *info;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void cleanup_inactive_connections(ConnectionManager *manager) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ) {
        if (current_time - manager->connections[i].timestamp > manager->timeout) {
            // Remove inactive connection
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->connections[j] = manager->connections[j + 1];
            }
            --manager->count;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void update_connection_info(ConnectionManager *manager, int UE_ID, LTE_MME_CONNECTION_INFO new_info) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].UE_ID == UE_ID) {
            manager->connections[i] = new_info;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void *cleanup_thread(void *arg) {
    ConnectionManager *manager = (ConnectionManager *)arg;
    while (1) {
        cleanup_inactive_connections(manager);
        sleep(60); // Adjust the interval as needed
    }
    return NULL;
}
