#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int timestamp;
    char sourceIP[16];
    char destinationIP[16];
    int payloadLength;
} NetworkPacket;

typedef struct {
    NetworkPacket* packets;
    size_t count;
    size_t capacity;
} PacketArray;

void initPacketArray(PacketArray* array, size_t initialCapacity) {
    array->packets = (NetworkPacket*)malloc(initialCapacity * sizeof(NetworkPacket));
    if (array->packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initialCapacity;
}

void addPacket(PacketArray* array, NetworkPacket packet) {
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NetworkPacket* newPackets = (NetworkPacket*)realloc(array->packets, newCapacity * sizeof(NetworkPacket));
        if (newPackets == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->packets = newPackets;
        array->capacity = newCapacity;
    }
    array->packets[array->count++] = packet;
}

void updatePacket(PacketArray* array, size_t index, NetworkPacket packet) {
    if (index < array->count) {
        array->packets[index] = packet;
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
}

int calculateTotalDataTransferred(PacketArray* array) {
    int total = 0;
    for (size_t i = 0; i < array->count; ++i) {
        total += array->packets[i].payloadLength;
    }
    return total;
}
