typedef struct {
    int value;
} record;

void* aligned_malloc(size_t size, size_t alignment) {
    void* ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

int initialize_data_structures(long** offsets, int** keys, record*** records, size_t size, size_t alignment, int min_val, int max_val) {
    *offsets = aligned_malloc(size * sizeof(long), alignment);
    if (!*offsets) return -1;

    *keys = aligned_malloc(size * sizeof(int), alignment);
    if (!*keys) {
        free(*offsets);
        return -2;
    }

    *records = aligned_malloc(size * sizeof(record*), alignment);
    if (!*records) {
        free(*keys);
        free(*offsets);
        return -3;
    }

    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = aligned_malloc(sizeof(record), alignment);
        if (!(*records)[i]) {
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*records);
            free(*keys);
            free(*offsets);
            return -4;
        }

        (*offsets)[i] = i * 1024L; // Example offset calculation
        (*keys)[i] = (int)i;

        // Non-blocking random number generation using xorshift
        uint64_t state = time(NULL) + i;
        (*records)[i]->value = ((state ^ (state >> 30)) * 0xbf58476d1ce4e5b9ULL) % (max_val - min_val + 1) + min_val;
    }

    return 0;
}

void cleanup_data_structures(long* offsets, int* keys, record** records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}
