#include <stdlib.h>
#include <semaphore.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int UE_ID;
    int MME_ID;
    int TAC;
    char SUCI[256];
} LTE_MME_CONNECTION_INFO;

typedef struct {
    LTE_MME_CONNECTION_INFO *connections;
    size_t capacity;
    size_t size;
    sem_t semaphore;
} LTE_MME_CONNECTION_MANAGER;

LTE_MME_CONNECTION_MANAGER* create_connection_manager() {
    LTE_MME_CONNECTION_MANAGER *manager = (LTE_MME_CONNECTION_MANAGER*)malloc(sizeof(LTE_MME_CONNECTION_MANAGER));
    if (!manager) return NULL;

    manager->connections = (LTE_MME_CONNECTION_INFO*)calloc(INITIAL_CAPACITY, sizeof(LTE_MME_CONNECTION_INFO));
    if (!manager->connections) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    sem_init(&manager->semaphore, 0, 1); // Initialize semaphore with initial value of 1

    return manager;
}

void destroy_connection_manager(LTE_MME_CONNECTION_MANAGER *manager) {
    if (manager) {
        free(manager->connections);
        sem_destroy(&manager->semaphore);
        free(manager);
    }
}

int add_connection(LTE_MME_CONNECTION_MANAGER *manager, LTE_MME_CONNECTION_INFO info) {
    sem_wait(&manager->semaphore); // Acquire semaphore

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_MME_CONNECTION_INFO *new_connections = (LTE_MME_CONNECTION_INFO*)realloc(manager->connections, new_capacity * sizeof(LTE_MME_CONNECTION_INFO));
        if (!new_connections) {
            sem_post(&manager->semaphore); // Release semaphore
            return -1; // Memory allocation failed
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    manager->connections[manager->size++] = info;

    sem_post(&manager->semaphore); // Release semaphore
    return 0; // Success
}

int validate_connection_info(LTE_MME_CONNECTION_INFO info) {
    // Add validation logic here
    if (info.UE_ID <= 0 || info.MME_ID <= 0 || info.TAC < 0 || strlen(info.SUCI) == 0) {
        return -1; // Invalid connection info
    }
    return 0; // Valid connection info
}
