typedef enum {
    AES,
    DES,
    TRIPLE_DES
} CipherAlgorithm;

typedef enum {
    ECB,
    CBC,
    CFB,
    OFB
} ModeOfOperation;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    CipherAlgorithm algorithm;
    ModeOfOperation mode;
    unsigned char key[32];
    unsigned char iv[16];
} CipherContext;

CipherContext* create_cipher_context(CipherAlgorithm algorithm, ModeOfOperation mode) {
    CipherContext *ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->algorithm = algorithm;
    ctx->mode = mode;
    EVP_CIPHER *cipher = NULL;
    switch (algorithm) {
        case AES: cipher = EVP_aes_256_cbc(); break;
        case DES: cipher = EVP_des_ecb(); break;
        case TRIPLE_DES: cipher = EVP_des3_ede_cbc(); break;
    }
    ctx->ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, NULL, NULL);
    return ctx;
}

void set_key(CipherContext *ctx, const unsigned char *key, int key_len) {
    switch (ctx->algorithm) {
        case AES: memcpy(ctx->key, key, 32); break;
        case DES: memcpy(ctx->key, key, 8); break;
        case TRIPLE_DES: memcpy(ctx->key, key, 24); break;
    }
    EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, ctx->key, ctx->iv);
}

void set_iv(CipherContext *ctx, const unsigned char *iv) {
    memcpy(ctx->iv, iv, 16);
    EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, ctx->key, ctx->iv);
}

void encrypt_data(CipherContext *ctx, const unsigned char *in, int in_len, unsigned char *out) {
    int len;
    EVP_EncryptUpdate(ctx->ctx, out, &len, in, in_len);
    int final_len;
    EVP_EncryptFinal_ex(ctx->ctx, out + len, &final_len);
}

void decrypt_data(CipherContext *ctx, const unsigned char *in, int in_len, unsigned char *out) {
    int len;
    EVP_DecryptUpdate(ctx->ctx, out, &len, in, in_len);
    int final_len;
    EVP_DecryptFinal_ex(ctx->ctx, out + len, &final_len);
}

void destroy_cipher_context(CipherContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
