int allocate_and_initialize(long **offsets, int **keys, record **records, size_t size, size_t alignment) {
    *offsets = aligned_alloc(alignment, sizeof(long) * size);
    if (*offsets == NULL) return -1;

    *keys = aligned_alloc(alignment, sizeof(int) * size);
    if (*keys == NULL) {
        free(*offsets);
        return -2;
    }

    *records = aligned_alloc(alignment, sizeof(record) * size);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3;
    }

    for (size_t i = 0; i < size; ++i) {
        (*keys)[i] = i;
        if (!RAND_bytes((unsigned char *)&((*records)[i].value), sizeof(int))) {
            free(*offsets);
            free(*keys);
            free(*records);
            return -4;
        }
    }

    return 0;
}

void cleanup(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
