import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

public class StringHashProcessor {

    private static final int MAX_THREAD_POOL_SIZE = 10;
    private static final int CHARACTER_LIMIT = 10000;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(MAX_THREAD_POOL_SIZE);
    private static final Logger logger = new Logger();

    public static String processStrings(List<String> strings, boolean enableLogging) throws CustomException {
        long startTime = System.currentTimeMillis();
        List<HashTask> tasks = strings.stream()
                .map(s -> new HashTask(s, enableLogging))
                .collect(Collectors.toList());

        List<String> results = tasks.parallelStream()
                .map(task -> executorService.submit(task))
                .map(future -> {
                    try {
                        return future.get();
                    } catch (Exception e) {
                        logger.logError("Error processing string: " + e.getMessage());
                        throw new CustomException("Failed to process string", e);
                    }
                })
                .collect(Collectors.toList());

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }

        long endTime = System.currentTimeMillis();
        logger.logInfo("Total processing time: " + (endTime - startTime) + " ms");
        return String.join("", results);
    }

    private static class HashTask implements Callable<String> {

        private final String input;
        private final boolean enableLogging;

        public HashTask(String input, boolean enableLogging) {
            this.input = input;
            this.enableLogging = enableLogging;
        }

        @Override
        public String call() throws Exception {
            if (input == null || input.isEmpty()) {
                throw new CustomException("Input string is null or empty");
            }
            if (input.length() > CHARACTER_LIMIT) {
                logger.logWarning("String exceeds character limit: " + input);
            }

            long startTime = System.currentTimeMillis();
            String hash = computeMD5Hash(input);
            long endTime = System.currentTimeMillis();

            if (enableLogging) {
                logger.logInfo("Hash computation time for string: " + (endTime - startTime) + " ms");
            }

            return hash;
        }

        private String computeMD5Hash(String input) throws NoSuchAlgorithmException {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        }
    }

    private static class Logger {

        public void logInfo(String message) {
            System.out.println("INFO: " + message);
        }

        public void logWarning(String message) {
            System.err.println("WARNING: " + message);
        }

        public void logError(String message) {
            System.err.println("ERROR: " + message);
        }
    }

    public static class CustomException extends Exception {

        public CustomException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
