#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float value;
    char name[20];
    struct sub_data *sub;
} data_point;

typedef struct {
    int id;
    double precision;
} sub_data;

void* manage_memory(void* arg) {
    // Function to manage dynamic memory allocation and file reading
    FILE *file = fopen("data.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    size_t num_entries = 0;
    double *double_array = NULL;
    unsigned short *short_array = NULL;
    data_point *data_points = NULL;

    // Read number of entries from the file
    if (fscanf(file, "%zu", &num_entries) != 1) {
        perror("Failed to read number of entries");
        fclose(file);
        return NULL;
    }

    // Allocate memory for arrays
    double_array = malloc(num_entries * sizeof(double));
    short_array = malloc(num_entries * sizeof(unsigned short));
    data_points = malloc(num_entries * sizeof(data_point));

    if (!double_array || !short_array || !data_points) {
        perror("Memory allocation failed");
        free(double_array);
        free(short_array);
        free(data_points);
        fclose(file);
        return NULL;
    }

    // Read data from file
    for (size_t i = 0; i < num_entries; ++i) {
        if (fscanf(file, "%lf %hu %f %s", &double_array[i], &short_array[i],
                   &data_points[i].value, data_points[i].name) != 4) {
            perror("Failed to read data");
            free(double_array);
            free(short_array);
            free(data_points);
            fclose(file);
            return NULL;
        }
    }

    // Allocate memory for sub_data
    for (size_t i = 0; i < num_entries; ++i) {
        data_points[i].sub = malloc(sizeof(sub_data));
        if (!data_points[i].sub) {
            perror("Memory allocation failed");
            for (size_t j = 0; j <= i; ++j) {
                free(data_points[j].sub);
            }
            free(double_array);
            free(short_array);
            free(data_points);
            fclose(file);
            return NULL;
        }
    }

    // Read sub_data from file
    for (size_t i = 0; i < num_entries; ++i) {
        if (fscanf(file, "%d %lf", &data_points[i].sub->id, &data_points[i].sub->precision) != 2) {
            perror("Failed to read sub_data");
            for (size_t j = 0; j <= i; ++j) {
                free(data_points[j].sub);
            }
            free(double_array);
            free(short_array);
            free(data_points);
            fclose(file);
            return NULL;
        }
    }

    // Close file
    fclose(file);

    // Function to manage concurrent access and data integrity
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Perform operations with the allocated memory

    pthread_mutex_unlock(&mutex);

    // Free dynamically allocated memory
    for (size_t i = 0; i < num_entries; ++i) {
        free(data_points[i].sub);
    }
    free(double_array);
    free(short_array);
    free(data_points);

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, manage_memory, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

This code snippet provides a basic structure for managing dynamic memory allocation and file reading in C. It includes error handling for file operations and memory allocation failures. The function `manage_memory` is designed to be executed by a separate thread, ensuring data integrity through the use of a mutex. The code also demonstrates how to allocate and free memory for arrays and structures, including nested structures.

To extend this implementation, you can add more fields to the `struct data_point` or support additional file formats by modifying the reading logic accordingly. The use of dynamic memory allocation and thread safety mechanisms ensures that the function is flexible and robust.']

