#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int userID;
    time_t startTime;
    time_t endTime;
    time_t activityDuration;
} UserSession;

typedef struct {
    UserSession* sessions;
    size_t capacity;
    size_t size;
} SessionManager;

void initSessionManager(SessionManager* manager, size_t initialCapacity) {
    manager->sessions = (UserSession*)malloc(initialCapacity * sizeof(UserSession));
    if (!manager->sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initialCapacity;
    manager->size = 0;
}

void addOrUpdateSession(SessionManager* manager, int userID, time_t startTime, time_t endTime) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i].userID == userID) {
            manager->sessions[i].startTime = startTime;
            manager->sessions[i].endTime = endTime;
            manager->sessions[i].activityDuration = difftime(endTime, startTime);
            return;
        }
    }
    if (manager->size >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        UserSession* newSessions = (UserSession*)realloc(manager->sessions, newCapacity * sizeof(UserSession));
        if (!newSessions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    }
    manager->sessions[manager->size].userID = userID;
    manager->sessions[manager->size].startTime = startTime;
    manager->sessions[manager->size].endTime = endTime;
    manager->sessions[manager->size].activityDuration = difftime(endTime, startTime);
    ++manager->size;
}

void calculateTotalActiveTime(SessionManager* manager) {
    time_t totalActivity = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        totalActivity += manager->sessions[i].activityDuration;
    }
    printf("Total active time across all users: %ld seconds\n", totalActivity);
}

void detectAndMarkInactiveSessions(SessionManager* manager, time_t threshold) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (difftime(time(NULL), manager->sessions[i].startTime) > threshold) {
            // Mark session for cleanup
            printf("Session with user ID %d is inactive and marked for cleanup\n", manager->sessions[i].userID);
        }
    }
}

void freeSessionManager(SessionManager* manager) {
    free(manager->sessions);
    manager->sessions = NULL;
    manager->capacity = 0;
    manager->size = 0;
}
