typedef struct {
    int value;
    long offset;
    int key;
} record;

void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

record* manage_record_storage(const char* config_file, int value_range_start, int value_range_end) {
    json_object* config = json_object_from_file(config_file);
    if (!config) {
        fprintf(stderr, "Failed to parse JSON configuration file\n");
        return NULL;
    }

    json_object* offsets_obj;
    json_object* keys_obj;
    json_object* records_obj;

    if (json_object_object_get_ex(config, "offsets", &offsets_obj) &&
        json_object_object_get_ex(config, "keys", &keys_obj) &&
        json_object_object_get_ex(config, "records", &records_obj)) {

        int offsets_size = json_object_array_length(offsets_obj);
        int keys_size = json_object_array_length(keys_obj);
        int records_size = json_object_array_length(records_obj);

        if (offsets_size != keys_size || offsets_size != records_size) {
            fprintf(stderr, "Configuration error: arrays must be of the same size\n");
            json_object_put(config);
            return NULL;
        }

        record* records = custom_malloc(records_size * sizeof(record));

        for (int i = 0; i < records_size; ++i) {
            json_object* offset_obj = json_object_array_get(offsets_obj, i);
            json_object* key_obj = json_object_array_get(keys_obj, i);
            json_object* record_obj = json_object_array_get(records_obj, i);

            long offset;
            int key;

            if (json_object_is_type(offset_obj, json_type_int) &&
                json_object_is_type(key_obj, json_type_int)) {

                offset = json_object_get_int(offset_obj);
                key = json_object_get_int(key_obj);

                records[i].offset = offset;
                records[i].key = key;

                int value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
                records[i].value = value;
            } else {
                fprintf(stderr, "Configuration error: invalid data type in JSON\n");
                custom_free(records);
                json_object_put(config);
                return NULL;
            }
        }

        json_object_put(config);
        return records;
    } else {
        fprintf(stderr, "Configuration error: missing required fields in JSON\n");
        json_object_put(config);
        return NULL;
    }
}

int main() {
    record* records = manage_record_storage("config.json", 100, 200);
    if (records) {
        // Use the records array
        custom_free(records);
    }
    return 0;
}
```

