#define MAX_PDU_LENGTH 1472

typedef struct {
    uint16_t LCID;
    uint16_t PDU_LENGTH;
} MAC_PDU_HEADER;

typedef struct {
    uint8_t data[127];
} MAC_USER_DATA;

typedef struct {
    MAC_PDU_HEADER header;
    MAC_USER_DATA user_data;
} MAC_Transport_PDU;

int initialize_and_populate_PDUs(MAC_Transport_PDU *pdus, int num_pdus) {
    if (num_pdus <= 0 || pdus == NULL) {
        return -1; // Invalid input
    }

    int total_payload_size = 0;
    for (int i = 0; i < num_pdus; i++) {
        pdus[i].header.LCID = i + 1; // Assign unique LCID
        pdus[i].header.PDU_LENGTH = MIN_PDU_LENGTH + rand() % (MAX_PDU_LENGTH - MIN_PDU_LENGTH);

        if (pdus[i].header.PDU_LENGTH > 127) {
            return -2; // PDU length exceeds MAC_USER_DATA size
        }

        total_payload_size += pdus[i].header.PDU_LENGTH;
        if (total_payload_size > MAX_PAYLOAD_SIZE) {
            return -3; // Total payload size exceeds limit
        }

        // Dynamically generate payload data
        for (int j = 0; j < pdus[i].header.PDU_LENGTH; j++) {
            pdus[i].user_data.data[j] = rand() % 256;
        }
    }

    return 0; // Success
}

int main() {
    const int num_pdus = 10;
    MAC_Transport_PDU pdus[num_pdus];

    if (initialize_and_populate_PDUs(pdus, num_pdus) == 0) {
        printf("PDUs initialized and populated successfully.\n");
    } else {
        printf("Failed to initialize and populate PDUs.\n");
    }

    return 0;
}
