#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <pthread.h>

#define MAX_QUERIES 500
#define CACHE_SIZE 1024
#define TTL 1800 // 30 minutes in seconds

typedef struct {
    char hostname[256];
    u_char ip[4];
    time_t expire_time;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

int dns_resolve(const char *hostname, u_char *ip) {
    // Check cache
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0 && time(NULL) < cache[i].expire_time) {
            memcpy(ip, cache[i].ip, 4);
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    // Rate limiting
    static int query_count = 0;
    static struct timeval last_query_time = {0};
    struct timeval current_time;
    gettimeofday(&current_time, NULL);
    if (query_count >= 10 && (current_time.tv_sec - last_query_time.tv_sec) < 1) {
        return -EAGAIN; // Too many queries
    }
    query_count++;
    last_query_time = current_time;

    // Perform DNS resolution
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        return -1; // DNS resolution failed
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip, &(ipv4->sin_addr), 4);

    // Update cache
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].expire_time == 0) {
            strcpy(cache[i].hostname, hostname);
            memcpy(cache[i].ip, ip, 4);
            cache[i].expire_time = time(NULL) + TTL;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    freeaddrinfo(res);
    return 0;
}

int main() {
    u_char ip[4];
    int result = dns_resolve("example.com", ip);
    if (result == 0) {
        printf("IP address: %d.%d.%d.%d\n", ip[0], ip[1], ip[2], ip[3]);
    } else {
        printf("Error: %d\n", result);
    }
    return 0;
}
