import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

public class CSVIntegerProcessor {

    private static final String DIRECTORY_PATH = "path/to/directory";
    private static final String CHECKSUM_FILE = "checksum.txt";
    private static final int CACHE_SIZE = 100;

    private Map<Integer, Integer> cache = new ConcurrentHashMap<>();
    private ExecutorService executor = Executors.newSingleThreadExecutor();
    private Path directoryPath;
    private Path checksumFilePath;

    public CSVIntegerProcessor() {
        this.directoryPath = Paths.get(DIRECTORY_PATH);
        this.checksumFilePath = Paths.get(DIRECTORY_PATH, CHECKSUM_FILE);
        loadIntegersFromCSV();
        startDirectoryMonitor();
    }

    private void loadIntegersFromCSV() {
        Path csvFile = directoryPath.resolve("integers.csv");
        if (Files.exists(csvFile)) {
            try (BufferedReader reader = Files.newBufferedReader(csvFile)) {
                String line;
                while ((line = reader.readLine()) != null) {
                    int number = Integer.parseInt(line.trim());
                    cache.put(number, number);
                }
            } catch (IOException e) {
                System.err.println("Error reading CSV file: " + e.getMessage());
            }
        }
    }

    private void startDirectoryMonitor() {
        executor.submit(() -> {
            try {
                WatchService watcher = FileSystems.getDefault().newWatchService();
                directoryPath.register(watcher, StandardWatchEventKinds.ENTRY_MODIFY);

                while (true) {
                    WatchKey key;
                    try {
                        key = watcher.take();
                    } catch (InterruptedException e) {
                        return;
                    }

                    for (WatchEvent<?> event : key.pollEvents()) {
                        if (event.context().toString().equals("integers.csv")) {
                            loadIntegersFromCSV();
                        }
                    }

                    boolean valid = key.reset();
                    if (!valid) {
                        break;
                    }
                }
            } catch (IOException e) {
                System.err.println("Error starting directory monitor: " + e.getMessage());
            }
        });
    }

    private void verifyChecksum() {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] fileBytes = Files.readAllBytes(checksumFilePath);
            byte[] computedChecksum = md.digest(fileBytes);

            Path checksumFile = directoryPath.resolve(CHECKSUM_FILE);
            if (!Files.exists(checksumFile)) {
                System.err.println("Checksum file not found.");
                return;
            }

            byte[] storedChecksum = Files.readAllBytes(checksumFile);
            if (!Arrays.equals(computedChecksum, storedChecksum)) {
                Files.deleteIfExists(directoryPath.resolve("integers.csv"));
                System.err.println("Checksum mismatch. File deleted for further investigation.");
            }
        } catch (IOException | NoSuchAlgorithmException e) {
            System.err.println("Error verifying checksum: " + e.getMessage());
        }
    }

    public int findLargestInteger() {
        verifyChecksum();
        return cache.values().stream().max(Integer::compare).orElseThrow(NoSuchElementException::new);
    }

    public static void main(String[] args) {
        CSVIntegerProcessor processor = new CSVIntegerProcessor();
        System.out.println("Largest integer: " + processor.findLargestInteger());
    }
}
