    MYSQL *conn;
    MYSQL_RES *res;
    MYSQL_ROW row;
    NFAPI_CRC_INDICATION_PDU_T* reports = NULL;
    int report_count = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        conn = mysql_init(NULL);
        if (!mysql_real_connect(conn, host_url, username, password, "nfadb", 0, NULL, 0)) {
            fprintf(stderr, "%s\n", mysql_error(conn));
            mysql_close(conn);
            continue;
        }

        char query[256];
        snprintf(query, sizeof(query), "SELECT employee_name, city, address FROM employees WHERE supervisor_id = %d", supervisor_id);

        if (mysql_query(conn, query)) {
            fprintf(stderr, "%s\n", mysql_error(conn));
            mysql_close(conn);
            continue;
        }

        res = mysql_use_result(conn);
        if (res == NULL) {
            fprintf(stderr, "%s\n", mysql_error(conn));
            mysql_close(conn);
            continue;
        }

        while ((row = mysql_fetch_row(res)) != NULL) {
            EmployeeReportData* report_data = malloc(sizeof(EmployeeReportData));
