            reports = realloc(reports, (report_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            reports[report_count++] = *report;
        }

        mysql_free_result(res);
        mysql_close(conn);

        break; // Success
    }

    return reports;
}

int main() {
