#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define MAX_IP_SIZE 16
#define CACHE_LIMIT 1024

typedef struct {
    char hostname[256];
    u_char ip[MAX_IP_SIZE];
} DNSCacheEntry;

DNSCacheEntry cache[CACHE_LIMIT];
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* dns_lookup(void* arg) {
    char* hostname = (char*)arg;
    struct addrinfo hints, *res, *p;
    int status;
    u_char ip[MAX_IP_SIZE];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        printf("  %s\n", ipstr);

        // Copy the IP address to the output buffer
        memcpy(ip, addr, INET6_ADDRSTRLEN);
    }

    freeaddrinfo(res);

    return (void*)ip;
}

int main() {
    char hostname[] = "example.com";
    u_char* result;

    pthread_t thread;
    if (pthread_create(&thread, NULL, dns_lookup, hostname) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, (void**)&result);

    // Use the result as needed
    printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr*)result));

    return 0;
}
```

