            if ($this->isStrongPassword($newPassword)) {
                $transaction = $this->db->beginTransaction();
                try {
                    $stmt = $this->db->prepare("UPDATE users SET password = :password WHERE id = :id");
                    $stmt->execute([':password' => password_hash($newPassword, PASSWORD_DEFAULT), ':id' => $userId]);
                    $transaction->commit();
                    return "Password updated successfully.";
                } catch (Exception $e) {
                    $transaction->rollBack();
                    return "Failed to update password: " . $e->getMessage();
                }
            } else {
                return "New password does not meet the strength requirements.";
            }
        } else {
            return "Invalid session or old password.";
