import subprocess
import requests
from cryptography.fernet import Fernet
import logging
import os
import hashlib

# Initialize logging
logging.basicConfig(filename='config_update.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def fetch_latest_kickstart(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        logging.error(f"Failed to fetch Kickstart file: {e}")
        raise

def encrypt_password(password, key):
    fernet = Fernet(key)
    encrypted_password = fernet.encrypt(password.encode())
    return encrypted_password.decode()

def update_kickstart(file_path, params, password, line_number=None):
    with open(file_path, 'r') as file:
        lines = file.readlines()

    for placeholder, value in params.items():
        if placeholder not in lines:
            logging.warning(f"Placeholder {placeholder} not found in Kickstart file.")
            continue
        lines[lines.index(placeholder)] = f"{value}\n"

    if password:
        key = Fernet.generate_key()
        encrypted_password = encrypt_password(password, key)
        if line_number is not None and 0 <= line_number < len(lines):
            lines.insert(line_number, f"ENCRYPTED_PASSWORD={encrypted_password}\n")
        else:
            lines.append(f"ENCRYPTED_PASSWORD={encrypted_password}\n")

    with open(file_path, 'w') as file:
        file.writelines(lines)

def apply_changes(file_path, params, password, line_number=None):
    try:
        update_kickstart(file_path, params, password, line_number)
        logging.info(f"Configuration updated successfully in {file_path}")
    except Exception as e:
        logging.error(f"Failed to update configuration: {e}")

# Example usage
params = {
    "PLACEHOLDER1": "value1",
    "PLACEHOLDER2": "value2"
}
password = "my_secure_password"
line_number = 5

apply_changes("path/to/kickstart.ks", params, password, line_number)
