#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef enum {
    ALG_DES,
    ALG_AES
} EncryptionAlgorithm;

typedef enum {
    MODE_ECB,
    MODE_CBC,
    MODE_CFB,
    MODE_GCM
} EncryptionMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[24];
    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
} CipherInstance;

CipherInstance* create_cipher_instance(EncryptionAlgorithm alg, EncryptionMode mode, const unsigned char *key, size_t key_size) {
    CipherInstance *cipher = (CipherInstance*)malloc(sizeof(CipherInstance));
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }
    switch (alg) {
        case ALG_DES:
            if (mode == MODE_ECB) {
                EVP_EncryptInit_ex(cipher->ctx, EVP_des_ecb(), NULL, key, NULL);
            } else if (mode == MODE_CFB) {
                EVP_EncryptInit_ex(cipher->ctx, EVP_des_cfb8(), NULL, key, NULL);
            }
            break;
        case ALG_AES:
            switch (key_size) {
                case 16:
                    if (mode == MODE_ECB) {
                        EVP_EncryptInit_ex(cipher->ctx, EVP_aes_128_ecb(), NULL, key, NULL);
                    } else if (mode == MODE_CBC) {
                        EVP_EncryptInit_ex(cipher->ctx, EVP_aes_128_cbc(), NULL, key, NULL);
                    } else if (mode == MODE_CFB) {
                        EVP_EncryptInit_ex(cipher->ctx, EVP_aes_128_cfb8(), NULL, key, NULL);
                    }
                    break;
                case 32:
                    if (mode == MODE_ECB) {
                        EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_ecb(), NULL, key, NULL);
                    } else if (mode == MODE_CBC) {
                        EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, key, NULL);
                    } else if (mode == MODE_CFB) {
                        EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cfb8(), NULL, key, NULL);
                    }
                    break;
                default:
                    fprintf(stderr, "Unsupported AES key size\n");
                    EVP_CIPHER_CTX_free(cipher->ctx);
                    free(cipher);
                    return NULL;
            }
            break;
        default:
            fprintf(stderr, "Unsupported encryption algorithm\n");
            EVP_CIPHER_CTX_free(cipher->ctx);
            free(cipher);
            return NULL;
    }
    memcpy(cipher->key, key, key_size);
    if (mode == MODE_CBC) {
        if (!RAND_bytes(cipher->iv, EVP_MAX_BLOCK_LENGTH)) {
            fprintf(stderr, "Failed to generate IV\n");
            EVP_CIPHER_CTX_free(cipher->ctx);
            free(cipher);
            return NULL;
        }
    }
    return cipher;
}

void encrypt_data(CipherInstance *cipher, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    int len;
    if (!EVP_EncryptUpdate(cipher->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption failed\n");
        return;
    }
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(cipher->ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Encryption finalization failed\n");
        return;
    }
    ciphertext_len += len;
}

void decrypt_data(CipherInstance *cipher, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    int len;
    if (!EVP_DecryptUpdate(cipher->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Decryption failed\n");
        return;
    }
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(cipher->ctx, plaintext + len, &len)) {
        fprintf(stderr, "Decryption finalization failed\n");
        return;
    }
    plaintext_len += len;
}

void free_cipher_instance(CipherInstance *cipher) {
    EVP_CIPHER_CTX_free(cipher->ctx);
    free(cipher);
}
