#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int Request_ID;
    int Status_Code;
    char Response_Body[1024];
    int ErrorFlag;
} HTTP_RESPONSE_PDU_T;

HTTP_RESPONSE_PDU_T* create_http_pdu(int request_id, int status_code, const char* response_body) {
    HTTP_RESPONSE_PDU_T* pdu = (HTTP_RESPONSE_PDU_T*)malloc(sizeof(HTTP_RESPONSE_PDU_T));
    if (pdu == NULL) {
        return NULL;
    }
    pdu->Request_ID = request_id;
    pdu->Status_Code = status_code;
    strcpy(pdu->Response_Body, response_body);
    pdu->ErrorFlag = 0;
    return pdu;
}

void free_http_pdu(HTTP_RESPONSE_PDU_T* pdu) {
    if (pdu != NULL) {
        free(pdu);
    }
}

int add_to_list(HTTP_RESPONSE_PDU_T** list, int* size, HTTP_RESPONSE_PDU_T* new_pdu) {
    for (int i = 0; i < *size; i++) {
        if (list[i]->Request_ID == new_pdu->Request_ID) {
            return -1; // Duplicate Request-ID
        }
    }
    list[*size] = new_pdu;
    (*size)++;
    return 0;
}

void serialize_list(HTTP_RESPONSE_PDU_T** list, int size, FILE* file) {
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        fwrite(list[i], sizeof(HTTP_RESPONSE_PDU_T), 1, file);
    }
}

void deserialize_list(HTTP_RESPONSE_PDU_T** list, int* size, FILE* file) {
    fread(size, sizeof(int), 1, file);
    for (int i = 0; i < *size; i++) {
        HTTP_RESPONSE_PDU_T* pdu = (HTTP_RESPONSE_PDU_T*)malloc(sizeof(HTTP_RESPONSE_PDU_T));
        fread(pdu, sizeof(HTTP_RESPONSE_PDU_T), 1, file);
        list[i] = pdu;
    }
}

void free_list(HTTP_RESPONSE_PDU_T** list, int size) {
    for (int i = 0; i < size; i++) {
        free_http_pdu(list[i]);
    }
    free(list);
}
