import pickle

class HTTPResponsePDU:
    def __init__(self, request_id, status_code, response_body):
        self.request_id = request_id
        self.status_code = status_code
        self.response_body = response_body
        self.error_flag = 0

def add_to_list(http_pdu_list, new_pdu):
    for pdu in http_pdu_list:
        if pdu.request_id == new_pdu.request_id:
            return -1  # Duplicate Request-ID
    http_pdu_list.append(new_pdu)
    return 0

def serialize_list(http_pdu_list, filename):
    with open(filename, 'wb') as file:
        pickle.dump(http_pdu_list, file)

def deserialize_list(filename):
    with open(filename, 'rb') as file:
        return pickle.load(file)

def free_list(http_pdu_list):
    for pdu in http_pdu_list:
        del pdu
