import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class PokemonReportGenerator {
    private static final Logger LOGGER = Logger.getLogger(PokemonReportGenerator.class.getName());
    private static final Map<String, TypeData> typeCache = new ConcurrentHashMap<>();
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private static final String API_URL = "https://api.pokemontcg.io/v2/types";

    public static void generateReports(List<Pokemon> pokemons) {
        for (Pokemon pokemon : pokemons) {
            CompletableFuture.runAsync(() -> processPokemon(pokemon), executorService)
                    .exceptionally(ex -> {
                        LOGGER.log(Level.SEVERE, "Error processing Pokemon: " + pokemon.getName(), ex);
                        return null;
                    });
        }
    }

    private static void processPokemon(Pokemon pokemon) {
        try {
            String name = fetchNameFromCacheOrAPI(pokemon.getId());
            TypeData typeData = getTypeData(pokemon.getType());

            StringBuilder report = new StringBuilder();
            report.append("Name: ").append(name).append("\n");
            report.append("Type: ").append(pokemon.getType()).append("\n");
            report.append("Weaknesses: ").append(String.join(", ", typeData.getWeaknesses())).append("\n");
            report.append("Resistances: ").append(String.join(", ", typeData.getResistances())).append("\n");
            report.append("Immunities: ").append(String.join(", ", typeData.getImmunities())).append("\n");

            double effectiveness = calculateEffectiveness(typeData, Arrays.asList("Fire", "Water"));
            report.append("Effectiveness against Fire/Water: ").append(effectiveness).append("\n");

            LOGGER.info(report.toString());
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error processing Pokemon: " + pokemon.getName(), e);
        }
    }

    private static String fetchNameFromCacheOrAPI(String id) throws Exception {
        // Simulate fetching from cache or API
        return typeCache.computeIfAbsent(id, key -> {
            try {
                // Fetch from API
                return fetchNameFromAPI(key);
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Failed to fetch name for Pokemon ID: " + id, e);
                return "Unknown";
            }
        });
    }

    private static String fetchNameFromAPI(String id) throws Exception {
        // Simulate API call
        Thread.sleep(100); // Simulate network delay
        return "Pokemon" + id;
    }

    private static TypeData getTypeData(String type) throws Exception {
        return typeCache.computeIfAbsent(type, key -> {
            try {
                // Fetch from external API
                return fetchTypeDataFromAPI(key);
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Failed to fetch type data for: " + key, e);
                return new TypeData(new ArrayList<>(), new ArrayList<>(), new ArrayList<>());
            }
        });
    }

    private static TypeData fetchTypeDataFromAPI(String type) throws Exception {
        // Simulate API call
        Thread.sleep(100); // Simulate network delay
        return new TypeData(Arrays.asList("Water"), Arrays.asList("Fire"), Collections.emptyList());
    }

    private static double calculateEffectiveness(TypeData typeData, List<String> types) {
        double effectiveness = 1.0;
        for (String type : types) {
            if (typeData.getWeaknesses().contains(type)) {
                effectiveness *= 2.0;
            } else if (typeData.getResistances().contains(type)) {
                effectiveness /= 2.0;
            }
        }
        return effectiveness;
    }

    static class TypeData {
        private List<String> weaknesses;
        private List<String> resistances;
        private List<String> immunities;

        public TypeData(List<String> weaknesses, List<String> resistances, List<String> immunities) {
            this.weaknesses = weaknesses;
            this.resistances = resistances;
            this.immunities = immunities;
        }

        public List<String> getWeaknesses() {
            return weaknesses;
        }

        public List<String> getResistances() {
            return resistances;
        }

        public List<String> getImmunities() {
            return immunities;
        }
    }

    static class Pokemon {
        private String id;
        private String type;

        public Pokemon(String id, String type) {
            this.id = id;
            this.type = type;
        }

        public String getId() {
            return id;
        }

        public String getType() {
            return type;
        }

        public String getName() {
            return "Pokemon" + id; // Simulated name
        }
    }
}
