#define MAX_N 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_indication_pdu(int N, int seed) {
    if (N <= 0 || N > MAX_N) {
        fprintf(stderr, "Invalid value for N. Must be between 1 and %d.\n", MAX_N);
        return NULL;
    }

    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    int unique_tags[MAX_N] = {0};
    int allocated_count = 0;

    for (int i = 0; i < N; ++i) {
        int tag;
        do {
            tag = rand() % MAX_N + 1;
        } while (unique_tags[tag - 1]);

        unique_tags[tag - 1] = 1;
        array[i].RX_UE_INFORMATION_TAG = tag;
        array[i].RNTI = rand() % 65536; // Random RNTI value
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG (0 or 1)

        allocated_count++;
    }

    printf("Successfully allocated %d structures.\n", allocated_count);
    return array;
}

void free_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array) {
        free(array);
    }
}

int main() {
    int N = 500;
    int seed = 42;

    NFAPI_CRC_INDICATION_PDU_T* array = allocate_nfaapi_crc_indication_pdu(N, seed);
    if (array) {
        // Use the allocated array for further processing
        free_nfaapi_crc_indication_pdu(array, N);
    }

    return 0;
}
