typedef struct {
    int user_id;
    time_t start_time;
    time_t end_time;
    time_t total_activity_duration;
} UserSession;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *nfapi_pdu;
    UserSession sessions[MAX_SESSIONS];
    int session_count;
    pthread_mutex_t mutex;
} SessionManager;

void init_session_manager(SessionManager *manager) {
    manager->nfapi_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->session_count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void add_or_update_session(SessionManager *manager, int user_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->session_count; i++) {
        if (manager->sessions[i].user_id == user_id) {
            time_t current_time = time(NULL);
            manager->sessions[i].end_time = current_time;
            manager->sessions[i].total_activity_duration += (current_time - manager->sessions[i].start_time);
            manager->sessions[i].start_time = current_time;
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }
    if (manager->session_count < MAX_SESSIONS) {
        UserSession new_session = {user_id, time(NULL), 0, 0};
        manager->sessions[manager->session_count++] = new_session;
    } else {
        printf("Maximum sessions reached.\n");
    }
    pthread_mutex_unlock(&manager->mutex);
}

void calculate_total_activity_time(SessionManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    time_t total_activity = 0;
    for (int i = 0; i < manager->session_count; i++) {
        total_activity += manager->sessions[i].total_activity_duration;
    }
    printf("Total activity time: %ld seconds\n", total_activity);
    pthread_mutex_unlock(&manager->mutex);
}

void detect_and_cleanup_inactive_sessions(SessionManager *manager, int idle_threshold) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->session_count; i++) {
        time_t current_time = time(NULL);
        if ((current_time - manager->sessions[i].end_time) > idle_threshold) {
            printf("Cleaning up inactive session for user %d\n", manager->sessions[i].user_id);
            // Implement cleanup logic here
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void *session_manager_thread(void *arg) {
    SessionManager *manager = (SessionManager *)arg;
    while (1) {
        add_or_update_session(manager, rand() % 100); // Simulate user activity
        calculate_total_activity_time(manager);
        detect_and_cleanup_inactive_sessions(manager, IDLE_THRESHOLD);
        sleep(5); // Simulate periodic checks
    }
    return NULL;
}

int main() {
    SessionManager manager;
    init_session_manager(&manager);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, session_manager_thread, &manager);

    pthread_join(thread_id, NULL);

    free(manager.nfapi_pdu);
    return 0;
}
