#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_memory(long *offsets, int *keys, record **records, long offset_size, int key_length, int range_start, int range_end) {
    srand(time(NULL));

    for (long i = 0; i < offset_size; i++) {
        offsets[i] = rand() % (1024 * 1024); // Example size
    }

    char *key_string = generate_random_string(key_length);
    if (!key_string) {
        fprintf(stderr, "Failed to generate key string\n");
        return;
    }

    for (int i = 0; i < key_length; i++) {
        keys[i] = key_string[i];
    }
    free(key_string);

    *records = malloc(offset_size * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    for (long i = 0; i < offset_size; i++) {
        (*records)[i].value = rand() % (range_end - range_start + 1) + range_start;
    }
}

char *generate_random_string(int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *str = malloc(length + 1);
    if (!str) return NULL;

    for (int i = 0; i < length; i++) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length] = '\0';

    return str;
}

void free_memory(long *offsets, int *keys, record *records, long offset_size) {
    free(offsets);
    free(keys);
    free(records);
}
