void* initialize_data_structures(size_t num_records, size_t max_value) {
    if (num_records == 0 || max_value <= 0) {
        return NULL;
    }

    long* offsets = malloc(num_records * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    int* ids = malloc(num_records * sizeof(int));
    if (!ids) {
        free(offsets);
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        free(offsets);
        free(ids);
        return NULL;
    }

    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        free(offsets);
        free(ids);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * 1024L; // Example initialization
        ids[i] = i + 1;

        int random_value;
        do {
            random_value = rand() % max_value;
        } while (random_value == 0); // Ensure non-zero value

        records[i].value = random_value;
    }

    // Log initialization details
    printf("Initialized %zu offsets, %zu ids, and %zu records.\n", num_records, num_records, num_records);

    return records;
}

void free_data_structures(void* data) {
    if (data) {
        Record* records = (Record*)data;
        free(records);
    }
}
