#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_QUERIES 5
#define CACHE_SIZE 10
#define BACKOFF_FACTOR 2
#define MAX_BACKOFF_SECONDS 60

typedef struct {
    char hostname[NI_MAXHOST];
    char ip[INET6_ADDRSTRLEN];
    time_t expiration;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int concurrent_queries = 0;
pthread_mutex_t query_lock = PTHREAD_MUTEX_INITIALIZER;

void* dns_query_thread(void* arg) {
    char* hostname = (char*)arg;
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        // save the result in cache
        pthread_mutex_lock(&cache_lock);
        for (int i = 0; i < CACHE_SIZE; i++) {
            if (strcmp(cache[i].hostname, hostname) == 0) {
                strcpy(cache[i].ip, ipstr);
                cache[i].expiration = time(NULL) + 10;
                break;
            }
        }
        pthread_mutex_unlock(&cache_lock);

        freeaddrinfo(res); // all done with this structure
        return NULL;
    }

    freeaddrinfo(res); // all done with this structure
    return NULL;
}

int resolve_dns(const char* hostname) {
    if (concurrent_queries >= MAX_CONCURRENT_QUERIES) {
        printf("Too many concurrent queries\n");
        return -1;
    }

    pthread_mutex_lock(&query_lock);
    concurrent_queries++;
    pthread_mutex_unlock(&query_lock);

    pthread_t thread_id;
    int status = pthread_create(&thread_id, NULL, dns_query_thread, (void*)hostname);
    if (status != 0) {
        printf("Error creating thread\n");
        return -1;
    }

    pthread_join(thread_id, NULL);

    pthread_mutex_lock(&query_lock);
    concurrent_queries--;
    pthread_mutex_unlock(&query_lock);

    return 0;
}

int main() {
    resolve_dns("example.com");
    return 0;
}
```

This code provides a basic structure for a DNS resolver with caching and concurrency control. It uses POSIX threads to manage concurrent queries and a simple cache mechanism to store resolved IP addresses. The `resolve_dns` function handles the creation of threads for each query, ensuring that no more than `MAX_CONCURRENT_QUERIES` are running at once. The cache is updated with the results of successful DNS queries, and entries expire after 10 seconds. This example does not include error handling for network interruptions or DNS server unavailability, nor does it implement a backoff strategy or a sophisticated logging system. These features would need to be added based on specific requirements and testing.']

