typedef struct {
    char* name;
    struct timeval schedule_time;
    int priority;
} task;

task* create_task_queue(int size) {
    task* queue = (task*)malloc(size * sizeof(task));
    if (queue == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return queue;
}

void free_task_queue(task* queue, int size) {
    for (int i = 0; i < size; i++) {
        free(queue[i].name);
    }
    free(queue);
}

char* generate_job_name(int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* name = (char*)malloc((length + 1) * sizeof(char));
    if (name == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < length; i++) {
        name[i] = charset[rand() % strlen(charset)];
    }
    name[length] = '\0';
    return name;
}

void measure_execution_time(void (*func)(), int size) {
    struct timeval start, end;
    gettimeofday(&start, NULL);
    func(size);
    gettimeofday(&end, NULL);
    long seconds = end.tv_sec - start.tv_sec;
    long microseconds = end.tv_usec - start.tv_usec;
    printf("Execution time: %ld.%06ld seconds\n", seconds, microseconds);
}

void simulate_job_scheduling(int size) {
    task* queue = create_task_queue(size);
    for (int i = 0; i < size; i++) {
        queue[i].name = generate_job_name(10);
        gettimeofday(&queue[i].schedule_time, NULL);
        queue[i].priority = rand() % 5;
    }
    free_task_queue(queue, size);
}

int main() {
    srand(time(NULL));
    measure_execution_time(simulate_job_scheduling, 1000);
    return 0;
}
