typedef struct Record {
    int key;
    time_t timestamp;
    long offset;
} Record;

typedef struct HashTable {
    Record** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record* record = table->buckets[i];
        if (record) {
            free(record);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(int key, size_t capacity) {
    return abs(key) % capacity;
}

Record* find_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    Record* record = table->buckets[index];

    while (record && record->key != key) {
        record = NULL; // Key not found
    }

    pthread_mutex_unlock(&table->lock);
    return record;
}

void insert_record(HashTable* table, int key, time_t timestamp, long offset) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);

    if (table->buckets[index]) {
        // Handle collision, e.g., chaining or open addressing
        printf("Collision handling not implemented\n");
    } else {
        Record* new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            pthread_mutex_unlock(&table->lock);
            return; // Allocation failure
        }

        new_record->key = key;
        new_record->timestamp = timestamp;
        new_record->offset = offset;

        table->buckets[index] = new_record;
        ++table->size;
    }

    pthread_mutex_unlock(&table->lock);
}

void update_timestamp(HashTable* table, int key, time_t new_timestamp) {
    Record* record = find_record(table, key);
    if (record) {
        pthread_mutex_lock(&table->lock);
        record->timestamp = new_timestamp;
        pthread_mutex_unlock(&table->lock);
    }
}
