#include <semaphore.h>

#define MAX_LOG_STREAMS 2000

typedef struct {
    char *data;
    int size;
} LogEntry;

typedef struct {
    LogEntry logs[MAX_LOG_STREAMS];
    sem_t log_count;
    pthread_mutex_t lock;
} LogQueue;

void init_log_queue(LogQueue *queue) {
    sem_init(&queue->log_count, 0, 0);
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue_log(LogQueue *queue, char *data, int size) {
    pthread_mutex_lock(&queue->lock);
    queue->logs[sem_wait(&queue->log_count)].data = data;
    queue->logs[sem_wait(&queue->log_count)].size = size;
    sem_post(&queue->log_count);
    pthread_mutex_unlock(&queue->lock);
}

void *process_logs(void *arg) {
    LogQueue *queue = (LogQueue *)arg;
    while (1) {
        int index = sem_wait(&queue->log_count);
        if (index < 0) break; // Exit thread on error
        pthread_mutex_lock(&queue->lock);
        char *data = queue->logs[index].data;
        int size = queue->logs[index].size;
        // Process log data here
        printf("Processing log of size %d\n", size);
        free(data); // Free allocated memory for log data
        sem_post(&queue->log_count);
        pthread_mutex_unlock(&queue->lock);
    }
    return NULL;
}

int main() {
    LogQueue queue;
    init_log_queue(&queue);

    pthread_t threads[MAX_LOG_STREAMS];
    for (int i = 0; i < MAX_LOG_STREAMS; i++) {
        pthread_create(&threads[i], NULL, process_logs, &queue);
    }

    // Simulate log data processing
    for (int i = 0; i < 1000; i++) {
        char *log_data = malloc(1024); // Allocate memory for log data
        int size = sprintf(log_data, "Log entry %d", i);
        enqueue_log(&queue, log_data, size);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_LOG_STREAMS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
