    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $characters[rand(0, strlen($characters) - 1)];
    }
    return $randomString;
}

function hashInput($input, $algorithm = 'sha256') {
    return hash($algorithm, $input);
