function encryptWithCDES($data, $key, $mode = 'ECB') {
    if (empty($key)) {
        return $data; // Null encryption
    }

    $desModes = ['ECB', 'EDE', 'EDE3', 'CFB'];
    if (!in_array($mode, $desModes)) {
        throw new Exception("Unsupported DES mode: $mode");
    }

    $encryptedData = '';
    for ($i = 0; $i < strlen($data); $i += 8) {
        $block = substr($data, $i, 8);
        $encryptedBlock = openssl_encrypt($block, "DES-$mode", $key, OPENSSL_RAW_DATA);
        $encryptedData .= $encryptedBlock;
    }

    return base64_encode($encryptedData);
}

function decryptWithCDES($encryptedData, $key, $mode = 'ECB') {
    if (empty($key)) {
        return $encryptedData; // Null encryption
    }

    $desModes = ['ECB', 'EDE', 'EDE3', 'CFB'];
    if (!in_array($mode, $desModes)) {
        throw new Exception("Unsupported DES mode: $mode");
    }

    $encryptedData = base64_decode($encryptedData);
    $decryptedData = '';
    for ($i = 0; $i < strlen($encryptedData); $i += 8) {
        $block = substr($encryptedData, $i, 8);
        $decryptedBlock = openssl_decrypt($block, "DES-$mode", $key, OPENSSL_RAW_DATA);
        $decryptedData .= $decryptedBlock;
    }

    return $decryptedData;
}

