        fprintf(stderr, "Invalid input: N must be between 1 and 1000.\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indications == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(seed);
    int uniqueTags[1000] = {0};
    int tagCount = 0;

    for (int i = 0; i < N; ++i) {
        while (uniqueTags[tagCount]) {
            tagCount++;
        }
        indications[i].RX_UE_INFORMATION_TAG = tagCount;
        uniqueTags[tagCount++] = 1;

        indications[i].RNTI = rand() % 1000 + 1;
        indications[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return indications;
}
