import java.util.Arrays;

public class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public boolean areDisjoint(int x, int y) {
        return find(x) != find(y);
    }
}

public class Main {
    public static void main(String[] args) {
        UnionFind uf = new UnionFind(1000);

        long startTime = System.currentTimeMillis();
        for (int i = 0; i < 999; i++) {
            uf.union(i, i + 1);
        }
        long endTime = System.currentTimeMillis();

        System.out.println("Time taken to compute disjoint pairs: " + (endTime - startTime) + " ms");
    }

    public static int countDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);

        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (uf.areDisjoint(array[i], array[j])) {
                    uf.union(array[i], array[j]);
                }
            }
        }

        return uf.parent[0];
    }
}
