    printf("Error: %s\n", message);
}

Status validate_param1(int value, int min, int max) {
    if (value < min || value > max) {
        return INVALID_PARAM;
    }
    return SUCCESS;
}

Status validate_param2(const char* str, size_t max_length) {
    if (str == NULL || strlen(str) > max_length) {
        return INVALID_PARAM;
    }
    return SUCCESS;
}

Status validate_param3(double value, double min, double max) {
    if (value < min || value > max) {
        return INVALID_PARAM;
    }
    return SUCCESS;
}

Config* init_config(int param1, const char* param2, double param3, int min_param1, int max_param1, size_t max_param2_length, double min_param3, double max_param3) {
    Config* config = (Config*)malloc(sizeof(Config));
    if (config == NULL) {
        log_error("Failed to allocate memory for configuration");
        return NULL;
    }

    Status status = validate_param1(param1, min_param1, max_param1);
    if (status != SUCCESS) {
        free(config);
        log_error("Invalid param1 value");
        return NULL;
    }

    config->param1 = param1;

    status = validate_param2(param2, max_param2_length);
    if (status != SUCCESS) {
        free(config);
        log_error("Invalid param2 value");
        return NULL;
    }

    config->param2 = strdup(param2);
    if (config->param2 == NULL) {
        free(config);
        log_error("Failed to allocate memory for param2");
        return NULL;
    }

    status = validate_param3(param3, min_param3, max_param3);
    if (status != SUCCESS) {
        free(config->param2);
        free(config);
        log_error("Invalid param3 value");
        return NULL;
    }

    config->param3 = param3;

    return config;
}

void destroy_config(Config* config) {
    if (config == NULL) {
        return;
    }
    free(config->param2);
    free(config);
}
