    for (int i = 0; i < MAX_KEYS; i++) {
        cipher_pool[i] = malloc(sizeof(CipherInstance));
    }
}

CipherInstance* get_cipher_instance() {
    if (pool_index >= MAX_KEYS) {
        return NULL;
    }
    return cipher_pool[pool_index++];
}

void release_cipher_instance(CipherInstance* instance) {
    pool_index--;
    cipher_pool[pool_index] = instance;
}

