    DES_key_schedule schedule;
    if (DES_set_key((const_DES_cblock*)key, &schedule) != 0) {
        return -1;
    }
    for (int i = 0; i < length; i += DES_KEY_LENGTH) {
        DES_ecb_encrypt((const_DES_cblock*)(plaintext + i), (DES_cblock*)(ciphertext + i), &schedule, DES_ENCRYPT);
    }
    return 0;
}

