typedef struct {
    time_t timestamp;
    char sourceIP[16];
    char destinationIP[16];
    int payloadLength;
    char protocolType[10];
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t count;
    size_t capacity;
} PacketArray;

void initPacketArray(PacketArray *array) {
    array->count = 0;
    array->capacity = 16;
    array->packets = (NetworkPacket *)malloc(array->capacity * sizeof(NetworkPacket));
}

void freePacketArray(PacketArray *array) {
    free(array->packets);
    array->count = 0;
    array->capacity = 0;
}

void addPacket(PacketArray *array, NetworkPacket packet) {
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->packets = (NetworkPacket *)realloc(array->packets, array->capacity * sizeof(NetworkPacket));
    }
    array->packets[array->count++] = packet;
}

void updatePacket(PacketArray *array, size_t index, NetworkPacket newPacket) {
    if (index < array->count) {
        array->packets[index] = newPacket;
    }
}

double calculateTotalDataTransferred(PacketArray *array) {
    double totalData = 0.0;
    for (size_t i = 0; i < array->count; ++i) {
        totalData += array->packets[i].payloadLength;
    }
    return totalData;
}

void simulateNetworkConditions(PacketArray *array, double packetDropProbability) {
    srand(time(NULL));
    for (size_t i = 0; i < array->count; ++i) {
        if ((double)rand() / RAND_MAX < packetDropProbability) {
            // Simulate packet loss
            printf("Packet dropped at index %zu\n", i);
        }
    }
}

void logMetrics(PacketArray *array, double packetLossRate, int retransmissionCount) {
    printf("Total data transferred: %.2f bytes\n", calculateTotalDataTransferred(array));
    printf("Packet loss rate: %.2f%%\n", packetLossRate * 100);
    printf("Retransmission count: %d\n", retransmissionCount);
}

