#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long timestamp;
    long offset;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(size, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = size;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_record(HashTable* table, Record record) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(record.key, table->size);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    new_node->data = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);
}

Record* retrieve_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->size);
    Node* current = table->buckets[index];

    while (current) {
        if (current->data.key == key) {
            Record* result = (Record*)malloc(sizeof(Record));
            if (!result) {
                pthread_mutex_unlock(&table->lock);
                return NULL;
            }
            *result = current->data;
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->size);
    Node* current = table->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (current->data.key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                table->buckets[index] = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
}

void compact_database(HashTable* table) {
    // Implement compaction logic here
}

size_t hash_function(int key, size_t size) {
    return (key % size);
}

int main() {
    HashTable* table = create_hash_table(100);
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    Record record = {1, 1633072800, 12345};
    insert_record(table, record);

    Record* retrieved_record = retrieve_record(table, 1);
    if (retrieved_record) {
        printf("Retrieved record: key=%d, timestamp=%ld, offset=%ld\n", 
               retrieved_record->key, retrieved_record->timestamp, retrieved_record->offset);
        free(retrieved_record);
    }

    delete_record(table, 1);

    compact_database(table);

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);

    return 0;
}
