    int SessionID;
    int ConnectionStatus;
    NetworkPacket *Packets;
    int NumPackets;
    pthread_mutex_t mutex;
} NetworkSession;

typedef struct NetworkManager {
    NetworkSession **Sessions;
    int NumSessions;
    int BandwidthLimit;
    pthread_mutex_t sessionsMutex;
} NetworkManager;

NetworkManager* createNetworkManager(int initialCapacity, int bandwidthLimit) {
    NetworkManager *manager = (NetworkManager*)malloc(sizeof(NetworkManager));
    manager->Sessions = (NetworkSession**)malloc(initialCapacity * sizeof(NetworkSession*));
    manager->NumSessions = 0;
    manager->BandwidthLimit = bandwidthLimit;
    pthread_mutex_init(&manager->sessionsMutex, NULL);
    return manager;
}

void addSession(NetworkManager *manager, int sessionID) {
    pthread_mutex_lock(&manager->sessionsMutex);
    if (manager->NumSessions >= initialCapacity) {
        // Resize the sessions array
        NetworkSession **newSessions = (NetworkSession**)realloc(manager->Sessions, 2 * initialCapacity * sizeof(NetworkSession*));
        manager->Sessions = newSessions;
    }
    NetworkSession *session = (NetworkSession*)malloc(sizeof(NetworkSession));
    session->SessionID = sessionID;
    session->ConnectionStatus = 1; // Assuming active
    session->Packets = NULL;
    session->NumPackets = 0;
    pthread_mutex_init(&session->mutex, NULL);
    manager->Sessions[manager->NumSessions++] = session;
    pthread_mutex_unlock(&manager->sessionsMutex);
}

void addPacketToSession(NetworkManager *manager, int sessionID, NetworkPacket packet) {
    pthread_mutex_lock(&manager->sessionsMutex);
    for (int i = 0; i < manager->NumSessions; i++) {
        if (manager->Sessions[i]->SessionID == sessionID) {
            pthread_mutex_lock(&manager->Sessions[i]->mutex);
            // Check and handle packet fragmentation
            if (packet.PacketSize > manager->BandwidthLimit) {
                int numPackets = (packet.PacketSize + manager->BandwidthLimit - 1) / manager->BandwidthLimit;
                for (int j = 0; j < numPackets; j++) {
                    NetworkPacket newPacket;
                    newPacket.SequenceNumber = packet.SequenceNumber + j;
                    newPacket.PacketSize = (j == numPackets - 1) ? packet.PacketSize % manager->BandwidthLimit : manager->BandwidthLimit;
                    memcpy(newPacket.Payload, packet.Payload + j * manager->BandwidthLimit, newPacket.PacketSize);
                    // Add the new packet to the session
                }
            } else {
                // Add the packet to the session
            }
            pthread_mutex_unlock(&manager->Sessions[i]->mutex);
            break;
        }
    }
    pthread_mutex_unlock(&manager->sessionsMutex);
}

void iterateOverPackets(NetworkManager *manager, int sessionID) {
    pthread_mutex_lock(&manager->sessionsMutex);
    for (int i = 0; i < manager->NumSessions; i++) {
        if (manager->Sessions[i]->SessionID == sessionID) {
            pthread_mutex_lock(&manager->Sessions[i]->mutex);
            // Iterate over packets in the session
            for (int j = 0; j < manager->Sessions[i]->NumPackets; j++) {
                NetworkPacket packet = manager->Sessions[i]->Packets[j];
                // Process the packet
            }
            pthread_mutex_unlock(&manager->Sessions[i]->mutex);
            break;
        }
    }
    pthread_mutex_unlock(&manager->sessionsMutex);
}

void destroyNetworkManager(NetworkManager *manager) {
    for (int i = 0; i < manager->NumSessions; i++) {
        free(manager->Sessions[i]);
    }
    free(manager->Sessions);
    pthread_mutex_destroy(&manager->sessionsMutex);
    free(manager);
