#define TABLE_SIZE 1024

typedef struct Record {
    int key;
    time_t timestamp;
    long offset;
} Record;

typedef struct HashNode {
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(TABLE_SIZE, sizeof(HashNode*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_record(HashTable* table, Record record) {
    pthread_mutex_lock(&table->lock);
    int index = abs(record.key % TABLE_SIZE);
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    pthread_mutex_unlock(&table->lock);
}

Record* find_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    int index = abs(key % TABLE_SIZE);
    HashNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->record.key == key) {
            Record* result = &node->record;
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    int index = abs(key % TABLE_SIZE);
    HashNode* node = table->buckets[index];
    HashNode* prev = NULL;
    while (node != NULL) {
        if (node->record.key == key) {
            if (prev == NULL) {
                table->buckets[index] = node->next;
            } else {
                prev->next = node->next;
            }
            free(node);
            break;
        }
        prev = node;
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
}

