void manage_resource(NFAPI_CRC_INDICATION_PDU_T** resources, int* count, const char* identifier, const char* request_body, int operation) {
    for (int i = 0; i < *count; i++) {
        if (strcmp(resources[i]->ue_info.identifier, identifier) == 0) {
            if (operation == PUT) {
                // Perform HTTP PUT operation with request_body
