#include <json-c/json.h>

#define MAX_RECORDS 1024

typedef struct {
    int value;
    long offset;
    int key;
} Record;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    size_t count;
} CRC_Indication_System;

int parse_json(const char *filename, Record records[], size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open JSON file");
        return -1;
    }

    struct json_object *parsed_json;
    parsed_json = json_tokener_parse_file(file);
    fclose(file);

    if (!parsed_json) {
        fprintf(stderr, "Error parsing JSON\n");
        return -1;
    }

    struct json_object *long_array, *int_array, *record_array;
    if (json_object_object_get_ex(parsed_json, "long_array", &long_array) &&
        json_object_object_get_ex(parsed_json, "int_array", &int_array) &&
        json_object_object_get_ex(parsed_json, "record_array", &record_array)) {

        size_t long_count = json_object_array_length(long_array);
        size_t int_count = json_object_array_length(int_array);
        size_t record_count = json_object_array_length(record_array);

        if (record_count > MAX_RECORDS) {
            fprintf(stderr, "Too many records\n");
            return -1;
        }

        for (size_t i = 0; i < record_count; ++i) {
            struct json_object *record_obj = json_object_array_get_idx(record_array, i);
            struct json_object *value_obj, *offset_obj, *key_obj;

            if (json_object_object_get_ex(record_obj, "value", &value_obj) &&
                json_object_object_get_ex(record_obj, "offset", &offset_obj) &&
                json_object_object_get_ex(record_obj, "key", &key_obj)) {

                records[i].value = json_object_get_int(value_obj);
                records[i].offset = json_object_get_long(offset_obj);
                records[i].key = json_object_get_int(key_obj);

                if (records[i].offset >= long_count || records[i].key >= int_count) {
                    fprintf(stderr, "Invalid offset or key\n");
                    return -1;
                }
            } else {
                fprintf(stderr, "Missing field in record\n");
                return -1;
            }
        }

        *count = record_count;
        json_object_put(parsed_json);
        return 0;
    } else {
        fprintf(stderr, "Missing array in JSON\n");
        json_object_put(parsed_json);
        return -1;
    }
}

CRC_Indication_System* create_crc_indication_system(const char *filename) {
    Record records[MAX_RECORDS];
    size_t count;

    if (parse_json(filename, records, &count) != 0) {
        return NULL;
    }

    CRC_Indication_System *system = malloc(sizeof(CRC_Indication_System));
    if (!system) {
        perror("Failed to allocate memory for system");
        return NULL;
    }

    system->records = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!system->records) {
        perror("Failed to allocate memory for records");
        free(system);
        return NULL;
    }

    system->count = count;

    for (size_t i = 0; i < count; ++i) {
        // Populate NFAPI_CRC_INDICATION_PDU_T structure
        // Example:
        // system->records[i].rx_ue_information_tag = records[i].key;
        // system->records[i].rnti = records[i].value;
        // system->records[i].crc_indication_rel8_tag.crcflag = rand() % 2; // Random CRC flag
    }

    return system;
}

void destroy_crc_indication_system(CRC_Indication_System *system) {
    free(system->records);
    free(system);
}
