fn create_directory_with_env_var(dir_name: &str) -> Result<(), String> {
    if let Some(env_dir) = env::var_os("MY_DIRECTORY_ENV_VAR") {
        let env_path = Path::new(&env_dir);
        if !env_path.exists() || !env_path.is_dir() {
            return Err(format!("Environment variable path does not exist or is not a directory: {:?}", env_path));
        }
        Ok(())
    } else {
        let mut builder = DirBuilder::new();
        builder.recursive(true);
        match builder.create(dir_name) {
            Ok(_) => {
                env::set_var("MY_DIRECTORY_ENV_VAR", dir_name);
                Ok(())
            },
            Err(e) => Err(format!("Failed to create directory: {:?}", e)),
        }
    }
}

fn populate_nfaapi_crc_indication_pdu_list(n: usize) -> Result<Vec<NFAPI_CRC_INDICATION_PDU_T>, String> {
    let mut rng = rand::thread_rng();
    let dir_name = "my_directory";

    if let Err(e) = create_directory_with_env_var(dir_name) {
        return Err(e);
    }

    let pdu_list: Vec<NFAPI_CRC_INDICATION_PDU_T> = (0..n).map(|_| {
        NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag: RX_UE_INFORMATION_TAG { /* Initialize fields */ },
            rnti: rng.gen(),
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag: rng.gen() },
        }
    }).collect();

    Ok(pdu_list)
}

