#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <random>
#include <chrono>

// Mock logging function
void logEvent(const std::string& message) {
    // Simulate logging to a centralized service
    std::cout << "Log: " << message << std::endl;
}

class AttackStrategy {
public:
    virtual void execute() = 0;
};

class StrategyA : public AttackStrategy {
public:
    void execute() override {
        logEvent("Executing Strategy A");
        // Simulate attack logic
    }
};

class StrategyB : public AttackStrategy {
public:
    void execute() override {
        logEvent("Executing Strategy B");
        // Simulate attack logic
    }
};

class GameCharacter {
private:
    std::mutex bufferMutex;
    std::condition_variable inputReady;
    std::queue<int> inputBuffer;
    int largestInteger = INT_MIN;
    bool isAttacking = false;
    std::chrono::time_point<std::chrono::system_clock> lastAttackTime;

public:
    void processInput() {
        while (true) {
            int value;
            std::cin >> value;
            if (value == -1) break; // Assuming -1 as the end-of-input marker

            std::unique_lock<std::mutex> lock(bufferMutex);
            inputBuffer.push(value);
            largestInteger = std::max(largestInteger, value);
            inputReady.notify_one();
        }
    }

    void executeAttack() {
        while (true) {
            std::unique_lock<std::mutex> lock(bufferMutex);
            inputReady.wait(lock, [this] { return !inputBuffer.empty(); });

            int value = inputBuffer.front();
            inputBuffer.pop();

            if (!isAttacking && std::chrono::system_clock::now() - lastAttackTime >= std::chrono::seconds(9)) {
                isAttacking = true;
                lastAttackTime = std::chrono::system_clock::now();

                std::random_device rd;
                std::mt19937 gen(rd());
                std::uniform_int_distribution<> dis(0, 1);
                int strategyChoice = dis(gen);

                AttackStrategy* strategy = nullptr;
                if (strategyChoice == 0) {
                    strategy = new StrategyA();
                } else {
                    strategy = new StrategyB();
                }

                try {
                    strategy->execute();
                } catch (const std::exception& e) {
                    logEvent("Error executing attack: " + std::string(e.what()));
                }

                delete strategy;
                isAttacking = false;
            }
        }
    }
};

int main() {
    GameCharacter character;
    std::thread inputThread(&GameCharacter::processInput, &character);
    std::thread attackThread(&GameCharacter::executeAttack, &character);

    inputThread.join();
    attackThread.join();

    return 0;
}
