        Camellia camellia(key);
        camellia.decrypt(data);
    }
}

std::string CryptoLibrary::computeHash(const std::string& data) const {
    SHA256 sha256;
    sha256.update(reinterpret_cast<const unsigned char*>(data.c_str()), data.size());
    return sha256.digest();
}

bool CryptoLibrary::verifySignature(const std::string& publicKey, const std::string& data, const std::string& signature) const {
    RSA rsa(publicKey, "");
    return rsa.verify(data, signature);
}

