#include <openssl/pem.h>
#include <openssl/kdf.h>
#include <pthread.h>

#define SALT_LEN 16
#define IV_LEN 12

typedef struct {
    unsigned char key[32];
    unsigned char iv[IV_LEN];
} AESKeyIV;

AESKeyIV* init_aes_256_gcm(const char* password, int iteration_count) {
    AESKeyIV* key_iv = malloc(sizeof(AESKeyIV));
    if (!key_iv) return NULL;

    unsigned char salt[SALT_LEN];
    if (!RAND_bytes(salt, SALT_LEN)) {
        free(key_iv);
        return NULL;
    }

    EVP_KDF* kdf = EVP_KDF_fetch(NULL, "PBKDF2", NULL);
    if (!kdf) {
        free(key_iv);
        return NULL;
    }

    EVP_KDF_CTX* ctx = EVP_KDF_CTX_new(kdf);
    if (!ctx) {
        EVP_KDF_free(kdf);
        free(key_iv);
        return NULL;
    }

    EVP_KDF_set_params(ctx, EVP_PKEY_KEYLEN(32), EVP_PKEY_ITER(iteration_count),
                       EVP_PKEY_SALT(salt), SALT_LEN);

    unsigned char derived_key[32];
    size_t derived_len = 0;
    if (!EVP_KDF_derive(ctx, derived_key, sizeof(derived_key), &derived_len)) {
        EVP_KDF_CTX_free(ctx);
        EVP_KDF_free(kdf);
        free(key_iv);
        return NULL;
    }

    memcpy(key_iv->key, derived_key, sizeof(key_iv->key));
    EVP_KDF_CTX_free(ctx);
    EVP_KDF_free(kdf);

    if (!RAND_bytes(key_iv->iv, IV_LEN)) {
        free(key_iv);
        return NULL;
    }

    return key_iv;
}

void free_aes_key_iv(AESKeyIV* key_iv) {
    free(key_iv);
}
