    node->data = data;
    node->next = node->prev = NULL;
    return node;
}

void insert_doubly_linked_list(Node **head, Record *record) {
    Node *new_node = create_node(record);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *last = *head;
        while (last->next != NULL)
            last = last->next;
        last->next = new_node;
        new_node->prev = last;
