    if (node != NULL) {
        free_record(node->data);
        free_node(node->next);
        free(node);
    }
}

void free_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node *current = ht->buckets[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free_node(temp);
        }
    }
    free(ht->buckets);
    free(ht);
}

