#define MAX_RECORDS 1024

typedef struct {
    int value;
    long offset;
    int key;
} Record;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T records[MAX_RECORDS];
    int record_count;
} CRC_Indication_System;

int parse_json_config(const char *filename, Record **records, int *record_count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open JSON config file");
        return -1;
    }

    struct json_object *parsed_json;
    parsed_json = json_tokener_parse_file(file);
    fclose(file);

    if (!parsed_json) {
        fprintf(stderr, "Error parsing JSON\n");
        return -1;
    }

    struct json_object *long_offsets, *int_keys, *record_array;
    if (json_object_object_get_ex(parsed_json, "long_offsets", &long_offsets) &&
        json_object_object_get_ex(parsed_json, "int_keys", &int_keys) &&
        json_object_object_get_ex(parsed_json, "records", &record_array)) {

        int num_records = json_object_array_length(record_array);
        if (num_records > MAX_RECORDS) {
            fprintf(stderr, "Too many records\n");
            return -1;
        }

        *record_count = num_records;
        *records = malloc(num_records * sizeof(Record));
        if (!*records) {
            perror("Failed to allocate memory for records");
            json_object_put(parsed_json);
            return -1;
        }

        for (int i = 0; i < num_records; i++) {
            struct json_object *record_obj = json_object_array_get_idx(record_array, i);
            struct json_object *value_obj, *offset_obj, *key_obj;

            if (json_object_object_get_ex(record_obj, "value", &value_obj) &&
                json_object_object_get_ex(record_obj, "offset", &offset_obj) &&
                json_object_object_get_ex(record_obj, "key", &key_obj)) {

                (*records)[i].value = json_object_get_int(value_obj);
                (*records)[i].offset = json_object_get_long(offset_obj);
                (*records)[i].key = json_object_get_int(key_obj);
            } else {
                fprintf(stderr, "Invalid record format\n");
                free(*records);
                *records = NULL;
                return -1;
            }
        }

        json_object_put(parsed_json);
        return 0;
    } else {
        fprintf(stderr, "Missing required JSON fields\n");
        json_object_put(parsed_json);
        return -1;
    }
}

CRC_Indication_System* initialize_crc_indication_system(const char *config_file) {
    Record *records = NULL;
    int record_count = 0;

    if (parse_json_config(config_file, &records, &record_count) != 0) {
        fprintf(stderr, "Failed to parse JSON config file\n");
        return NULL;
    }

    CRC_Indication_System *system = malloc(sizeof(CRC_Indication_System));
    if (!system) {
        perror("Failed to allocate memory for CRC Indication System");
        free(records);
        return NULL;
    }

    system->record_count = record_count;
    memcpy(system->records, records, record_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    free(records);
    return system;
}

void cleanup_crc_indication_system(CRC_Indication_System *system) {
    if (system) {
        free(system);
    }
}
