#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

#define MAX_RECORDS 1024

typedef struct {
    long offset;
    int key;
    NFAPI_CRC_INDICATION_PDU_T record;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int size;
    pthread_mutex_t lock;
} RecordStorage;

void initialize_record_storage(RecordStorage *storage, const char *config_file) {
    json_object *config = json_read_file(config_file);
    if (!config) {
        fprintf(stderr, "Failed to read configuration file\n");
        return;
    }

    int long_offset_size = json_object_get_int(json_object_object_get(config, "long_offset_size"));
    int int_key_size = json_object_get_int(json_object_object_get(config, "int_key_size"));

    storage->size = 0;
    pthread_mutex_init(&storage->lock, NULL);

    // Initialize records with random values within specified ranges
    for (int i = 0; i < long_offset_size; i++) {
        Record record;
        record.offset = rand() % 1000000L;
        record.key = rand() % int_key_size;

        // Populate NFAPI_CRC_INDICATION_PDU_T structure with random values
        record.record.RX_UE_INFORMATION_TAG = rand();
        record.record.RNTI = rand();
        record.record.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? true : false;

        pthread_mutex_lock(&storage->lock);
        storage->records[storage->size++] = record;
        pthread_mutex_unlock(&storage->lock);
    }

    json_object_put(config);
}

void *record_storage_thread(void *arg) {
    RecordStorage *storage = (RecordStorage *)arg;
    // Simulate concurrent access and processing of records
    for (int i = 0; i < storage->size; i++) {
        pthread_mutex_lock(&storage->lock);
        NFAPI_CRC_INDICATION_PDU_T record = storage->records[i];
        pthread_mutex_unlock(&storage->lock);

        // Process the record
        printf("Processing record with RNTI: %d, CRCFLAG: %s\n", record.RNTI, (record.CRC_INDICATION_REL8_TAG.CRCFLAG) ? "true" : "false");
    }
    return NULL;
}

int main() {
    RecordStorage storage;
    initialize_record_storage(&storage, "config.json");

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, record_storage_thread, &storage);
    pthread_create(&thread2, NULL, record_storage_thread, &storage);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
