#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* deserialize_nfaapi_crc_indication_pdu(const char* filename, size_t* num_objects) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t num_bytes_to_read = (size_t)file_size;
    NFAPI_CRC_INDICATION_PDU_T* objects = malloc(num_bytes_to_read);
    if (!objects) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(objects, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_bytes_to_read / sizeof(NFAPI_CRC_INDICATION_PDU_T), file);
    if (bytes_read != num_bytes_to_read / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        perror("Failed to read file");
        free(objects);
        fclose(file);
        return NULL;
    }

    *num_objects = bytes_read;

    // Handle endianness and alignment issues
    for (size_t i = 0; i < *num_objects; ++i) {
        objects[i].RX_UE_INFORMATION_TAG = ntohl(objects[i].RX_UE_INFORMATION_TAG);
        objects[i].RNTI = ntohs(objects[i].RNTI);
        // CRC_INDICATION_REL8_TAG is a single byte, no need to swap
    }

    fclose(file);
