typedef struct LogBuffer {
    LogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer, size_t initial_capacity) {
    buffer->capacity = initial_capacity;
    buffer->count = 0;
    buffer->entries = (LogEntry *)malloc(initial_capacity * sizeof(LogEntry));
    pthread_mutex_init(&buffer->lock, NULL);
}

void free_log_buffer(LogBuffer *buffer) {
    pthread_mutex_destroy(&buffer->lock);
    free(buffer->entries);
}

void add_log_entry(LogBuffer *buffer, LogEntry entry) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->count >= buffer->capacity) {
        buffer->capacity *= 2;
        buffer->entries = (LogEntry *)realloc(buffer->entries, buffer->capacity * sizeof(LogEntry));
    }
    buffer->entries[buffer->count++] = entry;
    pthread_mutex_unlock(&buffer->lock);
}

