        return;
    }

    *data_array = (data*)malloc(num_elements * sizeof(data));
    if (*data_array == NULL) {
        free(*double_ptr);
        free(*char_ptr);
        fprintf(stderr, "Error: Failed to allocate memory for data array.\n");
        return;
    }

