        maxSessions *= 2;
        sessions = realloc(sessions, maxSessions * sizeof(UserSession));
        if (!sessions) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
    sessions[sessionCount].userID = userID;
    sessions[sessionCount].startTime = startTime;
    sessions[sessionCount].endTime = 0;
    sessions[sessionCount].activityDuration = 0;
    sessionCount++;
}

void updateSession(int userID, time_t endTime) {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i].userID == userID && sessions[i].endTime == 0) {
            sessions[i].endTime = endTime;
            sessions[i].activityDuration = difftime(endTime, sessions[i].startTime);
            return;
        }
    }
}

void manageInactiveSessions(time_t inactivityThreshold) {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i].endTime != 0 && difftime(sessions[i].endTime, time(NULL)) > inactivityThreshold) {
            printf("Marking session for cleanup: UserID %d\n", sessions[i].userID);
            // Implement cleanup logic here
        }
    }
}

