typedef struct {
    char* buffer;
    int value;
    int ref_count;
} custom_record;

void init_custom_record(custom_record* record, const char* input, int val) {
    record->buffer = strdup(input);
    record->value = val;
    record->ref_count = 1;
}

void free_custom_record(custom_record* record) {
    if (record->buffer != NULL) {
        free(record->buffer);
        record->buffer = NULL;
    }
    record->value = 0;
    record->ref_count = 0;
}

void increment_ref_count(custom_record* record) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    record->ref_count++;
    pthread_mutex_unlock(&mutex);
}

void decrement_ref_count(custom_record* record, void (*free_func)(custom_record*)) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    if (--record->ref_count == 0) {
        free_func(record);
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    long offsets[10];
    int keys[10];
    custom_record records[10];

    // Example usage
    for (int i = 0; i < 10; i++) {
        init_custom_record(&records[i], "example", i);
        offsets[i] = i * sizeof(long);
        keys[i] = i;
    }

    // Simulate concurrent access and deallocation
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, (void*)increment_ref_count, &records[i]);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < 10; i++) {
        decrement_ref_count(&records[i], free_custom_record);
    }

    return 0;
}
