#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NFAPIS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_NFAPIS];
    int count;
    pthread_mutex_t lock;
} NFAPILibrary;

NFAPILibrary* create_library() {
    NFAPILibrary* lib = (NFAPILibrary*)malloc(sizeof(NFAPILibrary));
    if (!lib) return NULL;
    lib->count = 0;
    pthread_mutex_init(&lib->lock, NULL);
    return lib;
}

void destroy_library(NFAPILibrary* lib) {
    pthread_mutex_destroy(&lib->lock);
    free(lib);
}

int insert_nfaapi(NFAPILibrary* lib, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&lib->lock);
    if (lib->count >= MAX_NFAPIS) {
        pthread_mutex_unlock(&lib->lock);
        return -1; // Library is full
    }
    lib->data[lib->count++] = pdu;
    pthread_mutex_unlock(&lib->lock);
    return 0;
}

int delete_nfaapi(NFAPILibrary* lib, int RNTI) {
    pthread_mutex_lock(&lib->lock);
    for (int i = 0; i < lib->count; i++) {
        if (lib->data[i].RNTI == RNTI) {
            memmove(&lib->data[i], &lib->data[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (lib->count - i - 1));
            lib->count--;
            pthread_mutex_unlock(&lib->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return -1; // RNTI not found
}

NFAPI_CRC_INDICATION_PDU_T* get_nfaapi(NFAPILibrary* lib, int RNTI) {
    pthread_mutex_lock(&lib->lock);
    for (int i = 0; i < lib->count; i++) {
        if (lib->data[i].RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T* result = &lib->data[i];
            pthread_mutex_unlock(&lib->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return NULL; // RNTI not found
}

int http_put(NFAPILibrary* lib, int identifier, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&lib->lock);
    for (int i = 0; i < lib->count; i++) {
        if (lib->data[i].RNTI == identifier) {
            lib->data[i] = new_data;
            pthread_mutex_unlock(&lib->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return -1; // Identifier not found
}

int http_delete(NFAPILibrary* lib, int identifier) {
    return delete_nfaapi(lib, identifier);
}
