        free(ds);
        free(d);
        return NULL;
    }
    snprintf(ds->buffer, 1024, "Random data: %d", rand());
    ds->ptr = (int*)malloc(sizeof(int));
    if (!ds->ptr) {
        perror("Failed to allocate memory for int pointer");
        free(ds->buffer);
        free(ds);
        free(d);
        return NULL;
    }
    *ds->ptr = rand();

    // Simulate reading from file
    FILE* fp = fopen("data.txt", "r");
    if (!fp) {
        perror("Failed to open file for reading");
        free(ds->ptr);
        free(ds->buffer);
        free(ds);
        free(d);
        return NULL;
    }
    int file_data;
    fscanf(fp, "%d", &file_data);
    fclose(fp);

    // Simulate writing to file
    fp = fopen("output.txt", "w");
    if (!fp) {
        perror("Failed to open file for writing");
        free(ds->ptr);
        free(ds->buffer);
        free(ds);
        free(d);
        return NULL;
    }
    fprintf(fp, "Processed data: %d\n", *ds->ptr + file_data);
    fclose(fp);

    // Free allocated memory
    free(ds->ptr);
    free(ds->buffer);
    free(ds);
    free(d);

    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, thread_func, NULL) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("All threads completed.\n");

    return EXIT_SUCCESS;
}
