#include <json-c/json.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
} CipherConfig;

CipherConfig* configure_cipher(const char *file_path, const char *option) {
    CipherConfig *config = (CipherConfig *)malloc(sizeof(CipherConfig));
    if (!config) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    config->ctx = EVP_CIPHER_CTX_new();
    if (!config->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(config);
        return NULL;
    }

    json_object *json_obj = json_object_from_file(file_path);
    if (!json_obj) {
        fprintf(stderr, "Failed to load JSON configuration file\n");
        EVP_CIPHER_CTX_free(config->ctx);
        free(config);
        return NULL;
    }

    const char *cipher_name = json_object_get_string(json_object_object_get(json_obj, option));
    config->cipher = EVP_get_cipherbyname(cipher_name);
    if (!config->cipher) {
        fprintf(stderr, "Invalid cipher name: %s\n", cipher_name);
        json_object_put(json_obj);
        EVP_CIPHER_CTX_free(config->ctx);
        free(config);
        return NULL;
    }

    int rc = EVP_EncryptInit_ex(config->ctx, config->cipher, NULL, NULL, NULL);
    if (!rc) {
        fprintf(stderr, "Failed to initialize cipher\n");
        json_object_put(json_obj);
        EVP_CIPHER_CTX_free(config->ctx);
        free(config);
        return NULL;
    }

    json_object_put(json_obj);

    // Log configuration details
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    printf("Cipher configured at %s with option: %s\n", timestamp, option);

    return config;
}

void cleanup_cipher(CipherConfig *config) {
    if (config->ctx) {
        EVP_CIPHER_CTX_free(config->ctx);
    }
    free(config);
}
