#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 1024

typedef struct {
    int timestamp;
    char source_ip[16];
    char destination_ip[16];
    int payload_length;
    int status; // 0 for inactive, 1 for active
} Packet;

Packet* packet_array[MAX_PACKETS];
int packet_count = 0;

void add_packet(int timestamp, const char* source_ip, const char* destination_ip, int payload_length) {
    if (packet_count >= MAX_PACKETS) {
        printf("Error: Maximum number of packets reached.\n");
        return;
    }
    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) {
        printf("Error: Memory allocation failed.\n");
        return;
    }
    new_packet->timestamp = timestamp;
    strcpy(new_packet->source_ip, source_ip);
    strcpy(new_packet->destination_ip, destination_ip);
    new_packet->payload_length = payload_length;
    new_packet->status = 1; // Active by default
    packet_array[packet_count++] = new_packet;
}

void update_packet(int index, int timestamp, const char* source_ip, const char* destination_ip, int payload_length) {
    if (index < 0 || index >= packet_count) {
        printf("Error: Invalid packet index.\n");
        return;
    }
    Packet* packet = packet_array[index];
    packet->timestamp = timestamp;
    strcpy(packet->source_ip, source_ip);
    strcpy(packet->destination_ip, destination_ip);
    packet->payload_length = payload_length;
}

void mark_packet_status(int index, int status) {
    if (index < 0 || index >= packet_count) {
        printf("Error: Invalid packet index.\n");
        return;
    }
    Packet* packet = packet_array[index];
    packet->status = status;
}

int calculate_total_data_transferred() {
    int total = 0;
    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->status == 1) {
            total += packet_array[i]->payload_length;
        }
    }
    return total;
}

void filter_packets_by_source_ip(const char* source_ip) {
    for (int i = 0; i < packet_count; i++) {
        if (strcmp(packet_array[i]->source_ip, source_ip) == 0) {
            printf("Packet found: %s -> %s\n", packet_array[i]->source_ip, packet_array[i]->destination_ip);
        }
    }
}

void filter_packets_by_destination_ip(const char* destination_ip) {
    for (int i = 0; i < packet_count; i++) {
        if (strcmp(packet_array[i]->destination_ip, destination_ip) == 0) {
            printf("Packet found: %s -> %s\n", packet_array[i]->source_ip, packet_array[i]->destination_ip);
        }
    }
}

void prune_inactive_packets() {
    int new_count = 0;
    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->status == 1) {
            packet_array[new_count++] = packet_array[i];
        } else {
            free(packet_array[i]);
        }
    }
    packet_count = new_count;
}

void log_packet_activity(int index, const char* activity) {
    printf("Packet %d: %s\n", index, activity);
}
