    double* double_array = (double*)malloc(5 * sizeof(double));
    if (double_array == NULL) {
        fprintf(stderr, "Memory allocation failed for double array.\n");
        return;
    }

    char* char_buffer = (char*)malloc(1024); // Example buffer size
    if (char_buffer == NULL) {
        free(double_array);
        fprintf(stderr, "Memory allocation failed for char buffer.\n");
        return;
    }

    int* int_array = (int*)malloc(5 * sizeof(int));
    if (int_array == NULL) {
        free(double_array);
        free(char_buffer);
        fprintf(stderr, "Memory allocation failed for int array.\n");
        return;
    }

    data** data_array = (data**)malloc(5 * sizeof(data*));
    if (data_array == NULL) {
        free(double_array);
        free(char_buffer);
        free(int_array);
        fprintf(stderr, "Memory allocation failed for data array.\n");
        return;
    }

    log** log_entries = (log**)malloc(MAX_LOG_ENTRIES * sizeof(log*));
    if (log_entries == NULL) {
        free(double_array);
        free(char_buffer);
        free(int_array);
        free(data_array);
        fprintf(stderr, "Memory allocation failed for log entries array.\n");
        return;
    }

    // Populate structures with values
    for (int i = 0; i < 5; i++) {
        double_array[i] = (double)rand() / RAND_MAX;
        char_buffer[i] = 'A' + rand() % 26;
        int_array[i] = rand();
        data* d = create_data(double_array[i], (unsigned short)i);
        if (d != NULL) {
            data_array[i] = d;
            log* l = create_log(time(NULL), i, d);
            if (l != NULL) {
                log_entries[i % MAX_LOG_ENTRIES] = l;
            }
        }
    }

    // Free allocated memory
    for (int i = 0; i < 5; i++) {
        free(data_array[i]->buffer);
        free(data_array[i]);
        free(log_entries[i]);
    }
    free(double_array);
    free(char_buffer);
    free(int_array);
    free(data_array);
    free(log_entries);

    printf("Structures initialized and memory freed.\n");
}

int main() {
    initialize_structures();
    return 0;
}
