    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addLogEntry(DynamicList* list, LogEntry entry) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = entry;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void updateLogEntry(DynamicList* list, int session_id, LogEntry new_entry) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.session_id == session_id) {
            current->data = new_entry;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void calculateAverageResponseTime(DynamicList* list, int user_id) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    double total_response_time = 0;
    int count = 0;
    while (current != NULL) {
        if (current->data.user_id == user_id) {
            time_t now = time(NULL);
            total_response_time += difftime(now, current->data.timestamp);
            count++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    if (count > 0) {
        double average_response_time = total_response_time / count;
        printf("Average response time for user %d: %f\n", user_id, average_response_time);
    } else {
        printf("No log entries found for user %d\n", user_id);
    }
}

void freeDynamicList(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
