#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    double value;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct DynamicCollection {
    Node* head;
    size_t count;
    size_t capacity;
} DynamicCollection;

DynamicCollection* init_collection(size_t initial_capacity) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for collection.\n");
        return NULL;
    }
    collection->head = NULL;
    collection->count = 0;
    collection->capacity = initial_capacity;

    srand(time(NULL)); // Seed the random number generator

    return collection;
}

void free_collection(DynamicCollection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(collection);
}

Node* find_node(DynamicCollection* collection, int key) {
    Node* current = collection->head;
    while (current) {
        if (current->data.key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void update_record(DynamicCollection* collection, int key, double new_value) {
    Node* node = find_node(collection, key);
    if (node) {
        node->data.value = new_value;
    } else {
        fprintf(stderr, "Key not found in the collection.\n");
    }
}

int main() {
    DynamicCollection* collection = init_collection(10);
    if (!collection) {
        return 1;
    }

    update_record(collection, 42, 3.14);

    free_collection(collection);
    return 0;
}
```

This code snippet provides a basic implementation of a dynamic collection of records in C. It includes functions to initialize and free the collection, find a node by key, and update a record's value. The `main` function demonstrates how to use these functions.

Please note that this is a simplified example and does not include advanced features such as dynamic resizing or multi-threading support. For a production environment, additional considerations would be necessary to ensure thread safety and efficient memory management.']

