NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(int N, int* error_code) {
    if (N > MAX_ELEMENTS) {
        *error_code = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_code = -2;
        return NULL;
    }

    srand(time(NULL));
    int rnti_set[MAX_ELEMENTS] = {0};
    int unique_rnti_count = 0;

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % MAX_ELEMENTS;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        array[i].CRCFLAG = rand() % 2;

        while (rnti_set[array[i].RNTI]) {
            array[i].RNTI = rand() % MAX_ELEMENTS;
        }
        rnti_set[array[i].RNTI] = 1;
        unique_rnti_count++;
    }

    if (unique_rnti_count != N) {
        log_error("Duplicate RNTI detected during population.");
    }

    *error_code = 0;
    return array;
}

