// Serialization function
void serialize_array(const NFAPI_CRC_INDICATION_PDU_T* array, int N, FILE* file) {
    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
}

// Deserialization function
NFAPI_CRC_INDICATION_PDU_T* deserialize_array(int N, FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    size_t elements_read = fread(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    if (elements_read != N) {
        free(array);
        return NULL;
    }

    return array;
}

// Stress test function
void stress_test(int max_elements) {
    for (int N = 0; N <= max_elements; ++N) {
