    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} PacketList;

int init_packet_list(PacketList *list, size_t initial_capacity) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) return -1; // Memory allocation failure
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

void destroy_packet_list(PacketList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

int add_packet_to_list(PacketList *list, int RX_UE_INFORMATION_TAG, int RNTI, int seed) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    int CRCFLAG = (rand_r((unsigned int *)&seed) % 2); // Pseudo-random sequence generator
    list->data[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->size].RNTI = RNTI;
    list->data[list->size].CRC_INDICATION_REL8_TAG = CRCFLAG;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void *iterate_packet_list(PacketList *list) {
    // Generator-like approach to iterate over the list
    for (size_t i = 0; i < list->size; ++i) {
        yield(list->data[i]);
    }
    return NULL;
}
