public class GameConfigManager
{
    private XDocument configDoc;
    private Dictionary<string, string> cache = new Dictionary<string, string>();
    private const string ConfigFilePath = "game_config.xml";
    private const string BackupFilePath = "game_config_backup.xml";

    public GameConfigManager()
    {
        LoadConfiguration();
    }

    private void LoadConfiguration()
    {
        try
        {
            if (File.Exists(ConfigFilePath))
            {
                configDoc = XDocument.Load(ConfigFilePath);
                CacheSettings();
            }
            else
            {
                // Handle missing configuration file
                Console.WriteLine("Configuration file not found. Using default settings.");
                CreateDefaultConfig();
                SaveConfiguration();
            }
        }
        catch (Exception ex)
        {
            // Handle XML parsing errors
            Console.WriteLine($"Error loading configuration: {ex.Message}");
            CreateDefaultConfig();
            SaveConfiguration();
        }
    }

    private void CacheSettings()
    {
        foreach (var element in configDoc.Root.Elements())
        {
            cache[element.Name.LocalName] = element.Value;
        }
    }

    private void CreateDefaultConfig()
    {
        configDoc = new XDocument(
            new XElement("GameConfig",
                new XElement("TileSize", "32"),
                new XElement("WorldWidth", "1024"),
                new XElement("WorldHeight", "768"),
                new XElement("CameraSpeed", "2.5")
            ));
    }

    public void SaveConfiguration()
    {
        try
        {
            configDoc.Save(ConfigFilePath);
            File.Copy(ConfigFilePath, BackupFilePath, true);
        }
        catch (Exception ex)
        {
            // Handle file saving errors
            Console.WriteLine($"Error saving configuration: {ex.Message}");
        }
    }

    public string GetSetting(string key)
    {
        if (cache.ContainsKey(key))
        {
            return cache[key];
        }
        else
        {
            var setting = configDoc.Root.Element(key)?.Value;
            if (setting != null)
            {
                cache[key] = setting;
                return setting;
            }
            else
            {
                // Handle missing settings with default values
                Console.WriteLine($"Missing setting: {key}. Using default value.");
                return GetDefaultSetting(key);
            }
        }
    }

    private string GetDefaultSetting(string key)
    {
        switch (key)
        {
            case "TileSize":
                return "32";
            case "WorldWidth":
                return "1024";
            case "WorldHeight":
                return "768";
            case "CameraSpeed":
                return "2.5";
            default:
                return null;
        }
    }

    public void UpdateSetting(string key, string value)
    {
        var element = configDoc.Root.Element(key);
        if (element != null)
        {
            element.Value = value;
            cache[key] = value;
            SaveConfiguration();
        }
        else
        {
            Console.WriteLine($"Invalid setting: {key}");
        }
    }

    public void ValidateSettings()
    {
        int tileSize, worldWidth, worldHeight;
        float cameraSpeed;

        if (int.TryParse(GetSetting("TileSize"), out tileSize) && tileSize % 16 != 0)
        {
            UpdateSetting("TileSize", "32");
        }

        if (int.TryParse(GetSetting("WorldWidth"), out worldWidth) && int.TryParse(GetSetting("WorldHeight"), out worldHeight))
        {
            if (worldWidth % tileSize != 0 || worldHeight % tileSize != 0)
            {
                UpdateSetting("WorldWidth", "1024");
                UpdateSetting("WorldHeight", "768");
            }
        }

        if (float.TryParse(GetSetting("CameraSpeed"), out cameraSpeed) && cameraSpeed < 0.5f || cameraSpeed > 5.0f)
        {
            UpdateSetting("CameraSpeed", "2.5");
        }
    }
}
