typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRCList;

CRCList* create_crc_list(size_t initial_capacity) {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        log_error("Failed to allocate memory for CRC list");
        return NULL;
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        log_error("Failed to allocate memory for CRC data");
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(CRCList *list) {
    if (list) {
        pthread_mutex_lock(&list->mutex);
        free(list->data);
        pthread_mutex_unlock(&list->mutex);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_to_crc_list(CRCList *list, NFAPI_CRC_INDICATION_PDU_T item, int crc_range_min, int crc_range_max) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            log_error("Failed to reallocate memory for CRC data");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    if (item.CRC_INDICATION_REL8_TAG.CRCFLAG < crc_range_min || item.CRC_INDICATION_REL8_TAG.CRCFLAG > crc_range_max) {
        log_error("CRCFLAG out of range");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void* manage_crc_list(void *arg) {
    CRCList *list = (CRCList*)arg;
