#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Metric {
    int id;
    long timestamp;
    unsigned long packet_count;
    double throughput;
    double latency;
    struct Metric *prev, *next;
} Metric;

typedef struct DoublyLinkedList {
    Metric *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DoublyLinkedList *list) {
    Metric *current = list->head;
    while (current) {
        Metric *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_metric(DoublyLinkedList *list, int id, long timestamp, unsigned long packet_count, double throughput, double latency) {
    if (throughput < 0 || throughput > 1000.0 || latency < 0 || latency > 1000.0) return -1;
    Metric *new_metric = (Metric*)malloc(sizeof(Metric));
    if (!new_metric) return -2;
    new_metric->id = id;
    new_metric->timestamp = timestamp;
    new_metric->packet_count = packet_count;
    new_metric->throughput = throughput;
    new_metric->latency = latency;
    new_metric->prev = list->tail;
    new_metric->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = new_metric;
    } else {
        list->head = new_metric;
    }
    list->tail = new_metric;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void log_metric_update(Metric *metric) {
    // Log successful metric update to external monitoring API
    printf("Metric updated: ID=%d, Timestamp=%ld, Packet Count=%lu, Throughput=%.2f, Latency=%.2f\n",
           metric->id, metric->timestamp, metric->packet_count, metric->throughput, metric->latency);
}

void report_failure() {
    // Report failure to external monitoring API
    printf("Failed to update metric\n");
}
