void create_user_account(UserAccount* new_account) {
    // Simulate database insertion
    user_accounts = realloc(user_accounts, (account_count + 1) * sizeof(UserAccount));
    memcpy(&user_accounts[account_count], new_account, sizeof(UserAccount));
    account_count++;
}

void update_user_account(int id, UserAccount* updated_account) {
    for (int i = 0; i < account_count; i++) {
        if (user_accounts[i].id == id) {
            // Simulate database update
            memcpy(&user_accounts[i], updated_account, sizeof(UserAccount));
            return;
        }
    }
}

void delete_user_account(int id) {
    for (int i = 0; i < account_count; i++) {
        if (user_accounts[i].id == id) {
            // Simulate database deletion
            for (int j = i; j < account_count - 1; j++) {
                user_accounts[j] = user_accounts[j + 1];
            }
            account_count--;
            return;
        }
    }
}

json_object* handle_user_request(json_object* request) {
    json_object* response = json_object_new_object();
