            json_object* password_obj = NULL;
            json_object_object_get_ex(request, "name", &name_obj);
            json_object_object_get_ex(request, "email", &email_obj);
            json_object_object_get_ex(request, "password", &password_obj);

            if (json_object_is_type(name_obj, json_type_string) &&
                json_object_is_type(email_obj, json_type_string) &&
                json_object_is_type(password_obj, json_type_string)) {
                strcpy(new_account.name, json_object_get_string(name_obj));
                strcpy(new_account.email, json_object_get_string(email_obj));
                strcpy(new_account.password, json_object_get_string(password_obj));
                new_account.id = id;

                create_user_account(&new_account);
            } else {
                message = json_object_new_string("Invalid input data");
                json_object_object_add(response, "message", message);
            }
        } else if (strcmp(sub_action, "update") == 0) {
            // Extract user account details
            json_object* name_obj = NULL;
            json_object* email_obj = NULL;
            json_object* password_obj = NULL;
            json_object_object_get_ex(request, "name", &name_obj);
            json_object_object_get_ex(request, "email", &email_obj);
            json_object_object_get_ex(request, "password", &password_obj);

            if (json_object_is_type(name_obj, json_type_string) &&
                json_object_is_type(email_obj, json_type_string) &&
                json_object_is_type(password_obj, json_type_string)) {
                strcpy(new_account.name, json_object_get_string(name_obj));
                strcpy(new_account.email, json_object_get_string(email_obj));
                strcpy(new_account.password, json_object_get_string(password_obj));
                new_account.id = id;

                update_user_account(id, &new_account);
            } else {
                message = json_object_new_string("Invalid input data");
                json_object_object_add(response, "message", message);
            }
        } else if (strcmp(sub_action, "delete") == 0) {
            delete_user_account(id);
        }
    }

    return response;
}

int main() {
