<?php

function manageUserAccount($_REQUEST) {
    $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
    $name = $_REQUEST['name'] ?? '';
    $email = $_REQUEST['email'] ?? '';
    $password = $_REQUEST['password'] ?? '';
    $confirm_password = $_REQUEST['confirm_password'] ?? '';
    $sub_action = $_REQUEST['sub_action'] ?? '';

    // Validate input
    if (empty($name) || empty($email) || empty($password)) {
        return json_encode(['error' => 'Name, email, and password are required']);
    }
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode(['error' => 'Invalid email format']);
    }
    if ($password !== $confirm_password) {
        return json_encode(['error' => 'Passwords do not match']);
    }

    // Check for password strength
    if (strlen($password) < 8 || !preg_match('/[A-Z]/', $password) || !preg_match('/[a-z]/', $password) || !preg_match('/\d/', $password)) {
        return json_encode(['error' => 'Password must be at least 8 characters long and include uppercase, lowercase, and numbers']);
    }

    // External API for authentication and identity verification
    $authApiUrl = 'https://api.example.com/auth';
    $identityApiUrl = 'https://api.example.com/identity';

    // Asynchronous API calls using cURL
    $ch1 = curl_init($authApiUrl);
    curl_setopt($ch1, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch1, CURLOPT_POST, 1);
    curl_setopt($ch1, CURLOPT_POSTFIELDS, http_build_query(['email' => $email]));
    $ch2 = curl_init($identityApiUrl);
    curl_setopt($ch2, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch2, CURLOPT_POST, 1);
    curl_setopt($ch2, CURLOPT_POSTFIELDS, http_build_query(['name' => $name, 'password' => $password]));

    // Execute cURL requests asynchronously
    $mh = curl_multi_init();
    curl_multi_add_handle($mh, $ch1);
    curl_multi_add_handle($mh, $ch2);
    do {
        $status = curl_multi_exec($mh, $active);
    } while ($status === CURLM_CALL_MULTI_PERFORM || $active);

    // Check for errors
    if ($status !== CURLM_OK) {
        return json_encode(['error' => 'Error with external API calls']);
    }

    // Process responses
    $responses = [];
    do {
        $msg = curl_multi_info_read($mh);
        if ($msg['msg'] == CURLMSG_DONE) {
            $ch = $msg['handle'];
            $response = curl_multi_getcontent($ch);
            $responses[] = json_decode($response, true);
            curl_multi_remove_handle($mh, $ch);
            curl_close($ch);
        }
    } while ($msg);

    // Handle responses
    if (isset($responses[0]['error']) || isset($responses[1]['error'])) {
        return json_encode(['error' => 'Error with external API calls']);
    }

    // Database operations
    $db = new PDO('mysql:host=localhost;dbname=users', 'username', 'password');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    if ($sub_action === 'delete') {
        // Delete user account
        $stmt = $db->prepare('DELETE FROM users WHERE id = :id');
        $stmt->execute(['id' => $id]);
    } else {
        // Create or update user account
        if ($id) {
            // Update existing user
            $stmt = $db->prepare('UPDATE users SET name = :name, email = :email WHERE id = :id');
            $stmt->execute(['id' => $id, 'name' => $name, 'email' => $email]);
        } else {
            // Create new user
            $stmt = $db->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)');
            $stmt->execute(['name' => $name, 'email' => $email, 'password' => password_hash($password, PASSWORD_DEFAULT)]);
        }
    }

    // Return success response
    return json_encode(['success' => true]);
}

// Example usage
echo manageUserAccount($_REQUEST);
?>
