#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(int rx_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->RX_UE_INFORMATION_TAG = rx_tag;
    new_node->RNTI = rnti;
    new_node->CRC_INDICATION_REL8_TAG = 0; // Initialize CRC flag
    new_node->next = NULL;
    return new_node;
}

void add_node(NFAPI_CRC_INDICATION_PDU_T** head, int rx_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(rx_tag, rnti);
    if (*head == NULL) {
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

void set_crc_flags(NFAPI_CRC_INDICATION_PDU_T** head, int total_nodes) {
    srand(time(NULL));
    int half_nodes = total_nodes / 2;
    int count = 0;

    NFAPI_CRC_INDICATION_PDU_T* temp = *head;
    while (temp != NULL && count < half_nodes) {
        if (rand() % 2 == 0) {
            temp->CRCFLAG = 1;
            count++;
        }
        temp = temp->next;
    }

    // Ensure exactly half nodes have CRC flag set
    while (count < half_nodes) {
        NFAPI_CRC_INDICATION_PDU_T* current = *head;
        while (current != NULL && count < half_nodes) {
            if (current->CRCFLAG == 0) {
                current->CRCFLAG = 1;
                count++;
            }
            current = current->next;
        }
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Example usage
    add_node(&head, 1, 100);
    add_node(&head, 2, 200);
    add_node(&head, 3, 300);

    int total_nodes = 3;
    set_crc_flags(&head, total_nodes);

    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while (temp != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", temp->RX_UE_INFORMATION_TAG, temp->RNTI, temp->CRCFLAG);
        temp = temp->next;
    }

    free_list(&head);

    return 0;
}
