#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

bool is_valid_rnti(int rnti, int min_rnti, int max_rnti) {
    return rnti >= min_rnti && rnti <= max_rnti;
}

bool add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu, int min_rnti, int max_rnti) {
    if (!is_valid_rnti(pdu.RNTI, min_rnti, max_rnti)) return false;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return false;
    new_node->data = pdu;
    new_node->next = NULL;

    if (list->count > 0 && list->tail->data.CRC_INDICATION_REL8_TAG == pdu.CRC_INDICATION_REL8_TAG) {
        free(new_node);
        return false;
    }

    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(DynamicList* list, size_t index) {
    if (index >= list->count) return NULL;

    Node* current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }
    return &current->data;
}

