void* init_cipher(CipherMode mode, int key_size, int block_size) {
    void* cipher_handle = NULL;

    switch (mode) {
        case ECB:
            // Initialize ECB cipher
            printf("Initializing ECB cipher with key size %d and block size %d\n", key_size, block_size);
