#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct {
    record *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_collection;

void init_collection(dynamic_collection *collection, size_t initial_capacity) {
    collection->data = malloc(initial_capacity * sizeof(record));
    if (collection->data == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void free_collection(dynamic_collection *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->data);
    collection->data = NULL;
    collection->capacity = 0;
    collection->size = 0;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

void add_record(dynamic_collection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        // Resize the array
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        record *new_data = realloc(collection->data, new_capacity * sizeof(record));
        if (new_data == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&collection->lock);
            exit(EXIT_FAILURE);
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }
    collection->data[collection->size].offset = rand();
    collection->data[collection->size].key = key;
    collection->data[collection->size].value = (double)rand() / RAND_MAX * 100.0;
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

void update_record(dynamic_collection *collection, int key, double new_value) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->data[i].key == key) {
            collection->data[i].value = new_value;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

double get_record_value(dynamic_collection *collection, int key) {
    double value = -1.0; // Default value if not found
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->data[i].key == key) {
            value = collection->data[i].value;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return value;
}
