#define MAX_DESTINATIONS 10

typedef enum {
    LOG_FILE,
    LOG_STDERR,
    LOG_NETWORK
} LogDestination;

typedef struct {
    LogDestination type;
    void* destination; // Pointer to file, stderr, or network stream
    int message_count;
    pthread_mutex_t lock;
} Logger;

Logger loggers[MAX_DESTINATIONS];
int logger_count = 0;
pthread_mutex_t logger_lock;

void init_logger(LogDestination type, void* destination) {
    pthread_mutex_lock(&logger_lock);
    if (logger_count < MAX_DESTINATIONS) {
        loggers[logger_count].type = type;
        loggers[logger_count].destination = destination;
        loggers[logger_count].message_count = 0;
        pthread_mutex_init(&loggers[logger_count].lock, NULL);
        logger_count++;
    }
    pthread_mutex_unlock(&logger_lock);
}

void log_message(LogDestination type, const char* message) {
    for (int i = 0; i < logger_count; i++) {
        if (loggers[i].type == type) {
            pthread_mutex_lock(&loggers[i].lock);
            switch (type) {
                case LOG_FILE:
                    fprintf((FILE*)loggers[i].destination, "%s\n", message);
                    break;
                case LOG_STDERR:
                    fprintf(stderr, "%s\n", message);
                    break;
                case LOG_NETWORK:
                    // Implement network logging
                    break;
            }
            loggers[i].message_count++;
            pthread_mutex_unlock(&loggers[i].lock);
        }
    }
}

int get_message_count(LogDestination type) {
    int count = 0;
    for (int i = 0; i < logger_count; i++) {
        if (loggers[i].type == type) {
            pthread_mutex_lock(&loggers[i].lock);
            count += loggers[i].message_count;
            pthread_mutex_unlock(&loggers[i].lock);
        }
    }
    return count;
}

void cleanup_loggers() {
    for (int i = 0; i < logger_count; i++) {
        pthread_mutex_destroy(&loggers[i].lock);
    }
}
