#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    char type[50];
    void* metadata;
} TrafficEvent;

typedef struct {
    TrafficEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager(size_t initial_capacity) {
    TrafficManager* manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    if (!manager) return NULL;

    manager->events = (TrafficEvent*)calloc(initial_capacity, sizeof(TrafficEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_traffic_manager(TrafficManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->events[i].metadata);
    }
    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_event(TrafficManager* manager, TrafficEvent event) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TrafficEvent* new_events = (TrafficEvent*)realloc(manager->events, new_capacity * sizeof(TrafficEvent));
        if (!new_events) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    manager->events[manager->size++] = event;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_event(TrafficManager* manager, int timestamp, TrafficEvent new_event) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].timestamp == timestamp) {
            free(manager->events[i].metadata);
            manager->events[i] = new_event;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Event not found
}

int query_events(TrafficManager* manager, int start_timestamp, int end_timestamp, TrafficEvent** events, size_t* count) {
    pthread_mutex_lock(&manager->lock);

    *count = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].timestamp >= start_timestamp && manager->events[i].timestamp <= end_timestamp) {
            (*count)++;
        }
    }

    *events = (TrafficEvent*)malloc(*count * sizeof(TrafficEvent));
    if (!*events) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }

    size_t j = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].timestamp >= start_timestamp && manager->events[i].timestamp <= end_timestamp) {
            (*events)[j++] = manager->events[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}
