const fs = require('fs').promises;
const path = require('path');

async function readFilesInDirectory(directoryPath, fileExtension) {
  try {
    const files = await fs.readdir(directoryPath);
    const filteredFiles = files.filter(file => path.extname(file).toLowerCase() === fileExtension.toLowerCase());

    const contents = await Promise.all(filteredFiles.map(async (file) => {
      try {
        const filePath = path.join(directoryPath, file);
        const content = await fs.readFile(filePath, 'utf8');
        return content;
      } catch (error) {
        console.error(`Failed to read file ${file}:`, error.message);
        return '';
      }
    }));

    return contents.join('');
  } catch (error) {
    console.error('Failed to read directory:', error.message);
    return '';
  }
}

// Example usage:
const directoryPath = './example_directory';
const fileExtension = '.txt';

readFilesInDirectory(directoryPath, fileExtension)
  .then(result => {
    console.log('Concatenated contents:', result);
  })
  .catch(error => {
    console.error('Error:', error.message);
  });
```

This code snippet demonstrates how to asynchronously read multiple files from a specified directory, filter them based on a given extension, and concatenate their contents into a single string. It handles errors gracefully by logging detailed error messages for each file that fails to load. The solution uses `Promise.all` to read files in parallel when possible, ensuring efficient performance under varying file sizes and network latency."]

