#include <semaphore.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    sem_t *sem;
    pthread_mutex_t mutex;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(const char* name, int initial_value) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    manager->sem = sem_open(name, O_CREAT | O_EXCL, 0644, initial_value);
    if (manager->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    sem_close(manager->sem);
    sem_unlink("/path_to_semaphore"); // Replace with actual semaphore name
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void increment_semaphore(SemaphoreManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    sem_post(manager->sem);
    pthread_mutex_unlock(&manager->mutex);
}

void decrement_semaphore(SemaphoreManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    while (sem_wait(manager->sem) == -1 && errno == EINTR); // Handle interruptions
    pthread_mutex_unlock(&manager->mutex);
}
