#include <forward_list>
#include <string>
#include <atomic>
#include <chrono>
#include <thread>

void insertStringAfterTimeout(std::forward_list<std::string>& lst, const std::string& target, const std::string& insertStr, int timeout) {
    auto start = std::chrono::high_resolution_clock::now();
    while (true) {
        if (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start).count() > timeout) {
            return; // Timeout reached, operation failed
        }
        auto it = lst.begin();
        for (; it != lst.end(); ++it) {
            if (*it == target) {
                lst.insert_after(it, insertStr);
                return; // Insertion successful
            }
        }
        std::this_thread::yield(); // Yield CPU to other threads
    }
}
