namespace RandomEngine {
    class MersenneTwister {
    public:
        MersenneTwister(uint64_t seed, uint8_t bitWidth) : gen(seed), dist(0, (1ULL << bitWidth) - 1) {}

        ~MersenneTwister() = default;

        int32_t generateSignedInt(int32_t min, int32_t max) {
            return std::uniform_int_distribution<int32_t>(min, max)(gen);
        }

        uint32_t generateUnsignedInt(uint32_t min, uint32_t max) {
            return std::uniform_int_distribution<uint32_t>(min, max)(gen);
        }

        float generateFloat(float min, float max) {
            return std::uniform_real_distribution<float>(min, max)(gen);
        }

    private:
        std::mt19937_64 gen;
        std::uniform_int_distribution<> dist;
    };
}

// Unit tests
#include <gtest/gtest.h>

TEST(MersenneTwisterTest, GenerateSignedInt) {
    RandomEngine::MersenneTwister rng(0x123456789ABCDEF0ULL, 32);
    EXPECT_GE(rng.generateSignedInt(-1000, 1000), -1000);
    EXPECT_LE(rng.generateSignedInt(-1000, 1000), 1000);
}

TEST(MersenneTwisterTest, GenerateUnsignedInt) {
    RandomEngine::MersenneTwister rng(0x123456789ABCDEF0ULL, 32);
    EXPECT_GE(rng.generateUnsignedInt(0, 1000), 0);
    EXPECT_LE(rng.generateUnsignedInt(0, 1000), 1000);
}

