from flask import Flask, request, jsonify
import requests
from functools import wraps
import time

app = Flask(__name__)

# Mock external service URL
EXTERNAL_SERVICE_URL = "http://example.com/api/resource"

def retry_on_failure(max_retries=3, delay=2):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except requests.RequestException as e:
                    attempts += 1
                    time.sleep(delay)
            raise Exception("External service is unavailable")
        return wrapper
    return decorator

def validate_request_body(schema):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            request_data = request.get_json()
            if not schema.validate(request_data):
                return jsonify({"error": "Invalid request body"}), 400
            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/update/<int:resource_id>', methods=['PUT'])
@retry_on_failure(max_retries=3, delay=2)
@validate_request_body(schema)
def update_resource(resource_id):
    try:
        # Fetch the latest resource state from external service
        response = requests.get(f"{EXTERNAL_SERVICE_URL}/{resource_id}")
        if response.status_code != 200:
            return jsonify({"error": "Resource not found"}), 404

        current_resource = response.json()
        updated_data = request.get_json()

        # Check for optimistic concurrency control
        if 'version' in updated_data and updated_data['version'] != current_resource['version']:
            return jsonify({"error": "Conflict", "message": "Resource has been modified"}), 409

        # Update the resource with new data
        updated_resource = {**current_resource, **updated_data}
        updated_resource['version'] += 1

        # Simulate updating the resource in the database
        time.sleep(1)  # Simulate network latency

        return jsonify(updated_resource), 200
    except Exception as e:
        app.logger.error(f"Error updating resource: {e}")
        return jsonify({"error": "Internal server error"}), 500

@app.route('/delete/<int:resource_id>', methods=['DELETE'])
@retry_on_failure(max_retries=3, delay=2)
def delete_resource(resource_id):
    try:
        # Fetch the latest resource state from external service
        response = requests.get(f"{EXTERNAL_SERVICE_URL}/{resource_id}")
        if response.status_code != 200:
            return jsonify({"error": "Resource not found"}), 404

        current_resource = response.json()

        # Check if the resource has been modified since last fetch
        if 'last_modified' in request.args and request.args['last_modified'] != current_resource['last_modified']:
            return jsonify({"error": "Conflict", "message": "Resource has been modified"}), 409

        # Simulate deleting the resource from the database
        time.sleep(1)  # Simulate network latency

        # Return a new resource with default values
        new_resource = {
            'id': resource_id,
            'name': 'Default Name',
            'value': 'Default Value'
        }

        return jsonify(new_resource), 200
    except Exception as e:
        app.logger.error(f"Error deleting resource: {e}")
        return jsonify({"error": "Internal server error"}), 500

if __name__ == '__main__':
    app.run(debug=True)
