import java.io.*;
import java.util.concurrent.TimeUnit;

public class StateLoader {

    public static MoSTState loadStateFromFile(String filePath) {
        int maxRetries = 5;
        long backoffTime = 100; // Initial backoff time in milliseconds

        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
                Object obj = ois.readObject();
                if (obj instanceof MoSTState) {
                    MoSTState state = (MoSTState) obj;
                    if (isValidVersion(state)) {
                        logSuccess(filePath, state.getVersion());
                        return state;
                    } else {
                        logFailure(filePath, "Invalid version");
                    }
                } else {
                    logFailure(filePath, "Incorrect object type");
                }
            } catch (IOException | ClassNotFoundException e) {
                if (attempt == maxRetries) {
                    logFailure(filePath, "Failed to load state after retries", e);
                    return null;
                }
                logFailure(filePath, "Transient failure, retrying in " + backoffTime + "ms", e);
                try {
                    TimeUnit.MILLISECONDS.sleep(backoffTime);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    logFailure(filePath, "Interrupted during retry");
                    return null;
                }
                backoffTime *= 2; // Exponential backoff
            }
        }

        return null;
    }

    private static boolean isValidVersion(MoSTState state) {
