            regcomp(&oldTestamentRegexes[i], bookNames[i], REG_EXTENDED);
        }
        regexCompiled = 1;
    }

    time_t currentTime = time(NULL);
    if (currentTime - lastCacheTime > 3600 || numBooks == NULL) { // Cache for an hour or no cache requested
        BIBLE_BOOK_REFERENCE* results = malloc(MAX_BOOKS * sizeof(BIBLE_BOOK_REFERENCE));
        if (!results) {
            return NULL; // Handle memory allocation failure
        }

        int bookIndex = 0;
        for (int i = 0; i < MAX_BOOKS && bookNames[i]; ++i) {
            regmatch_t matches[1];
            const char* searchStart = text;
            while (regexec(&oldTestamentRegexes[i], searchStart, 1, matches, 0) == REG_OKAY) {
                if (matches[0].rm_so != -1) {
                    results[bookIndex].tag = getRX_UE_INFORMATION_TAG(); // External API call
                    strncpy(results[bookIndex].book_name, bookNames[i], sizeof(results[bookIndex].book_name));
                    results[bookIndex].count++;
                    searchStart += matches[0].rm_eo;
                } else {
                    break;
                }
            }
        }

        *numBooks = bookIndex + 1;
        free(cachedResults);
        cachedResults = results;
        cachedNumBooks = *numBooks;
        lastCacheTime = currentTime;

        return cachedResults;
    } else {
        *numBooks = cachedNumBooks;
        return cachedResults;
    }
}

// Example usage
int main() {
    const char* text = "Genesis 1:1, Exodus 20:2, Leviticus 3:3";
    int numBooks;
    BIBLE_BOOK_REFERENCE* references = processTextForBibleReferences(text, &numBooks);
    if (references) {
        for (int i = 0; i < numBooks; ++i) {
            printf("Book: %s, Tag: %d, Count: %d\n", references[i].book_name, references[i].tag, references[i].count);
        }
        free(references);
    } else {
        printf("Failed to process text.\n");
    }
    return 0;
}
