function renderWidgets(widgets) {
    const cache = {};
    let cssPath = '';

    function loadCSS(url) {
        if (cache[url]) return Promise.resolve(cache[url]);
        return new Promise((resolve, reject) => {
            const link = document.createElement('link');
            link.rel = 'stylesheet';
            link.href = url;
            link.onload = () => resolve(link);
            link.onerror = () => reject(new Error(`Failed to load CSS from ${url}`));
            document.head.appendChild(link);
        }).then(link => {
            cache[url] = link;
            return url;
        });
    }

    function renderWidget(widget) {
        const { title, description, iconUrl } = widget;
        const icon = iconUrl ? `<img src="${iconUrl}" alt="Icon">` : '';
        const desc = description || 'No description available';
        return `
            <div class="widget">
                ${icon}
                <h3>${title}</h3>
                <p>${desc}</p>
            </div>
        `;
    }

    function renderWidgetsAsync(widgets) {
        return Promise.all(widgets.map(widget => loadCSS(widget.cssPath)))
            .then(cssPaths => {
                cssPath = cssPaths[0]; // Assuming all widgets use the same CSS
                return widgets.map(renderWidget).join('');
            })
            .catch(error => {
                console.error('Error rendering widgets:', error);
                return '';
            });
    }

    return renderWidgetsAsync(widgets)
        .then(html => ({ html, cssPath }));
}
