async function traverseDOM(selector, visibilityCriteria, apiEndpoint, maxConcurrentRequests = 5, cacheTTL = 60000) {
    const cache = new Map();
    let activeRequests = 0;
    const results = [];

    async function fetchMetadata(element) {
        if (cache.has(element)) {
            return cache.get(element);
        }

        try {
            const response = await fetch(apiEndpoint + element.id);
            if (!response.ok) throw new Error('Failed to fetch metadata');
            const data = await response.json();
            cache.set(element, data);
            setTimeout(() => cache.delete(element), cacheTTL);
            return data;
        } catch (error) {
            console.error(`Error fetching metadata for ${element.id}:`, error);
            return null;
        }
    }

    async function processElement(element) {
        if (!isVisible(element)) return;

        const metadata = await fetchMetadata(element);
        if (metadata) {
            results.push({ element, metadata });
        }

        activeRequests--;
        if (activeRequests < maxConcurrentRequests && queue.length > 0) {
            processNext();
        }
    }

    function isVisible(element) {
        return window.getComputedStyle(element).display !== 'none' &&
               window.getComputedStyle(element).visibility !== 'hidden';
    }

    const queue = Array.from(document.querySelectorAll(selector));

    async function processNext() {
        if (queue.length === 0) {
            if (activeRequests === 0) {
                callback(null, results);
            }
            return;
        }

        const element = queue.shift();
        activeRequests++;
        await processElement(element);
        processNext();
    }

    processNext();

    function callback(error, data) {
        // Handle completion notification
    }
}
