import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;
import java.util.concurrent.ConcurrentHashMap;

public class NetworkManager {
    private Selector selector;
    private ConcurrentHashMap<String, SocketChannel> tcpConnections;
    private ConcurrentHashMap<String, DatagramChannel> udpChannels;
    private Configuration config;

    public NetworkManager(Configuration config) throws IOException {
        this.config = config;
        selector = Selector.open();
        tcpConnections = new ConcurrentHashMap<>();
        udpChannels = new ConcurrentHashMap<>();
        startSelectorThread();
    }

    private void startSelectorThread() {
        Thread thread = new Thread(() -> {
            try {
                while (true) {
                    selector.select();
                    Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
                    while (keys.hasNext()) {
                        SelectionKey key = keys.next();
                        if (key.isAcceptable()) handleAccept(key);
                        else if (key.isReadable()) handleRead(key);
                        else if (key.isWritable()) handleWrite(key);
                        keys.remove();
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        });
        thread.start();
    }

    private void handleAccept(SelectionKey key) throws IOException {
        ServerSocketChannel serverSocketChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientChannel = serverSocketChannel.accept();
        clientChannel.configureBlocking(false);
        clientChannel.register(selector, SelectionKey.OP_READ);
        if (config.isTCP()) tcpConnections.put(clientChannel.getRemoteAddress().toString(), clientChannel);
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(config.getBufferSize());
        int bytesRead = channel.read(buffer);
        if (bytesRead == -1) {
            channel.close();
            tcpConnections.remove(channel.getRemoteAddress().toString());
        } else if (bytesRead > 0) {
            processBuffer(buffer, channel);
        }
    }

    private void handleWrite(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = (ByteBuffer) key.attachment();
        while (buffer.hasRemaining()) {
            channel.write(buffer);
        }
        if (!buffer.hasRemaining()) {
            key.interestOps(SelectionKey.OP_READ);
        }
    }

    private void processBuffer(ByteBuffer buffer, SocketChannel channel) {
        // Process the received data
    }

    public void sendTCPMessage(String address, String message) throws IOException {
        SocketChannel channel = tcpConnections.get(address);
        if (channel != null) {
            ByteBuffer buffer = ByteBuffer.wrap(message.getBytes());
            channel.register(selector, SelectionKey.OP_WRITE, buffer);
        }
    }

    public void sendUDPMessage(String address, int port, String message) throws IOException {
        DatagramChannel channel = udpChannels.computeIfAbsent(address + ":" + port, k -> {
            try {
                return DatagramChannel.open();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        });
        ByteBuffer buffer = ByteBuffer.wrap(message.getBytes());
        channel.send(buffer, new InetSocketAddress(address, port));
    }

    public void reconfigure(Configuration newConfig) {
        this.config = newConfig;
        // Reconfigure the network manager based on the new settings
    }

    public static class Configuration {
        private boolean isTCP;
        private int bufferSize;

        public Configuration(boolean isTCP, int bufferSize) {
            this.isTCP = isTCP;
            this.bufferSize = bufferSize;
        }

        public boolean isTCP() {
            return isTCP;
        }

        public int getBufferSize() {
            return bufferSize;
        }
    }
}
