#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define N 10 // Number of nodes in the linked list

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;
    return new_node;
}

Node* initialize_list(int N) {
    Node* head = create_node(0, 0, 0);
    Node* current = head;
    for (int i = 1; i < N; i++) {
        current->next = create_node(i, i * 2, i * 3);
        current = current->next;
    }
    return head;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int resolve_dns(const char* hostname, struct in_addr* ip_address) {
    struct hostent* host_info = gethostbyname(hostname);
    if (host_info == NULL) {
        herror("gethostbyname");
        return -1;
    }
    memcpy(ip_address, host_info->h_addr_list[0], sizeof(struct in_addr));
    return 0;
}

void retry_dns_resolution(const char* hostname, struct in_addr* ip_address, int max_retries, int delay) {
    for (int i = 0; i < max_retries; i++) {
        if (resolve_dns(hostname, ip_address) == 0) {
            break;
        }
        sleep(delay);
    }
}

int main() {
    Node* head = initialize_list(N);
    // Use the linked list and perform operations
    free_list(head);

    const char* hostname = "example.com";
    struct in_addr ip_address;
    retry_dns_resolution(hostname, &ip_address, 3, 2); // Retry up to 3 times with a delay of 2 seconds

    return 0;
}
