<?php

class ConfigManager {
    private $config;
    private $cache;

    public function __construct($environment) {
        $this->loadConfig($environment);
        $this->initCache();
    }

    private function loadConfig($environment) {
        $filePath = "config/{$environment}.yaml";
        if (file_exists($filePath)) {
            $this->config = yaml_parse_file($filePath);
        } else {
            throw new Exception("Configuration file not found for environment: {$environment}");
        }
    }

    private function initCache() {
        $this->cache = new Cache();
    }

    public function getSetting($key) {
        if ($this->cache->has($key)) {
            return $this->cache->get($key);
        } else {
            $value = $this->config[$key] ?? null;
            $this->cache->set($key, $value);
            return $value;
        }
    }

    public function updateSetting($key, $value) {
        $this->config[$key] = $value;
        $this->cache->set($key, $value);
        // Notify key management service to rotate sensitive keys
        if (strpos($key, 'secret') !== false) {
            KeyManagementService::rotateKey($key, $value);
        }
