use reqwest::Client;
use rand::{thread_rng, Rng};
use std::sync::{Arc, Mutex};

pub struct HttpClientBuilder {
    client: Client,
    base_url: String,
    disable_certificate_validation: bool,
    range_min: i32,
    range_max: i32,
    log_enabled: bool,
    external_data_source: Option<String>,
}

impl HttpClientBuilder {
    pub fn new(base_url: &str, disable_certificate_validation: bool) -> Self {
        HttpClientBuilder {
            client: Client::new(),
            base_url: base_url.to_string(),
            disable_certificate_validation,
            range_min: 0,
            range_max: 100,
            log_enabled: false,
            external_data_source: None,
        }
    }

    pub fn with_range(mut self, min: i32, max: i32) -> Self {
        if min < max {
            self.range_min = min;
            self.range_max = max;
        } else {
            eprintln!("Invalid range. Using default (0-100).");
        }
        self
    }

    pub fn with_logging(mut self, enabled: bool) -> Self {
        self.log_enabled = enabled;
        self
    }

    pub fn with_external_data_source(mut self, source: &str) -> Self {
        self.external_data_source = Some(source.to_string());
        self
    }

    pub fn build_request(&self) -> reqwest::RequestBuilder {
        let mut builder = self.client.get(&self.base_url);
        if self.disable_certificate_validation {
            // Assuming a method to disable certificate validation exists in reqwest
            builder = builder.dangerously_ignore_redirects();
        }
        builder
    }

    pub fn generate_random_int(&self) -> i32 {
        thread_rng().gen_range(self.range_min..=self.range_max)
    }

    pub fn generate_random_float(&self) -> f64 {
        thread_rng().gen_range(self.range_min as f64..=self.range_max as f64)
    }

    pub fn generate_random_vector<T>(&self, size: usize) -> Vec<T>
    where
        T: rand::distributions::Distribution<T> + Copy,
    {
        (0..size).map(|_| thread_rng().sample(T::Sampler)).collect()
    }

    pub fn generate_random_matrix<T>(&self, rows: usize, cols: usize) -> Vec<Vec<T>>
    where
        T: rand::distributions::Distribution<T> + Copy,
    {
        (0..rows)
            .map(|_| self.generate_random_vector(cols))
            .collect()
    }

    pub fn reset(&mut self) {
        *self = HttpClientBuilder::new(&self.base_url, self.disable_certificate_validation);
    }

    pub fn to_string(&self) -> String {
        format!(
            "HttpClientBuilder {{ base_url: {}, disable_certificate_validation: {}, range_min: {}, range_max: {}, log_enabled: {}, external_data_source: {:?} }}",
            self.base_url,
            self.disable_certificate_validation,
            self.range_min,
            self.range_max,
            self.log_enabled,
            self.external_data_source
        )
    }
}
