use std::process::{Command, Stdio};
use std::fs;
use std::time::{Instant, Duration};
use std::sync::{Arc, Mutex};
use std::collections::HashMap;

struct BuildContext {
    project_dir: String,
    dependencies: Vec<String>,
    features: Vec<String>,
    target_platform: Option<String>,
    optimization_level: u8,
}

impl BuildContext {
    fn new(project_dir: &str) -> Self {
        BuildContext {
            project_dir: project_dir.to_string(),
            dependencies: Vec::new(),
            features: Vec::new(),
            target_platform: None,
            optimization_level: 2, // Default to medium optimization
        }
    }

    fn add_dependency(&mut self, dep: &str) {
        self.dependencies.push(dep.to_string());
    }

    fn add_feature(&mut self, feature: &str) {
        self.features.push(feature.to_string());
    }

    fn set_target_platform(&mut self, platform: Option<&str>) {
        self.target_platform = platform.map(|p| p.to_string());
    }

    fn set_optimization_level(&mut self, level: u8) {
        if level >= 0 && level <= 3 {
            self.optimization_level = level;
        }
    }
}

fn compile_project(ctx: &BuildContext) -> Result<(String, Duration), String> {
    let start_time = Instant::now();
    let mut cargo_args = vec!["build"];

    if let Some(target) = ctx.target_platform.as_ref() {
        cargo_args.push("--target");
        cargo_args.push(target);
    }

    if !ctx.features.is_empty() {
        cargo_args.push("--features");
        cargo_args.extend(ctx.features.iter().map(|f| f.as_str()));
    }

    cargo_args.push("--release");
    cargo_args.push(&format!("--opt-level={}", ctx.optimization_level));

    let output = Command::new("cargo")
        .args(cargo_args)
        .current_dir(&ctx.project_dir)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
        .map_err(|e| format!("Failed to run cargo: {}", e))?;

    let duration = start_time.elapsed();
    if output.status.success() {
        Ok((String::from_utf8_lossy(&output.stdout).to_string(), duration))
    } else {
        Err(String::from_utf8_lossy(&output.stderr).to_string())
    }
}

fn main() {
    let mut ctx = BuildContext::new("path/to/project");
    ctx.add_dependency("some-dependency");
    ctx.set_target_platform(Some("x86_64-unknown-linux-gnu"));
    ctx.set_optimization_level(3);

    match compile_project(&ctx) {
        Ok((report, duration)) => println!("Build successful in {:?}\n{}", duration, report),
        Err(err) => eprintln!("Build failed: {}", err),
    }
}
```

