<?php

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp, $lastModifiedDate) {
    // Define valid statuses and transitions
    $validStatuses = ['active', 'inactive', 'suspended'];
    $statusTransitions = [
        'active' => ['inactive', 'suspended'],
        'inactive' => ['active', 'suspended'],
        'suspended' => ['active', 'inactive']
    ];

    // Validate input
    if (!is_numeric($clinicId) || !in_array($newStatus, $validStatuses)) {
        return "Invalid clinic ID or status.";
    }

    // Connect to the database with retry mechanism
    for ($retry = 0; $retry < 3; $retry++) {
        try {
            $db = new PDO('mysql:host=localhost;dbname=healthcare', 'username', 'password');
            $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
            break;
        } catch (PDOException $e) {
            if ($retry == 2) {
                return "Failed to connect to the database after multiple attempts.";
            }
            sleep(1); // Wait before retrying
        }
    }

    // Check current status and validate transition
    $stmt = $db->prepare("SELECT status FROM clinics WHERE id = :id FOR UPDATE");
    $stmt->execute(['id' => $clinicId]);
    $currentStatus = $stmt->fetchColumn();
    if (!in_array($newStatus, $statusTransitions[$currentStatus])) {
        return "Invalid transition from current status.";
    }

    // Update clinic status
    $stmt = $db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = :date WHERE id = :id");
    $stmt->execute(['status' => $newStatus, 'ip' => $lastModifiedIp, 'date' => $lastModifiedDate, 'id' => $clinicId]);

    // Log update attempt asynchronously
    logUpdateAttempt($clinicId, $newStatus, $lastModifiedIp, $lastModifiedDate);

    return "Clinic status updated successfully.";
}

function logUpdateAttempt($clinicId, $status, $ip, $date) {
    // Simulate external logging service with fallback mechanism
    try {
        // Asynchronous logging using cURL or similar
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, "https://logging-service.com/log");
        curl_setopt($ch, CURLOPT_POST, 1);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
            'timestamp' => time(),
            'error_message' => '',
            'clinic_id' => $clinicId
        ]));
        curl_setopt($ch, CURLOPT_TIMEOUT, 5); // Set timeout for external service
        curl_exec($ch);
        curl_close($ch);
    } catch (Exception $e) {
        // Fallback mechanism: log to local file or database
        error_log("Failed to log update attempt: " . $e->getMessage());
    }
}
