CREATE PROCEDURE GetEmployeeInfo
    @SupervisorID INT = NULL,
    @DepartmentName NVARCHAR(100) = NULL,
    @StartDate DATE = NULL,
    @EndDate DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @SQL NVARCHAR(MAX);
        DECLARE @Params NVARCHAR(MAX);

        SET @SQL = N'
            SELECT e.EmployeeName, e.City, e.Address, e.HireDate
            FROM Employees e
            WHERE e.IsActive = 1 AND DATEDIFF(YEAR, e.HireDate, GETDATE()) >= 1';

        IF @SupervisorID IS NOT NULL
        BEGIN
            SET @SQL += N' AND e.SupervisorID = @SupervisorID';
        END

        IF @DepartmentName IS NOT NULL
        BEGIN
            SET @SQL += N' AND e.DepartmentName = @DepartmentName';
        END

        IF @StartDate IS NOT NULL AND @EndDate IS NOT NULL
        BEGIN
            SET @SQL += N' AND e.HireDate BETWEEN @StartDate AND @EndDate';
        END

        SET @Params = N'@SupervisorID INT, @DepartmentName NVARCHAR(100), @StartDate DATE, @EndDate DATE';

        EXEC sp_executesql @SQL, @Params, @SupervisorID, @DepartmentName, @StartDate, @EndDate;
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000);
        DECLARE @ErrorSeverity INT;
        DECLARE @ErrorState INT;

        SELECT 
            @ErrorMessage = ERROR_MESSAGE(),
            @ErrorSeverity = ERROR_SEVERITY(),
            @ErrorState = ERROR_STATE();

        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
