<?php

class SecureStringGenerator {
    private $characterSet;
    private $hashAlgorithm;
    private $rateLimit;
    private $cache;

    public function __construct($characterSet, $hashAlgorithm = 'sha256', $rateLimit = 10) {
        $this->characterSet = $characterSet;
        $this->hashAlgorithm = $hashAlgorithm;
        $this->rateLimit = $rateLimit;
        $this->cache = new Cache();
    }

    public function generateRandomString($length) {
        if (!$this->isValidCharacterSet()) {
            throw new Exception('Character set must include at least one uppercase letter, one lowercase letter, one digit, and one special character.');
        }

        return substr(str_shuffle(str_repeat($this->characterSet, ceil($length / strlen($this->characterSet)))), 1, $length);
    }

    public function hashPassword($password) {
        if ($this->isRateLimited()) {
            throw new Exception('Too many attempts. Please try again later.');
        }

        $hashedPassword = password_hash($password, PASSWORD_BCRYPT);

        $this->cache->set($password, $hashedPassword);
        return $hashedPassword;
    }

    private function isValidCharacterSet() {
        return preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^\da-zA-Z]).+$/', $this->characterSet) > 0;
    }

    private function isRateLimited() {
        $ip = $_SERVER['REMOTE_ADDR'];
        $currentTime = time();
        $lastAttemptTime = $this->cache->get($ip . '_last_attempt');

        if ($lastAttemptTime && $currentTime - $lastAttemptTime < 60) {
            $attempts = (int)$this->cache->get($ip . '_attempts') + 1;
            if ($attempts >= $this->rateLimit) {
                return true;
            }
            $this->cache->set($ip . '_attempts', $attempts);
        } else {
            $this->cache->set($ip . '_last_attempt', $currentTime);
            $this->cache->set($ip . '_attempts', 1);
        }

        return false;
    }
}

class Cache {
    private $data = [];

    public function set($key, $value) {
        $this->data[$key] = $value;
    }

    public function get($key) {
        return isset($this->data[$key]) ? $this->data[$key] : null;
    }
}

// Usage example
$generator = new SecureStringGenerator('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()');
echo $generator->generateRandomString(10);

$password = 'mySecurePassword';
try {
    echo $generator->hashPassword($password);
} catch (Exception $e) {
    echo $e->getMessage();
}
?>
