#include <iostream>
#include <forward_list>
#include <string>
#include <fstream>
#include <openssl/pem.h>

bool processOAuthRequestAndModifyList(const OAuthRequest& request, std::forward_list<std::string>& list, const std::string& insertBefore, const std::string& insertAfter) {
    try {
        // Parse the OAuth request to get paths
        std::string privateKeyPath = request.getPrivateKeyPath();
        std::string certificatePath = request.getCertificatePath();

        // Check if paths are valid
        if (privateKeyPath.empty() || certificatePath.empty()) {
            std::cerr << "Invalid paths in OAuth request." << std::endl;
            return false;
        }

        // Combine into a single PEM file
        std::ofstream pemFile("combined.pem", std::ios::binary);
        if (!pemFile.is_open()) {
            std::cerr << "Failed to create PEM file." << std::endl;
            return false;
        }

        // Read private key and certificate files
        std::ifstream privateKey(privateKeyPath, std::ios::binary);
        std::ifstream certificate(certificatePath, std::ios::binary);

        if (!privateKey.is_open() || !certificate.is_open()) {
            std::cerr << "Failed to open private key or certificate file." << std::endl;
            return false;
        }

        // Write private key and certificate to PEM file
        pemFile.write(privateKey.rdbuf()->data(), privateKey.rdbuf()->in_avail());
        pemFile.write(certificate.rdbuf()->data(), certificate.rdbuf()->in_avail());

        privateKey.close();
        certificate.close();
        pemFile.close();

        // Ensure the certificate is correctly formatted
        FILE* pemFP = fopen("combined.pem", "r");
        if (!pemFP) {
            std::cerr << "Failed to open PEM file for formatting." << std::endl;
            return false;
        }

        X509* cert = PEM_read_X509(pemFP, nullptr, nullptr, nullptr);
        fclose(pemFP);

        if (!cert) {
            std::cerr << "Certificate is not correctly formatted." << std::endl;
            return false;
        }

        // Insert the second string parameter into the forward list
        auto it = std::find(list.begin(), list.end(), insertBefore);
        if (it != list.end()) {
            list.insert_after(it, insertAfter);
        } else {
            list.push_back(insertAfter);
        }

        X509_free(cert);

        return true;
    } catch (const std::exception& e) {
        std::cerr << "Error processing OAuth request: " << e.what() << std::endl;
        return false;
    }
}
