    public function logout() {
        session_start();
        unset($_SESSION[$this->sessionName]);
        unset($_SESSION['user_info']);
        session_destroy();
    }

    public function logAuthAttempt($success, $message) {
        $logEntry = date('Y-m-d H:i:s') . ' - ' . ($success ? 'SUCCESS' : 'ERROR') . ': ' . $message . PHP_EOL;
