                    throw new Exception("Password does not meet complexity requirements");
                }

                if ($this->passwordHistoryDAO->checkPasswordHistory($userId, $newHashedPassword)) {
                    throw new Exception("New password is too similar to previous ones");
                }

                // Log attempt
                $this->logAttempt($userId, $newHashedPassword, true);

                // Update password and add to history
                $this->passwordUpdateDAO->updatePassword($userId, $newHashedPassword);
                $this->passwordHistoryDAO->addPasswordToHistory($userId, $newHashedPassword);

                return true;
            } catch (Exception $e) {
                // Log failure
                $this->logAttempt($userId, $newHashedPassword, false, $e->getMessage());

                if ($retryCount < $this->maxRetries - 1) {
                    sleep(1); // Exponential backoff
                }

                $retryCount++;
            }
        }

        return false;
    }

