#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int Request_ID;
    int Status_Code;
    char Response_Body[1024];
    int ErrorFlag;
} HTTP_RESPONSE_PDU_T;

typedef struct Node {
    HTTP_RESPONSE_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;

void add_response_pdu(HTTP_RESPONSE_PDU_T response) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    new_node->data = response;
    new_node->next = head;
    head = new_node;
}

HTTP_RESPONSE_PDU_T* get_response_pdu(int request_id) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.Request_ID == request_id) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

void serialize_responses(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        return;
    }
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(HTTP_RESPONSE_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_responses(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Failed to open file for reading\n");
        return;
    }
    HTTP_RESPONSE_PDU_T response;
    while (fread(&response, sizeof(HTTP_RESPONSE_PDU_T), 1, file) == 1) {
        add_response_pdu(response);
    }
    fclose(file);
}

int main() {
    // Example usage
    HTTP_RESPONSE_PDU_T response = {12345, 200, "OK", 0};
    add_response_pdu(response);

    HTTP_RESPONSE_PDU_T* retrieved_response = get_response_pdu(12345);
    if (retrieved_response != NULL) {
        printf("Retrieved Response: Request-ID=%d, Status-Code=%d, Response-Body=%s\n",
               retrieved_response->Request_ID, retrieved_response->Status_Code, retrieved_response->Response_Body);
    }

    serialize_responses("responses.bin");
    deserialize_responses("responses.bin");

    return 0;
}
