                response_body = file.read(1024).decode('utf-8').rstrip('\x00')
                error_flag = struct.unpack('i', file.read(4))[0]
                responses.append(HTTP_RESPONSE_PDU_T(request_id, status_code, response_body, error_flag))
            except struct.error:
                break
    return responses

