State* constructStateSequence(int* initialStates, int numInitialStates, FSA* fsa, int lastState, bool loopBack, int maxLength, int maxRevisit) {
    State* sequence = (State*)malloc(maxLength * sizeof(State));
    if (!sequence) return NULL;

    for (int i = 0; i < numInitialStates; ++i) {
        sequence[i].id = initialStates[i];
        sequence[i].next = &sequence[(i + 1) % maxLength];
    }

    int currentStateId = lastState;
    int revisitCount[fsa->numStates] = {0};

    for (int i = numInitialStates; i < maxLength; ++i) {
        // Simulate transition based on FSA rules
        // For example:
        // currentStateId = fsa->states[currentStateId]->transitions[nextSymbol];

        if (++revisitCount[currentStateId] > maxRevisit) {
            free(sequence);
            return NULL;
        }

        sequence[i].id = currentStateId;
        sequence[i].next = &sequence[(i + 1) % maxLength];
    }

    if (loopBack) {
        sequence[maxLength - 1].next = sequence;
    } else {
        sequence[maxLength - 1].next = NULL;
    }

    return sequence;
}
