};

class GameCharacter {
public:
    void performAttack(GameServerHandler& serverHandler) {
        if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - lastAttackTime).count() < COOLDOWN_SECONDS) {
            std::cout << "Cooldown period not yet over. Please wait." << std::endl;
            return;
        }

        try {
            serverHandler.fetchAttackStats();
            serverHandler.fetchUserProfile();

            int attack = std::rand() % 3 + 1; // Randomly select an attack (1, 2, or 3)
