char* process_string(const char* source, size_t size_limit, bool null_terminate) {
    if (source == NULL || size_limit == 0) {
        return NULL;
    }

    size_t source_len = strlen(source);
    if (source_len >= size_limit) {
        source_len = size_limit - 1;
    }

    char* result = (char*)malloc((source_len + 2) * sizeof(char));
    if (result == NULL) {
        return NULL;
    }

    strncpy(result, source, source_len);
    result[source_len] = '\0';

    if (null_terminate && source_len < size_limit - 1) {
        result[source_len++] = '/';
    }

    return result;
}
