#define MAX_FILENAME_LENGTH 256

char* modify_filename_with_timestamp(const char* filename, const char* file_type) {
    // Extract directory path, base name, and extension
    char* dir_path = strdup(filename);
    char* base_name = strrchr(dir_path, '/');
    if (base_name != NULL) {
        *base_name++ = '\0';
    } else {
        base_name = dir_path;
        dir_path = "";
    }
    char* ext = strrchr(base_name, '.');
    if (ext != NULL) {
        *ext++ = '\0';
    }

    // Generate unique timestamp
    time_t now = time(NULL);
    struct tm* tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tm_info);

    // Determine sequence number
    int seq_num = 1;
    DIR* dir = opendir(dir_path);
    if (dir != NULL) {
        struct dirent* entry;
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, base_name, strlen(base_name)) == 0 &&
                strcmp(strrchr(entry->d_name, '.'), ext) == 0) {
                seq_num++;
            }
        }
        closedir(dir);
    }

    // Construct new filename
    size_t new_filename_len = strlen(dir_path) + strlen(base_name) +
                             strlen(ext) + strlen(timestamp) +
                             strlen(file_type) + 1;
    if (new_filename_len > MAX_FILENAME_LENGTH) {
        new_filename_len = MAX_FILENAME_LENGTH;
    }
    char* new_filename = malloc(new_filename_len);
    if (new_filename == NULL) {
        free(dir_path);
        return NULL;
    }

    snprintf(new_filename, new_filename_len, "%s%s.%s_%d.%s",
             dir_path, base_name, timestamp, seq_num, file_type);

    // Clean up
    free(dir_path);

    return new_filename;
}
