#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_JOB_QUEUE_SIZE 100

typedef struct {
    char image_path[MAX_FILENAME_LENGTH];
    char pdf_path[MAX_FILENAME_LENGTH];
    int priority;
    time_t estimated_time;
} Job;

Job job_queue[MAX_JOB_QUEUE_SIZE];
int queue_size = 0;

void add_job(const char* image_path, const char* pdf_path, int priority, time_t estimated_time) {
    if (queue_size < MAX_JOB_QUEUE_SIZE) {
        strcpy(job_queue[queue_size].image_path, image_path);
        strcpy(job_queue[queue_size].pdf_path, pdf_path);
        job_queue[queue_size].priority = priority;
        job_queue[queue_size].estimated_time = estimated_time;
        queue_size++;
    }
}

void process_jobs() {
    while (queue_size > 0) {
        int max_priority = -1;
        int max_index = -1;

        for (int i = 0; i < queue_size; i++) {
            if (job_queue[i].priority > max_priority) {
                max_priority = job_queue[i].priority;
                max_index = i;
            }
        }

        if (max_index != -1) {
            char command[MAX_FILENAME_LENGTH * 2];
            snprintf(command, sizeof(command), "convert %s %s", job_queue[max_index].image_path, job_queue[max_index].pdf_path);
            int pid = fork();
            if (pid == 0) {
                system(command);
                exit(0);
            } else if (pid > 0) {
                wait(NULL);
                memmove(&job_queue[max_index], &job_queue[max_index + 1], sizeof(Job) * (queue_size - max_index - 1));
                queue_size--;
            }
        }
    }
}

int main() {
    DIR* dir = opendir(".");
    if (dir == NULL) {
        perror("opendir");
        return 1;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
