    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    size_t capacity;
} DynamicList;

DynamicList* create_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= list->capacity) {
        // Resize logic here
        return -1; // Return error code for resize failure
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    // CRCFLAG check and RNTI range validation logic here

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(DynamicList* list, size_t index) {
    if (index >= list->size) return NULL;

    Node* current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }

    return &current->data;
}

void log_operation(DynamicList* list, const char* operation) {
    // Logging logic here
}

