            printf("Item %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%u, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
                   i, item->RX_UE_INFORMATION_TAG, item->RNTI, item->CRC_INDICATION_REL8_TAG, item->CRCFLAG);
        }
