typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_POOL_T;

NFAPI_CRC_INDICATION_POOL_T* create_pool(size_t N) {
    NFAPI_CRC_INDICATION_POOL_T *pool = (NFAPI_CRC_INDICATION_POOL_T*)malloc(sizeof(NFAPI_CRC_INDICATION_POOL_T));
    if (!pool) return NULL;

    pool->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->entries) {
        free(pool);
        return NULL;
    }

    pool->count = N;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_pool(NFAPI_CRC_INDICATION_POOL_T *pool) {
    if (pool) {
        free(pool->entries);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int add_entry(NFAPI_CRC_INDICATION_POOL_T *pool, uint16_t RNTI, RX_UE_INFORMATION_TAG tag, uint8_t CRCFLAG) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (!pool->entries[i].RNTI) {
            pool->entries[i].RNTI = RNTI;
            pool->entries[i].tag = tag;
            pool->entries[i].CRCFLAG = CRCFLAG;
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // Pool is full
}

