#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

int execute_and_manage_bundle(const char *command, const char *file_path) {
    pid_t pid;
    int status;
    FILE *bundle_file = fopen(file_path, "r");
    if (!bundle_file) {
        perror("Failed to open resource bundle file");
        return 0;
    }

    // Count items in the bundle
    int item_count = 0;
    char line[256];
    while (fgets(line, sizeof(line), bundle_file)) {
        item_count++;
    }
    fclose(bundle_file);

    pid = fork();
    if (pid == -1) {
        perror("Failed to fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("Failed to execute command");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Command execution failed\n");
            return 0;
        }
    }

    return item_count;
}
