public class WebsiteManager
{
    private static readonly object _lock = new object();
    private static bool _isAddingWebsite = false;

    public Process AddAndStartWebsite(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
        {
            LogError("Directory does not exist: " + directoryPath);
            return null;
        }

        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            LogError("Missing web.config file in directory: " + directoryPath);
            return null;
        }

        lock (_lock)
        {
            if (_isAddingWebsite)
            {
                LogInfo("Another instance is already adding a website. Waiting...");
                while (_isAddingWebsite)
                {
                    Thread.Sleep(100); // Wait for 100ms before checking again
                }
            }

            _isAddingWebsite = true;
        }

        try
        {
            Process process = new Process();
            process.StartInfo.FileName = "dotnet";
            process.StartInfo.Arguments = $"run --project {directoryPath}";
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.CreateNoWindow = true;

            process.OutputDataReceived += (sender, e) => LogInfo(e.Data);
            process.ErrorDataReceived += (sender, e) => LogError(e.Data);

            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            return process;
        }
        catch (Exception ex)
        {
            LogError("Failed to start website: " + ex.Message);
            return null;
        }
        finally
        {
            lock (_lock)
            {
                _isAddingWebsite = false;
            }
        }
    }

    private static void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    private static void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}
