public class JwtTokenProcessor
{
    private readonly string _keyServerUrl;
    private readonly string _corporateDirectoryUrl;
    private readonly TimeSpan _gracePeriod;
    private readonly HttpClient _httpClient;

    public JwtTokenProcessor(string keyServerUrl, string corporateDirectoryUrl, TimeSpan gracePeriod)
    {
        _keyServerUrl = keyServerUrl;
        _corporateDirectoryUrl = corporateDirectoryUrl;
        _gracePeriod = gracePeriod;
        _httpClient = new HttpClient();
    }

    public async Task<Dictionary<string, object>> ProcessTokenAsync(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var validationParameters = new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = await GetPublicKeyAsync(),
            ValidateIssuer = false,
            ValidateAudience = false,
            ClockSkew = _gracePeriod
        };

        try
        {
            var principal = tokenHandler.ValidateToken(token, validationParameters, out _);
            return ExtractUserInfo(principal);
        }
        catch (Exception)
        {
            // Handle token validation failure gracefully
            return null;
        }
    }

    private async Task<SecurityKey> GetPublicKeyAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync(_keyServerUrl);
            response.EnsureSuccessStatusCode();
            var publicKeyJson = await response.Content.ReadAsStringAsync();
            // Parse the public key from JSON and return it as a SecurityKey
            return new SymmetricSecurityKey(System.Text.Encoding.UTF8.GetBytes(publicKeyJson));
        }
        catch (HttpRequestException)
        {
            // Handle network issues by returning a cached public key or default
            return new SymmetricSecurityKey(System.Text.Encoding.UTF8.GetBytes("CachedPublicKey"));
        }
    }

    private Dictionary<string, object> ExtractUserInfo(ClaimsPrincipal principal)
    {
        var userInfo = new Dictionary<string, object>
        {
            { "Username", principal.FindFirstValue(ClaimTypes.Name) },
            { "Role", principal.FindFirstValue(ClaimTypes.Role) }
        };
        return userInfo;
    }

    public async Task<Dictionary<string, object>> RefreshTokenAsync(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var validationParameters = new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = await GetPublicKeyAsync(),
            ValidateIssuer = false,
            ValidateAudience = false,
            ClockSkew = _gracePeriod
        };

        try
        {
            var principal = tokenHandler.ValidateToken(token, validationParameters, out var securityToken);
            if (securityToken is JwtSecurityToken jwtToken && IsTokenExpiring(jwtToken))
            {
                // Refresh the token logic here
                return await ProcessTokenAsync(token); // Simplified for example
            }
        }
        catch (Exception)
        {
            // Handle token validation failure gracefully
            return null;
        }

        return null;
    }

    private bool IsTokenExpiring(JwtSecurityToken jwtToken)
    {
        var expirationTime = jwtToken.ValidTo;
        var currentTime = DateTime.UtcNow;
        return expirationTime - currentTime <= _gracePeriod;
    }
}
