import java.io.*;
import java.util.concurrent.*;

public class ObjectDeserializer {

    private static final long TIMEOUT = 5000; // 5 seconds
    private static final int MAX_SIZE = 1024 * 1024; // 1 MB

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws DeserializationTimeoutException {
        if (data == null || data.length > MAX_SIZE) {
            throw new IllegalArgumentException("Invalid byte array size");
        }

        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<Object> future = executor.submit(() -> {
            try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
                return clazz.cast(ois.readObject());
            } catch (IOException | ClassNotFoundException e) {
                if (e instanceof IOException && "Stream closed".equals(e.getMessage())) {
                    throw new DeserializationTimeoutException("Deserialization timed out", e);
                }
                return null;
            }
        });

        try {
            return clazz.cast(future.get(TIMEOUT, TimeUnit.MILLISECONDS));
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            future.cancel(true);
            if (e instanceof TimeoutException) {
                throw new DeserializationTimeoutException("Deserialization timed out", e);
            }
            return null;
        } finally {
            executor.shutdownNow();
        }
    }

    public static class DeserializationTimeoutException extends Exception {
        public DeserializationTimeoutException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
```

