    int cellId;
    int tti;
    float channelQuality;
    MeasurementReport *reports;
    size_t reportCount;
    size_t maxReports;
} LTEPHYChannelStats;

LTEPHYChannelStats* initLTEPHYChannelStats(int cellId, int tti, float channelQuality) {
    LTEPHYChannelStats *stats = (LTEPHYChannelStats*)malloc(sizeof(LTEPHYChannelStats));
    if (!stats) return NULL;

    stats->cellId = cellId;
    stats->tti = tti;
    stats->channelQuality = channelQuality;
    stats->reports = (MeasurementReport*)calloc(1000, sizeof(MeasurementReport));
    if (!stats->reports) {
        free(stats);
        return NULL;
    }
    stats->reportCount = 0;
    stats->maxReports = 1000;

    return stats;
}

void addMeasurementReport(LTEPHYChannelStats *stats, int timestamp, float signalStrength) {
    if (stats->reportCount >= stats->maxReports) {
        MeasurementReport *newReports = (MeasurementReport*)realloc(stats->reports, stats->maxReports * 2 * sizeof(MeasurementReport));
        if (!newReports) return;
        stats->reports = newReports;
        stats->maxReports *= 2;
    }
    stats->reports[stats->reportCount].timestamp = timestamp;
    stats->reports[stats->reportCount].signalStrength = signalStrength;
    stats->reportCount++;
}

void freeLTEPHYChannelStats(LTEPHYChannelStats *stats) {
    if (stats->reports) free(stats->reports);
    free(stats);
}
