use tokio::sync::Mutex as AsyncMutex;
use log::{info, error, warn};

struct DirectoryManager {
    directory_path: PathBuf,
    env_var_name: String,
    logger: Arc<AsyncLogger>,
}

impl DirectoryManager {
    fn new(directory_path: PathBuf, env_var_name: String, logger: Arc<AsyncLogger>) -> Self {
        DirectoryManager {
            directory_path,
            env_var_name,
            logger,
        }
    }

    async fn create_directory(&self) -> Result<(), Box<dyn std::error::Error>> {
        if !self.directory_path.exists() {
            fs::create_dir_all(&self.directory_path)?;
            info!(logger: &*self.logger, "Directory created: {:?}", self.directory_path);
        } else {
            info!(logger: &*self.logger, "Directory already exists: {:?}", self.directory_path);
        }
        Ok(())
    }

    async fn set_env_variable(&self) -> Result<(), Box<dyn std::error::Error>> {
        let current_dir = env::current_dir()?;
        if let Some(env_var_value) = env::var_os(&self.env_var_name) {
            if Path::new(&env_var_value).exists() {
                env::set_var(&self.env_var_name, &current_dir);
                info!(logger: &*self.logger, "Updated environment variable {} to {:?}", self.env_var_name, current_dir);
            } else {
                env::set_var(&self.env_var_name, &current_dir);
                info!(logger: &*self.logger, "Set environment variable {} to {:?}", self.env_var_name, current_dir);
            }
        } else {
            env::set_var(&self.env_var_name, &current_dir);
            info!(logger: &*self.logger, "Set environment variable {} to {:?}", self.env_var_name, current_dir);
        }
        Ok(())
    }

    async fn retry_operation<F>(&self, operation: F) -> Result<(), Box<dyn std::error::Error>>
    where
        F: Fn() -> Result<(), Box<dyn std::error::Error>>,
    {
        for attempt in 1..=3 {
            match operation() {
                Ok(_) => return Ok(()),
                Err(e) => {
                    warn!(logger: &*self.logger, "Attempt {} failed: {}", attempt, e);
                    tokio::time::sleep(Duration::from_secs(1)).await;
                }
            }
        }
        error!(logger: &*self.logger, "Operation failed after 3 attempts");
        Err("Operation failed".into())
    }

    async fn manage_directory(&self) -> Result<(), Box<dyn std::error::Error>> {
        self.retry_operation(|| self.create_directory()).await?;
        self.retry_operation(|| self.set_env_variable()).await?;
        Ok(())
    }
}

