#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_PACKETS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->pool_size = initial_size;
    mp->used_count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_packet(MemoryPool *mp) {
    NFAPI_CRC_INDICATION_PDU_T *packet = NULL;
    pthread_mutex_lock(&mp->lock);
    if (mp->used_count < mp->pool_size) {
        packet = &mp->pool[mp->used_count++];
    }
    pthread_mutex_unlock(&mp->lock);
    return packet;
}

void free_packet(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *packet) {
    pthread_mutex_lock(&mp->lock);
    // Assuming packets are freed in the order they were allocated
    if (packet >= mp->pool && packet < &mp->pool[mp->used_count]) {
        mp->used_count--;
    }
    pthread_mutex_unlock(&mp->lock);
}

void generate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *packet) {
    // Pseudo-random sequence generator for CRCFLAG
    static uint32_t seed = 12345;
    seed = (seed * 1664525 + 1013904223) % UINT32_MAX;
    packet->CRC_INDICATION_REL8_TAG = (uint8_t)(seed & 0xFF);
}

void initialize_packets(MemoryPool *mp, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *packet = allocate_packet(mp);
        if (packet) {
            packet->RX_UE_INFORMATION_TAG = i;
            packet->RNTI = i % 16384;
            generate_crc_indication(packet);
        }
    }
}

void iterate_packets(MemoryPool *mp, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->used_count; ++i) {
        callback(&mp->pool[i]);
    }
    pthread_mutex_unlock(&mp->lock);
}

void log_event(const char *message) {
    // Simple logging function
    printf("LOG: %s\n", message);
}
