void* thread_function(void* arg) {
    int num_pdus = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdus = create_and_populate_pdus(num_pdus);
    if (pdus) {
        // Process PDUs
        free(pdus);
    }
    return NULL;
}

int main() {
