#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <mutex>
#include <json/json.h>

class DynamicRecordCollection {
private:
    struct Record {
        long offset;
        int key;
        double value;
    };

    std::vector<Record> records;
    std::mutex mutex;

public:
    DynamicRecordCollection(size_t size) : records(size) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 100.0);

        for (auto& record : records) {
            record.offset = rand();
            record.key = rand() % 1000; // Assuming keys are within a small range
            record.value = dis(gen);
        }
    }

    void updateValue(int key, double newValue) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& record : records) {
            if (record.key == key) {
                record.value = newValue;
                return;
            }
        }
        // Handle the case where the key does not exist
    }

    void resize(size_t newSize) {
        std::lock_guard<std::mutex> lock(mutex);
        records.resize(newSize);
    }

    std::string toJson() const {
        Json::Value root;
        for (const auto& record : records) {
            Json::Value item;
            item["offset"] = record.offset;
            item["key"] = record.key;
            item["value"] = record.value;
            root.append(item);
        }
        return root.toStyledString();
    }

    static DynamicRecordCollection fromJson(const std::string& jsonStr) {
        Json::Value root = Json::parse(jsonStr);
        DynamicRecordCollection collection(root.size());
        for (size_t i = 0; i < root.size(); ++i) {
            collection.records[i].offset = root[i]["offset"].asLong();
            collection.records[i].key = root[i]["key"].asInt();
            collection.records[i].value = root[i]["value"].asDouble();
        }
        return collection;
    }

    // Additional methods for factory functions, external data source integration,
    // and memory management can be added here.
};
