# Python code for JWT management

import hmac
import hashlib
from time import time
from functools import lru_cache

class JWTManager:
    def __init__(self, secret_key):
        self.secret_key = secret_key.encode('utf-8')

    @lru_cache(maxsize=128)
    def generate_token(self, user_id, issuer):
        payload = f"{user_id}|{issuer}|{int(time())}"
        signature = hmac.new(self.secret_key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
        return f"{payload}.{signature}"

# Example usage
jwt_manager = JWTManager("your_secret_key")
token = jwt_manager.generate_token(123, "example_issuer")
print(token)
```

