#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define GROWTH_FACTOR 2

typedef struct {
    struct timeval timestamp;
    char source_ip[INET_ADDRSTRLEN];
    char destination_ip[INET_ADDRSTRLEN];
    int payload_length;
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);
        freeaddrinfo(res); // Free the linked list
        return 0;
    }

    freeaddrinfo(res); // Free the linked list if no address found
    return -1;
}

int add_packet(PacketArray *array, NetworkPacket packet) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        NetworkPacket *new_packets = realloc(array->packets, new_capacity * sizeof(NetworkPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Additional functions for updating packets, iterating over the array,
// calculating total data transferred, and cleaning up unused entries
// would be implemented here.

int main() {
    PacketArray packet_array;
    pthread_mutex_init(&packet_array.lock, NULL);

    // Example usage:
    NetworkPacket new_packet = {0};
    gettimeofday(&new_packet.timestamp, NULL);
    strcpy(new_packet.source_ip, "192.168.1.1");
    strcpy(new_packet.destination_ip, "8.8.8.8");
    new_packet.payload_length = 1024;

    if (add_packet(&packet_array, new_packet) == -1) {
        fprintf(stderr, "Failed to add packet\n");
    }

    // Clean up and destroy mutex
    pthread_mutex_destroy(&packet_array.lock);
    free(packet_array.packets);

    return 0;
}
