typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t mutex;
} PDU_LIST_T;

void initialize_pdu_list(PDU_LIST_T *list, size_t count) {
    list->count = count;
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
}

void populate_pdu_list(PDU_LIST_T *list) {
    srand(time(NULL));

    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_lock(&list->mutex);

        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pdus[i];
        pdu->RX_UE_INFORMATION_TAG = i + 1;
        pdu->RNTI = rand() % (MAX_RNTI + 1);
        pdu->CRC_INDICATION_REL8_TAG = i + 100;
        pdu->CRCFLAG = rand() % 2;

        // Log creation of PDU with timestamp and unique identifier
        time_t now = time(NULL);
        printf("PDU created at %s, ID: %zu\n", ctime(&now), i);

        pthread_mutex_unlock(&list->mutex);
    }
}

void destroy_pdu_list(PDU_LIST_T *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
}
