#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void iterate_list(DynamicList* list, void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        operation(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_crcflag(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Example operation: Toggle CRCFLAG
    data->CRCFLAG = !data->CRCFLAG;
}

int main() {
    DynamicList* list = create_list();
    if (!list) return -1;

    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = rand() % 1000,
            .CRC_INDICATION_REL8_TAG = rand() % 10000,
            .CRCFLAG = rand() % 2
        };
        if (add_to_list(list, data) != 0) {
            destroy_list(list);
            return -1;
        }
    }

    iterate_list(list, update_crcflag);

    destroy_list(list);
    return 0;
}
