void initLogArray(LogArray* logArray, size_t initialCapacity) {
    logArray->entries = (LogEntry*)malloc(initialCapacity * sizeof(LogEntry));
    if (logArray->entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    logArray->count = 0;
    logArray->capacity = initialCapacity;
}

void resizeLogArray(LogArray* logArray) {
    size_t newCapacity = logArray->capacity * 2;
    LogEntry* newEntries = (LogEntry*)realloc(logArray->entries, newCapacity * sizeof(LogEntry));
    if (newEntries == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    logArray->entries = newEntries;
    logArray->capacity = newCapacity;
}

void addLogEntry(LogArray* logArray, LogEntry entry) {
    if (logArray->count >= logArray->capacity * 0.8) {
        resizeLogArray(logArray);
    }
    logArray->entries[logArray->count++] = entry;
}

void updateLogEntry(LogArray* logArray, int index, LogEntry newEntry) {
    if (index < 0 || index >= logArray->count) {
        fprintf(stderr, "Invalid index\n");
        return;
    }
    logArray->entries[index] = newEntry;
}

void deleteLogEntry(LogArray* logArray, int index) {
    if (index < 0 || index >= logArray->count) {
        fprintf(stderr, "Invalid index\n");
        return;
    }
    for (size_t i = index; i < logArray->count - 1; ++i) {
        logArray->entries[i] = logArray->entries[i + 1];
    }
    --logArray->count;
}

void iterateLogArray(LogArray* logArray, void (*callback)(LogEntry*)) {
    for (size_t i = 0; i < logArray->count; ++i) {
        callback(&logArray->entries[i]);
    }
}

int filterByUserID(LogArray* logArray, int userID) {
