int allocate_memory(int offsets_size, int keys_size, record **records_ptr, long **offsets_ptr, int **keys_ptr) {
    size_t total_size = (size_t)offsets_size * sizeof(long) + 
                        (size_t)keys_size * sizeof(int) + 
                        (size_t)keys_size * sizeof(record);

    if (total_size > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory allocation exceeds threshold.\n");
        return -1;
    }

    *offsets_ptr = (long *)malloc(offsets_size * sizeof(long));
    *keys_ptr = (int *)malloc(keys_size * sizeof(int));
    *records_ptr = (record *)malloc(keys_size * sizeof(record));

    if (!*offsets_ptr || !*keys_ptr || !*records_ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(*offsets_ptr);
        free(*keys_ptr);
        free(*records_ptr);
        return -1;
