    for (int i = 0; i < keys_size; ++i) {
        int key;
        do {
            key = rand() % 1001; // Generate a random number between 0 and 1000
        } while (!validate_key(key));

        (*keys_ptr)[i] = key;
        initialize_record(&(*records_ptr)[i], key);
    }

    return 0;
}

void free_memory(long *offsets, int *keys, record *records) {
