const fs = require('fs').promises;
const path = require('path');
const Ajv = require('ajv');

async function processFiles(directory, schema) {
  const ajv = new Ajv();
  const validate = ajv.compile(schema);
  const results = [];

  try {
    const files = await fs.readdir(directory);

    for (const file of files) {
      const filePath = path.join(directory, file);
      const fileContent = await fs.readFile(filePath, 'utf8');
      const data = JSON.parse(fileContent);

      if (!validate(data)) {
        console.error(`Validation error in ${file}:`, validate.errors);
        continue;
      }

      results.push(data);
    }
  } catch (error) {
    console.error('Error processing files:', error);
  }

  return results;
}

// Example usage:
const directoryPath = './data';
const jsonSchema = {
  type: 'object',
  properties: {
    name: { type: 'string' },
    age: { type: 'number' }
  },
  required: ['name', 'age'],
  additionalProperties: false
};

processFiles(directoryPath, jsonSchema)
  .then(validatedData => console.log('Validated Data:', validatedData))
  .catch(error => console.error('Error:', error));
```

This code snippet demonstrates how to asynchronously process multiple files from a specified directory using JavaScript. It uses the `fs.promises` module for file operations and the `ajv` library for JSON schema validation. The function reads each file, parses its content as JSON, validates it against a provided schema, and collects all validated objects in an array. Error handling and logging mechanisms are integrated to provide detailed feedback for each file processed.

The solution is designed to handle large datasets efficiently by minimizing memory usage and preventing race conditions through sequential processing of files. It can be easily integrated into an existing codebase while maintaining backward compatibility with minimal changes. The use of `async/await` ensures that the function scales gracefully with an increasing number of files, optimizing for both throughput and latency.

Different approaches for managing file buffering and asynchronous processing are considered to balance between memory usage and performance. The impact of varying file sizes and the frequency of schema updates on the overall system is also taken into account."]

