#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_crc_list() {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRCList *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_indication(CRCList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        // Handle potential buffer overflow
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    for (size_t i = 0; i < list->count; ++i) {
        if (list->elements[i].RNTI == RNTI) {
            // Prevent duplicate RNTI values
            pthread_mutex_unlock(&list->lock);
            return -2;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T new_element = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG};
    list->elements[list->count++] = new_element;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Example usage
int main() {
    CRCList *crc_list = create_crc_list();
    add_crc_indication(crc_list, 1, 2, 3, 4);
    // Add more elements as needed
    destroy_crc_list(crc_list);
    return 0;
}
