#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a custom data structure for network packets
typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_length;
} NetworkPacket;

// Define a dynamic array structure to manage network packets
typedef struct {
    NetworkPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

// Function to initialize the packet array
void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->packets = (NetworkPacket *)malloc(initial_capacity * sizeof(NetworkPacket));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

// Function to add a new packet to the array
void add_packet(PacketArray *array, NetworkPacket packet) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->packets = (NetworkPacket *)realloc(array->packets, array->capacity * sizeof(NetworkPacket));
    }
    array->packets[array->count++] = packet;
    pthread_mutex_unlock(&array->lock);
}

// Function to update an existing packet in the array
void update_packet(PacketArray *array, size_t index, NetworkPacket new_packet) {
    pthread_mutex_lock(&array->lock);
    if (index < array->count) {
        array->packets[index] = new_packet;
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to iterate over the array and calculate total data transferred
size_t calculate_total_data_transferred(PacketArray *array) {
    size_t total_data = 0;
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; i++) {
        total_data += array->packets[i].payload_length;
    }
    pthread_mutex_unlock(&array->lock);
    return total_data;
}

// Function to retrieve network statistics and debug information
void get_network_statistics(PacketArray *array) {
    pthread_mutex_lock(&array->lock);
    printf("Total packets: %zu\n", array->count);
    printf("Total data transferred: %zu bytes\n", calculate_total_data_transferred(array));
    pthread_mutex_unlock(&array->lock);
}

// Function to free the memory allocated for the packet array
void free_packet_array(PacketArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    pthread_mutex_unlock(&array->lock);
}
