#define MAX_ELEMENTS 5000

typedef struct {
    int CELL_ID;
    // Other fields...
} MEASUREMENT_OBJECT;

typedef struct {
    MEASUREMENT_OBJECT object;
    // Other fields...
} MEASUREMENT_RESULT;

typedef struct {
    MEASUREMENT_RESULT *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_RRC_MEASUREMENT_REPORT_T;

LTE_RRC_MEASUREMENT_REPORT_T* create_measurement_report() {
    LTE_RRC_MEASUREMENT_REPORT_T *report = (LTE_RRC_MEASUREMENT_REPORT_T*)malloc(sizeof(LTE_RRC_MEASUREMENT_REPORT_T));
    if (!report) return NULL;

    report->array = (MEASUREMENT_RESULT*)calloc(MAX_ELEMENTS, sizeof(MEASUREMENT_RESULT));
    if (!report->array) {
        free(report);
        return NULL;
    }

    report->size = 0;
    report->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&report->lock, NULL);

    return report;
}

void destroy_measurement_report(LTE_RRC_MEASUREMENT_REPORT_T *report) {
    if (report) {
        free(report->array);
        pthread_mutex_destroy(&report->lock);
        free(report);
    }
}

int add_measurement_result(LTE_RRC_MEASUREMENT_REPORT_T *report, MEASUREMENT_RESULT result) {
    pthread_mutex_lock(&report->lock);

    for (size_t i = 0; i < report->size; ++i) {
        if (report->array[i].object.CELL_ID == result.object.CELL_ID) {
            pthread_mutex_unlock(&report->lock);
            return -1; // Duplicate CELL_ID
        }
    }

    if (report->size >= report->capacity) {
        size_t new_capacity = report->capacity * 2;
        MEASUREMENT_RESULT *new_array = (MEASUREMENT_RESULT*)realloc(report->array, new_capacity * sizeof(MEASUREMENT_RESULT));
        if (!new_array) {
            pthread_mutex_unlock(&report->lock);
            return -1; // Memory allocation failed
        }

        report->array = new_array;
        report->capacity = new_capacity;
    }

    report->array[report->size++] = result;

    pthread_mutex_unlock(&report->lock);
    return 0;
}

MEASUREMENT_RESULT* get_measurement_result(LTE_RRC_MEASUREMENT_REPORT_T *report, int cell_id) {
    pthread_mutex_lock(&report->lock);

    for (size_t i = 0; i < report->size; ++i) {
        if (report->array[i].object.CELL_ID == cell_id) {
            pthread_mutex_unlock(&report->lock);
            return &report->array[i];
        }
    }

    pthread_mutex_unlock(&report->lock);
    return NULL;
}
