#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRC_INDICATION_REL8_TAG; }
#define MAX_MEMORY_SIZE 1024 * 1024 * 1024 // 1GB

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N) {
    if (N > MAX_MEMORY_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Memory allocation exceeds maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory for array.");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    return array;
}

void serialize_to_file(NFAPI_CRC_INDICATION_PDU_T* array, int N, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing.");
        return;
    }

    size_t written = fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    if (written != N) {
        fprintf(stderr, "Error during serialization: %zu elements written instead of %d.\n", written, N);
    } else {
        printf("Serialization successful. %d elements written to %s\n", N, filename);
    }

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading.");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int N = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (N <= 0) {
        fprintf(stderr, "Invalid file size for deserialization.\n");
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory for deserialized array.");
        fclose(file);
        return NULL;
    }

    size_t read = fread(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    if (read != N) {
        fprintf(stderr, "Error during deserialization: %zu elements read instead of %d.\n", read, N);
        free(array);
        fclose(file);
        return NULL;
    }

    fclose(file);
    printf("Deserialization successful. %d elements read from %s\n", N, filename);

    return array;
}

int main() {
    int N = 1000; // Example size
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_populate_array(N);
    if (array) {
        serialize_to_file(array, N, "crc_indication_pdu.bin");
        NFAPI_CRC_INDICATION_PDU_T* deserialized_array = deserialize_from_file("crc_indication_pdu.bin");
        free(array);
        free(deserialized_array);
    }

    return 0;
}
