    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s %zu bytes at %s\n", action, size, ctime(&now));
        fclose(log_file);
    }
}

void serialize_to_file(NFAPI_CRC_INDICATION_PDU_T* data, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        fwrite(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open file for writing\n");
    }
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_from_file(const char* filename, int* count) {
    FILE* file = fopen(filename, "rb");
    if (file != NULL) {
        fseek(file, 0, SEEK_END);
        *count = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
        fseek(file, 0, SEEK_SET);

        NFAPI_CRC_INDICATION_PDU_T* data = safe_realloc(NULL, *count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), *count, file);
        fclose(file);
        return data;
    } else {
        fprintf(stderr, "Failed to open file for reading\n");
        *count = 0;
        return NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_data(int N) {
    NFAPI_CRC_INDICATION_PDU_T* data = safe_realloc(NULL, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    log_memory_event("Allocated", N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        data[i].RX_UE_INFORMATION_TAG = rand() % 100;
        data[i].RNTI = rand() % 1000;
        data[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        data[i].CRCFLAG = rand() % 2;
    }

    return data;
}

void free_data(NFAPI_CRC_INDICATION_PDU_T* data) {
    if (data != NULL) {
        log_memory_event("Freed", sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(data);
    }
}
