import java.io.*;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicInteger;
import java.time.LocalDateTime;

public class ServiceManager {
    private static final String CONFIG_FILE = "service_manager.properties";
    private static final int CYCLES_PER_REPORT = 10;
    private AtomicInteger startCount = new AtomicInteger(0);
    private AtomicInteger stopCount = new AtomicInteger(0);
    private Properties config = loadConfig();
    private ExternalLoggingService externalLogger;

    public ServiceManager() {
        this.externalLogger = new ExternalLoggingService(config.getProperty("external.logging.service.url"));
    }

    public void startService() {
        logEvent("START");
        startCount.incrementAndGet();
    }

    public void stopService() {
        logEvent("STOP");
        stopCount.incrementAndGet();
    }

    private void logEvent(String event) {
        String timestamp = LocalDateTime.now().toString();
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(CONFIG_FILE, true))) {
            writer.write(timestamp + " - " + event);
            writer.newLine();
        } catch (IOException e) {
            System.err.println("Failed to log event: " + e.getMessage());
        }
    }

    public void runCycles(int cycles) {
        for (int i = 0; i < cycles; i++) {
            try {
                int delay = Integer.parseInt(config.getProperty("service.start.delay"));
                Thread.sleep(delay);
                startService();
                delay = Integer.parseInt(config.getProperty("service.stop.delay"));
                Thread.sleep(delay);
                stopService();
            } catch (InterruptedException e) {
                System.err.println("Cycle interrupted: " + e.getMessage());
                Thread.currentThread().interrupt();
            }
        }

        if ((cycles % CYCLES_PER_REPORT) == 0) {
            generateSummaryReport(cycles);
        }
    }

    private void generateSummaryReport(int cycles) {
        int successfulStarts = startCount.get();
        int successfulStops = stopCount.get();
        String anomalies = checkForAnomalies();

        try {
            externalLogger.log("Cycle " + cycles / CYCLES_PER_REPORT + ": Successful Starts - " + successfulStarts +
                               ", Successful Stops - " + successfulStops + ", Anomalies - " + anomalies);
        } catch (IOException e) {
            System.err.println("Failed to send summary report: " + e.getMessage());
        }
    }

    private String checkForAnomalies() {
        // Implement anomaly detection logic here
        return "None";
    }

    private Properties loadConfig() {
        Properties properties = new Properties();
        try (InputStream input = new FileInputStream(CONFIG_FILE)) {
            properties.load(input);
        } catch (IOException e) {
            System.err.println("Failed to load configuration: " + e.getMessage());
        }
        return properties;
    }

    public void shutdown() {
        // Implement graceful shutdown logic here
        System.out.println("ServiceManager is shutting down gracefully.");
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        int cycles = Integer.parseInt(manager.config.getProperty("max.cycles"));
        manager.runCycles(cycles);
        Runtime.getRuntime().addShutdownHook(new Thread(() -> manager.shutdown()));
    }
}
