const std::vector<int> attacks = {1, 2}; // List of available attacks

void generateUEIndications() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1); // For CRCFLAG
    std::uniform_int_distribution<> attackDis(0, attacks.size() - 1); // For selecting an attack

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (true) {
        std::lock_guard<std::mutex> lock(mtx);
        if (attackCooldown <= 0) {
            int selectedAttack = attackDis(gen);
            pdu.RX_UE_INFORMATION_TAG = 123; // Example value
            pdu.RNTI = 456; // Example value
            pdu.CRCFLAG = dis(gen); // Randomly set CRCFLAG to true or false
            std::cout << "Selected Attack: " << attacks[selectedAttack] << std::endl;
            attackCooldown = 9; // Reset cooldown after selecting an attack
        }
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate time passing
    }
}

int main() {
    generateUEIndications();
    return 0;
