#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define RETRY_LIMIT 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_crc_indication(NFAPI_CRC_INDICATION_PDU_T *indication) {
    indication->RX_UE_INFORMATION_TAG = rand() % 1000;
    indication->RNTI = rand() % 256;
    indication->CRC_INDICATION_REL8_TAG = rand() % 2;
}

int validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *indication, int reference_value) {
    return indication->CRC_INDICATION_REL8_TAG == reference_value;
}

void process_crc_indications(NFAPI_CRC_INDICATION_PDU_T **list, int *size, int reference_value) {
    if (*size >= MAX_ELEMENTS) {
        printf("Error: List is full.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
        printf("Memory allocation failed. Rolling back...\n");
        return;
    }

    initialize_crc_indication(new_element);
    (*list)[*size] = *new_element;
    (*size)++;

    for (int i = 0; i < RETRY_LIMIT; i++) {
        if (validate_crc_indication(&(*list)[*size - 1], reference_value)) {
            printf("CRC validation successful.\n");
            break;
        } else {
            printf("CRC validation failed. Retrying...\n");
            initialize_crc_indication(new_element);
            (*list)[*size - 1] = *new_element;
        }
    }

    if (!validate_crc_indication(&(*list)[*size - 1], reference_value)) {
        printf("Failed to validate CRC after retries. Discarding element.\n");
        free((*list) + (*size - 1));
        (*size)--;
    }
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *crc_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list) {
        printf("Memory allocation failed. Exiting...\n");
        return 1;
    }

    int list_size = 0;
    int reference_value = 1;

    for (int i = 0; i < 5; i++) { // Example processing
        process_crc_indications(&crc_list, &list_size, reference_value);
    }

    free(crc_list);

    return 0;
}
