#define MAX_PACKETS 1000
#define MAC_HEADER_SIZE 14
#define MAC_PAYLOAD_SIZE 1500

typedef struct {
    unsigned char data[MAC_HEADER_SIZE];
} MAC_HEADER;

typedef struct {
    unsigned char data[MAC_PAYLOAD_SIZE];
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    time_t timestamp;
} MAC_PACKET_BUFFER;

int allocate_memory(MAC_PACKET_BUFFER **buffer, int num_packets) {
    if (num_packets > MAX_PACKETS) {
        return -1; // Exceeds maximum allowed packets
    }
    *buffer = (MAC_PACKET_BUFFER *)malloc(num_packets * sizeof(MAC_PACKET_BUFFER));
    if (*buffer == NULL) {
        return -2; // Memory allocation failed
    }
    return 0;
}

int serialize_to_file(const MAC_PACKET_BUFFER *buffer, int num_packets, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // Failed to open file for writing
    }
    size_t bytes_written = fwrite(buffer, sizeof(MAC_PACKET_BUFFER), num_packets, file);
    fclose(file);
    if (bytes_written != (size_t)num_packets) {
        return -2; // Serialization failed
    }
    return 0;
}

int deserialize_from_file(MAC_PACKET_BUFFER *buffer, int max_packets, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Failed to open file for reading
    }
    size_t bytes_read = fread(buffer, sizeof(MAC_PACKET_BUFFER), max_packets, file);
    fclose(file);
    if (bytes_read > (size_t)max_packets) {
        return -2; // Deserialization failed
    }
    return (int)bytes_read;
}

void free_memory(MAC_PACKET_BUFFER *buffer) {
    free(buffer);
}
