        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        LTE_DL_FRAME_MESSAGE** new_messages = (LTE_DL_FRAME_MESSAGE**)realloc(list->messages, new_capacity * sizeof(LTE_DL_FRAME_MESSAGE*));
        if (new_messages == NULL) return -1;
        list->messages = new_messages;
        list->capacity = new_capacity;
    }
    list->messages[list->count++] = message;
