#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LTE_DL_FRAME_MESSAGE {
    MAC_RLC_AM_PDU pdu;
    PHY_DOWNLINK_HARQ_PROCESS harq_process;
    uint8_t* payload;
    size_t payload_size;
    time_t ttl;
    pthread_mutex_t lock;
} LTE_DL_FRAME_MESSAGE;

typedef struct MessageList {
    LTE_DL_FRAME_MESSAGE** messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageList;

LTE_DL_FRAME_MESSAGE* create_message(MAC_RLC_AM_PDU pdu, PHY_DOWNLINK_HARQ_PROCESS harq_process, const uint8_t* payload, size_t payload_size, time_t ttl) {
    LTE_DL_FRAME_MESSAGE* message = (LTE_DL_FRAME_MESSAGE*)malloc(sizeof(LTE_DL_FRAME_MESSAGE));
    if (message == NULL) {
        return NULL;
    }
    message->pdu = pdu;
    message->harq_process = harq_process;
    message->payload_size = payload_size;
    message->payload = (uint8_t*)malloc(payload_size);
    if (message->payload == NULL) {
        free(message);
        return NULL;
    }
    memcpy(message->payload, payload, payload_size);
    message->ttl = ttl;
    pthread_mutex_init(&message->lock, NULL);
    return message;
}

void destroy_message(LTE_DL_FRAME_MESSAGE* message) {
    if (message != NULL) {
        pthread_mutex_lock(&message->lock);
        free(message->payload);
        pthread_mutex_unlock(&message->lock);
        pthread_mutex_destroy(&message->lock);
        free(message);
    }
}

MessageList* create_message_list() {
    MessageList* list = (MessageList*)malloc(sizeof(MessageList));
    if (list == NULL) {
        return NULL;
    }
    list->messages = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_message_list(MessageList* list) {
    if (list != NULL) {
        pthread_mutex_lock(&list->lock);
        for (size_t i = 0; i < list->count; ++i) {
            destroy_message(list->messages[i]);
        }
        free(list->messages);
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_message(MessageList* list, LTE_DL_FRAME_MESSAGE* message) {
    if (list == NULL || message == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity > 0 ? list->capacity * 2 : 4;
        LTE_DL_FRAME_MESSAGE** new_messages = (LTE_DL_FRAME_MESSAGE**)realloc(list->messages, new_capacity * sizeof(LTE_DL_FRAME_MESSAGE*));
        if (new_messages == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->messages = new_messages;
        list->capacity = new_capacity;
    }
    list->messages[list->count++] = message;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

LTE_DL_FRAME_MESSAGE* remove_message(MessageList* list, size_t index) {
    if (list == NULL || index >= list->count) {
        return NULL;
    }
    pthread_mutex_lock(&list->lock);
    LTE_DL_FRAME_MESSAGE* message = list->messages[index];
    for (size_t i = index; i < list->count - 1; ++i) {
        list->messages[i] = list->messages[i + 1];
    }
    --list->count;
    pthread_mutex_unlock(&list->lock);
    return message;
}

LTE_DL_FRAME_MESSAGE* get_message(MessageList* list, size_t index) {
    if (list == NULL || index >= list->count) {
        return NULL;
    }
    pthread_mutex_lock(&list->lock);
    LTE_DL_FRAME_MESSAGE* message = list->messages[index];
    pthread_mutex_unlock(&list->lock);
    return message;
}
