struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

struct AttackCooldown {
    std::string type;
    double cooldown;
    std::chrono::time_point<std::chrono::system_clock> lastUpdated;
};

class NetworkEventHandler {
public:
    void processNetworkEvents(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& events) {
        for (const auto& event : events) {
            handleEvent(event);
        }
    }

private:
    std::mutex cooldownMutex;
    std::vector<AttackCooldown> attackCooldowns = {
        {"slash", 10.0, std::chrono::system_clock::now()},
        {"fireball", 20.0, std::chrono::system_clock::now()},
        {"shockwave", 30.0, std::chrono::system_clock::now()}
    };

    void handleEvent(const NFAPI_CRC_INDICATION_PDU_T& event) {
        bool shouldAttack = false;
        int attackNumber = selectAttack();
        if (attackNumber != -1) {
            shouldAttack = true;
        }

        std::lock_guard<std::mutex> lock(cooldownMutex);
        for (auto& cooldown : attackCooldowns) {
            if (cooldown.type == "slash" && shouldAttack) {
                cooldown.cooldown -= 0.5; // Simulate cooldown reduction
                if (cooldown.cooldown <= 0) {
                    std::cout << "Attacking with slash!" << std::endl;
                    cooldown.lastUpdated = std::chrono::system_clock::now();
                }
            } else if (cooldown.type == "fireball" && shouldAttack) {
                cooldown.cooldown -= 1.0; // Simulate cooldown reduction
                if (cooldown.cooldown <= 0) {
                    std::cout << "Attacking with fireball!" << std::endl;
                    cooldown.lastUpdated = std::chrono::system_clock::now();
                }
            } else if (cooldown.type == "shockwave" && shouldAttack) {
                cooldown.cooldown -= 2.0; // Simulate cooldown reduction
                if (cooldown.cooldown <= 0) {
                    std::cout << "Attacking with shockwave!" << std::endl;
                    cooldown.lastUpdated = std::chrono::system_clock::now();
                }
            }
        }

        event.CRCFLAG = shouldAttack ? true : false;
        std::cout << "CRCFLAG: " << (event.CRCFLAG ? "true" : "false") << std::endl;
    }

    int selectAttack() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(0, 2);

        return dis(gen);
    }
};

int main() {
    NetworkEventHandler handler;

    NFAPI_CRC_INDICATION_PDU_T event1 = {1, 100, false};
    NFAPI_CRC_INDICATION_PDU_T event2 = {2, 200, false};
    std::vector<NFAPI_CRC_INDICATION_PDU_T> events = {event1, event2};

    handler.processNetworkEvents(events);

    return 0;
}
