#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct record {
    int value;
    char buffer[BUFFER_SIZE];
    struct record *next;
} Record;

int initialize_arrays(long **offsets, int **keys, Record **records) {
    srand(time(NULL));

    *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        (*offsets)[i] = rand() % 1000000L;
        (*keys)[i] = rand() % 1000;

        (*records)[i].value = rand() % 1000;
        for (int j = 0; j < BUFFER_SIZE - 1; j++) {
            (*records)[i].buffer[j] = 'A' + rand() % 62;
        }
        (*records)[i].buffer[BUFFER_SIZE - 1] = '\0';

        if (i > 0) {
            (*records)[i].next = &(*records)[i - 1];
        } else {
            (*records)[i].next = NULL;
        }
    }

    return 0; // Success
}

void free_arrays(long *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    free(records);
}
