#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_OFFSET 1000000
#define MAX_RECORDS 10000
#define MAX_STRING_LENGTH 64

typedef struct {
    int value;
    char* string;
    unsigned char identifier[MD5_DIGEST_LENGTH];
} record;

record* allocate_and_initialize_arrays(int max_records, long max_offset) {
    if (max_records > MAX_RECORDS || max_offset > MAX_OFFSET) {
        return NULL;
    }

    record* records = malloc(max_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    int* keys = malloc(max_records * sizeof(int));
    if (!keys) {
        free(records);
        return NULL;
    }

    long* offsets = malloc(max_records * sizeof(long));
    if (!offsets) {
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < max_records; i++) {
        keys[i] = i + 1;

        do {
            offsets[i] = rand() % (max_offset + 1);
        } while (i > 0 && offsets[i] == offsets[i - 1]);

        records[i].value = rand() % 1001;
        while (i > 0 && records[i].value == records[i - 1].value) {
            records[i].value = rand() % 1001;
        }

        records[i].string = malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!records[i].string) {
            for (int j = 0; j < i; j++) {
                free(records[j].string);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        for (int j = 0; j < MAX_STRING_LENGTH - 1; j++) {
            records[i].string[j] = 'a' + rand() % 26;
        }
        records[i].string[MAX_STRING_LENGTH - 1] = '\0';

        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, &keys[i], sizeof(int));
        MD5_Update(&md5, &offsets[i], sizeof(long));
        MD5_Final(records[i].identifier, &md5);
    }

    printf("Memory allocated and initialized successfully.\n");
    return records;
}

void free_records(record* records, int max_records) {
    for (int i = 0; i < max_records; i++) {
        free(records[i].string);
    }
    free(records);
}

int main() {
    record* records = allocate_and_initialize_arrays(1000, 1000000);
    if (!records) {
        printf("Failed to allocate and initialize arrays.\n");
        return 1;
    }

    // Iterate over all records
    for (int i = 0; i < 1000; i++) {
        printf("Record %d: Value=%d, String=%s\n", i + 1, records[i].value, records[i].string);
    }

    free_records(records, 1000);
    return 0;
}
```

