        var response = await _httpClient.PutAsync($"api/configuration/{id}", content);
        response.EnsureSuccessStatusCode();
    }

    public async Task DeleteConfigurationAsync(string id)
    {
        var response = await _httpClient.DeleteAsync($"api/configuration/{id}");
        response.EnsureSuccessStatusCode();
    }
}

