#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    // Define MAC_RLC_AM_PDU structure
} MAC_RLC_AM_PDU;

typedef struct {
    // Define PHY_DOWNLINK_HARQ_PROCESS structure
} PHY_DOWNLINK_HARQ_PROCESS;

typedef struct LTE_DL_FRAME_MESSAGE {
    MAC_RLC_AM_PDU rlc_pdu;
    PHY_DOWNLINK_HARQ_PROCESS harq_process;
    char* payload;
    size_t payload_length;
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
} LTE_DL_FRAME_MESSAGE;

typedef struct {
    LTE_DL_FRAME_MESSAGE** messages;
    size_t count;
    size_t capacity;
} MessageList;

void init_message_list(MessageList* list, size_t initial_capacity) {
    list->messages = (LTE_DL_FRAME_MESSAGE**)malloc(initial_capacity * sizeof(LTE_DL_FRAME_MESSAGE*));
    list->count = 0;
    list->capacity = initial_capacity;
}

void free_message_list(MessageList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->messages[i]->payload);
        free(list->messages[i]);
    }
    free(list->messages);
    list->messages = NULL;
    list->count = 0;
    list->capacity = 0;
}

void add_message(MessageList* list, LTE_DL_FRAME_MESSAGE* message) {
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->messages = (LTE_DL_FRAME_MESSAGE**)realloc(list->messages, list->capacity * sizeof(LTE_DL_FRAME_MESSAGE*));
    }
    list->messages[list->count++] = message;
}

void remove_message(MessageList* list, size_t index) {
    if (index >= list->count) return;
    free(list->messages[index]->payload);
    free(list->messages[index]);
    for (size_t i = index; i < list->count - 1; ++i) {
        list->messages[i] = list->messages[i + 1];
    }
    --list->count;
}

LTE_DL_FRAME_MESSAGE* get_message(MessageList* list, size_t index) {
    if (index >= list->count) return NULL;
    return list->messages[index];
}

void calculate_total_data_transferred(MessageList* list, size_t* total_length) {
    *total_length = 0;
    for (size_t i = 0; i < list->count; ++i) {
        *total_length += list->messages[i]->payload_length;
    }
}
