    if (pool_index < MAX_NF_API_STRUCTS) {
        struct_ptr = nfapi_struct_pool[pool_index++];
    } else {
        fprintf(stderr, "No available structures in the pool\n");
        struct_ptr = NULL;
    }
    pthread_mutex_unlock(&pool_mutex);
    return struct_ptr;
}

