typedef struct {
    int value;
} record;

void* allocate_and_initialize(int size, int alignment) {
    long* offset_array = aligned_alloc(alignment, sizeof(long) * size);
    if (!offset_array) return NULL;

    int* key_array = aligned_alloc(alignment, sizeof(int) * size);
    if (!key_array) {
        free(offset_array);
        return NULL;
    }

    record* records = aligned_alloc(alignment, sizeof(record) * size);
    if (!records) {
        free(key_array);
        free(offset_array);
        return NULL;
    }

