record* initialize_records(int initial_size, int max_size, int key_range, long timestamp_range, unsigned int seed) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(initial_size * sizeof(long));
    int* keys = (int*)malloc(initial_size * sizeof(int));
    record* records = (record*)malloc(initial_size * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize mutex for thread-safe operations
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Seed random number generator
    srand(seed);

    // Initialize arrays
    for (int i = 0; i < initial_size; ++i) {
        offsets[i] = i;
        keys[i] = rand() % key_range + 1; // Ensure unique keys within the range
        records[i].timestamp = rand() % timestamp_range + 1;
        records[i].status = (rand() % 2 == 0) ? 'A' : 'B';
    }

    // Function to reset arrays
    void reset_arrays(int new_size) {
        pthread_mutex_lock(&mutex);
        offsets = realloc(offsets, new_size * sizeof(long));
        keys = realloc(keys, new_size * sizeof(int));
        records = realloc(records, new_size * sizeof(record));

        if (!offsets || !keys || !records) {
            // Handle memory allocation failure
            return;
        }

        for (int i = initial_size; i < new_size; ++i) {
            offsets[i] = i;
            keys[i] = rand() % key_range + 1; // Ensure unique keys within the range
            records[i].timestamp = rand() % timestamp_range + 1;
            records[i].status = (rand() % 2 == 0) ? 'A' : 'B';
        }
        initial_size = new_size;
        pthread_mutex_unlock(&mutex);
    }

    // Function to dynamically resize arrays
    void resize_arrays(int new_size) {
        if (new_size > max_size) {
            return; // Prevent exceeding maximum allowed size
        }
        reset_arrays(new_size);
    }

    // Example usage of the function
    // ...

    // Clean up resources
    pthread_mutex_destroy(&mutex);
    free(offsets);
    free(keys);
    free(records);

    return records;
}
