            rnti = rand() % num_ues + 1;
        } while (is_rnti_used(crc_indications, i, rnti));

        crc_indications[i].RX_UE_INFORMATION_TAG = ue_identifiers[rnti - 1];
        crc_indications[i].RNTI = rnti;
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    return crc_indications;
