void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdu_array(int N) {
    if (N > MAX_NF_API_CRC_INDICATION_PDU) {
        fprintf(stderr, "Exceeds maximum allowed structures\n");
        return NULL;
    }
    return safe_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void populate_nfaapi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void print_max_integer(int* array, int size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Maximum integer: %d\n", max);
}

void serialize_nfaapi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, int N, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);
}

int deserialize_nfaapi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, int* size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return -1;
    }
    fseek(file, 0, SEEK_END);
    *size = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fseek(file, 0, SEEK_SET);
    *array = safe_malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (fread(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T), *size, file) != *size) {
        perror("Failed to read data from file");
        free(*array);
        *array = NULL;
        *size = 0;
    }
    fclose(file);
    return 0;
}

int main() {
    int N = 5;
    NFAPI_CRC_INDICATION_PDU_T* array = create_nfaapi_crc_indication_pdu_array(N);
    populate_nfaapi_crc_indication_pdu_array(array, N);

