typedef struct {
    int value;
    char data[16];
} record;

int manage_records(const char *filename, long *offsets, int *keys, record **records, int num_records) {
    // Initialize random seed
    srand(time(NULL));

    // Determine number of digits for extension based on filename length and character distribution
    int num_digits = 0;
    if (strlen(filename) > 10) {
        num_digits = 3; // Limit to avoid excessively long filenames
    } else {
        num_digits = strlen(filename);
    }

    // Allocate memory for records
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize records with default values
    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = 0;
        memset((*records)[i].data, 'A', sizeof((*records)[i].data) - 1);
        (*records)[i].data[sizeof((*records)[i].data) - 1] = '\0';
    }

    // Allocate memory for keys and offsets
    keys = (int *)malloc(num_records * sizeof(int));
    offsets = (long *)malloc(num_records * sizeof(long));
    if (keys == NULL || offsets == NULL) {
        free(*records);
        return -1; // Memory allocation failed
    }

    // Initialize keys with unique random values
    for (int i = 0; i < num_records; i++) {
        int key;
        do {
            key = rand() % num_records;
        } while (i > 0 && key == keys[i - 1]); // Collision resolution
        keys[i] = key;
    }

    // Modify filename extension
    char new_filename[256];
    strcpy(new_filename, filename);
    strcat(new_filename, "_");
    for (int i = 0; i < num_digits; i++) {
        sprintf(&new_filename[strlen(new_filename)], "%d", rand() % 10);
    }
    strcat(new_filename, ".txt");

    // Free allocated memory
    free(*records);
    free(keys);
    free(offsets);

    return 0; // Success
}
