#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 10000
#define FLUSH_INTERVAL 1800 // 30 minutes in seconds

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int payload_length;
    char packet_type[4]; // "TCP" or "UDP"
} Packet;

Packet *packet_array[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t packet_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_packet(Packet *packet) {
    memset(packet, 0, sizeof(Packet));
}

void add_packet(Packet *new_packet) {
    pthread_mutex_lock(&packet_lock);
    if (packet_count < MAX_PACKETS) {
        packet_array[packet_count++] = new_packet;
    }
    pthread_mutex_unlock(&packet_lock);
}

void update_packet(int index, Packet *updated_packet) {
    pthread_mutex_lock(&packet_lock);
    if (index >= 0 && index < packet_count) {
        memcpy(packet_array[index], updated_packet, sizeof(Packet));
    }
    pthread_mutex_unlock(&packet_lock);
}

void flush_old_packets() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&packet_lock);
    for (int i = 0; i < packet_count; ) {
        if (current_time - packet_array[i]->timestamp > FLUSH_INTERVAL) {
            free(packet_array[i]);
            memmove(&packet_array[i], &packet_array[i + 1], sizeof(Packet*) * (packet_count - i - 1));
            packet_count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&packet_lock);
}

void log_packets() {
    pthread_mutex_lock(&packet_lock);
    printf("Total Packets: %d\n", packet_count);
    int tcp_count = 0, udp_count = 0;
    for (int i = 0; i < packet_count; i++) {
        if (strcmp(packet_array[i]->packet_type, "TCP") == 0) {
            tcp_count++;
        } else if (strcmp(packet_array[i]->packet_type, "UDP") == 0) {
            udp_count++;
        }
    }
    printf("TCP Packets: %d\n", tcp_count);
    printf("UDP Packets: %d\n", udp_count);
    pthread_mutex_unlock(&packet_lock);
}

void *log_thread(void *arg) {
    while (1) {
        log_packets();
        sleep(60); // Log every minute
    }
    return NULL;
}

int main() {
    pthread_t log_tid;
    pthread_create(&log_tid, NULL, log_thread, NULL);

    // Example usage
    Packet new_packet;
    initialize_packet(&new_packet);
    strcpy(new_packet.source_ip, "192.168.1.1");
    strcpy(new_packet.destination_ip, "10.0.0.1");
    new_packet.payload_length = 1024;
    strcpy(new_packet.packet_type, "TCP");
    time(&new_packet.timestamp);
    add_packet(&new_packet);

    update_packet(0, &new_packet);

    flush_old_packets();

    pthread_join(log_tid, NULL);
    return 0;
}
```

This code provides a basic structure for managing a dynamic array of network packets with thread safety and periodic flushing. It includes functions to add, update, and flush packets, as well as a logging thread that outputs statistics every minute. The example usage in the `main` function demonstrates how to use these functions.']

