#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char* str;
    int ref_count;
} record;

typedef struct hash_table_entry {
    int key;
    record* rec;
    struct hash_table_entry* next;
} hash_table_entry;

typedef struct {
    hash_table_entry** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} hash_table;

hash_table* create_hash_table(size_t initial_capacity) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    if (!ht) return NULL;

    ht->buckets = (hash_table_entry**)calloc(initial_capacity, sizeof(hash_table_entry*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    ht->capacity = initial_capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

void destroy_hash_table(hash_table* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        hash_table_entry* entry = ht->buckets[i];
        while (entry) {
            hash_table_entry* next = entry->next;
            free(entry->rec->str);
            free(entry->rec);
            free(entry);
            entry = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

size_t hash_function(int key, size_t capacity) {
    return (size_t)(key % capacity);
}

void insert_record(hash_table* ht, int key, record* rec) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->capacity);
    hash_table_entry* entry = ht->buckets[index];

    while (entry) {
        if (entry->key == key) {
            free(entry->rec->str);
            free(entry->rec);
            entry->rec = rec;
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        entry = entry->next;
    }

    hash_table_entry* new_entry = (hash_table_entry*)malloc(sizeof(hash_table_entry));
    if (!new_entry) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }

    new_entry->key = key;
    new_entry->rec = rec;
    new_entry->next = ht->buckets[index];
    ht->buckets[index] = new_entry;
    ++ht->size;

    pthread_mutex_unlock(&ht->lock);
}

record* find_record(hash_table* ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->capacity);
    hash_table_entry* entry = ht->buckets[index];

    while (entry) {
        if (entry->key == key) {
            ++entry->rec->ref_count;
            pthread_mutex_unlock(&ht->lock);
            return entry->rec;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void release_record(record* rec) {
    if (rec && --rec->ref_count == 0) {
        free(rec->str);
        free(rec);
    }
}
