#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_length;
} Packet;

typedef struct {
    Packet *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

void init_packet_array(PacketArray *array) {
    array->packets = (Packet *)malloc(INITIAL_CAPACITY * sizeof(Packet));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&array->lock, NULL);
}

void add_packet(PacketArray *array, Packet packet) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet *new_packets = (Packet *)realloc(array->packets, new_capacity * sizeof(Packet));
        if (!new_packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->count++] = packet;
    pthread_mutex_unlock(&array->lock);
}

void update_packet(PacketArray *array, size_t index, Packet packet) {
    pthread_mutex_lock(&array->lock);
    if (index < array->count) {
        array->packets[index] = packet;
    }
    pthread_mutex_unlock(&array->lock);
}

size_t total_data_transferred(PacketArray *array) {
    size_t total = 0;
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        total += array->packets[i].payload_length;
    }
    pthread_mutex_unlock(&array->lock);
    return total;
}

void serialize_packets(PacketArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&array->lock);
    size_t count = array->count;
    fwrite(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        Packet packet = array->packets[i];
        fwrite(&packet.timestamp, sizeof(time_t), 1, file);
        fwrite(packet.source_ip, sizeof(char), 16, file);
        fwrite(packet.destination_ip, sizeof(char), 16, file);
        fwrite(&packet.payload_length, sizeof(size_t), 1, file);
    }
    pthread_mutex_unlock(&array->lock);

    fclose(file);
}

void deserialize_packets(PacketArray *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&array->lock);
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    Packet *new_packets = (Packet *)realloc(array->packets, count * sizeof(Packet));
    if (!new_packets) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->packets = new_packets;
    array->count = count;

    for (size_t i = 0; i < count; ++i) {
        Packet packet;
        fread(&packet.timestamp, sizeof(time_t), 1, file);
        fread(packet.source_ip, sizeof(char), 16, file);
        fread(packet.destination_ip, sizeof(char), 16, file);
        fread(&packet.payload_length, sizeof(size_t), 1, file);
        array->packets[i] = packet;
    }
    pthread_mutex_unlock(&array->lock);

    fclose(file);
}

void destroy_packet_array(PacketArray *array) {
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}
