import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

public class FileProcessor {

    public static Result processFile(String filePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            List<String> lines = new ArrayList<>();
            String line;
            while ((line = reader.readLine()) != null) {
                lines.add(line);
            }

            if (lines.size() < 2) {
                return new Result("Insufficient lines for processing");
            }

            Collections.sort(lines, String.CASE_INSENSITIVE_ORDER);

            String lastLine = lines.get(lines.size() - 1);
            String md5Hash = computeMD5(lastLine);

            return new Result(md5Hash, lastLine);
        } catch (FileNotFoundException e) {
            logError("File not found: " + filePath, e);
            return new Result("File not found");
        } catch (IOException e) {
            logError("I/O error while processing file: " + filePath, e);
            return new Result("I/O error");
        }
    }

    private static String computeMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(no.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString();
        } catch (NoSuchAlgorithmException e) {
            logError("MD5 algorithm not found", e);
            return null;
        }
    }

    private static void logError(String message, Exception e) {
        // Integrate with an existing logging framework here
        System.err.println(message + " - " + e.getMessage());
    }

    public static class Result {
        private String md5Hash;
        private String lastLine;

        public Result(String md5Hash, String lastLine) {
            this.md5Hash = md5Hash;
            this.lastLine = lastLine;
        }

        public Result(String message) {
            this(null, null);
            // Handle insufficient lines or other error messages
        }

        @Override
        public String toString() {
            if (md5Hash != null && lastLine != null) {
                return "MD5 Hash: " + md5Hash + ", Last Line: " + lastLine;
            } else {
                return message;
            }
        }
    }
}
