import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class StringHasher {
    private static final int MAX_STRING_LENGTH = 1024;
    private static final MessageDigest md5Digest;
    private static final Map<String, String> cache = new ConcurrentHashMap<>();

    static {
        try {
            md5Digest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    public List<String> hashStrings(List<String> inputStrings) {
        List<String> result = new ArrayList<>();
        for (String str : inputStrings) {
            if (str == null || str.length() > MAX_STRING_LENGTH) {
                result.add("Invalid input");
            } else {
                String hash = cache.computeIfAbsent(str, s -> computeMD5(s));
                result.add(hash);
            }
        }
        return result;
    }

    private static String computeMD5(String input) {
        md5Digest.reset();
        byte[] digest = md5Digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        StringHasher hasher = new StringHasher();
        List<String> inputStrings = List.of("example1", "example2", null, "example3");
        List<String> hashes = hasher.hashStrings(inputStrings);
        System.out.println(hashes);
    }
}
