#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    int key;
    long value;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list(size_t initial_capacity) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(int key, long value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->key = key;
    node->value = value;
    node->next = NULL;

    return node;
}

void insert_node(LinkedList* list, int key, long value) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(key, value);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->count == list->capacity) {
        // Resize the list
        size_t new_capacity = list->capacity * 2;
        Node** nodes = (Node**)realloc(list->head, new_capacity * sizeof(Node*));
        if (!nodes) {
            free(new_node);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->head = nodes;
        list->capacity = new_capacity;
    }

    // Insert in sorted order
    Node** current = &list->head;
    while (*current && (*current)->key < key) {
        current = &(*current)->next;
    }
    new_node->next = *current;
    *current = new_node;

    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void update_node(LinkedList* list, int key, long value) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current && current->key != key) {
        current = current->next;
    }
    if (current) {
        current->value = value;
    }
    pthread_mutex_unlock(&list->lock);
}

int get_node_value(LinkedList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current && current->key != key) {
        current = current->next;
    }
    if (current) {
        long value = current->value;
        pthread_mutex_unlock(&list->lock);
        return value;
    } else {
        pthread_mutex_unlock(&list->lock);
        return -1; // Node not found
    }
}
