#define MAX_SEGMENTS 1024
#define INCREMENT_SIZE 256

typedef struct {
    // Define the structure fields here
} LTE_TRANSPORT_BLOCK_SEGMENT;

typedef struct {
    LTE_TRANSPORT_BLOCK_SEGMENT *segments;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} LTE_TRANSPORT_BLOCK_ARRAY;

int lte_transport_block_array_init(LTE_TRANSPORT_BLOCK_ARRAY *array) {
    array->segments = (LTE_TRANSPORT_BLOCK_SEGMENT *)malloc(INCREMENT_SIZE * sizeof(LTE_TRANSPORT_BLOCK_SEGMENT));
    if (!array->segments) {
        return -1; // Memory allocation failed
    }
    array->count = 0;
    array->capacity = INCREMENT_SIZE;
    pthread_mutex_init(&array->mutex, NULL);
    return 0;
}

int lte_transport_block_array_add(LTE_TRANSPORT_BLOCK_ARRAY *array, LTE_TRANSPORT_BLOCK_SEGMENT segment) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        LTE_TRANSPORT_BLOCK_SEGMENT *new_segments = (LTE_TRANSPORT_BLOCK_SEGMENT *)realloc(array->segments, (array->capacity + INCREMENT_SIZE) * sizeof(LTE_TRANSPORT_BLOCK_SEGMENT));
        if (!new_segments) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory reallocation failed
        }
        array->segments = new_segments;
        array->capacity += INCREMENT_SIZE;
    }
    array->segments[array->count++] = segment;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void lte_transport_block_array_destroy(LTE_TRANSPORT_BLOCK_ARRAY *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->segments);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}
