#define MAX_STRUCTURES 1000
#define CACHE_SIZE 100

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
} DynamicList;

typedef struct {
    RX_UE_INFORMATION_TAG key;
    int index;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];

int findInCache(RX_UE_INFORMATION_TAG tag) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].key == tag) {
            return cache[i].index;
        }
    }
    return -1;
}

void addToCache(RX_UE_INFORMATION_TAG tag, int index) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].key == RX_UE_INFORMATION_TAG_INVALID) {
            cache[i].key = tag;
            cache[i].index = index;
            return;
        }
    }
}

DynamicList* createDynamicList() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i].key = RX_UE_INFORMATION_TAG_INVALID;
    }
    return list;
}

void addStructure(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    int index = findInCache(pdu->tag);
    if (index == -1) {
        if (list->count < MAX_STRUCTURES) {
            list->data[list->count] = pdu;
            addToCache(pdu->tag, list->count);
            list->count++;
        } else {
            printf("List is full\n");
        }
    } else {
        printf("Tag already exists\n");
    }
    pthread_mutex_unlock(&list->lock);
}

int getStructureCount(DynamicList *list) {
    return list->count;
}

void freeDynamicList(DynamicList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->data[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
