#include <pthread.h>

typedef struct record {
    int value;
    char* str;
    int ref_count;
} Record;

typedef struct hash_table_entry {
    int key;
    Record* record;
    struct hash_table_entry* next;
} HashTableEntry;

typedef struct hash_table {
    HashTableEntry** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (HashTableEntry**)calloc(size, sizeof(HashTableEntry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = size;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashTableEntry* entry = table->buckets[i];
        while (entry) {
            HashTableEntry* next = entry->next;
            free(entry->record->str);
            free(entry->record);
            free(entry);
            entry = next;
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

Record* create_record(int value, const char* str) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = value;
    record->str = strdup(str);
    if (!record->str) {
        free(record);
        return NULL;
    }

    record->ref_count = 0;

    return record;
}

void destroy_record(Record* record) {
    free(record->str);
    free(record);
}

int hash_function(int key, size_t size) {
    return abs(key) % size;
}

void insert_into_hash_table(HashTable* table, int key, Record* record) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key, table->size);
    HashTableEntry* entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!entry) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    entry->key = key;
    entry->record = record;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;

    pthread_mutex_unlock(&table->lock);
}

Record* get_from_hash_table(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key, table->size);
    HashTableEntry* entry = table->buckets[index];
    while (entry) {
        if (entry->key == key) {
            entry->record->ref_count++;
            pthread_mutex_unlock(&table->lock);
            return entry->record;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void release_record(HashTable* table, Record* record) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(record->value, table->size);
    HashTableEntry** prev_entry = &table->buckets[index];
    while (*prev_entry) {
        if ((*prev_entry)->record == record) {
            (*prev_entry)->record->ref_count--;
            if ((*prev_entry)->record->ref_count == 0) {
                free((*prev_entry)->record->str);
                free((*prev_entry)->record);
                HashTableEntry* temp = *prev_entry;
                *prev_entry = (*prev_entry)->next;
                free(temp);
            }
            pthread_mutex_unlock(&table->lock);
            return;
        }
        prev_entry = &(*prev_entry)->next;
    }

    pthread_mutex_unlock(&table->lock);
}

int main() {
    HashTable* table = create_hash_table(1024);

    Record* record1 = create_record(1, "Hello");
    insert_into_hash_table(table, 1, record1);

    Record* retrieved_record = get_from_hash_table(table, 1);
    if (retrieved_record) {
        printf("Retrieved value: %d\n", retrieved_record->value);
        release_record(table, retrieved_record);
    }

    destroy_hash_table(table);

    return 0;
}
