#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

#define STRUCT_COUNT 1024
#define MAX_INT_COUNT 65535

typedef struct {
    uint16_t rnti;
    bool in_use;
} PDU;

PDU pdu_pool[STRUCT_COUNT];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void init_pdu_pool() {
    for (int i = 0; i < STRUCT_COUNT; i++) {
        pdu_pool[i].rnti = 0;
        pdu_pool[i].in_use = false;
    }
}

bool is_rnti_valid(uint16_t rnti) {
    return rnti <= MAX_INT_COUNT;
}

PDU* get_pdu(uint16_t rnti) {
    if (!is_rnti_valid(rnti)) {
        return NULL; // Invalid RNTI
    }

    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < STRUCT_COUNT; i++) {
        if (!pdu_pool[i].in_use && pdu_pool[i].rnti == rnti) {
            pdu_pool[i].in_use = true;
            pthread_mutex_unlock(&pool_lock);
            return &pdu_pool[i];
        }
    }

    // No available PDU with the given RNTI
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void release_pdu(PDU* pdu) {
    if (pdu == NULL || !pdu->in_use) {
        return; // Invalid or already released PDU
    }

    pthread_mutex_lock(&pool_lock);
    pdu->in_use = false;
    pthread_mutex_unlock(&pool_lock);
}
