#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current) {
        if (current->data.RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_RNTI(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T* result = &current->data;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int main() {
    List* list = create_list();
    if (!list) {
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, 4};
    add_element(list, pdu);

    NFAPI_CRC_INDICATION_PDU_T* retrieved_pdu = get_element_by_RNTI(list, 2);
    if (retrieved_pdu) {
        printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               retrieved_pdu->RX_UE_INFORMATION_TAG,
               retrieved_pdu->RNTI,
               retrieved_pdu->CRC_INDICATION_REL8_TAG,
               retrieved_pdu->CRCFLAG);
    }

    remove_element(list, 2);

    destroy_list(list);
    return 0;
}
