    if (sessionCount >= MAX_SESSIONS) {
        printf("Session array is full. Cannot add more sessions.\n");
        return;
    }
    UserSession newSession = {userID, startTime, duration, requests, time(NULL)};
    sessions[sessionCount++] = newSession;
}

void updateSession(int userID, time_t duration, int requests) {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i].userID == userID) {
            sessions[i].duration += duration;
            sessions[i].requests += requests;
            sessions[i].lastAccessed = time(NULL);
            return;
        }
    }
    printf("Session for user ID %d not found.\n", userID);
}

void iterateSessions(time_t startTime, time_t endTime, int *totalDuration, int *activeSessions) {
    *totalDuration = 0;
    *activeSessions = 0;
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i].startTime >= startTime && sessions[i].lastAccessed <= endTime) {
            *totalDuration += sessions[i].duration;
            (*activeSessions)++;
        }
    }
}

void evictOldSessions(time_t threshold) {
    for (int i = 0; i < sessionCount; ) {
        if (time(NULL) - sessions[i].startTime > threshold) {
            for (int j = i; j < sessionCount - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            sessionCount--;
        } else {
            i++;
        }
    }
}

// Example usage
int main() {
    addSession(1, time(NULL), 3600, 5);
    updateSession(1, 7200, 10);

    int totalDuration, activeSessions;
    iterateSessions(time(NULL) - 86400, time(NULL), &totalDuration, &activeSessions);
    printf("Total Duration: %d\n", totalDuration);
    printf("Active Sessions: %d\n", activeSessions);

    evictOldSessions(3600 * 24); // Evict sessions older than 1 day

    return 0;
}
```

This code provides a basic implementation of managing user sessions with the specified functionalities. It includes functions to add, update, iterate over, and evict sessions based on certain criteria. The example usage in `main` demonstrates how these functions can be called.']

