#include <pthread.h>

typedef struct {
    int SequenceNumber;
    time_t Timestamp;
    char DataPayload[1024];
} NFDataRecord;

typedef struct {
    NFDataRecord *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->records = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void freeDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->records);
    array->records = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

void addRecord(DynamicArray *array, NFDataRecord record) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        array->records = realloc(array->records, new_capacity * sizeof(NFDataRecord));
        array->capacity = new_capacity;
    }
    array->records[array->count++] = record;
    pthread_mutex_unlock(&array->lock);
}

void filterRecords(DynamicArray *array, time_t threshold) {
    pthread_mutex_lock(&array->lock);
    size_t i = 0, j = 0;
    while (i < array->count) {
        if (array->records[i].Timestamp >= threshold) {
            array->records[j++] = array->records[i];
        }
        i++;
    }
    array->count = j;
    pthread_mutex_unlock(&array->lock);
}

void *readFileThread(void *arg) {
    DynamicArray *array = (DynamicArray *)arg;
    // Simulate reading from a file
    NFDataRecord record;
    while (/* read data from file */) {
        addRecord(array, record);
    }
    return NULL;
}

int main() {
    DynamicArray array;
    initDynamicArray(&array);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, readFileThread, &array);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    time_t threshold = /* set timestamp threshold */;
    filterRecords(&array, threshold);

    // Log metrics and free resources
    freeDynamicArray(&array);

    return 0;
}
