#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Task {
    int id;
    int priority;
    int status; // 0: pending, 1: in progress, 2: completed
    time_t estimated_completion_time;
    struct Task* next;
} Task;

typedef struct TaskManager {
    Task* head;
    pthread_mutex_t lock;
} TaskManager;

TaskManager* create_task_manager() {
    TaskManager* manager = (TaskManager*)malloc(sizeof(TaskManager));
    if (!manager) {
        perror("Failed to allocate memory for task manager");
        return NULL;
    }
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_task(TaskManager* manager, int id, int priority, time_t estimated_completion_time) {
    pthread_mutex_lock(&manager->lock);
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) {
        perror("Failed to allocate memory for task");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    new_task->id = id;
    new_task->priority = priority;
    new_task->status = 0; // pending
    new_task->estimated_completion_time = estimated_completion_time;
    new_task->next = manager->head;
    manager->head = new_task;
    pthread_mutex_unlock(&manager->lock);
}

void update_task(TaskManager* manager, int id, int status) {
    pthread_mutex_lock(&manager->lock);
    Task* current = manager->head;
    while (current != NULL) {
        if (current->id == id) {
            current->status = status;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

time_t calculate_total_time(TaskManager* manager) {
    time_t total_time = 0;
    pthread_mutex_lock(&manager->lock);
    Task* current = manager->head;
    while (current != NULL) {
        if (current->status == 0 || current->status == 1) { // pending or in progress
            total_time += difftime(current->estimated_completion_time, time(NULL));
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return total_time;
}

void identify_overdue_tasks(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);
    Task* current = manager->head;
    while (current != NULL) {
        if (current->status == 0 || current->status == 1) { // pending or in progress
            time_t now = time(NULL);
            if (difftime(current->estimated_completion_time, now) < 0) {
                printf("Task %d is overdue\n", current->id);
            }
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_task_manager(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);
    Task* current = manager->head;
    while (current != NULL) {
        Task* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
