#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    int key;
    long value;
    struct Node* next;
} Node;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

Node* create_node(int key, long value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

void insert_node(LinkedList* list, int key, long value) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(key, value);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle memory allocation failure
    }
    if (list->head == NULL || list->head->key > key) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
