#define MAX_UE_CONTEXTS 1024

typedef struct {
    uint64_t UE_ID;
    int RRC_STATE;
    uint32_t PDCP_SN;
    time_t last_updated;
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} UEContextManager;

UEContextManager* create_UEContextManager() {
    UEContextManager *manager = (UEContextManager*)malloc(sizeof(UEContextManager));
    if (!manager) return NULL;

    manager->contexts = (UEContext*)calloc(MAX_UE_CONTEXTS, sizeof(UEContext));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = MAX_UE_CONTEXTS;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_UEContextManager(UEContextManager *manager) {
    if (manager) {
        free(manager->contexts);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_UEContext(UEContextManager *manager, UEContext context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UEContext *new_contexts = (UEContext*)realloc(manager->contexts, new_capacity * sizeof(UEContext));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    manager->contexts[manager->count++] = context;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void cleanup_expired_contexts(UEContextManager *manager, time_t current_time) {
    pthread_mutex_lock(&manager->lock);

    size_t i = 0;
    while (i < manager->count) {
        if (difftime(current_time, manager->contexts[i].last_updated) > 3600) { // Example: Cleanup contexts older than 1 hour
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }
            --manager->count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
