    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRCList* list) {
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->data[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int modify_crc_entry(CRCList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Index out of bounds
    }
    list->data[index] = new_entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int search_crc_entry(CRCList* list, uint16_t rnti, size_t* index) {
