}

int validate_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 1; i < list->count; ++i) {
        if (list->data[i].RNTI == list->data[i - 1].RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI found
        }
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}
