    for (size_t i = 0; i < size; ++i) {
        (*offset_array)[i] = rand() % (RAND_MAX / 2); // Avoid overflow
        (*key_array)[i] = i;

        // Initialize record structure with a random value
        (*record_array)[i].value = rand() % (max_value + 1);
    }
}

