#include <time.h>

#define MAX_LINKED_LIST_SIZE 1000
#define DYNAMIC_ARRAY_INITIAL_CAPACITY 10

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct DynamicArray {
    SystemEvent* events;
    size_t capacity;
    size_t size;
} DynamicArray;

typedef struct SystemEvent {
    time_t timestamp;
    int userID;
    int sessionID;
    char action[100];
    int responseCode;
} SystemEvent;

LinkedListNode* createLinkedListNode(NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed for linked list node.\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertAtEndOfList(LinkedListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* newNode = createLinkedListNode(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        LinkedListNode* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void freeLinkedList(LinkedListNode** head) {
    LinkedListNode* current = *head;
    LinkedListNode* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

DynamicArray* createDynamicArray() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for dynamic array.\n");
        exit(EXIT_FAILURE);
    }
    array->events = (SystemEvent*)calloc(DYNAMIC_ARRAY_INITIAL_CAPACITY, sizeof(SystemEvent));
    if (array->events == NULL) {
        fprintf(stderr, "Memory allocation failed for dynamic array events.\n");
        free(array);
        exit(EXIT_FAILURE);
    }
    array->capacity = DYNAMIC_ARRAY_INITIAL_CAPACITY;
    array->size = 0;
    return array;
}

void resizeDynamicArray(DynamicArray* array) {
    size_t newCapacity = array->capacity * 2;
    SystemEvent* newEvents = (SystemEvent*)realloc(array->events, newCapacity * sizeof(SystemEvent));
    if (newEvents == NULL) {
        fprintf(stderr, "Memory reallocation failed for dynamic array.\n");
        free(array->events);
        exit(EXIT_FAILURE);
    }
    array->events = newEvents;
    array->capacity = newCapacity;
}

void addSystemEvent(DynamicArray* array, SystemEvent event) {
    if (array->size >= array->capacity * 0.8) {
        resizeDynamicArray(array);
    }
    array->events[array->size++] = event;
}

void freeDynamicArray(DynamicArray* array) {
    free(array->events);
    free(array);
}
