#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* dynamic_list_create() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ENTRIES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = MAX_ENTRIES;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->entries);
    pthread_mutex_unlock(&list->lock);
    free(list);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        // Handle insufficient memory condition
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rnti == entry.rnti) {
            // Prevent consecutive entries with the same RNTI
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    list->entries[list->count++] = entry;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int dynamic_list_remove(DynamicList *list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rnti == rnti) {
            // Shift elements to fill the gap
            for (size_t j = i; j < list->count - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int dynamic_list_update(DynamicList *list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rnti == rnti) {
            // Update the entry
            list->entries[i] = new_entry;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int dynamic_list_get(DynamicList *list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rnti == rnti) {
            *entry = list->entries[i];
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}
