#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int SequenceNumber;
    time_t Timestamp;
    void* DataPayload;
    size_t PayloadSize;
} NFDataRecord;

typedef struct {
    NFDataRecord** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->records = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->records[i]->DataPayload);
        free(array->records[i]);
    }
    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void add_record(DynamicArray* array, NFDataRecord* record) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        array->records = realloc(array->records, new_capacity * sizeof(NFDataRecord*));
        array->capacity = new_capacity;
    }
    array->records[array->count++] = record;
    pthread_mutex_unlock(&array->lock);
}

void compact_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    size_t new_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i]->Timestamp > threshold_timestamp) {
            array->records[new_count++] = array->records[i];
        } else {
            free(array->records[i]->DataPayload);
            free(array->records[i]);
        }
    }
    array->count = new_count;
    pthread_mutex_unlock(&array->lock);
}

void* read_log_file(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    FILE* file = fopen("log.txt", "r");
    if (!file) return NULL;

    NFDataRecord record;
    while (fread(&record, sizeof(NFDataRecord), 1, file)) {
        add_record(array, &record);
    }

    fclose(file);
    return NULL;
}

void* monitor_memory_usage(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    while (1) {
        pthread_mutex_lock(&array->lock);
        size_t total_size = 0;
        for (size_t i = 0; i < array->count; ++i) {
            total_size += sizeof(NFDataRecord) + array->records[i]->PayloadSize;
        }
        printf("Memory Usage: %zu bytes\n", total_size);
        pthread_mutex_unlock(&array->lock);
        sleep(10); // Monitor every 10 seconds
    }
    return NULL;
}

int main() {
    DynamicArray* array = create_dynamic_array();
    pthread_t reader_thread, monitor_thread;

    pthread_create(&reader_thread, NULL, read_log_file, array);
    pthread_create(&monitor_thread, NULL, monitor_memory_usage, array);

    pthread_join(reader_thread, NULL);
    pthread_join(monitor_thread, NULL);

    destroy_dynamic_array(array);
    return 0;
}
```

