['```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class RequestIdentifierGenerator {
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final int CACHE_SIZE_LIMIT = 10000; // Adjust based on memory constraints

    public static String generateIdentifier(String headers, String body) throws NoSuchAlgorithmException {
        String key = headers + body;
        if (cache.containsKey(key)) {
            return cache.get(key);
        }

        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest((key).getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        String identifier = hexString.toString();

        // Cache the result
        if (cache.size() >= CACHE_SIZE_LIMIT) {
            cache.remove(cache.keySet().iterator().next());
        }
        cache.put(key, identifier);

        return identifier;
    }

    public static void main(String[] args) {
        try {
            String headers = "Content-Type: application/json";
            String body = "{\"user\":\"john\", \"action\":\"login\"}";
            String identifier = generateIdentifier(headers, body);
            System.out.println("Generated Identifier: " + identifier);
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
```

