    time_t startTime;
    time_t lastActivityTime;
    char sessionState[20];
    long totalDataTransferred;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} Session;

Node* createNode(int key, long value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->key = key;
    newNode->value = value;
    newNode->next = NULL;
    return newNode;
}

Session* createSession(int userID, time_t startTime, time_t lastActivityTime, const char* sessionState, long totalDataTransferred, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Session* newSession = (Session*)malloc(sizeof(Session));
    if (newSession == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newSession->userID = userID;
    newSession->startTime = startTime;
    newSession->lastActivityTime = lastActivityTime;
    strncpy(newSession->sessionState, sessionState, sizeof(newSession->sessionState));
    newSession->totalDataTransferred = totalDataTransferred;
    newSession->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newSession->RNTI = RNTI;
    newSession->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newSession->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return newSession;
}

void addNode(Node** head, int key, long value) {
    Node* newNode = createNode(key, value);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void addSession(Session** sessions, int userID, time_t startTime, time_t lastActivityTime, const char* sessionState, long totalDataTransferred, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Session* newSession = createSession(userID, startTime, lastActivityTime, sessionState, totalDataTransferred, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (*sessions == NULL) {
        *sessions = newSession;
    } else {
        // Assuming sessions are stored in an array or linked list for easy access
        // Add code to handle adding the session to the appropriate data structure
    }
}

void cleanUpSessions(Session** sessions, time_t currentTime, int expirationThreshold) {
    if (*sessions != NULL) {
        Session* current = *sessions;
        Session* prev = NULL;
        while (current != NULL) {
            if ((currentTime - current->lastActivityTime) > expirationThreshold) {
                if (prev == NULL) {
                    *sessions = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current);
                current = prev->next;
            } else {
                prev = current;
                current = current->next;
            }
        }
    }
}

int main() {
    srand(time(NULL));
    Node* graph = NULL;
    Session* sessions = NULL;

    addNode(&graph, 1, rand());
    addSession(&sessions, 101, time(NULL), time(NULL), "Active", rand(), 12345, 67890, 1);

    cleanUpSessions(&sessions, time(NULL), 3600); // Clean up sessions older than 1 hour

    return 0;
}
