using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Logging;
using System.Security.Claims;
using System.Text.RegularExpressions;

public class CustomAuthenticationHandler : AuthenticationHandler<CustomAuthenticationOptions>
{
    private readonly UserManager<ApplicationUser> _userManager;
    private readonly SignInManager<ApplicationUser> _signInManager;
    private readonly ILogger<CustomAuthenticationHandler> _logger;

    public CustomAuthenticationHandler(
        IOptionsMonitor<CustomAuthenticationOptions> options,
        ILoggerFactory loggerFactory,
        UrlEncoder encoder,
        ISystemClock clock,
        UserManager<ApplicationUser> userManager,
        SignInManager<ApplicationUser> signInManager)
        : base(options, loggerFactory, encoder, clock)
    {
        _userManager = userManager;
        _signInManager = signInManager;
        _logger = loggerFactory.CreateLogger<CustomAuthenticationHandler>();
    }

    protected override async Task<AuthenticateResult> HandleAuthenticateAsync()
    {
        var token = Request.Headers["Authorization"].ToString().Replace("Bearer ", "");
        if (string.IsNullOrEmpty(token))
            return AuthenticateResult.NoResult();

        var user = await _userManager.FindByLoginAsync("custom", token);
        if (user == null)
            return AuthenticateResult.Fail("Invalid token");

        var claims = new List<Claim>
        {
            new Claim(ClaimTypes.Name, user.UserName),
            new Claim(ClaimTypes.Role, "User")
        };

        var identity = new ClaimsIdentity(claims, Scheme.Name);
        var ticket = new AuthenticationTicket(new ClaimsPrincipal(identity), Scheme.Name);

        return AuthenticateResult.Success(ticket);
    }

    protected override async Task HandleChallengeAsync(AuthenticationProperties properties)
    {
        // Implement challenge logic here
    }
}

public class CustomAuthenticationOptions : AuthenticationSchemeOptions
{
    public string Realm { get; set; } = "CustomAuth";
}

public class ApplicationUser : IdentityUser
{
    public bool IsLockedOut { get; set; }
    public DateTime? LockoutEnd { get; set; }
}

public class CustomAuthorizationHandler : AuthorizationHandler<CustomRequirement>
{
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext context, CustomRequirement requirement)
    {
        if (context.User.IsInRole("Admin"))
            context.Succeed(requirement);
        return Task.CompletedTask;
    }
}

public class CustomRequirement : IAuthorizationRequirement
{
}

public static class CustomAuthenticationExtensions
{
    public static AuthenticationBuilder AddCustomAuthentication(this AuthenticationBuilder builder)
    {
        builder.AddScheme<CustomAuthenticationOptions, CustomAuthenticationHandler>("CustomAuth", options => { });
        return builder;
    }

    public static AuthorizationBuilder AddCustomAuthorization(this AuthorizationBuilder builder)
    {
        builder.AddPolicy("AdminOnly", policy => policy.Requirements.Add(new CustomRequirement()));
        return builder;
    }
}
