        printf("Error: Maximum entries reached.\n");
        return;
    }

    int index = -1;
    for (int i = 0; i < count; i++) {
        if (array[i]->RNTI == RNTI) {
            index = i;
            break;
        }
    }

    if (index != -1) {
        // Overwrite existing entry
        free(array[index]);
        array[index] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array[index]->RNTI = RNTI;
        // Initialize other fields...
    } else {
        // Add new entry
        if (count < MAX_ENTRIES) {
            array[count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array[count]->RNTI = RNTI;
            // Initialize other fields...
            count++;
        }
    }

    printf("Current count: %d\n", count);
}

void free_array() {
    for (int i = 0; i < count; i++) {
        free(array[i]);
    }
    count = 0;
