#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    char source_ip[16];
    char destination_ip[16];
    int payload_length;
    int status; // 0 for inactive, 1 for active
} Packet;

typedef struct {
    Packet* packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketArray;

void init_packet_array(PacketArray* array, size_t initial_capacity) {
    array->packets = (Packet*)malloc(initial_capacity * sizeof(Packet));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void add_packet(PacketArray* array, Packet packet) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet* new_packets = (Packet*)realloc(array->packets, new_capacity * sizeof(Packet));
        if (!new_packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
}

void update_packet(PacketArray* array, int index, Packet packet) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        array->packets[index] = packet;
    }
    pthread_mutex_unlock(&array->lock);
}

void mark_packet_status(PacketArray* array, int index, int status) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        array->packets[index].status = status;
    }
    pthread_mutex_unlock(&array->lock);
}

int calculate_total_data_transferred(PacketArray* array) {
    int total = 0;
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i].status == 1) {
            total += array->packets[i].payload_length;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return total;
}

void filter_packets_by_source_ip(PacketArray* array, char* source_ip) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->packets[i].source_ip, source_ip) != 0) {
            mark_packet_status(array, i, 0); // Mark as inactive
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void filter_packets_by_destination_ip(PacketArray* array, char* destination_ip) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->packets[i].destination_ip, destination_ip) != 0) {
            mark_packet_status(array, i, 0); // Mark as inactive
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void prune_inactive_packets(PacketArray* array) {
    pthread_mutex_lock(&array->lock);
    size_t new_size = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i].status == 1) {
            array->packets[new_size++] = array->packets[i];
        }
    }
    array->size = new_size;
    pthread_mutex_unlock(&array->lock);
}

void destroy_packet_array(PacketArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}
