// Define structures
typedef struct {
    double value;
    char unit[10];
    struct sensor_info *sensor;
} measurement;

typedef struct {
    int id;
    float voltage;
    char model[50];
} sensor_info;

// Global variables for shared resources
double **double_array = NULL;
unsigned int *int_array = NULL;
measurement **measurement_array = NULL;
sensor_info **sensor_info_array = NULL;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory and handle errors
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize data structures
void init_data_structures(int num_entries) {
    double_array = safe_malloc(num_entries * sizeof(double *));
    int_array = safe_malloc(num_entries * sizeof(unsigned int));
    measurement_array = safe_malloc(num_entries * sizeof(measurement *));
    sensor_info_array = safe_malloc(num_entries * sizeof(sensor_info *));

    for (int i = 0; i < num_entries; i++) {
        double_array[i] = safe_malloc(sizeof(double));
        int_array[i] = safe_malloc(sizeof(unsigned int));
        measurement_array[i] = safe_malloc(sizeof(measurement));
        sensor_info_array[i] = safe_malloc(sizeof(sensor_info));
    }
}

// Function to read data from files
void read_data_from_files(const char *file_paths[], int num_files, int num_entries) {
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, read_file_thread, (void *)file_paths[i]) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Thread function to read data from a single file
void* read_file_thread(void *file_path) {
    const char *path = (const char *)file_path;
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        perror("File opening failed");
        return NULL;
    }

    // Read data and store in shared arrays
    for (int i = 0; i < num_entries; i++) {
        fscanf(file, "%lf %u %s %d %f %s", 
               double_array[i], int_array[i], measurement_array[i]->unit,
               &sensor_info_array[i]->id, &sensor_info_array[i]->voltage, sensor_info_array[i]->model);
    }

    fclose(file);
    return NULL;
}

// Function to free allocated memory
void free_memory(int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(double_array[i]);
        free(int_array[i]);
        free(measurement_array[i]);
        free(sensor_info_array[i]);
    }
    free(double_array);
    free(int_array);
    free(measurement_array);
    free(sensor_info_array);
}

// Main function
int main() {
    int num_entries = 100; // Example number of entries
    const char *file_paths[] = {"file1.txt", "file2.txt"}; // Example file paths

    init_data_structures(num_entries);
    read_data_from_files(file_paths, sizeof(file_paths) / sizeof(file_paths[0]), num_entries);

    // Perform operations on the data structures...

    free_memory(num_entries);
    return 0;
}
