}

void loadFileInChunks(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        logOperation(ENCRYPT, "Failed to open file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = (char*)malloc(fileSize + 1);
    if (!buffer) {
        logOperation(ENCRYPT, "Failed to allocate memory");
        fclose(file);
        return;
    }

    size_t bytesRead = fread(buffer, 1, fileSize, file);
    if (bytesRead != fileSize) {
        logOperation(ENCRYPT, "Failed to read file");
        free(buffer);
        fclose(file);
        return;
    }
    buffer[bytesRead] = '\0';

    // Process the file based on operation
    switch (op) {
        case ENCRYPT:
            // Encrypt logic here
            break;
        case DECRYPT:
            // Decrypt logic here
            break;
        case SIGN:
            // Sign logic here
            break;
    }

    exportResults(buffer, bytesRead, "text");
    free(buffer);
    fclose(file);
}

