NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu(int rx_ue_information_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    return pdu;
}

LogEntry* create_log_entry(time_t timestamp, int severity_level, int unique_log_id, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (entry == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    entry->timestamp = timestamp;
    entry->severity_level = severity_level;
    entry->unique_log_id = unique_log_id;
    strncpy(entry->message, message, sizeof(entry->message));
