    *keys = aligned_malloc(size * sizeof(int), 8);
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = aligned_malloc(size * sizeof(record), 32);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (size_t i = 0; i < size; ++i) {
        (*keys)[i] = i;
        (*records)[i].value = rand();
    }

    return 0;
}

void cleanup(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
