#include <stdlib.h>
#include <string.h>
#include "external_string_lib.h"
#include "memory_pool.h"

typedef struct Record {
    int value;
    char* key;
    int ref_count;
    int id;
} Record;

typedef struct HashTable {
    size_t size;
    Record** buckets;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = (HashTable*)memory_pool_alloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = size;
    table->buckets = (Record**)memory_pool_alloc(size * sizeof(Record*));
    if (!table->buckets) {
        memory_pool_free(table);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        table->buckets[i] = NULL;
    }

    return table;
}

void destroy_hash_table(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        Record* record = table->buckets[i];
        while (record) {
            Record* next = record->next;
            external_string_free(record->key);
            memory_pool_free(record);
            record = next;
        }
    }

    memory_pool_free(table->buckets);
    memory_pool_free(table);
}

Record* create_record(int value, const char* key, int id) {
    Record* record = (Record*)memory_pool_alloc(sizeof(Record));
    if (!record) return NULL;

    record->value = value;
    record->key = external_string_duplicate(key);
    if (!record->key) {
        memory_pool_free(record);
        return NULL;
    }

    record->ref_count = 1;
    record->id = id;
    record->next = NULL;

    return record;
}

void destroy_record(Record* record) {
    if (!record) return;

    external_string_free(record->key);
    memory_pool_free(record);
}

int hash_function(const char* key, size_t size) {
    // Simple hash function for demonstration
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % size;
}

void insert_record(HashTable* table, Record* record) {
    if (!table || !record) return;

    size_t index = hash_function(record->key, table->size);
    record->next = table->buckets[index];
    table->buckets[index] = record;
}

Record* find_record(HashTable* table, const char* key) {
    if (!table || !key) return NULL;

    size_t index = hash_function(key, table->size);
    Record* record = table->buckets[index];
    while (record) {
        if (strcmp(record->key, key) == 0) {
            record->ref_count++;
            return record;
        }
        record = record->next;
    }

    return NULL;
}

void remove_record(HashTable* table, const char* key) {
    if (!table || !key) return;

    size_t index = hash_function(key, table->size);
    Record** prev = &table->buckets[index];
    Record* record = *prev;
    while (record) {
        if (strcmp(record->key, key) == 0) {
            record->ref_count--;
            if (record->ref_count == 0) {
                *prev = record->next;
                destroy_record(record);
            }
            return;
        }
        prev = &record->next;
        record = *prev;
    }
}
