#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int user_id;
    time_t start_time;
    time_t end_time;
    size_t total_bytes;
    int priority;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionManager;

void session_manager_init(SessionManager *manager, size_t initial_capacity) {
    manager->sessions = malloc(initial_capacity * sizeof(UserSession));
    if (manager->sessions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void session_manager_add(SessionManager *manager, UserSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UserSession *new_sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession));
        if (new_sessions == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void session_manager_update(SessionManager *manager, int user_id, UserSession updated_session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].user_id == user_id) {
            manager->sessions[i] = updated_session;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void session_manager_delete(SessionManager *manager, int user_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].user_id == user_id) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(UserSession));
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void session_manager_log_sessions(SessionManager *manager, const char *log_file_path, time_t threshold) {
    FILE *log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        time_t active_time = manager->sessions[i].end_time - manager->sessions[i].start_time;
        if (active_time > threshold) {
            fprintf(log_file, "User ID: %d, Active Time: %ld seconds\n", manager->sessions[i].user_id, active_time);
        }
    }
    pthread_mutex_unlock(&manager->lock);
    fclose(log_file);
}

void session_manager_destroy(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}
