struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    std::atomic<bool> CRCFLAG;
};

class DynamicArrayManager {
public:
    DynamicArrayManager(size_t initialCapacity) : capacity(initialCapacity), size(0), data(capacity) {}

    void addPacket(int rxTag, int rnti) {
        if (size == capacity) {
            resize();
        }
        data[size].RX_UE_INFORMATION_TAG = rxTag;
        data[size].RNTI = rnti;
        data[size].CRCFLAG.store(false); // Initialize CRCFLAG to false
        ++size;
    }

    void processPackets() {
        for (size_t i = 0; i < size; ++i) {
            // Simulate packet processing logic
            data[i].CRCFLAG.store(true);
        }
    }

private:
    void resize() {
        capacity *= 2;
        std::vector<NFAPI_CRC_INDICATION_PDU_T> newData(capacity);
        for (size_t i = 0; i < size; ++i) {
            newData[i] = data[i];
        }
        data = std::move(newData);
    }

    size_t capacity;
    size_t size;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
};

int main() {
    DynamicArrayManager manager(10);

    // Simulate adding packets
    for (int i = 0; i < 20; ++i) {
        manager.addPacket(i, i * 10);
    }

    // Process packets
    manager.processPackets();

    return 0;
}
