#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    int priority;
    time_t estimated_completion;
    time_t actual_start;
    char status[20];
} Task;

typedef struct Node {
    Task task;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} TaskList;

void initTaskList(TaskList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addTask(TaskList* list, Task task) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->task = task;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void updateTask(TaskList* list, int taskId, Task updatedTask) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->task.id == taskId) {
            current->task = updatedTask;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void markTaskCompleted(TaskList* list, int taskId) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->task.id == taskId) {
            strcpy(current->task.status, "completed");
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void identifyOverdueTasks(TaskList* list, time_t deadlineThreshold) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (time(NULL) > current->task.estimated_completion + deadlineThreshold && strcmp(current->task.status, "pending") == 0) {
            printf("Task %d is overdue and needs review.\n", current->task.id);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeTaskList(TaskList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
