#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

int initialize_cipher_context(const char *password, size_t password_len,
                              const unsigned char *salt, size_t salt_len,
                              unsigned char **key, unsigned char **iv,
                              EVP_CIPHER_CTX **ctx, int key_length,
                              int iterations) {
    // Derive key and IV using PBKDF2
    if (PKCS5_PBKDF2_HMAC_SHA256(password, password_len, salt, salt_len,
                                  iterations, key_length, key) != 1 ||
        RAND_bytes(iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc())) != 1) {
        return -1;
    }

    // Initialize cipher context
    *ctx = EVP_CIPHER_CTX_new();
    if (*ctx == NULL) {
        return -1;
    }
    if (EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, *key, *iv) != 1) {
        EVP_CIPHER_CTX_free(*ctx);
        return -1;
    }

    return 0;
}

void cleanup_cipher_context(EVP_CIPHER_CTX **ctx, unsigned char **key,
                            unsigned char **iv) {
    if (*ctx != NULL) {
        EVP_CIPHER_CTX_free(*ctx);
        *ctx = NULL;
    }
    if (*key != NULL) {
        OPENSSL_cleanse(*key, EVP_CIPHER_key_length(EVP_aes_256_cbc()));
        free(*key);
        *key = NULL;
    }
    if (*iv != NULL) {
        OPENSSL_cleanse(*iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc()));
        free(*iv);
        *iv = NULL;
    }
}

int initialize_records(Record **records, size_t num_records, int min_value,
                        int max_value) {
    *records = (Record *)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return 0;
}

void cleanup_records(Record **records, size_t num_records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}
