#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 10000

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int payload_length;
    int packet_flags;
    int sequence_number;
    char type[32];
} Packet;

Packet* packets[MAX_PACKETS];
int packet_count = 0;

void add_packet(Packet* new_packet) {
    if (packet_count < MAX_PACKETS) {
        packets[packet_count++] = new_packet;
    } else {
        printf("Error: Maximum number of packets reached.\n");
    }
}

void update_packet(int index, Packet* updated_packet) {
    if (index >= 0 && index < packet_count) {
        packets[index] = updated_packet;
    } else {
        printf("Error: Invalid packet index.\n");
    }
}

void delete_packet(int index) {
    if (index >= 0 && index < packet_count) {
        for (int i = index; i < packet_count - 1; i++) {
            packets[i] = packets[i + 1];
        }
        packet_count--;
    } else {
        printf("Error: Invalid packet index.\n");
    }
}

void calculate_statistics() {
    int total_data_transferred = 0;
    double average_packet_size = 0.0;
    char most_frequent_type[32] = "";
    int max_frequency = 0;

    for (int i = 0; i < packet_count; i++) {
        total_data_transferred += packets[i]->payload_length;
        if (packets[i]->payload_length > average_packet_size) {
            average_packet_size = packets[i]->payload_length;
        }
        int frequency = 1;
        for (int j = i + 1; j < packet_count; j++) {
            if (strcmp(packets[j]->type, packets[i]->type) == 0) {
                frequency++;
            }
        }
        if (frequency > max_frequency) {
            max_frequency = frequency;
            strcpy(most_frequent_type, packets[i]->type);
        }
    }

    printf("Total data transferred: %d\n", total_data_transferred);
    printf("Average packet size: %.2f\n", average_packet_size);
    printf("Most frequent packet type: %s\n", most_frequent_type);
}

void export_to_csv(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error: Unable to open file for writing.\n");
        return;
    }

    fprintf(file, "Timestamp,Source IP,Destination IP,Payload Length,Packet Flags,Sequence Number,Type\n");

    for (int i = 0; i < packet_count; i++) {
        fprintf(file, "%ld,%s,%s,%d,%d,%d,%s\n",
                packets[i]->timestamp,
                packets[i]->source_ip,
                packets[i]->destination_ip,
                packets[i]->payload_length,
                packets[i]->packet_flags,
                packets[i]->sequence_number,
                packets[i]->type);
    }

    fclose(file);
}

int main() {
    // Example usage
    Packet packet1 = {time(NULL), "192.168.1.1", "10.0.0.1", 1024, 0x01, 1, "TCP"};
    add_packet(&packet1);

    calculate_statistics();
    export_to_csv("packets.csv");

    return 0;
}
