typedef struct {
    int cell_id;
    float ul_error_rate;
    float dl_error_rate;
    double throughput_ul;
    double throughput_dl;
    int signal_strength;
} LTEPHYLayerStats;

typedef struct {
    LTEPHYLayerStats *stats_array;
    size_t array_size;
    size_t used_entries;
    pthread_mutex_t lock;
} LTEPHYLayerStatsArray;

LTEPHYLayerStatsArray* init_stats_array(size_t initial_size) {
    LTEPHYLayerStatsArray *array = (LTEPHYLayerStatsArray*)malloc(sizeof(LTEPHYLayerStatsArray));
    if (!array) return NULL;

    array->stats_array = (LTEPHYLayerStats*)calloc(initial_size, sizeof(LTEPHYLayerStats));
    if (!array->stats_array) {
        free(array);
        return NULL;
    }

    array->array_size = initial_size;
    array->used_entries = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_stats_array(LTEPHYLayerStatsArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array->stats_array);
        free(array);
    }
}

int add_stats_entry(LTEPHYLayerStatsArray *array, LTEPHYLayerStats stats) {
    pthread_mutex_lock(&array->lock);

    if (array->used_entries >= array->array_size) {
        size_t new_size = array->array_size * 2;
        LTEPHYLayerStats *new_array = (LTEPHYLayerStats*)realloc(array->stats_array, new_size * sizeof(LTEPHYLayerStats));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->stats_array = new_array;
        array->array_size = new_size;
    }

    array->stats_array[array->used_entries++] = stats;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void validate_and_cleanup(LTEPHYLayerStatsArray *array) {
    pthread_mutex_lock(&array->lock);

