#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CELLS 1024

typedef struct {
    int cell_id;
    float uplink_error_rate;
    float downlink_error_rate;
    double throughput;
    int signal_strength;
} LTEPHYLayerStats;

LTEPHYLayerStats *stats_array = NULL;
int array_size = 0;
sem_t stats_mutex;
sem_t resize_semaphore;

void initialize_stats_array() {
    sem_init(&stats_mutex, 0, 1);
    sem_init(&resize_semaphore, 0, 1);
    stats_array = (LTEPHYLayerStats *)malloc(MAX_CELLS * sizeof(LTEPHYLayerStats));
    array_size = MAX_CELLS;
}

void resize_stats_array(int new_size) {
    LTEPHYLayerStats *new_array = (LTEPHYLayerStats *)realloc(stats_array, new_size * sizeof(LTEPHYLayerStats));
    if (new_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    stats_array = new_array;
    array_size = new_size;
}

void update_stats(int cell_id, float uplink_error_rate, float downlink_error_rate, double throughput, int signal_strength) {
    sem_wait(&stats_mutex);
    if (cell_id >= array_size) {
        resize_stats_array(cell_id + 1);
    }
    stats_array[cell_id].cell_id = cell_id;
    stats_array[cell_id].uplink_error_rate = uplink_error_rate;
    stats_array[cell_id].downlink_error_rate = downlink_error_rate;
    stats_array[cell_id].throughput = throughput;
    stats_array[cell_id].signal_strength = signal_strength;
    sem_post(&stats_mutex);
}

void validate_and_cleanup() {
    sem_wait(&resize_semaphore);
    // Implement validation and cleanup logic here
    sem_post(&resize_semaphore);
}

void export_stats_to_file(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    sem_wait(&stats_mutex);
    for (int i = 0; i < array_size; i++) {
        fprintf(file, "Cell ID: %d, Uplink Error Rate: %.2f%%, Downlink Error Rate: %.2f%%, Throughput: %.2f Mbps, Signal Strength: %d dBm\n",
                stats_array[i].cell_id,
                stats_array[i].uplink_error_rate * 100,
                stats_array[i].downlink_error_rate * 100,
                stats_array[i].throughput,
                stats_array[i].signal_strength);
    }
    sem_post(&stats_mutex);
    fclose(file);
}

void cleanup() {
    sem_destroy(&stats_mutex);
    sem_destroy(&resize_semaphore);
    free(stats_array);
}
