#include <pthread.h>

#define MAX_PACKETS 1024
#define PAYLOAD_LENGTH 1500
#define IDENTIFIER_RANGE 1000

typedef struct {
    time_t timestamp;
    u_char source_ip[4];
    u_char destination_ip[4];
    int payload_length;
    int identifier;
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

int init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->packets = (NetworkPacket *)aligned_alloc(64, initial_capacity * sizeof(NetworkPacket));
    if (!array->packets) return -1; // Memory allocation failed
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return 0;
}

void destroy_packet_array(PacketArray *array) {
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}

int add_packet(PacketArray *array, NetworkPacket packet) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NetworkPacket *new_packets = (NetworkPacket *)aligned_alloc(64, new_capacity * sizeof(NetworkPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        memcpy(new_packets, array->packets, array->size * sizeof(NetworkPacket));
        free(array->packets);
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_packet(PacketArray *array, size_t index, NetworkPacket packet) {
    if (index >= array->size) return -1; // Index out of bounds
    pthread_mutex_lock(&array->lock);
    array->packets[index] = packet;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int iterate_packets(PacketArray *array, void (*callback)(NetworkPacket *)) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        callback(&array->packets[i]);
    }
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int resolve_dns(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1; // DNS resolution failed
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &(ipv4->sin_addr), 4);
        break;
    }

    freeaddrinfo(res);
    return 0;
}

