#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 10000

typedef struct {
    int user_id;
    time_t start_time;
    time_t end_time;
    int active;
    size_t data_consumed;
} Session;

Session sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_session(int user_id, size_t data_consumed) {
    pthread_mutex_lock(&mutex);
    if (session_count < MAX_SESSIONS) {
        sessions[session_count].user_id = user_id;
        sessions[session_count].start_time = time(NULL);
        sessions[session_count].end_time = 0;
        sessions[session_count].active = 1;
        sessions[session_count].data_consumed = data_consumed;
        session_count++;
    } else {
        printf("Session limit reached.\n");
    }
    pthread_mutex_unlock(&mutex);
}

void end_session(int user_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].user_id == user_id && sessions[i].active) {
            sessions[i].end_time = time(NULL);
            sessions[i].active = 0;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void cleanup_inactive_sessions(time_t inactive_threshold) {
    pthread_mutex_lock(&mutex);
    for (int i = session_count - 1; i >= 0; i--) {
        if (!sessions[i].active && difftime(time(NULL), sessions[i].end_time) > inactive_threshold) {
            // Log session end event
            printf("Session %d ended.\n", sessions[i].user_id);
            memmove(&sessions[i], &sessions[i + 1], (session_count - i - 1) * sizeof(Session));
            session_count--;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* monitor_sessions(void* arg) {
    time_t inactive_threshold = *(time_t*)arg;
    while (1) {
        cleanup_inactive_sessions(inactive_threshold);
        sleep(60); // Check every minute
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread;
    time_t inactive_threshold = 3600; // 1 hour

    if (pthread_create(&monitor_thread, NULL, monitor_sessions, &inactive_threshold) != 0) {
        printf("Failed to create monitor thread.\n");
        return 1;
    }

    add_session(1, 1024);
    sleep(5);
    end_session(1);

    pthread_join(monitor_thread, NULL);
    return 0;
}
```

This code provides a basic framework for managing user session records in C. It includes functions to add and end sessions, cleanup inactive sessions, and monitor them periodically. The use of mutexes ensures thread safety, and the periodic cleanup helps manage memory efficiently by removing inactive sessions.']

