    for (int i = 0; i < MAX_RESOURCES; i++) {
        resource_list[i] = NULL;
    }
}

void populate_resource(int index, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (index >= 0 && index < MAX_RESOURCES) {
        NFAPI_CRC_INDICATION_PDU_T* new_resource = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_resource->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_resource->RNTI = RNTI;
