        sessions[session_count].latency_time = latency_time;
        session_count++;
    }
    pthread_mutex_unlock(&session_lock);
}

void update_session(const char* session_id, const char* user_agent, const char* request_method, const char* request_uri, int response_status_code, double latency_time) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].session_id, session_id) == 0) {
            strcpy(sessions[i].user_agent, user_agent);
            strcpy(sessions[i].request_method, request_method);
            strcpy(sessions[i].request_uri, request_uri);
            sessions[i].response_status_code = response_status_code;
            sessions[i].latency_time = latency_time;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

