            if (strcmp(sessions[i].request_method, request_methods[j]) == 0) {
                method_counts[j]++;
                break;
            }
        }
    }
    *avg_latency /= session_count;

    int max_count = 0;
    for (int i = 0; i < 10; i++) {
        if (method_counts[i] > max_count) {
            max_count = method_counts[i];
            strcpy(most_freq_method, request_methods[i]);
        }
    }

    pthread_mutex_unlock(&session_lock);
}

