#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} List;

void initList(List* list) {
    list->head = NULL;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertNode(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void freeList(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
}

int isRNTIDuplicate(List* list, int RNTI) {
    Node* temp = list->head;
    while (temp != NULL) {
        if (temp->data.RNTI == RNTI) {
            return 1; // Duplicate found
        }
        temp = temp->next;
    }
    return 0; // No duplicate found
}

void generateRandomPDU(NFAPI_CRC_INDICATION_PDU_T* pdu, int seed) {
    srand(seed);
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 1024; // Assuming RNTI is a 10-bit value
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
}

void manageNFAPDUList(List* list, int N, int seed) {
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generateRandomPDU(&pdu, seed);
        if (isRNTIDuplicate(list, pdu.RNTI)) {
            fprintf(stderr, "Error: Duplicate RNTI detected\n");
            freeList(list);
            exit(1);
        }
        insertNode(list, pdu);
    }
}

int main() {
    List list;
    initList(&list);

    int N = 10; // Number of PDUs to generate
    int seed = time(NULL); // Use current time as seed for random number generation

    manageNFAPDUList(&list, N, seed);

    freeList(&list);
    return 0;
}
