<?php

class OAuth2Client {
    private $client;
    private $cache;
    private $session;

    public function __construct($clientId, $clientSecret, $redirectUri) {
        $this->client = new League\OAuth2\Client\Client([
            'clientId' => $clientId,
            'clientSecret' => $clientSecret,
            'redirectUri' => $redirectUri,
        ]);
        $this->cache = new Symfony\Component\Cache\FilesystemCache('oauth_cache');
        $this->session = new Session();
    }

    public function authenticate($code) {
        try {
            $tokenResponse = $this->client->getAccessToken('authorization_code', [
                'code' => $code,
            ]);
            $this->cache->set('access_token', $tokenResponse->getToken(), $tokenResponse->getExpires());
            return true;
        } catch (\Exception $e) {
            return false;
        }
    }

    public function getUserInfo() {
        $accessToken = $this->cache->get('access_token');
        if (!$accessToken || $this->isTokenExpired($accessToken)) {
            $this->refreshAccessToken();
        }
        try {
            $userResponse = $this->client->getResourceOwner($accessToken);
            return $userResponse->toArray();
        } catch (\Exception $e) {
            return null;
        }
    }

    private function isTokenExpired($token) {
        $expiresAt = $this->cache->get('access_token_expires_at');
        return time() >= $expiresAt;
    }

    private function refreshAccessToken() {
        try {
            $refreshToken = $this->cache->get('refresh_token');
            $newTokenResponse = $this->client->getAccessToken('refresh_token', [
                'refresh_token' => $refreshToken,
            ]);
            $this->cache->set('access_token', $newTokenResponse->getToken(), $newTokenResponse->getExpires());
            $this->cache->set('refresh_token', $newTokenResponse->getRefreshToken(), $newTokenResponse->getExpires());
        } catch (\Exception $e) {
            // Handle token refresh failure
        }
    }

    public function logout() {
        $this->session->clear();
        $this->cache->deleteItem('access_token');
        $this->cache->deleteItem('refresh_token');
    }
}

class Session {
    public function clear() {
        session_unset();
        session_destroy();
    }
}
