#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    CMP_TYPE_A,
    CMP_TYPE_B,
    // Add more types as needed
} CMP_MESSAGE_TYPE;

typedef struct cmp_message {
    int session_id;
    int sequence_number;
    CMP_MESSAGE_TYPE type;
    struct cmp_message *next;
} CMP_Message;

typedef struct {
    CMP_Message *head;
    pthread_mutex_t lock;
} CMP_List;

void init_cmp_list(CMP_List *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_cmp_message(CMP_List *list, int session_id, int sequence_number, CMP_MESSAGE_TYPE type) {
    pthread_mutex_lock(&list->lock);
    CMP_Message *new_msg = (CMP_Message *)malloc(sizeof(CMP_Message));
    if (new_msg == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_msg->session_id = session_id;
    new_msg->sequence_number = sequence_number;
    new_msg->type = type;
    new_msg->next = list->head;
    list->head = new_msg;
    pthread_mutex_unlock(&list->lock);
}

void remove_cmp_message(CMP_List *list, int session_id) {
    pthread_mutex_lock(&list->lock);
    CMP_Message *current = list->head;
    CMP_Message *prev = NULL;

    while (current != NULL) {
        if (current->session_id == session_id) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_cmp_message(CMP_List *list, int session_id, int new_sequence_number) {
    pthread_mutex_lock(&list->lock);
    CMP_Message *current = list->head;

    while (current != NULL) {
        if (current->session_id == session_id) {
            current->sequence_number = new_sequence_number;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_cmp_list(CMP_List *list) {
    pthread_mutex_lock(&list->lock);
    CMP_Message *current = list->head;
    while (current != NULL) {
        CMP_Message *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    CMP_List cmp_list;
    init_cmp_list(&cmp_list);

    // Simulate adding messages
    add_cmp_message(&cmp_list, 1, 100, CMP_TYPE_A);
    add_cmp_message(&cmp_list, 2, 200, CMP_TYPE_B);

    // Simulate updating a message
    update_cmp_message(&cmp_list, 1, 150);

    // Simulate removing a message
    remove_cmp_message(&cmp_list, 2);

    free_cmp_list(&cmp_list);
    return 0;
}
```

This code provides a basic implementation of a linked list for managing CMP messages with thread-safe operations. It includes functions to add, update, and remove messages, as well as initializing and freeing the list. The use of mutexes ensures that concurrent access is handled safely. This example can be expanded and integrated into a larger system to demonstrate dynamic management of CMP messages under high load conditions.']

