#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    int client_id;
    time_t request_timestamp;
    char *data_buffer;
} Session;

Session session_pool[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t pool_lock;

int validate_client_id(int client_id) {
    for (int i = 0; i < session_count; i++) {
        if (session_pool[i].client_id == client_id) {
            return -1; // Duplicate ID found
        }
    }
    return 0; // Unique ID
}

void allocate_session(int client_id, time_t timestamp, int data_size) {
    pthread_mutex_lock(&pool_lock);
    if (session_count < MAX_SESSIONS && validate_client_id(client_id) == 0) {
        session_pool[session_count].client_id = client_id;
        session_pool[session_count].request_timestamp = timestamp;
        session_pool[session_count].data_buffer = malloc(data_size * sizeof(char));
        memset(session_pool[session_count].data_buffer, 0, data_size);
        session_count++;
    }
    pthread_mutex_unlock(&pool_lock);
}

void deallocate_session(int client_id) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < session_count; i++) {
        if (session_pool[i].client_id == client_id) {
            free(session_pool[i].data_buffer);
            memmove(&session_pool[i], &session_pool[i + 1], (session_count - i - 1) * sizeof(Session));
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

void initialize_session_pool() {
    pthread_mutex_init(&pool_lock, NULL);
}

void shutdown_session_pool() {
    for (int i = 0; i < session_count; i++) {
        free(session_pool[i].data_buffer);
    }
    pthread_mutex_destroy(&pool_lock);
}
