#include <time.h>

#define MAX_PDUS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pdu_list[MAX_PDUS];
int pdu_count = 0;

void init_random_seed(int seed) {
    srand(seed);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 65536; // Unique RNTI
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
    return pdu;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu_count >= MAX_PDUS) {
        fprintf(stderr, "PDU list is full\n");
        exit(1);
    }
    for (int i = 0; i < pdu_count; i++) {
        if (pdu_list[i]->RNTI == pdu->RNTI) {
            fprintf(stderr, "Duplicate RNTI detected: %d\n", pdu->RNTI);
            exit(1);
        }
    }
    pdu_list[pdu_count++] = pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    free(pdu);
}

void batch_add_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus[], int count) {
    for (int i = 0; i < count; i++) {
        add_pdu(pdus[i]);
    }
}

void simulate_memory_fragmentation() {
    // Simulate memory fragmentation by freeing and reallocating memory
    for (int i = 0; i < pdu_count / 2; i++) {
        free_pdu(pdu_list[i]);
        pdu_list[i] = NULL;
    }
