#include <arpa/inet.h>
#include <pthread.h>

#define MAX_PACKETS 2000
#define MAX_IP_LENGTH 16

typedef struct {
    time_t timestamp;
    char source_ip[MAX_IP_LENGTH];
    char destination_ip[MAX_IP_LENGTH];
    int payload_length;
} NetworkPacket;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NetworkPacket packet;
    NFAPI_CRC_INDICATION_PDU_T crc_info;
} PacketEntry;

PacketEntry *packet_array = NULL;
int packet_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

u_char* resolve_dns(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;
    static u_char ip[16];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy((char*)ip, ipstr);
    }

    freeaddrinfo(res); // all done with this structure
    return ip;
}

int add_packet(const char *hostname, int payload_length) {
    pthread_mutex_lock(&mutex);

    if (packet_count >= MAX_PACKETS) {
        fprintf(stderr, "Packet array is full\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    NetworkPacket packet;
    packet.timestamp = time(NULL);
    strcpy(packet.source_ip, resolve_dns(hostname));
    packet.destination_ip[0] = '\0'; // Set destination IP to empty for simplicity
    packet.payload_length = payload_length;

    NFAPI_CRC_INDICATION_PDU_T crc_info;
    crc_info.RX_UE_INFORMATION_TAG = rand();
    crc_info.RNTI = rand() % 65536;
    crc_info.CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;

    PacketEntry entry;
    entry.packet = packet;
    entry.crc_info = crc_info;

    if (packet_array == NULL) {
        packet_array = (PacketEntry *)malloc(MAX_PACKETS * sizeof(PacketEntry));
        if (packet_array == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    packet_array[packet_count++] = entry;

    pthread_mutex_unlock(&mutex);
    return 0;
}

int update_packet(int index, int new_payload_length) {
    pthread_mutex_lock(&mutex);

    if (index < 0 || index >= packet_count) {
        fprintf(stderr, "Invalid packet index\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    packet_array[index].packet.payload_length = new_payload_length;

    pthread_mutex_unlock(&mutex);
    return 0;
}

int calculate_total_data_transferred() {
    int total = 0;
    for (int i = 0; i < packet_count; i++) {
        total += packet_array[i].packet.payload_length;
    }
    return total;
}
