void initializeArrays(int arraySize, int minValue, int maxValue, int validateUnique) {
    if (arraySize <= 0 || minValue > maxValue) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    long* offset = (long*)malloc(arraySize * sizeof(long));
    int* key = (int*)malloc(arraySize * sizeof(int));
    record* records = (record*)malloc(arraySize * sizeof(record));

    if (!offset || !key || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offset);
        free(key);
        free(records);
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < arraySize; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;

        if (validateUnique) {
            int duplicate = 0;
            for (int j = 0; j < i; ++j) {
                if (records[j].value == records[i].value) {
                    fprintf(stderr, "Duplicate value detected: %d\n", records[i].value);
                    duplicate = 1;
                    break;
                }
            }

            if (duplicate) {
                // Fallback strategy for handling duplicates
                records[i].value = rand() % (maxValue - minValue + 1) + minValue;
                i--; // Retry the current index
            }
        }
    }

    // Log initialization details
    printf("Number of records: %d\n", arraySize);
    printf("Random value range: [%d, %d]\n", minValue, maxValue);

    // Free allocated memory
    free(offset);
    free(key);
    free(records);
}

int main() {
    int arraySize = 1000;
    int minValue = 1;
    int maxValue = 100;

    initializeArrays(arraySize, minValue, maxValue, 1); // Validate unique elements

    return 0;
}
