#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Define the PacketHeader structure
typedef struct {
    uint32_t source;
    uint32_t destination;
} PacketHeader;

// Define the DataPayload structure
typedef struct {
    uint8_t *data;
    size_t length;
} DataPayload;

// Define the NetworkPacket structure
typedef struct {
    uint64_t id;
    PacketHeader header;
    DataPayload payload;
    uint32_t checksum;
} NetworkPacket;

// Define a simple hash table for packet storage
#define MAX_PACKETS 10000
NetworkPacket *packet_table[MAX_PACKETS];
pthread_mutex_t packet_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to calculate the checksum of a data payload
uint32_t calculate_checksum(const DataPayload *payload) {
    uint32_t sum = 0;
    for (size_t i = 0; i < payload->length; ++i) {
        sum += payload->data[i];
    }
    return sum;
}

// Function to add a new packet to the table
int add_packet(uint64_t id, const PacketHeader *header, const DataPayload *payload) {
    pthread_mutex_lock(&packet_lock);
    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        if (packet_table[i] == NULL) {
            packet_table[i] = malloc(sizeof(NetworkPacket));
            if (packet_table[i] == NULL) {
                pthread_mutex_unlock(&packet_lock);
                return -1;
            }
            packet_table[i]->id = id;
            memcpy(&packet_table[i]->header, header, sizeof(PacketHeader));
            packet_table[i]->payload.data = malloc(payload->length);
            if (packet_table[i]->payload.data == NULL) {
                free(packet_table[i]);
                pthread_mutex_unlock(&packet_lock);
                return -1;
            }
            memcpy(packet_table[i]->payload.data, payload->data, payload->length);
            packet_table[i]->payload.length = payload->length;
            packet_table[i]->checksum = calculate_checksum(payload);
            pthread_mutex_unlock(&packet_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&packet_lock);
    return -1; // Table is full
}

// Function to update an existing packet by its ID
int update_packet(uint64_t id, const PacketHeader *header, const DataPayload *payload) {
    pthread_mutex_lock(&packet_lock);
    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        if (packet_table[i] != NULL && packet_table[i]->id == id) {
            free(packet_table[i]->payload.data);
            memcpy(&packet_table[i]->header, header, sizeof(PacketHeader));
            packet_table[i]->payload.data = malloc(payload->length);
            if (packet_table[i]->payload.data == NULL) {
                pthread_mutex_unlock(&packet_lock);
                return -1;
            }
            memcpy(packet_table[i]->payload.data, payload->data, payload->length);
            packet_table[i]->payload.length = payload->length;
            packet_table[i]->checksum = calculate_checksum(payload);
            pthread_mutex_unlock(&packet_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&packet_lock);
    return -1; // Packet not found
}

// Function to retrieve a packet by its ID
NetworkPacket *get_packet(uint64_t id) {
    pthread_mutex_lock(&packet_lock);
    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        if (packet_table[i] != NULL && packet_table[i]->id == id) {
            NetworkPacket *result = malloc(sizeof(NetworkPacket));
            if (result == NULL) {
                pthread_mutex_unlock(&packet_lock);
                return NULL;
            }
            memcpy(result, packet_table[i], sizeof(NetworkPacket));
            pthread_mutex_unlock(&packet_lock);
            return result;
        }
    }
    pthread_mutex_unlock(&packet_lock);
    return NULL; // Packet not found
}

// Function to free all allocated memory for packets
void free_packets() {
    pthread_mutex_lock(&packet_lock);
    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        if (packet_table[i] != NULL) {
            free(packet_table[i]->payload.data);
            free(packet_table[i]);
            packet_table[i] = NULL;
        }
    }
    pthread_mutex_unlock(&packet_lock);
}
```

This code provides a basic implementation of managing a dynamic array of `NetworkPacket` structures using a hash table. It includes functions for adding, updating, and retrieving packets, as well as freeing all allocated memory when done. The use of mutexes ensures thread safety, and the checksum calculation is kept simple to avoid excessive overhead.']

