#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 100000

typedef struct {
    char timestamp[20];
    char source_ip[46]; // IPv4: 15 + ':' + '.' * 3 + '\0', IPv6: 45 + ':' * 7 + '\0'
    char destination_ip[46];
    int payload_length;
    char protocol_type[10];
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int count;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
}

int add_packet(PacketManager *manager, const Packet *packet) {
    if (manager->count >= MAX_PACKETS) {
        return -1; // Overflow
    }
    memcpy(&manager->packets[manager->count], packet, sizeof(Packet));
    manager->count++;
    return 0;
}

void flush_packets_to_disk(const PacketManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        // Simulate writing to disk
        printf("Writing packet %d to disk\n", i);
    }
    manager->count = 0; // Reset count after flushing
}

void reset_packet_manager(PacketManager *manager) {
    manager->count = 0;
}

int main() {
    PacketManager pm;
    init_packet_manager(&pm);

    Packet p1 = {"2023-04-01 12:00:00", "192.168.1.1", "10.0.0.1", 1500, "TCP"};
    Packet p2 = {"2023-04-01 12:01:00", "2001:db8::1", "2001:db8::2", 2048, "UDP"};

    add_packet(&pm, &p1);
    add_packet(&pm, &p2);

    flush_packets_to_disk(&pm);

    reset_packet_manager(&pm);

    return 0;
}
