    *keys = (int*)malloc(500 * sizeof(int));
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    MapEntry* map = (MapEntry*)malloc(500 * sizeof(MapEntry));

    // Initialize offsets with unique random values
    for (int i = 0; i < 1000; ++i) {
        (*offsets)[i] = rand() % 2000;
    }

    // Initialize keys with unique random values
    for (int i = 0; i < 500; ++i) {
        (*keys)[i] = rand() % 1000;
    }

    // Populate records and map
    int usedOffsets[2000] = {0};
    for (int i = 0; i < numRecords; ++i) {
        records[i].value = rand() % 1000 + 1;
        do {
            records[i].offset = &(*offsets)[rand() % 1000];
        } while (usedOffsets[*records[i].offset]);
        usedOffsets[*records[i].offset] = 1;

        map[i].key = (*keys)[i % 500];
        map[i].index = i;
    }

    *offsetsSize = 1000;
    *keysSize = 500;

    return records;
}

void validateMap(MapEntry* map, int size) {
    for (int i = 0; i < size; ++i) {
        if (map[i].index == -1) {
            printf("Key %d not found in map\n", map[i].key);
        }
    }
}

