    int* offsets;
    int* keys;
    Record* records;
    int offsetsSize, keysSize;

    records = allocateRecords(2000, &offsets, &offsetsSize, &keys, &keysSize);

    // Initialize map entries with -1 to indicate not found
    MapEntry* map = (MapEntry*)malloc(keysSize * sizeof(MapEntry));
    for (int i = 0; i < keysSize; ++i) {
        map[i].key = keys[i];
        map[i].index = -1;
    }

    // Populate map with valid indices
    for (int i = 0; i < 2000; ++i) {
        int keyIndex = records[i].value % keysSize;
        if (map[keyIndex].key == keys[keyIndex]) {
            map[keyIndex].index = i;
        }
    }

    validateMap(map, keysSize);

    // Free allocated memory
    free(records);
    free(offsets);
    free(keys);
    free(map);

    return 0;
}
