#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Task {
    int id;
    int priority;
    // Other task attributes
} Task;

typedef struct TaskList {
    Task** tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TaskList;

TaskList* create_task_list() {
    TaskList* list = (TaskList*)malloc(sizeof(TaskList));
    if (!list) {
        perror("Failed to allocate memory for task list");
        return NULL;
    }
    list->tasks = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_task_list(TaskList* list) {
    if (list) {
        for (size_t i = 0; i < list->count; ++i) {
            free(list->tasks[i]);
        }
        free(list->tasks);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_task(TaskList* list, Task* task) {
    if (!list || !task) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 4;
        Task** new_tasks = (Task**)realloc(list->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            perror("Failed to reallocate memory for task list");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
