    DL_DATA_PDU_TAG tag;
    PDCP_SN sn;
} LTE_Downlink_Data_Packet;

typedef struct {
    LTE_Downlink_Data_Packet *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Packet_Array;

void packet_array_init(Packet_Array *array) {
    array->capacity = MAX_PACKETS;
    array->size = 0;
    array->packets = (LTE_Downlink_Data_Packet *)malloc(array->capacity * sizeof(LTE_Downlink_Data_Packet));
    pthread_mutex_init(&array->lock, NULL);
}

void packet_array_destroy(Packet_Array *array) {
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}

int packet_array_add(Packet_Array *array, DL_DATA_PDU_TAG tag, PDCP_SN sn) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_Downlink_Data_Packet *new_packets = (LTE_Downlink_Data_Packet *)realloc(array->packets, new_capacity * sizeof(LTE_Downlink_Data_Packet));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->size].tag = tag;
    array->packets[array->size].sn = sn;
    array->size++;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void packet_array_remove(Packet_Array *array, PDCP_SN sn) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; i++) {
        if (array->packets[i].sn == sn) {
            memmove(&array->packets[i], &array->packets[i + 1], (array->size - i - 1) * sizeof(LTE_Downlink_Data_Packet));
            array->size--;
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void packet_array_garbage_collect(Packet_Array *array) {
    pthread_mutex_lock(&array->lock);
    size_t new_size = 0;
    for (size_t i = 0; i < array->size; i++) {
        if (array->packets[i].sn != INVALID_PDCP_SN) {
            array->packets[new_size++] = array->packets[i];
        }
    }
    memmove(array->packets, array->packets + new_size, (array->size - new_size) * sizeof(LTE_Downlink_Data_Packet));
    array->size -= array->size - new_size;
    pthread_mutex_unlock(&array->lock);
}

