#include <sys/resource.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createNode(int RX_UE_INFORMATION_TAG, int RNTI) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        return NULL; // Handle memory allocation failure
    }
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRCFLAG = rand() % 2; // Stochastic algorithm for CRCFLAG
    newNode->next = NULL;
    return newNode;
}

void populateNfaapiPduList(Node** head, int numNodes) {
    if (numNodes <= 0) {
        return; // Handle edge case of zero or negative number of nodes
    }

    struct rusage startUsage, endUsage;
    getrusage(RUSAGE_SELF, &startUsage);

    for (int i = 0; i < numNodes; i++) {
        Node* newNode = createNode(rand() % 1000, rand() % 100); // Example data generation
        if (newNode == NULL) {
            // Handle memory allocation failure
            while (*head != NULL) {
                Node* temp = *head;
                *head = (*head)->next;
                free(temp);
            }
            return;
        }

        newNode->next = *head;
        *head = newNode;
    }

    getrusage(RUSAGE_SELF, &endUsage);

    // Log performance metrics
    printf("Time taken: %ld.%06ld seconds\n", endUsage.ru_utime.tv_sec - startUsage.ru_utime.tv_sec,
           endUsage.ru_utime.tv_usec - startUsage.ru_utime.tv_usec);
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    Node* head = NULL;
    populateNfaapiPduList(&head, 10); // Example call with 10 nodes

    // Clean up allocated memory
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
```

