typedef struct {
    LTE_DL_DATA_PDU *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_DynamicArray;

LTE_DynamicArray* create_dynamic_array() {
    LTE_DynamicArray *array = (LTE_DynamicArray*)malloc(sizeof(LTE_DynamicArray));
    array->data = (LTE_DL_DATA_PDU*)calloc(INITIAL_SIZE, sizeof(LTE_DL_DATA_PDU));
    array->size = 0;
    array->capacity = INITIAL_SIZE;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(LTE_DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void resize_dynamic_array(LTE_DynamicArray *array, size_t new_capacity) {
    LTE_DL_DATA_PDU *new_data = (LTE_DL_DATA_PDU*)realloc(array->data, new_capacity * sizeof(LTE_DL_DATA_PDU));
    if (new_data == NULL) {
        // Handle memory allocation failure
        return;
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void add_to_dynamic_array(LTE_DynamicArray *array, DL_DATA_PDU_TAG tag, uint32_t PDCP_SN) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        resize_dynamic_array(array, array->capacity * GROWTH_FACTOR);
    }
    LTE_DL_DATA_PDU *new_pdu = &array->data[array->size++];
    new_pdu->tag = tag;
    new_pdu->PDCP_SN = PDCP_SN;
    new_pdu->CRC_FLAG = rand() % 2; // Randomly set CRC FLAG
    new_pdu->timestamp = time(NULL);
    pthread_mutex_unlock(&array->lock);
}

void cleanup_old_data(LTE_DynamicArray *array, time_t threshold) {
    pthread_mutex_lock(&array->lock);
    size_t i = 0;
    while (i < array->size) {
        if (difftime(time(NULL), array->data[i].timestamp) > threshold) {
            memmove(&array->data[i], &array->data[i + 1], (array->size - i - 1) * sizeof(LTE_DL_DATA_PDU));
            array->size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void* performance_monitor(void *arg) {
    LTE_DynamicArray *array = (LTE_DynamicArray*)arg;
    while (1) {
        // Collect and log system state data
        // Adjust memory allocation strategy and expiration cleanup frequency based on actual load
        sleep(1); // Simulate periodic monitoring
    }
    return NULL;
}
