#include <pthread.h>

#define MAX_PDU_SIZE 1024
#define DEFAULT_ITERATIONS 10000

typedef struct {
    uint32_t DL_DATA_PDU_TAG;
    uint32_t PDCP_SN;
    unsigned char data[MAX_PDU_SIZE];
} DL_DATA_PDU;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} AES_CipherContext;

typedef struct {
    DL_DATA_PDU *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PDU_Array;

typedef struct {
    AES_CipherContext ctx;
    pthread_mutex_t mutex;
} CipherContext;

void init_pdu_array(PDU_Array *pdu_array, size_t initial_capacity) {
    pdu_array->array = malloc(initial_capacity * sizeof(DL_DATA_PDU));
    pdu_array->count = 0;
    pdu_array->capacity = initial_capacity;
    pthread_mutex_init(&pdu_array->mutex, NULL);
}

void free_pdu_array(PDU_Array *pdu_array) {
    pthread_mutex_lock(&pdu_array->mutex);
    free(pdu_array->array);
    pthread_mutex_unlock(&pdu_array->mutex);
    pthread_mutex_destroy(&pdu_array->mutex);
}

void init_cipher_context(CipherContext *ctx, const char *password, size_t iterations) {
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Failed to generate random salt\n");
        exit(EXIT_FAILURE);
    }

    EVP_PKEY_CTX *pkey_ctx = EVP_PKEY_CTX_new_id(EVP_PBE_HMAC_SHA256(), NULL);
    if (EVP_PKEY_derive_init(pkey_ctx) <= 0 ||
        EVP_PKEY_CTX_set_pbkdf2_salt(pkey_ctx, salt, sizeof(salt)) <= 0 ||
        EVP_PKEY_CTX_set_pbkdf2_iterations(pkey_ctx, iterations) <= 0 ||
        EVP_PKEY_CTX_set1_password(pkey_ctx, (unsigned char *)password, strlen(password)) <= 0 ||
        EVP_PKEY_derive(pkey_ctx, ctx->key, &ctx->key_len) <= 0) {
        fprintf(stderr, "Failed to derive key\n");
        exit(EXIT_FAILURE);
    }

    if (ctx->key_len == 32) {
        memcpy(ctx->iv, salt + sizeof(salt), 16);
    } else if (ctx->key_len == 16) {
        memcpy(ctx->iv, salt + sizeof(salt) - 8, 16);
    } else {
        fprintf(stderr, "Unsupported key length\n");
        exit(EXIT_FAILURE);
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }

    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) <= 0) {
        fprintf(stderr, "Failed to initialize cipher\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&ctx->mutex, NULL);
}

void free_cipher_context(CipherContext *ctx) {
    pthread_mutex_lock(&ctx->mutex);
    EVP_CIPHER_CTX_free(ctx->ctx);
    pthread_mutex_unlock(&ctx->mutex);
    pthread_mutex_destroy(&ctx->mutex);
}

void add_pdu(PDU_Array *pdu_array, DL_DATA_PDU pdu) {
    pthread_mutex_lock(&pdu_array->mutex);
    if (pdu_array->count == pdu_array->capacity) {
        size_t new_capacity = pdu_array->capacity ? pdu_array->capacity * 2 : 1;
        DL_DATA_PDU *new_array = realloc(pdu_array->array, new_capacity * sizeof(DL_DATA_PDU));
        if (!new_array) {
            fprintf(stderr, "Failed to reallocate memory\n");
            exit(EXIT_FAILURE);
        }
        pdu_array->array = new_array;
        pdu_array->capacity = new_capacity;
    }
    pdu_array->array[pdu_array->count++] = pdu;
    pthread_mutex_unlock(&pdu_array->mutex);
}

void encrypt_pdu(CipherContext *ctx, DL_DATA_PDU *pdu) {
    pthread_mutex_lock(&ctx->mutex);
    int len;
    if (EVP_EncryptUpdate(ctx->ctx, NULL, &len, NULL, 0) <= 0 ||
        EVP_EncryptUpdate(ctx->ctx, pdu->data, &len, pdu->data, sizeof(DL_DATA_PDU)) <= 0 ||
        EVP_EncryptFinal_ex(ctx->ctx, pdu->data + len, &len) <= 0) {
        fprintf(stderr, "Failed to encrypt PDU\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&ctx->mutex);
}

void process_pdu_array(PDU_Array *pdu_array, CipherContext *ctx) {
    for (size_t i = 0; i < pdu_array->count; ++i) {
        encrypt_pdu(ctx, &pdu_array->array[i]);
    }
}
