// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate memory for NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_T* allocatePdu(int size) {
    return (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Function to deallocate memory for NFAPI_CRC_INDICATION_PDU_T
void freePdu(NFAPI_CRC_INDICATION_PDU_T* pdu, int size) {
    free(pdu);
}

// Function to validate uniqueness of RX_UE_INFORMATION_TAG and RNTI
int isUnique(NFAPI_CRC_INDICATION_PDU_T* list, int size, NFAPI_CRC_INDICATION_PDU_T newPdu) {
    for (int i = 0; i < size; i++) {
        if (list[i].RX_UE_INFORMATION_TAG == newPdu.RX_UE_INFORMATION_TAG && 
            list[i].RNTI == newPdu.RNTI) {
            return 0;
        }
    }
    return 1;
}

// Function to handle errors and logging
void handleError(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Thread-safe function to add a new PDU to the list
void addPduThreadSafe(NFAPI_CRC_INDICATION_PDU_T** list, int* size, NFAPI_CRC_INDICATION_PDU_T newPdu) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    if (isUnique(*list, *size, newPdu)) {
        *list = realloc(*list, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*list == NULL) {
            handleError("Memory allocation failed");
            return;
        }
        (*list)[*size] = newPdu;
        (*size)++;
    } else {
        handleError("Duplicate PDU detected");
    }

    pthread_mutex_unlock(&mutex);
    pthread_mutex_destroy(&mutex);
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T* pduList = NULL;
    int size = 0;

    NFAPI_CRC_INDICATION_PDU_T newPdu = {1, 2, 3};
    addPduThreadSafe(&pduList, &size, newPdu);

    freePdu(pduList, size);
    return 0;
}
