#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WINDOW_SIZE 10
#define BURST_WINDOW_SECONDS 3

typedef struct {
    int id;
    time_t timestamp;
    double value;
} Transaction;

typedef struct {
    Transaction transactions[WINDOW_SIZE];
    int head;
    int count;
    double weighted_sum;
    int burst_count;
    time_t last_burst_timestamp;
    double exponential_weight;
} BurstDetector;

void init_detector(BurstDetector *detector) {
    detector->head = 0;
    detector->count = 0;
    detector->weighted_sum = 0.0;
    detector->burst_count = 0;
    detector->last_burst_timestamp = 0;
    detector->exponential_weight = 1.0;
}

void add_transaction(BurstDetector *detector, Transaction transaction) {
    int index = (detector->head + detector->count) % WINDOW_SIZE;
    detector->transactions[index] = transaction;

    if (detector->count < WINDOW_SIZE) {
        detector->count++;
    } else {
        detector->head = (detector->head + 1) % WINDOW_SIZE;
    }

    time_t current_time = time(NULL);
    double time_diff = difftime(current_time, detector->transactions[index].timestamp);

    if (time_diff <= BURST_WINDOW_SECONDS && detector->count > 1) {
        detector->burst_count++;
        detector->last_burst_timestamp = current_time;
    } else {
        detector->burst_count = 0;
    }

    double weight = exp(-time_diff / BURST_WINDOW_SECONDS);
    detector->exponential_weight = (detector->exponential_weight * weight + weight) / (weight + 1.0);

    detector->weighted_sum = 0.0;
    for (int i = 0; i < detector->count; i++) {
        int idx = (detector->head + i) % WINDOW_SIZE;
        detector->weighted_sum += detector->transactions[idx].value * exp(-difftime(current_time, detector->transactions[idx].timestamp) / BURST_WINDOW_SECONDS);
    }
}

void print_metrics(BurstDetector *detector) {
    printf("Burst Count: %d\n", detector->burst_count);
    printf("Weighted Sum: %.2f\n", detector->weighted_sum);
}

int main() {
    BurstDetector detector;
    init_detector(&detector);

    // Simulate adding transactions
    Transaction transaction1 = {1, time(NULL), 10.0};
    add_transaction(&detector, transaction1);

    Transaction transaction2 = {2, time(NULL) + 2, 20.0};
    add_transaction(&detector, transaction2);

    Transaction transaction3 = {3, time(NULL) + 4, 30.0};
    add_transaction(&detector, transaction3);

    print_metrics(&detector);

    return 0;
}
