NFAPI_CRC_INDICATION_PDU_T** ue_info_list = NULL;
int ue_info_count = 0;
JobQueueEntry job_queue[JOB_QUEUE_SIZE];
int job_queue_head = 0, job_queue_tail = 0;

void* custom_allocator(size_t size) {
    // Implement a custom allocator here
    return malloc(size);
}

void free_custom_allocator(void* ptr) {
    // Free memory allocated by the custom allocator
    free(ptr);
}

int add_ue_info(NFAPI_CRC_INDICATION_PDU_T* new_info) {
    if (ue_info_count >= MAX_UE_INFO) {
        fprintf(stderr, "Memory allocation failed: UE info list is full\n");
        return -1;
    }
    ue_info_list[ue_info_count++] = new_info;
    return 0;
}

int validate_ue_info(NFAPI_CRC_INDICATION_PDU_T* new_info) {
    for (int i = 0; i < ue_info_count; i++) {
        if (ue_info_list[i]->RX_UE_INFORMATION_TAG == new_info->RX_UE_INFORMATION_TAG &&
            ue_info_list[i]->RNTI == new_info->RNTI) {
            return -1;
        }
    }
    return 0;
}

int schedule_job(const char* job_name, struct timeval schedule_time, int priority) {
    if (job_queue_head == (job_queue_tail + 1) % JOB_QUEUE_SIZE) {
        fprintf(stderr, "Job queue is full\n");
        return -1;
    }
    JobQueueEntry new_job = {strdup(job_name), schedule_time, {0}, priority};
    job_queue[job_queue_tail] = new_job;
    job_queue_tail = (job_queue_tail + 1) % JOB_QUEUE_SIZE;
    return 0;
}

void free_job_queue() {
    for (int i = job_queue_head; i != job_queue_tail; i = (i + 1) % JOB_QUEUE_SIZE) {
        free(job_queue[i].job_name);
    }
}

void log_message(const char* message) {
    // Implement a logging mechanism here
    printf("%s\n", message);
}

int main() {
