#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <string>
#include <fstream>
#include <cstdlib>
#include <ctime>

class GameCharacter {
private:
    static const int DEFAULT_COOLDOWN = 9;
    static const int HISTORY_SIZE = 3;

    std::mutex mtx;
    std::condition_variable cv;
    bool ready;
    int cooldown;
    std::vector<std::string> attackHistory;
    std::string lastAttack;

public:
    GameCharacter(int initialCooldown = DEFAULT_COOLDOWN) : ready(false), cooldown(initialCooldown), lastAttack("") {
        loadAttackHistory();
    }

    void selectRandomAttack() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return ready; });
        ready = false;

        std::srand(std::time(0));
        int attackIndex = std::rand() % 2;
        std::string selectedAttack = (attackIndex == 0) ? "Fireball" : "Ice Lance";

        if (!attackHistory.empty()) {
            while (selectedAttack == lastAttack || selectedAttack == attackHistory.back() ||
                   selectedAttack == attackHistory[attackHistory.size() - 2] ||
                   selectedAttack == attackHistory[attackHistory.size() - 3]) {
                attackIndex = std::rand() % 2;
                selectedAttack = (attackIndex == 0) ? "Fireball" : "Ice Lance";
            }
        }

        lastAttack = selectedAttack;
        attackHistory.push_back(selectedAttack);
        if (attackHistory.size() > HISTORY_SIZE) {
            attackHistory.erase(attackHistory.begin());
        }

        saveAttackHistory();

        std::cout << "Selected Attack: " << selectedAttack << std::endl;

        cv.notify_all();
    }

    void setCooldown(int newCooldown) {
        std::unique_lock<std::mutex> lock(mtx);
        cooldown = newCooldown;
    }

private:
    void loadAttackHistory() {
        std::ifstream file("attack_history.txt");
        if (file.is_open()) {
            std::string line;
            while (getline(file, line)) {
                attackHistory.push_back(line);
            }
            file.close();
        }
    }

    void saveAttackHistory() {
        std::ofstream file("attack_history.txt");
        if (file.is_open()) {
            for (const auto& attack : attackHistory) {
                file << attack << "\n";
            }
            file.close();
        }
    }
};

int main() {
    GameCharacter character;
    std::thread t1(&GameCharacter::selectRandomAttack, &character);
    std::thread t2(&GameCharacter::selectRandomAttack, &character);

    t1.join();
    t2.join();

    return 0;
}
