void initSessionArray(SessionArray *array, size_t initialCapacity) {
    array->sessions = (UserSession *)malloc(initialCapacity * sizeof(UserSession));
    array->capacity = initialCapacity;
    array->size = 0;
}

void addSession(SessionArray *array) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->sessions = (UserSession *)realloc(array->sessions, array->capacity * sizeof(UserSession));
    }
    UserSession newSession;
    newSession.userID = rand();
    newSession.sessionStartTime = time(NULL);
    newSession.lastActivityTime = time(NULL);
    snprintf(newSession.sessionState, 20, "Active");
    newSession.totalDataTransferred = (size_t)rand() % 1000000;
    newSession.RX_UE_INFORMATION_TAG = rand();
    newSession.RNTI = rand();
    newSession.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    array->sessions[array->size++] = newSession;
}

void cleanupSessionArray(SessionArray *array) {
    free(array->sessions);
    array->sessions = NULL;
    array->capacity = 0;
    array->size = 0;
}

