        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_struct = struct_pool[pool_index++];
    pthread_mutex_unlock(&pool_lock);
    return new_struct;
}

void free_struct(NFAPI_CRC_INDICATION_PDU_T *struct_ptr) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index > 0 && pool_index <= MAX_STRUCTS) {
        struct_pool[--pool_index] = struct_ptr;
    }
    pthread_mutex_unlock(&pool_lock);
