#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int count;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void addNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_STRUCTS) {
        // Handle maximum allocation limit
        pthread_mutex_unlock(&list->lock);
        return;
    }
    Node* newNode = createNode(data);
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        list->tail->next = newNode;
    }
    list->tail = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    LinkedList list;
    initLinkedList(&list);

    NFAPI_CRC_INDICATION_PDU_T data;
    // Populate data with valid values

    addNode(&list, data);

    freeLinkedList(&list);

    return 0;
}
