    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    bool logging_enabled;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity, bool enable_logging) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    list->logging_enabled = enable_logging;
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool add_crc_entry(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, bool CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return false; // Duplicate RNTI
        }
    }

    list->list[list->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->list[list->count].RNTI = RNTI;
    list->list[list->count].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    ++list->count;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

void enable_logging(NFAPI_CRC_LIST_T *list, bool enable) {
    pthread_mutex_lock(&list->mutex);
    list->logging_enabled = enable;
    pthread_mutex_unlock(&list->mutex);
}
