public class SimulationRangeManager<T> where T : IComparable<T>
{
    private ConcurrentDictionary<(T min, T max), Random> _randomCache = new ConcurrentDictionary<(T min, T max), Random>();
    private (T min, T max) _currentRange;
    private Timer _validationTimer;

    public SimulationRangeManager(T min, T max)
    {
        SetRange(min, max);
        _validationTimer = new Timer(ValidateRange, null, TimeSpan.Zero, TimeSpan.FromSeconds(60));
    }

    public void SetRange(T min, T max)
    {
        if (min.CompareTo(max) >= 0)
            throw new ArgumentException("Invalid range: min must be less than max.");

        _currentRange = (min, max);
        _randomCache.TryRemove(_currentRange, out _); // Clear cache for the old range
    }

    public T GetRandomValue()
    {
        var random = _randomCache.GetOrAdd(_currentRange, key => new Random());
        return GenerateRandomValue(random, _currentRange.min, _currentRange.max);
    }

    private T GenerateRandomValue(Random random, T min, T max)
    {
        if (typeof(T) == typeof(int))
            return (T)(object)random.Next((int)min, (int)max + 1);
        else if (typeof(T) == typeof(float))
            return (T)(object)random.NextFloat((float)min, (float)max);
        else
            throw new NotSupportedException("Unsupported type for random value generation.");
    }

    private void ValidateRange(object state)
    {
        // Implement logic to validate range against real-time parameters
        // Update _currentRange if necessary
    }

    public override string ToString()
    {
        return $"Current Range: {_currentRange.min} to {_currentRange.max}";
    }
}
