#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int token_id;
    time_t expiration_timestamp;
    int access_level;
    time_t last_accessed_time;
    void* metadata;
} Token;

typedef struct {
    Token** tokens;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->tokens = (Token**)calloc(initial_capacity, sizeof(Token*));
    if (!cache->tokens) {
        free(cache);
        return NULL;
    }

    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void destroy_cache(Cache* cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        free(cache->tokens[i]->metadata);
        free(cache->tokens[i]);
    }
    free(cache->tokens);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int add_token(Cache* cache, Token* token) {
    pthread_mutex_lock(&cache->lock);

    if (cache->size >= cache->capacity) {
        // Handle capacity overflow
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    cache->tokens[cache->size++] = token;

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

int update_token(Cache* cache, int token_id, Token* new_token) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->size; ++i) {
        if (cache->tokens[i]->token_id == token_id) {
            free(cache->tokens[i]->metadata);
            *cache->tokens[i] = *new_token;
            pthread_mutex_unlock(&cache->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return -1;
}

int delete_token(Cache* cache, int token_id) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->size; ++i) {
        if (cache->tokens[i]->token_id == token_id) {
            free(cache->tokens[i]->metadata);
            free(cache->tokens[i]);

            // Shift elements to fill the gap
            for (size_t j = i; j < cache->size - 1; ++j) {
                cache->tokens[j] = cache->tokens[j + 1];
            }

            --cache->size;
            pthread_mutex_unlock(&cache->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return -1;
}

void invalidate_expired_tokens(Cache* cache) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->size; ++i) {
        if (time(NULL) > cache->tokens[i]->expiration_timestamp) {
            free(cache->tokens[i]->metadata);
            free(cache->tokens[i]);

            // Shift elements to fill the gap
            for (size_t j = i; j < cache->size - 1; ++j) {
                cache->tokens[j] = cache->tokens[j + 1];
            }

            --cache->size;
            --i; // Adjust index after deletion
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

int main() {
