#define MAX_MESSAGES 100000

typedef struct LTE_NAS_Message {
    int identifier;
    char imsi[20];
    void* sm_context;
} LTE_NAS_Message;

typedef struct MessageArray {
    LTE_NAS_Message messages[MAX_MESSAGES];
    pthread_mutex_t lock;
    int count;
} MessageArray;

void init_message_array(MessageArray* array) {
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
}

int add_message(MessageArray* array, LTE_NAS_Message message) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= MAX_MESSAGES) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    array->messages[array->count++] = message;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_message(MessageArray* array, int identifier, LTE_NAS_Message new_message) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->count; ++i) {
        if (array->messages[i].identifier == identifier) {
            array->messages[i] = new_message;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Message not found
}

LTE_NAS_Message* get_message(MessageArray* array, int identifier) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->count; ++i) {
        if (array->messages[i].identifier == identifier) {
            LTE_NAS_Message* result = &array->messages[i];
            pthread_mutex_unlock(&array->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL; // Message not found
}

void destroy_message_array(MessageArray* array) {
    pthread_mutex_destroy(&array->lock);
}
