#define MAX_PACKET_SIZE 1024

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int payload_length;
    char protocol_type[10];
} Packet;

typedef struct {
    Packet *packets;
    size_t count;
    size_t capacity;
    size_t total_data_transferred;
} PacketArray;

void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->packets = (Packet *)malloc(initial_capacity * sizeof(Packet));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
    array->total_data_transferred = 0;
}

void add_packet(PacketArray *array, Packet packet) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet *new_packets = (Packet *)realloc(array->packets, new_capacity * sizeof(Packet));
        if (!new_packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->count++] = packet;
    array->total_data_transferred += packet.payload_length;
}

void update_packet(PacketArray *array, size_t index, Packet new_packet) {
    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    array->packets[index] = new_packet;
    array->total_data_transferred += new_packet.payload_length - array->packets[index].payload_length;
}

void remove_packet(PacketArray *array, size_t index) {
    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    for (size_t i = index; i < array->count - 1; ++i) {
        array->packets[i] = array->packets[i + 1];
    }
    array->count--;
    array->total_data_transferred -= array->packets[index].payload_length;
}

double calculate_average_packet_size(PacketArray *array) {
    if (array->count == 0) {
        return 0.0;
    }
    return (double)array->total_data_transferred / array->count;
}

void compress_packets(PacketArray *array, size_t threshold) {
    if (array->count <= threshold) {
        return;
    }
    // Implement compression logic here
    printf("Compressing packets...\n");
}

void free_packet_array(PacketArray *array) {
    free(array->packets);
    array->packets = NULL;
    array->count = 0;
    array->capacity = 0;
    array->total_data_transferred = 0;
}
