#include <stdio.h>
#include <dirent.h>
#include <tiffio.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    char* compressionType;
    int extraSamplesCount;
    int* extraSamplesBitDepths;
} ImageInfo;

int processTIFFBatch(const char* directoryPath, ImageInfo** imageInfos, int* count) {
    DIR* dir = opendir(directoryPath);
    if (!dir) return -1; // Directory not found or cannot be opened

    struct dirent* entry;
    *count = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".tif")) {
            char filePath[256];
            snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, entry->d_name);

            TIFF* tif = TIFFOpen(filePath, "r");
            if (!tif) continue; // File not found or cannot be opened

            ImageInfo info;
            info.bitsPerSample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
            info.samplesPerPixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
            info.compressionType = (char*)TIFFGetField(tif, TIFFTAG_COMPRESSION);

            int extraSamplesCount;
            if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamplesCount)) {
                info.extraSamplesBitDepths = malloc(extraSamplesCount * sizeof(int));
                TIFFGetField(tif, TIFFTAG_SAMPLEBITS, info.extraSamplesBitDepths);
                info.extraSamplesCount = extraSamplesCount;
            } else {
                info.extraSamplesBitDepths = NULL;
                info.extraSamplesCount = 0;
            }

            imageInfos[*count] = malloc(sizeof(ImageInfo));
            memcpy(imageInfos[*count], &info, sizeof(ImageInfo));

            (*count)++;
            TIFFClose(tif);
        }
    }

    closedir(dir);
    return 0; // Success
}

int main() {
    const char* directoryPath = "/path/to/tiff/files";
    ImageInfo** imageInfos;
    int count;

    if (processTIFFBatch(directoryPath, &imageInfos, &count) == 0) {
        printf("Processed %d TIFF files.\n", count);
        for (int i = 0; i < count; i++) {
            printf("File: %s\n", imageInfos[i]->compressionType);
            free(imageInfos[i]);
        }
        free(imageInfos);
    } else {
        printf("Failed to process TIFF batch.\n");
    }

    return 0;
}
