#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* lastAccessed;
} DynamicList;

DynamicList* createDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = NULL;
    list->lastAccessed = NULL;
    return list;
}

void addOrUpdateElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T newElement) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == newElement.RNTI) {
            // Update existing element
            memcpy(&current->data, &newElement, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->lastAccessed = current;
            return;
        }
        current = current->next;
    }
    // Add new element
    Node* newNode = (Node*)malloc(sizeof(Node));
    memcpy(&newNode->data, &newElement, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = list->head;
    list->head = newNode;
    if (list->lastAccessed == NULL) {
        list->lastAccessed = newNode;
    }
}

void removeElement(DynamicList* list, int RNTI) {
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            if (list->lastAccessed == current) {
                list->lastAccessed = prev;
            }
            return;
        }
        prev = current;
        current = current->next;
    }
}

void freeDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
