#include <arpa/inet.h>
#include <netdb.h>
#include <time.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LEN 16
#define NFAPI_CRC_INDICATION_PDU_T struct nfapi_crc_indication_pdu_t

typedef struct {
    u_char rx_ue_information_tag;
    u_int16_t rnti;
    u_char crc_indication_rel8_tag;
} NFAPICRCIndicationPduT;

u_char* resolveHostnameToIP(const char* hostname) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[MAX_IP_LEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        freeaddrinfo(res); // all done with this structure
        return (u_char*)ipstr;
    }

    return NULL;
}

NFAPICRCIndicationPduT* createCRCIndicationPDUs(int count) {
    NFAPICRCIndicationPduT* pdus = (NFAPICRCIndicationPduT*)malloc(count * sizeof(NFAPICRCIndicationPduT));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < count; i++) {
        pdus[i].rx_ue_information_tag = rand() % 256;
        pdus[i].rnti = rand() % 65536;
        pdus[i].crc_indication_rel8_tag = rand() % 256;
    }

    return pdus;
}

void freeCRCIndicationPDUs(NFAPICRCIndicationPduT* pdus, int count) {
    if (pdus) {
        free(pdus);
    }
}
