    void* MME_CONTEXT;
    int PAGING_FLAG;
} LTE_MME_MESSAGE_T;

typedef struct DynamicList {
    LTE_MME_MESSAGE_T** messages;
    size_t capacity;
    size_t size;
    size_t last_accessed_index;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->messages = (LTE_MME_MESSAGE_T**)calloc(initial_capacity, sizeof(LTE_MME_MESSAGE_T*));
    if (!list->messages) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    list->last_accessed_index = -1;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->size; ++i) {
        free(list->messages[i]);
    }
    free(list->messages);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_message(DynamicList* list, LTE_MME_MESSAGE_T* message) {
    if (!list || !message) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_MME_MESSAGE_T** new_messages = (LTE_MME_MESSAGE_T**)realloc(list->messages, new_capacity * sizeof(LTE_MME_MESSAGE_T*));
        if (!new_messages) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->messages = new_messages;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (strcmp(list->messages[i]->IMSI, message->IMSI) == 0) {
            free(list->messages[i]);
            break;
        }
    }

    list->messages[list->size++] = message;
    list->last_accessed_index = list->size - 1;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

LTE_MME_MESSAGE_T* update_message(DynamicList* list, const char* IMSI, LTE_MME_MESSAGE_T* new_message) {
    if (!list || !IMSI || !new_message) return NULL;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (strcmp(list->messages[i]->IMSI, IMSI) == 0) {
            free(list->messages[i]);
            list->messages[i] = new_message;
            list->last_accessed_index = i;
            pthread_mutex_unlock(&list->lock);
            return new_message;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return NULL;
}

int remove_message(DynamicList* list, const char* IMSI) {
    if (!list || !IMSI) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (strcmp(list->messages[i]->IMSI, IMSI) == 0) {
            free(list->messages[i]);
            for (size_t j = i; j < list->size - 1; ++j) {
                list->messages[j] = list->messages[j + 1];
            }
            --list->size;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return -1;
}
