record pool[POOL_SIZE];
int pool_index = 0;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    long offset;
    int key;
} index_record;

index_record offsets[HASH_TABLE_SIZE];

pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;

void *allocate_record(int value, const char *user_id) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    record *rec = &pool[pool_index++];
    rec->value = value;
    rec->user_id = strdup(user_id);
    pthread_mutex_unlock(&pool_lock);
    return rec;
}

int hash_function(int key) {
    return abs(key % HASH_TABLE_SIZE);
}

void insert_record(long offset, int key, record *rec) {
    pthread_mutex_lock(&hash_table_lock);
    int index = hash_function(key);
    offsets[index].offset = offset;
    offsets[index].key = key;
    pthread_mutex_unlock(&hash_table_lock);
}

record* find_record(int key) {
    pthread_mutex_lock(&hash_table_lock);
    int index = hash_function(key);
    if (offsets[index].key == key) {
        record *rec = &pool[offsets[index].offset];
        pthread_mutex_unlock(&hash_table_lock);
        return rec;
    }
    pthread_mutex_unlock(&hash_table_lock);
    return NULL;
}

void update_records(int min_value, int max_value) {
    for (int i = 0; i < POOL_SIZE; i++) {
        record *rec = &pool[i];
        rec->value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void print_all_records() {
    pthread_mutex_lock(&hash_table_lock);
    for (int i = 0; i < POOL_SIZE; i++) {
        record *rec = &pool[i];
        printf("Value: %d, User ID: %s\n", rec->value, rec->user_id);
    }
    pthread_mutex_unlock(&hash_table_lock);
}

void* update_thread(void *arg) {
    while (1) {
        update_records(0, 100);
        sleep(60); // Update every minute
    }
    return NULL;
}

int main() {
    pthread_t update_tid;
    pthread_create(&update_tid, NULL, update_thread, NULL);

    record *rec = allocate_record(42, "user1");
    insert_record(0, 1, rec);

    record *found_rec = find_record(1);
    if (found_rec) {
        printf("Found Record: Value - %d, User ID - %s\n", found_rec->value, found_rec->user_id);
    }

    print_all_records();

    pthread_join(update_tid, NULL);
    return 0;
}
