    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_NODE;

NFAPI_CRC_INDICATION_PDU_NODE *list[MAX_LIST_SIZE];
int list_size = 0;
sem_t sem;
pthread_mutex_t list_mutex;

void init_list() {
    sem_init(&sem, 0, MAX_LIST_SIZE);
    pthread_mutex_init(&list_mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_NODE* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    NFAPI_CRC_INDICATION_PDU_NODE *node = (NFAPI_CRC_INDICATION_PDU_NODE*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_NODE));
    if (!node) return NULL;
    node->data = data;
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

void add_node(NFAPI_CRC_INDICATION_PDU_T data) {
    sem_wait(&sem);
    pthread_mutex_lock(&list_mutex);

    if (list_size >= MAX_LIST_SIZE) {
        printf("List is full\n");
        pthread_mutex_unlock(&list_mutex);
        sem_post(&sem);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_NODE *node = create_node(data);
    if (!node) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&list_mutex);
        sem_post(&sem);
        return;
    }

    list[list_size++] = node;

    pthread_mutex_unlock(&list_mutex);
    sem_post(&sem);
}

void remove_node(int index) {
    sem_wait(&sem);
    pthread_mutex_lock(&list_mutex);

    if (index < 0 || index >= list_size) {
        printf("Invalid index\n");
        pthread_mutex_unlock(&list_mutex);
        sem_post(&sem);
        return;
    }

    free(list[index]);
    for (int i = index; i < list_size - 1; i++) {
        list[i] = list[i + 1];
    }
    list[list_size - 1] = NULL;
    list_size--;

    pthread_mutex_unlock(&list_mutex);
    sem_post(&sem);
}

void destroy_list() {
    for (int i = 0; i < list_size; i++) {
        free(list[i]);
    }
    sem_destroy(&sem);
    pthread_mutex_destroy(&list_mutex);
}
