#include <string.h>

typedef struct {
    int PRACH_ROOT_SEQ_INDEX;
    int PRACH_FREQUENCY_OFFSET;
    // Add other parameters as needed
} PHY_RACH_CONFIG_T;

typedef struct Node {
    PHY_RACH_CONFIG_T data;
    int PRACH_ID;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* lastAccessed;
} DynamicList;

DynamicList* createDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = NULL;
    list->lastAccessed = NULL;
    return list;
}

void addOrUpdateElement(DynamicList* list, int PRACH_ID, PHY_RACH_CONFIG_T data) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->PRACH_ID == PRACH_ID) {
            // Update existing element
            current->data = data;
            list->lastAccessed = current;
            return;
        }
        current = current->next;
    }
    // Add new element
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->PRACH_ID = PRACH_ID;
    newNode->next = NULL;
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        list->lastAccessed->next = newNode;
    }
    list->lastAccessed = newNode;
}

void removeElement(DynamicList* list, int PRACH_ID) {
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->PRACH_ID == PRACH_ID) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void freeDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
