    size_t totalDataTransferred;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t capacity;
    size_t size;
} SessionArray;

void initSessionArray(SessionArray *array, size_t initialCapacity) {
    array->sessions = (UserSession *)malloc(initialCapacity * sizeof(UserSession));
    array->capacity = initialCapacity;
    array->size = 0;
}

void addSession(SessionArray *array, UserSession session) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->sessions = (UserSession *)realloc(array->sessions, array->capacity * sizeof(UserSession));
    }
    array->sessions[array->size++] = session;
}

void populateSessionArray(SessionArray *array) {
    srand(time(NULL));
    for (size_t i = 0; i < array->size; ++i) {
        UserSession session;
        session.userID = rand() % 1000;
        session.sessionStartTime = time(NULL);
        session.lastActivityTime = time(NULL);
        snprintf(session.sessionState, sizeof(session.sessionState), "Active");
        session.totalDataTransferred = rand() % 1000000;
        session.RX_UE_INFORMATION_TAG = rand() % 1000;
        session.RNTI = rand() % 1000;
        session.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        addSession(array, session);
    }
}

void cleanupSessionArray(SessionArray *array) {
    free(array->sessions);
    array->sessions = NULL;
    array->capacity = 0;
    array->size = 0;
}
