NFAPI_CRC_INDICATION_PDU_T crc_list[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char* operation) {
    FILE* log_file = fopen("crc_operations.log", "a");
    if (log_file == NULL) return;

    time_t now = time(NULL);
    pthread_t thread_id = pthread_self();
    fprintf(log_file, "%s [%ld] %s\n", ctime(&now), (long)thread_id, operation);
    fclose(log_file);
}

int add_crc_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&mutex);

    if (entry_count >= MAX_ENTRIES) {
        log_operation("Failed to add entry: List is full");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < entry_count; i++) {
        if (crc_list[i].RNTI == RNTI) {
            log_operation("Failed to add entry: Duplicate RNTI");
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    crc_list[entry_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    crc_list[entry_count].RNTI = RNTI;
    crc_list[entry_count].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    crc_list[entry_count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    entry_count++;
    log_operation("Added new entry");

    pthread_mutex_unlock(&mutex);
    return 0;
}

void* thread_function(void* arg) {
    int RX_UE_INFORMATION_TAG = *(int*)arg;
    free(arg);

    for (int i = 0; i < 100; i++) { // Simulate adding multiple entries
        add_crc_entry(RX_UE_INFORMATION_TAG, rand() % 65536, rand() % 256);
    }

    return NULL;
}

int main() {
    pthread_t threads[10];
    int* tags = (int*)malloc(10 * sizeof(int));

    for (int i = 0; i < 10; i++) {
        tags[i] = rand() % 10000;
        pthread_create(&threads[i], NULL, thread_function, &tags[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
