        packets[i].payload = (char*)malloc(packets[i].payloadSize * sizeof(char));
        if (!packets[i].payload) {
            if (logFile) fprintf(logFile, "Memory allocation failed for packet %d payload.\n", i);
            freeNetworkPacketArray(packets, i); // Free previously allocated packets
            return NULL;
        }
        strcpy(packets[i].payload, compressionAlgorithm);
    }

    return packets;
}

void freeNetworkPacketArray(NetworkPacket* packets, int numPackets) {
    for (int i = 0; i < numPackets; ++i) {
        if (packets[i].payload) free(packets[i].payload);
    }
    free(packets);
