    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int current_size = 0;
    srand(time(NULL));

    while (1) {
        if (*N == 0) break;

        // Check for memory allocation failure
        array = realloc(array, (*N + current_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array) {
            fprintf(log_file, "Memory allocation failed\n");
            return NULL;
