            new_rnti = rand() % (MAX_RNTI + 1);
        } while (is_duplicate(array, current_size, new_rnti));

        array[current_size].RX_UE_INFORMATION_TAG = rand();
        array[current_size].RNTI = new_rnti;
        array[current_size].CRC_INDICATION_REL8_TAG = calculate_crc_flag(new_rnti);

        current_size++;
        (*N)--;
    }

    return array;
}

int is_duplicate(NFAPI_CRC_INDICATION_PDU_T *array, int size, unsigned short rnti) {
    for (int i = 0; i < size; i++) {
        if (array[i].RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

int calculate_crc_flag(unsigned short rnti) {
    // Example CRC flag calculation based on RNTI
    return (rnti & 0xFF) ^ ((rnti >> 8) & 0xFF);
}
