#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_TASKS 100

typedef struct {
    char command[256];
    int id;
    char **envp;
} Task;

Task task_pool[MAX_TASKS];
int task_count = 0;
pid_t child_pids[MAX_TASKS];

void handle_sigterm(int sig) {
    for (int i = 0; i < task_count; i++) {
        if (child_pids[i] != 0) {
            kill(child_pids[i], SIGTERM);
        }
    }
}

int add_task(const char *command, int id, char **envp) {
    if (task_count >= MAX_TASKS) {
        return 0;
    }
    strcpy(task_pool[task_count].command, command);
    task_pool[task_count].id = id;
    task_pool[task_count].envp = envp;
    task_count++;
    return 1;
}

int execute_tasks() {
    for (int i = 0; i < task_count; i++) {
        pid_t pid = fork();
        if (pid == -1) {
            return 0;
        } else if (pid == 0) {
            execve("/bin/sh", (char *const[]){"/bin/sh", "-c", task_pool[i].command, NULL}, task_pool[i].envp);
            exit(1);
        } else {
            child_pids[i] = pid;
        }
    }

    for (int i = 0; i < task_count; i++) {
        int status;
        waitpid(child_pids[i], &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            return 0;
        }
    }

    return 1;
}

int main() {
    signal(SIGTERM, handle_sigterm);

    char *envp[] = {"VAR=value", NULL};
    add_task("echo Hello World", 1, envp);
    execute_tasks();

    return 1;
}
