#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_length;
    int packet_type;
    unsigned char flags;
} NetworkPacket;

typedef struct {
    NetworkPacket *packets[MAX_PACKETS];
    size_t count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_packet(PacketManager *manager, NetworkPacket *packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Packet manager is full
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void update_packet(PacketManager *manager, size_t index, NetworkPacket *new_packet) {
    pthread_mutex_lock(&manager->lock);
    if (index < manager->count) {
        manager->packets[index] = new_packet;
    }
    pthread_mutex_unlock(&manager->lock);
}

int remove_packet(PacketManager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);
    if (index >= manager->count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Index out of bounds
    }
    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->packets[i] = manager->packets[i + 1];
    }
    manager->count--;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void iterate_packets(PacketManager *manager, void (*callback)(NetworkPacket *)) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        callback(manager->packets[i]);
    }
    pthread_mutex_unlock(&manager->lock);
}

void compute_statistics(PacketManager *manager, size_t *total_data_transferred, double *average_packet_size) {
    *total_data_transferred = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        *total_data_transferred += manager->packets[i]->payload_length;
    }
    if (manager->count > 0) {
        *average_packet_size = (double)*total_data_transferred / manager->count;
    } else {
        *average_packet_size = 0;
    }
    pthread_mutex_unlock(&manager->lock);
}

void filter_packets(PacketManager *manager, void (*filter)(NetworkPacket *)) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (!filter(manager->packets[i])) {
            remove_packet(manager, i--); // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void snapshot_packets(PacketManager *manager, NetworkPacket **snapshot, size_t *snapshot_count) {
    pthread_mutex_lock(&manager->lock);
    *snapshot = (NetworkPacket *)malloc(sizeof(NetworkPacket) * manager->count);
    if (*snapshot == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return; // Error: Memory allocation failed
    }
    memcpy(*snapshot, manager->packets, sizeof(NetworkPacket) * manager->count);
    *snapshot_count = manager->count;
    pthread_mutex_unlock(&manager->lock);
}

void free_snapshot(NetworkPacket *snapshot, size_t snapshot_count) {
    free(snapshot);
}
