NFAPI_RRC_PDU_T* initialize_nfaapi_rrc_pdu_list(size_t initial_size) {
    NFAPI_RRC_PDU_T *list = (NFAPI_RRC_PDU_T*)malloc(initial_size * sizeof(NFAPI_RRC_PDU_T));
    if (!list) return NULL;

    for (size_t i = 0; i < initial_size; ++i) {
        list[i].shared_channels = (PHY_DOWNLINK_SHARED_CHANNEL*)malloc(MAX_ENTRIES * sizeof(PHY_DOWNLINK_SHARED_CHANNEL));
        if (!list[i].shared_channels) {
            // Handle memory allocation failure
            free(list);
            return NULL;
        }
        list[i].num_entries = 0;
        list[i].max_entries = MAX_ENTRIES;
        pthread_mutex_init(&list[i].lock, NULL);
    }

    return list;
}

void destroy_nfaapi_rrc_pdu_list(NFAPI_RRC_PDU_T *list, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(list[i].shared_channels);
        pthread_mutex_destroy(&list[i].lock);
    }
    free(list);
}

int add_entry_to_pdu_list(NFAPI_RRC_PDU_T *pdu, const REforgettable_CELL_UPDATE_REQUEST *cell_update_request, const PHY_DOWNLINK_SHARED_CHANNEL *shared_channel) {
    pthread_mutex_lock(&pdu->lock);

    if (pdu->num_entries >= pdu->max_entries) {
        size_t new_size = pdu->max_entries * 2;
        PHY_DOWNLINK_SHARED_CHANNEL *new_channels = (PHY_DOWNLINK_SHARED_CHANNEL*)realloc(pdu->shared_channels, new_size * sizeof(PHY_DOWNLINK_SHARED_CHANNEL));
        if (!new_channels) {
            pthread_mutex_unlock(&pdu->lock);
            return -1; // Handle memory allocation failure
        }
        pdu->shared_channels = new_channels;
        pdu->max_entries = new_size;
    }

    pdu->cell_update_request = *cell_update_request;
    pdu->shared_channels[pdu->num_entries++] = *shared_channel;

    pthread_mutex_unlock(&pdu->lock);
    return 0;
}
