    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_STRUCTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->count = 0;
    da->capacity = MAX_STRUCTS;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

int add_structure(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->count++] = new_struct;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int get_structure(DynamicArray *da, size_t index, NFAPI_CRC_INDICATION_PDU_T *result) {
