        return -1; // Invalid index
    }
    *result = da->array[index];
    return 0;
}

int update_structure(DynamicArray *da, size_t index, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    if (index >= da->count) {
        return -1; // Invalid index
    }
    pthread_mutex_lock(&da->lock);
    da->array[index] = new_struct;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

void compact_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    size_t new_capacity = da->count;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        da->array = new_array;
        da->capacity = new_capacity;
    }
    pthread_mutex_unlock(&da->lock);
}

