#define MAX_CONNECTIONS 1024

typedef struct {
    int id;
    float latency;
    float packet_loss;
    float throughput;
} ConnectionStatus;

typedef struct {
    ConnectionStatus *table[MAX_CONNECTIONS];
    pthread_mutex_t lock;
} NetworkHashTable;

NetworkHashTable* init_network_hash_table() {
    NetworkHashTable *ht = (NetworkHashTable*)malloc(sizeof(NetworkHashTable));
    if (!ht) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        ht->table[i] = NULL;
    }
    return ht;
}

void destroy_network_hash_table(NetworkHashTable *ht) {
    if (!ht) return;
    pthread_mutex_lock(&ht->lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        free(ht->table[i]);
    }
    pthread_mutex_unlock(&ht->lock);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void update_connection_status(NetworkHashTable *ht, int id, float latency, float packet_loss, float throughput) {
    if (!ht) return;
    pthread_mutex_lock(&ht->lock);
    ConnectionStatus *status = (ConnectionStatus*)malloc(sizeof(ConnectionStatus));
    if (!status) {
        perror("Failed to allocate memory for connection status");
        pthread_mutex_unlock(&ht->lock);
        return;
    }
    status->id = id;
    status->latency = latency;
    status->packet_loss = packet_loss;
    status->throughput = throughput;

    ht->table[id % MAX_CONNECTIONS] = status;
    pthread_mutex_unlock(&ht->lock);
}

void log_connection_status(NetworkHashTable *ht, int id) {
    if (!ht) return;
    pthread_mutex_lock(&ht->lock);
    ConnectionStatus *status = ht->table[id % MAX_CONNECTIONS];
    if (status) {
        printf("Connection ID: %d, Latency: %.2f ms, Packet Loss: %.2f%%, Throughput: %.2f Mbps\n",
               status->id, status->latency, status->packet_loss, status->throughput);
    } else {
        printf("No connection status found for ID: %d\n", id);
    }
    pthread_mutex_unlock(&ht->lock);
}
