public struct UserSession
{
    public int UserId { get; set; }
    public DateTime StartTime { get; set; }
    public DateTime LastActivityTime { get; set; }
    public string State { get; set; }
    public long DataTransferred { get; set; }
}

public class SessionManager
{
    private ConcurrentDictionary<int, UserSession> _sessions;
    private readonly object _lock = new object();
    private Timer _cleanupTimer;

    public SessionManager()
    {
        _sessions = new ConcurrentDictionary<int, UserSession>();
        _cleanupTimer = new Timer(CleanupInactiveSessions, null, TimeSpan.FromMinutes(5), TimeSpan.FromMinutes(5));
    }

    public void AddSession(int userId)
    {
        lock (_lock)
        {
            if (!_sessions.ContainsKey(userId))
            {
                _sessions.TryAdd(userId, new UserSession
                {
                    UserId = userId,
                    StartTime = DateTime.Now,
                    LastActivityTime = DateTime.Now,
                    State = "Active",
                    DataTransferred = 0
                });
            }
        }
    }

    public void UpdateSession(int userId, string state, long dataTransferred)
    {
        lock (_lock)
        {
            if (_sessions.ContainsKey(userId))
            {
                _sessions[userId] = new UserSession
                {
                    UserId = userId,
                    StartTime = _sessions[userId].StartTime,
                    LastActivityTime = DateTime.Now,
                    State = state,
                    DataTransferred = dataTransferred + _sessions[userId].DataTransferred
                };
            }
        }
    }

    public void RemoveSession(int userId)
    {
        lock (_lock)
        {
            if (_sessions.ContainsKey(userId))
            {
                _sessions.TryRemove(userId, out _);
            }
        }
    }

    private void CleanupInactiveSessions(object state)
    {
        var now = DateTime.Now;
        foreach (var session in _sessions.Values.ToList())
        {
            if ((now - session.LastActivityTime).TotalMinutes > 30) // Example expiration policy
            {
                RemoveSession(session.UserId);
            }
        }
    }

    public void LogSessionEvent(int userId, string eventType)
    {
        // Integrate with existing analytics framework here
    }
}
