typedef struct {
    int id;
    time_t timestamp;
    int active;
} Session;

typedef struct {
    Session* sessions;
    size_t capacity;
    size_t count;
} SessionManager;

SessionManager* initializeSessionManager(size_t initialCapacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->sessions = (Session*)calloc(initialCapacity, sizeof(Session));
    manager->capacity = initialCapacity;
    manager->count = 0;
    return manager;
}

void addOrUpdateSession(SessionManager* manager, int id, time_t timestamp, int active) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].id == id) {
            manager->sessions[i] = (Session){id, timestamp, active};
            return;
        }
    }
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = (Session*)realloc(manager->sessions, manager->capacity * sizeof(Session));
    }
    manager->sessions[manager->count++] = (Session){id, timestamp, active};
}

time_t calculateTotalActiveTime(SessionManager* manager) {
    time_t totalActiveTime = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].active) {
            totalActiveTime += time(NULL) - manager->sessions[i].timestamp;
        }
    }
    return totalActiveTime;
}

void cleanupInactiveSessions(SessionManager* manager, time_t idleThreshold) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (time(NULL) - manager->sessions[i].timestamp > idleThreshold && !manager->sessions[i].active) {
            // Mark session for cleanup
            // ...
        }
    }
}

void freeSessionManager(SessionManager* manager) {
    free(manager->sessions);
    free(manager);
}
