use reqwest::ClientBuilder;
use std::sync::{Arc, Mutex};
use log::{info, error};

#[derive(Clone)]
struct NFAPICRCIndicationPDU {
    rx_ue_information_tag: u32,
    rnti: u32,
    crc_indication_rel8_tag: u32,
    crcflag: bool,
}

impl NFAPICRCIndicationPDU {
    fn new() -> Self {
        NFAPICRCIndicationPDU {
            rx_ue_information_tag: rand::random(),
            rnti: rand::random(),
            crc_indication_rel8_tag: rand::random(),
            crcflag: rand::random(),
        }
    }
}

struct HTTPClient {
    client: ClientBuilder,
    crc_indications: Arc<Mutex<Vec<NFAPICRCIndicationPDU>>>,
}

impl HTTPClient {
    fn new(url: &str, disable_certificate_validation: bool) -> Self {
        let mut builder = ClientBuilder::new();
        if disable_certificate_validation {
            builder.danger_accept_invalid_certs(true);
        }
        builder = builder.build().unwrap();

        let crc_indications = Arc::new(Mutex::new(Vec::new()));

        HTTPClient {
            client: builder,
            crc_indications,
        }
    }

    fn create_crc_indications(&self, num_ues: usize) {
        for _ in 0..num_ues {
            self.crc_indications.lock().unwrap().push(NFAPICRCIndicationPDU::new());
        }
    }

    fn request_builder(&self) -> reqwest::RequestBuilder {
        self.client.request(reqwest::Method::GET, "http://example.com")
    }
}

fn main() {
    env_logger::init();

    let client = HTTPClient::new("http://example.com", false);
    client.create_crc_indications(10);

    let request_builder = client.request_builder();
    info!("Request builder created: {:?}", request_builder);
}
