int allocate_and_serialize(int N, PHY_MSG_PDU_T **array, char **serialized_data, size_t *data_size) {
    if (N <= 0) {
        return -1; // Invalid input
    }

    *array = (PHY_MSG_PDU_T *)malloc(N * sizeof(PHY_MSG_PDU_T));
    if (*array == NULL) {
        return -2; // Out of memory
    }

    for (int i = 0; i < N; i++) {
        (*array)[i].tag = i + 1; // Example initialization
        (*array)[i].channel_type = i % 3; // Example initialization
        (*array)[i].subframe_number = i * 2; // Example initialization
    }

    // Serialize the array into a binary format
    *data_size = N * sizeof(PHY_MSG_PDU_T);
    *serialized_data = (char *)malloc(*data_size);
    if (*serialized_data == NULL) {
        free(*array);
        return -3; // Out of memory
    }
    memcpy(*serialized_data, *array, *data_size);

    // Free the temporary array after serialization
    free(*array);
    *array = NULL;

    return 0; // Success
}

int deserialize_and_free(char *serialized_data, size_t data_size) {
    if (serialized_data == NULL || data_size == 0) {
        return -1; // Invalid input
    }

    PHY_MSG_PDU_T *array = (PHY_MSG_PDU_T *)malloc(data_size);
    if (array == NULL) {
        return -2; // Out of memory
    }
    memcpy(array, serialized_data, data_size);

    // Process the array as needed

    free(array);
    return 0; // Success
}
