#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MESSAGES 1000
#define MAX_PAYLOAD_SIZE 1024
#define MEMORY_LIMIT 5 * 1024 * 1024 // 5MB

typedef enum {
    PDU_TYPE_A,
    PDU_TYPE_B,
    PDU_TYPE_C,
    NUM_PDU_TYPES
} PDU_TYPE;

typedef struct {
    uint8_t* data;
    size_t size;
    bool compressed;
} TX_PDU_T;

typedef struct {
    PDU_TYPE type;
    TX_PDU_T* pdus;
    size_t pdu_count;
    time_t last_modified;
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T messages[MAX_MESSAGES];
size_t message_count = 0;
size_t total_memory_used = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

int allocate_pdu(TX_PDU_T* pdu, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE) {
        log_message("Error: Payload size exceeds maximum allowed.\n");
        return -1;
    }
    pdu->data = malloc(payload_size);
    if (!pdu->data) {
        log_message("Error: Failed to allocate memory for PDU payload.\n");
        return -1;
    }
    pdu->size = payload_size;
    pdu->compressed = false;
    return 0;
}

void free_pdu(TX_PDU_T* pdu) {
    if (pdu->data) {
        free(pdu->data);
        pdu->data = NULL;
        pdu->size = 0;
    }
}

int initialize_message(NFAPI_MESSAGE_T* message, PDU_TYPE type, size_t payload_size) {
    pthread_mutex_lock(&mutex);
    if (message_count >= MAX_MESSAGES) {
        log_message("Error: Maximum number of messages reached.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    message->type = type;
    message->pdu_count = 0;
    message->last_modified = time(NULL);
    total_memory_used += payload_size * sizeof(TX_PDU_T);
    if (total_memory_used > MEMORY_LIMIT) {
        log_message("Warning: Memory limit exceeded. Discarding oldest message.\n");
        free_pdu(&messages[0].pdus[0]);
        memmove(messages, messages + 1, (message_count - 1) * sizeof(NFAPI_MESSAGE_T));
        total_memory_used -= payload_size * sizeof(TX_PDU_T);
    }
    if (allocate_pdu(&message->pdus[message->pdu_count], payload_size) != 0) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    message_count++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

void update_message(NFAPI_MESSAGE_T* message, PDU_TYPE type, size_t payload_size) {
    pthread_mutex_lock(&mutex);
    if (message->type != type || message->pdus[message->pdu_count].size < payload_size) {
        free_pdu(&message->pdus[message->pdu_count]);
        if (allocate_pdu(&message->pdus[message->pdu_count], payload_size) != 0) {
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    message->type = type;
    message->last_modified = time(NULL);
    total_memory_used += payload_size * sizeof(TX_PDU_T);
    if (total_memory_used > MEMORY_LIMIT) {
        log_message("Warning: Memory limit exceeded. Discarding oldest message.\n");
        free_pdu(&messages[0].pdus[0]);
        memmove(messages, messages + 1, (message_count - 1) * sizeof(NFAPI_MESSAGE_T));
        total_memory_used -= payload_size * sizeof(TX_PDU_T);
    }
    pthread_mutex_unlock(&mutex);
}

void* message_thread(void* arg) {
    PDU_TYPE type = *(PDU_TYPE*)arg;
    size_t payload_size = rand() % MAX_PAYLOAD_SIZE + 1;
    if (initialize_message(&messages[message_count], type, payload_size) != 0) {
        log_message("Error: Failed to initialize message.\n");
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[NUM_PDU_TYPES];
    for (int i = 0; i < NUM_PDU_TYPES; i++) {
        if (pthread_create(&threads[i], NULL, message_thread, &i) != 0) {
            log_message("Error: Failed to create thread.\n");
            return -1;
        }
    }
    for (int i = 0; i < NUM_PDU_TYPES; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
