#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <mutex>
#include <unordered_set>
#include <string>

namespace NetworkUtils {
    struct LAYER2_PACKET {
        uint32_t L2_TAG;
        std::string MAC_ADDRESS;
        uint16_t STATUS_CODE;
        bool RANDOM_FLAG;
    };

    class RandomNumberGenerator {
    public:
        RandomNumberGenerator(uint64_t seed, int minRange, int maxRange)
            : gen(seed), dis(minRange, maxRange) {}

        int generate() {
            return dis(gen);
        }

    private:
        std::mt19937 gen;
        std::uniform_int_distribution<> dis;
    };

    class PacketGenerator {
    public:
        PacketGenerator(const std::vector<std::string>& macAddresses, int minRange, int maxRange)
            : rng(std::chrono::system_clock::now().time_since_epoch().count() + 1, minRange, maxRange),
              macSet(macAddresses.begin(), macAddresses.end()) {
            if (macSet.size() != macAddresses.size()) {
                throw std::invalid_argument("Duplicate MAC addresses provided.");
            }
        }

        std::vector<LAYER2_PACKET> generatePackets(int maxSize) {
            std::vector<LAYER2_PACKET> packets;
            for (int i = 0; i < std::min(maxSize, static_cast<int>(macSet.size())); ++i) {
                LAYER2_PACKET packet;
                packet.L2_TAG = rng.generate();
                packet.MAC_ADDRESS = *std::next(macSet.begin(), i);
                packet.STATUS_CODE = rng.generate();
                packet.RANDOM_FLAG = (rng.generate() % 2 == 0);
                packets.push_back(packet);
            }
            return packets;
        }

    private:
        RandomNumberGenerator rng;
        std::unordered_set<std::string> macSet;
    };
}

int main() {
    try {
        std::vector<std::string> macAddresses = {"00:1A:2B:3C:4D:5E", "AA:BB:CC:DD:EE:FF"};
        NetworkUtils::PacketGenerator generator(macAddresses, 100, 999);
        auto packets = generator.generatePackets(10);

        for (const auto& packet : packets) {
            std::cout << "L2_TAG: " << packet.L2_TAG
                      << ", MAC_ADDRESS: " << packet.MAC_ADDRESS
                      << ", STATUS_CODE: " << packet.STATUS_CODE
                      << ", RANDOM_FLAG: " << (packet.RANDOM_FLAG ? "true" : "false") << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
