    for (int i = 0; i < MAX_NFAPIS; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 100;
        crc_indications[i].RNTI = rand() % 256;
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        crc_indications[i].CRCFLAG = rand() % 2;
    }
    num_crc_indications = MAX_NFAPIS;
}

void update_crc_indications() {
    // Simulate fetching data from an external source
    for (int i = 0; i < num_crc_indications; i++) {
        crc_indications[i].CRCFLAG = rand() % 2; // Randomly update CRCFLAG
    }
}

void parse_png_file(const char* file_path) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open PNG file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char* buffer = (unsigned char*)malloc(file_size);
    if (!buffer) {
        perror("Failed to allocate memory for PNG file");
        fclose(file);
        return;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        perror("Failed to read PNG file");
        free(buffer);
        fclose(file);
        return;
    }

    // Process the PNG data
    printf("PNG file parsed successfully. Size: %ld bytes\n", file_size);

    free(buffer);
    fclose(file);
}

int main() {
    initialize_crc_indications();
    update_crc_indications();

    parse_png_file("path_to_png_file.png");

