#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int data;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** generateNfarcrcIndications(int N) {
    const double memoryLimit = 0.95; // 95% of available memory
    size_t initialSize = 1024 * 1024; // Initial allocation size in bytes
    size_t incrementSize = 1024 * 1024; // Incremental allocation size in bytes

    NFAPI_CRC_INDICATION_PDU_T** array = NULL;
    size_t allocatedSize = 0;

    while (allocatedSize < N) {
        size_t newSize = allocatedSize + incrementSize;
        if ((double)newSize / initialSize > memoryLimit) {
            incrementSize /= 2; // Reduce allocation incrementally
            continue;
        }

        array = realloc(array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (array == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        for (size_t i = allocatedSize; i < newSize; ++i) {
            array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (array[i] == NULL) {
                fprintf(stderr, "Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T\n");
                return NULL;
            }
        }

        allocatedSize = newSize;
    }

    return array;
}
