    manager->count = 0;
    manager->packets = (NetworkPacket *)malloc(max_count * sizeof(NetworkPacket));
    manager->crc_packets = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&manager->lock, NULL);
}

void add_packet(PacketManager *manager, NetworkPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < manager->max_count) {
        manager->packets[manager->count] = packet;
        manager->crc_packets[manager->count].ue_info_tag = generate_ue_info_tag();
        manager->crc_packets[manager->count].rnti = generate_rnti();
        manager->crc_packets[manager->count].crc_indication_rel8_tag.crcflag = rand() % 2;
        manager->count++;
    }
    pthread_mutex_unlock(&manager->lock);
}

void update_packet(PacketManager *manager, int index, NetworkPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (index >= 0 && index < manager->count) {
        manager->packets[index] = packet;
        manager->crc_packets[index].ue_info_tag = generate_ue_info_tag();
        manager->crc_packets[index].rnti = generate_rnti();
        manager->crc_packets[index].crc_indication_rel8_tag.crcflag = rand() % 2;
    }
    pthread_mutex_unlock(&manager->lock);
}

int calculate_total_data_transferred(PacketManager *manager) {
    int total = 0;
    for (int i = 0; i < manager->count; i++) {
        total += manager->packets[i].payload_length;
    }
    return total;
}

void check_crc_flags(PacketManager *manager) {
    int sum = 0;
    for (int i = 0; i < manager->count; i++) {
        sum += manager->crc_packets[i].crc_indication_rel8_tag.crcflag;
    }
    if (sum != 0) {
        printf("Error: Sum of CRC flags is not zero.\n");
    } else {
        printf("All CRC flags are correctly set to zero.\n");
    }
}

void destroy_packet_manager(PacketManager *manager) {
    free(manager->packets);
    free(manager->crc_packets);
    pthread_mutex_destroy(&manager->lock);
}
