#include <time.h>

#define MAX_NODES 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int tag, unsigned short rnti, int crcFlag) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->data.RX_UE_INFORMATION_TAG = tag;
    newNode->data.RNTI = rnti;
    newNode->data.CRC_INDICATION_REL8_TAG = crcFlag;
    newNode->next = NULL;
    return newNode;
}

Node* add_node(Node** head, int tag, unsigned short rnti, int crcFlag) {
    if (*head == NULL || (*head)->data.RNTI != rnti) {
        Node* newNode = create_node(tag, rnti, crcFlag);
        if (newNode != NULL) {
            newNode->next = *head;
            *head = newNode;
        }
        return *head;
    } else {
        fprintf(stderr, "RNTI already exists in the list\n");
        return *head;
    }
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    srand(time(NULL));
    Node* head = NULL;

    for (int i = 0; i < MAX_NODES; i++) {
        unsigned short rnti = rand() % 65536 + 1;
        int tag = i;
        int crcFlag = rand() % 2;
        add_node(&head, tag, rnti, crcFlag);
    }

    free_list(head);

    return 0;
}
