    if (n <= 0 || max_content_size == 0) {
        return NULL; // Invalid input
    }

    NFAPI_RRC_MESSAGE_T* messages = (NFAPI_RRC_MESSAGE_T*)malloc(n * sizeof(NFAPI_RRC_MESSAGE_T));
    if (!messages) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < n; ++i) {
        messages[i].type = RRC_MESSAGE_TYPE_1 + (i % 2); // Example type assignment
        messages[i].pdu_session_id = i;
        messages[i].content_size = max_content_size;
        messages[i].content = (char*)malloc(max_content_size);
        if (!messages[i].content) {
            // Handle memory allocation failure for individual message
            for (int j = 0; j < i; ++j) {
                free(messages[j].content);
            }
            free(messages);
            return NULL;
        }
    }

    return messages;
}

void destroy_rrc_messages(NFAPI_RRC_MESSAGE_T* messages, int n) {
    if (!messages || n <= 0) {
        return; // Invalid input
    }

    for (int i = 0; i < n; ++i) {
        free(messages[i].content);
    }
    free(messages);
}
