#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NODES 10000
#define RNTI_MIN 1
#define RNTI_MAX 65535
#define LOG_FILE "nfaapi_crc_indication.log"
#define MAX_LOG_SIZE (1 * 1024 * 1024) // 1 MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    int size;
} DoublyLinkedList;

void log_message(const char* message) {
    static FILE* log_file = NULL;
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Failed to open log file");
            return;
        }
    }

    if (ftell(log_file) >= MAX_LOG_SIZE) {
        fclose(log_file);
        remove(LOG_FILE);
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            perror("Failed to reopen log file after truncation");
            return;
        }
    }

    fprintf(log_file, "%s\n", message);
    fflush(log_file);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, unsigned short RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->next = NULL;
    node->prev = NULL;

    return node;
}

int insert_node(DoublyLinkedList* list, int RX_UE_INFORMATION_TAG, unsigned short RNTI, int CRC_INDICATION_REL8_TAG) {
    if (list->size >= MAX_NODES) {
        log_message("Maximum number of nodes reached");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (!new_node) {
        return -1;
    }

    if (list->size == 0) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    log_message("Node inserted with RNTI: %u", RNTI);
    list->size++;
    return 0;
}

void free_list(DoublyLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->size = 0;
}

int main() {
    srand(time(NULL));
    DoublyLinkedList list = {NULL, NULL, 0};

    for (int i = 0; i < MAX_NODES; i++) {
        unsigned short RNTI = RNTI_MIN + rand() % (RNTI_MAX - RNTI_MIN + 1);
        if (insert_node(&list, i, RNTI, rand())) {
            break;
        }
    }

    free_list(&list);

    return 0;
}
