#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NODES 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashTableEntry {
    unsigned short RNTI;
    NFAPI_CRC_INDICATION_PDU_T *node;
    struct HashTableEntry *next;
} HashTableEntry;

HashTableEntry *hashTable[MAX_NODES];

NFAPI_CRC_INDICATION_PDU_T* createNode(int RX_UE_INFORMATION_TAG, unsigned short RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;
    return newNode;
}

unsigned int hashFunction(unsigned short RNTI) {
    return RNTI % MAX_NODES;
}

int insertNode(NFAPI_CRC_INDICATION_PDU_T *node) {
    unsigned int index = hashFunction(node->RNTI);
    HashTableEntry *entry = hashTable[index];
    while (entry != NULL) {
        if (entry->RNTI == node->RNTI) {
            fprintf(stderr, "Duplicate RNTI detected\n");
            return -1;
        }
        entry = entry->next;
    }
    entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (entry == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    entry->RNTI = node->RNTI;
    entry->node = node;
    entry->next = hashTable[index];
    hashTable[index] = entry;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* findNode(unsigned short RNTI) {
    unsigned int index = hashFunction(RNTI);
    HashTableEntry *entry = hashTable[index];
    while (entry != NULL) {
        if (entry->RNTI == RNTI) {
            return entry->node;
        }
        entry = entry->next;
    }
    return NULL;
}

void freeList() {
    for (int i = 0; i < MAX_NODES; i++) {
        HashTableEntry *entry = hashTable[i];
        while (entry != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *node = entry->node;
            HashTableEntry *nextEntry = entry->next;
            free(node);
            free(entry);
            entry = nextEntry;
        }
    }
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < MAX_NODES; i++) {
        hashTable[i] = NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *node1 = createNode(1, 12345, 6789);
    if (insertNode(node1) != 0) {
        freeList();
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *node2 = findNode(12345);
    if (node2 == NULL) {
        fprintf(stderr, "Node not found\n");
        freeList();
        return -1;
    }

    printf("Found node with RNTI: %d\n", node2->RNTI);

    freeList();
    return 0;
}
