#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000
#define MIN_N 1
#define MAX_N 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* list[MAX_STRUCTS];
int total_structs = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random_crcflag(int *crcflag) {
    srand(time(NULL));
    do {
        *crcflag = rand() % 1000; // Adjust range as needed
    } while (*crcflag == 0); // Ensure non-zero CRCFLAG
}

int create_structures(int N) {
    pthread_mutex_lock(&mutex);
    if (N < MIN_N || N > MAX_N) {
        printf("Error: N is out of the allowed range.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    if (total_structs + N > MAX_STRUCTS) {
        printf("Error: Maximum number of structures reached.\n");
        pthread_mutex_unlock(&mutex);
        return -2;
    }

    for (int i = 0; i < N; i++) {
        list[total_structs] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[total_structs]) {
            printf("Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&mutex);
            return -3;
