typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} ThreadSafeList;

void init_thread_safe_list(ThreadSafeList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry_to_list(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Overflow
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int get_entry_by_rnti(ThreadSafeList *list, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].rnti == rnti) {
            *entry = list->entries[i];
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void destroy_thread_safe_list(ThreadSafeList *list) {
    pthread_mutex_destroy(&list->lock);
}
