int read_integers(int **array, size_t *size) {
    char buffer[256];
    if (!fgets(buffer, sizeof(buffer), stdin)) return -1;
    *size = 0;
    char *token = strtok(buffer, " ");
    while (token != NULL && *size < MAX_SIZE) {
        (*array)[(*size)++] = atoi(token);
        token = strtok(NULL, " ");
    }
    if (*size == MAX_SIZE) return -1; // Overflow
    return 0;
}

int find_largest(int *array, size_t size) {
    if (size == 0) return -1; // Empty list
    int largest = array[0];
    for (size_t i = 1; i < size; i++) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

