#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define BANDWIDTH_LIMIT 1024

typedef struct {
    int SequenceNumber;
    int PacketSize;
    char Payload[MAX_PACKET_SIZE];
} NetworkPacket;

typedef struct {
    int SessionID;
    int ConnectionStatus;
    NetworkPacket *Packets;
    int NumPackets;
    int TotalPayloadSize;
} NetworkSession;

typedef struct {
    NetworkSession **Sessions;
    int NumSessions;
    pthread_mutex_t mutex;
} NetworkManager;

NetworkManager* create_network_manager() {
    NetworkManager *manager = (NetworkManager*)malloc(sizeof(NetworkManager));
    manager->Sessions = NULL;
    manager->NumSessions = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void add_session(NetworkManager *manager, int session_id) {
    pthread_mutex_lock(&manager->mutex);
    NetworkSession *session = (NetworkSession*)malloc(sizeof(NetworkSession));
    session->SessionID = session_id;
    session->ConnectionStatus = 1; // Assuming all sessions are initially connected
    session->Packets = NULL;
    session->NumPackets = 0;
    session->TotalPayloadSize = 0;
    manager->Sessions = realloc(manager->Sessions, (manager->NumSessions + 1) * sizeof(NetworkSession*));
    manager->Sessions[manager->NumSessions++] = session;
    pthread_mutex_unlock(&manager->mutex);
}

void add_packet_to_session(NetworkManager *manager, int session_id, NetworkPacket packet) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->NumSessions; i++) {
        if (manager->Sessions[i]->SessionID == session_id) {
            if (manager->Sessions[i]->TotalPayloadSize + packet.PacketSize > BANDWIDTH_LIMIT) {
                // Handle fragmentation
                int remaining_payload_size = packet.PayloadSize;
                while (remaining_payload_size > 0) {
                    NetworkPacket new_packet;
                    new_packet.SequenceNumber = manager->Sessions[i]->NumPackets + 1;
                    new_packet.PacketSize = remaining_payload_size < MAX_PACKET_SIZE ? remaining_payload_size : MAX_PACKET_SIZE;
                    memcpy(new_packet.Payload, packet.Payload + packet.PayloadSize - remaining_payload_size, new_packet.PacketSize);
                    // Set tags for RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
                    // ...
                    manager->Sessions[i]->Packets = realloc(manager->Sessions[i]->Packets, (manager->Sessions[i]->NumPackets + 1) * sizeof(NetworkPacket));
                    manager->Sessions[i]->Packets[manager->Sessions[i]->NumPackets++] = new_packet;
                    remaining_payload_size -= new_packet.PacketSize;
                }
            } else {
                // Add packet directly
                manager->Sessions[i]->Packets = realloc(manager->Sessions[i]->Packets, (manager->Sessions[i]->NumPackets + 1) * sizeof(NetworkPacket));
                manager->Sessions[i]->Packets[manager->Sessions[i]->NumPackets++] = packet;
                manager->Sessions[i]->TotalPayloadSize += packet.PacketSize;
            }
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void destroy_network_manager(NetworkManager *manager) {
    for (int i = 0; i < manager->NumSessions; i++) {
        free(manager->Sessions[i]->Packets);
        free(manager->Sessions[i]);
    }
    free(manager->Sessions);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
