#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define MAX_ITEMS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicList {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t capacity;
    size_t size;
} DynamicList;

DynamicList* dynamic_list_init() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->items = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        free(list);
        return NULL;
    }
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    return list;
}

int dynamic_list_insert(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_items = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_items) return -1;
        list->items = new_items;
        list->capacity = new_capacity;
    }
    for (size_t i = 0; i < list->size; ++i) {
        if (list->items[i].RNTI == item.RNTI) return -2; // RNTI collision
    }
    list->items[list->size++] = item;
    return 0;
}

int dynamic_list_remove(DynamicList *list, int rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->items[i].RNTI == rnti) {
            memmove(&list->items[i], &list->items[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            return 0;
        }
    }
    return -3; // RNTI not found
}

void dynamic_list_traverse(DynamicList *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    for (size_t i = 0; i < list->size; ++i) {
        callback(list->items[i]);
    }
}

void dynamic_list_destroy(DynamicList *list) {
    free(list->items);
    free(list);
}
