NFAPI_RX_FRAME_PDU_T** initialize_rf_frame_array(size_t N) {
    NFAPI_RX_FRAME_PDU_T** frame_array = (NFAPI_RX_FRAME_PDU_T**)malloc(N * sizeof(NFAPI_RX_FRAME_PDU_T*));
    if (!frame_array) {
        perror("Failed to allocate memory for frame array");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        frame_array[i] = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!frame_array[i]) {
            perror("Failed to allocate memory for individual frame");
            // Clean up previously allocated frames
            for (size_t j = 0; j < i; ++j) {
                free(frame_array[j]);
            }
            free(frame_array);
            return NULL;
        }

        // Initialize header and other fields here
        frame_array[i]->header = (NFAPI_RX_FRAME_HEADER){};
        frame_array[i]->raw_data = NULL;
        frame_array[i]->data_size = 0;
        frame_array[i]->timestamp = -1;
        frame_array[i]->signal_strength = -1.0f;
        frame_array[i]->user_data = NULL;
        frame_array[i]->user_data_size = 0;
    }

    return frame_array;
}

void free_rf_frame_array(NFAPI_RX_FRAME_PDU_T** frame_array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        if (frame_array[i]) {
            free(frame_array[i]->raw_data);
            free(frame_array[i]);
        }
    }
    free(frame_array);
}

int process_rf_frame(NFAPI_RX_FRAME_PDU_T* frame, const uint8_t* raw_data, size_t data_size, int64_t timestamp, float signal_strength, void* user_data, size_t user_data_size) {
    if (!frame || !raw_data || data_size == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    // Resize raw_data buffer if necessary
    if (frame->data_size < data_size) {
        frame->raw_data = realloc(frame->raw_data, data_size);
        if (!frame->raw_data) {
            perror("Failed to reallocate memory for raw data");
            return -1;
        }
        frame->data_size = data_size;
    }

    // Copy raw data
    memcpy(frame->raw_data, raw_data, data_size);

    // Update metadata
    frame->timestamp = timestamp;
    frame->signal_strength = signal_strength;

    if (user_data && user_data_size > 0) {
        // Resize user_data buffer if necessary
        if (frame->user_data_size < user_data_size) {
            frame->user_data = realloc(frame->user_data, user_data_size);
            if (!frame->user_data) {
                perror("Failed to reallocate memory for user data");
                return -1;
            }
            frame->user_data_size = user_data_size;
        }

        // Copy user data
        memcpy(frame->user_data, user_data, user_data_size);
    } else {
        frame->user_data = NULL;
        frame->user_data_size = 0;
    }

    return 0;
}
