        S_NSSAI = "S-NSSAI-" + std::to_string(rand() % 10);
        AMF = "AMF-" + std::to_string(rand() % 10);
        return true;
    }

    bool UpdateUEContext(int UE_ID, const std::string& S_NSSAI, const std::string& AMF) {
        // Simulate network state verification and context update
        std::this_thread::sleep_for(std::chrono::milliseconds(50 + rand() % 100));
        if (rand() % 3 == 0) {
            return false; // Simulate failure during update
        }
        std::cout << "UE Context updated for UE ID: " << UE_ID << std::endl;
        return true;
    }
};

class LTEUEContextManager {
private:
    NetworkSliceSelectionFunction nssf;
    std::vector<LTEUEContextRequest> requests;
    bool isCooldown;

public:
    LTEUEContextManager() : isCooldown(false) {}

    void GenerateRequests(int M) {
        for (int i = 0; i < M; ++i) {
            LTEUEContextRequest request;
            request.UE_ID = rand() % 1000;
            request.TAI = "TAI-" + std::to_string(rand() % 10);
            request.RRC_Cause = "Cause-" + std::to_string(rand() % 5);
            requests.push_back(request);
        }
    }

    void ProcessRequests() {
        for (const auto& request : requests) {
            if (!isCooldown) {
                std::string S_NSSAI, AMF;
                if (nssf.RequestS_NSSAIAndAMF(S_NSSAI, AMF)) {
                    if (nssf.UpdateUEContext(request.UE_ID, S_NSSAI, AMF)) {
                        isCooldown = true;
                        std::this_thread::sleep_for(std::chrono::seconds(30));
                        isCooldown = false;
                    }
                } else {
                    std::cerr << "Failed to request S-NSSAI and AMF for UE ID: " << request.UE_ID << std::endl;
                }
            } else {
                std::cout << "Cooldown period active, skipping request for UE ID: " << request.UE_ID << std::endl;
            }
        }
    }

    void LogRequests() const {
        std::ofstream logFile("ue_context_requests.log");
        if (logFile.is_open()) {
            for (const auto& request : requests) {
                logFile << "UE ID: " << request.UE_ID << ", TAI: " << request.TAI << ", RRC Cause: " << request.RRC_Cause << std::endl;
            }
            logFile.close();
        } else {
            std::cerr << "Unable to open log file" << std::endl;
        }
    }
};

int main() {
    LTEUEContextManager manager;
    manager.GenerateRequests(10);
    manager.ProcessRequests();
    manager.LogRequests();
    return 0;
}
