// Mock InterfaceTable class for testing
class InterfaceTable {
public:
    static std::string FindVmUuidFromMetadataIp(const std::string& ip) {
        // Simulate metadata lookup with random delay and result
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        return "vm_uuid_" + ip;
    }
};

// NFAPI_CRC_INDICATION_PDU_T struct for network telemetry data
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;

    NFAPI_CRC_INDICATION_PDU_T(int rxTag, int rnti) : RX_UE_INFORMATION_TAG(rxTag), RNTI(rnti), CRCFLAG(rand() % 2) {}
};

// Data processing function
void ProcessData(const NFAPI_CRC_INDICATION_PDU_T& data) {
    std::string vmUuid = InterfaceTable::FindVmUuidFromMetadataIp("192.168.1." + std::to_string(data.RNTI));
    // Simulate data processing with random delay
    std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 500));
    std::cout << "Processed data for RNTI: " << data.RNTI << ", VM UUID: " << vmUuid << std::endl;
}

// Thread-safe queue for processing tasks
class TaskQueue {
private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> tasks;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void enqueue(const NFAPI_CRC_INDICATION_PDU_T& task) {
        std::lock_guard<std::mutex> lock(mtx);
        tasks.push(task);
        cv.notify_one();
    }

    bool dequeue(NFAPI_CRC_INDICATION_PDU_T& task) {
        std::unique_lock<std::mutex> lock(mtx);
        if (cv.wait_for(lock, std::chrono::seconds(1), [this] { return !tasks.empty(); })) {
            task = tasks.front();
            tasks.pop();
            return true;
        }
        return false;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mtx);
        return tasks.empty();
    }
};

// Worker thread function
void worker(TaskQueue& queue) {
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T task;
        if (queue.dequeue(task)) {
            ProcessData(task);
        } else {
            break; // Exit if no more tasks are available
        }
    }
}

// Function to parse XML using XPath and retrieve the first matching element by name
std::string ParseXmlWithXPath(const std::string& xml, const std::string& xpath) {
    xmlDocPtr doc = xmlReadMemory(xml.c_str(), xml.size(), "noname.xml", NULL, 0);
    if (!doc) throw std::runtime_error("Failed to parse XML");

    xmlXPathContextPtr ctx = xmlXPathNewContext(doc);
    if (!ctx) {
        xmlFreeDoc(doc);
        throw std::runtime_error("Failed to create XPath context");
    }

    xmlXPathObjectPtr obj = xmlXPathEvalExpression((xmlChar*)xpath.c_str(), ctx);
    if (!obj || obj->type != XPATH_NODESET) {
        xmlXPathFreeContext(ctx);
        xmlFreeDoc(doc);
        throw std::runtime_error("Invalid XPath expression or no matching elements");
    }

    xmlNodeSetPtr nodes = obj->nodesetval;
    if (nodes && nodes->nodeNr > 0) {
        std::string result((const char*)xmlNodeGetContent(nodes->nodeTab[0]));
        xmlXPathFreeObject(obj);
        xmlXPathFreeContext(ctx);
        xmlFreeDoc(doc);
        return result;
    } else {
        xmlXPathFreeObject(obj);
        xmlXPathFreeContext(ctx);
        xmlFreeDoc(doc);
        throw std::runtime_error("No matching elements found");
    }
}

int main() {
    TaskQueue queue;
    const int numThreads = 4;

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < numThreads; ++i) {
        workers.emplace_back(worker, std::ref(queue));
    }

    // Enqueue tasks
    for (int i = 1; i <= 100; ++i) {
        queue.enqueue(NFAPI_CRC_INDICATION_PDU_T(i, rand() % 256));
    }

    // Wait for all tasks to complete
    while (!queue.empty()) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    // Stop worker threads
    for (auto& w : workers) {
        queue.enqueue(NFAPI_CRC_INDICATION_PDU_T(-1, -1)); // Signal to exit
    }
    for (auto& w : workers) {
        w.join();
    }

    try {
        std::string xml = "<root><element>value</element></root>";
        std::string xpath = "//element";
        std::cout << "Parsed value: " << ParseXmlWithXPath(xml, xpath) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error parsing XML: " << e.what() << std::endl;
    }

    return 0;
}
