#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char* identifier;
} Item;

typedef struct {
    Item** items;
    size_t count;
    size_t capacity;
} ItemCollection;

ItemCollection* create_item_collection() {
    ItemCollection* collection = (ItemCollection*)malloc(sizeof(ItemCollection));
    if (!collection) return NULL;
    collection->items = NULL;
    collection->count = 0;
    collection->capacity = 0;
    return collection;
}

void destroy_item_collection(ItemCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->items[i]->identifier);
        free(collection->items[i]);
    }
    free(collection->items);
    free(collection);
}

int add_item(ItemCollection* collection, double value, const char* identifier) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        Item** new_items = (Item**)realloc(collection->items, new_capacity * sizeof(Item*));
        if (!new_items) return -1;
        collection->items = new_items;
        collection->capacity = new_capacity;
    }
    Item* item = (Item*)malloc(sizeof(Item));
    if (!item) return -1;
    item->value = value;
    item->identifier = strdup(identifier);
    if (!item->identifier) {
        free(item);
        return -1;
    }
    collection->items[collection->count++] = item;
    return 0;
}

int update_item(ItemCollection* collection, const char* identifier, double new_value) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->items[i]->identifier, identifier) == 0) {
            collection->items[i]->value = new_value;
            return 0;
        }
    }
    return -1;
}

void iterate_items(ItemCollection* collection, void (*callback)(Item*)) {
    for (size_t i = 0; i < collection->count; ++i) {
        callback(collection->items[i]);
    }
}

int export_to_file(ItemCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return -1;
    for (size_t i = 0; i < collection->count; ++i) {
        fprintf(file, "%s: %f\n", collection->items[i]->identifier, collection->items[i]->value);
    }
    fclose(file);
    return 0;
}
