void init_memory_pool(size_t initial_size) {
    if (initial_size < MIN_MEMORY_POOL_SIZE || initial_size > MAX_MEMORY_POOL_SIZE) {
        fprintf(stderr, "Invalid initial size for memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.capacity = initial_size;
