    }
}

void resize_memory_pool(size_t new_capacity) {
    if (new_capacity < MIN_MEMORY_POOL_SIZE || new_capacity > MAX_MEMORY_POOL_SIZE) {
        fprintf(stderr, "Invalid capacity for memory pool\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(memory_pool.pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
