    if (memory_pool.size >= memory_pool.capacity) {
        resize_memory_pool(memory_pool.capacity * 2);
    }
    memcpy(&memory_pool.pdus[memory_pool.size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memory_pool.size++;
    pthread_mutex_unlock(&memory_pool.lock);
}

void* background_thread(void *arg) {
    while (1) {
        // Monitor memory fragmentation and reclaim unused memory
        // Periodically check for and evict older entries if necessary
        sleep(60); // Check every minute
    }
    return NULL;
}

