#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *collection[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t collection_lock;

void initialize_collection() {
    pthread_mutex_init(&collection_lock, NULL);
}

void populate_collection(int num_entries) {
    if (num_entries > MAX_ENTRIES) {
        printf("Error: Number of entries exceeds maximum limit.\n");
        return;
    }

    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!entry) {
            printf("Error: Out of memory.\n");
            return;
        }
        entry->RX_UE_INFORMATION_TAG = rand() % 1000;
        entry->RNTI = rand() % 1000;
        entry->CRC_INDICATION_REL8_TAG = rand() % 1000;
        entry->CRCFLAG = rand() % 2;

        pthread_mutex_lock(&collection_lock);
        collection[i] = entry;
        entry_count++;
        pthread_mutex_unlock(&collection_lock);
    }
}

void update_collection(int index, NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    if (index < 0 || index >= entry_count) {
        printf("Error: Invalid index.\n");
        return;
    }

    pthread_mutex_lock(&collection_lock);
    free(collection[index]);
    collection[index] = new_entry;
    pthread_mutex_unlock(&collection_lock);
}

void serialize_collection(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Unable to open file for writing.\n");
        return;
    }

    fwrite(collection, sizeof(NFAPI_CRC_INDICATION_PDU_T *), entry_count, file);
    fclose(file);
}

void deserialize_collection(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Unable to open file for reading.\n");
        return;
    }

    int num_entries = fread(collection, sizeof(NFAPI_CRC_INDICATION_PDU_T *), MAX_ENTRIES, file);
    entry_count = num_entries > MAX_ENTRIES ? MAX_ENTRIES : num_entries;
    fclose(file);
}
