void initializeNfadecrypt(NFAPI_CRC_INDICATION_PDU_T **nfapi_list, int list_size, unsigned long seed, const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error
        return;
    }

    // Initialize NFAPI structures with pseudo-random values based on seed
    for (int i = 0; i < list_size; i++) {
        nfapi_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfapi_list[i]) {
            // Handle error
            EVP_CIPHER_CTX_free(ctx);
            return;
