        nfapi_list[i]->ue_info_tag = (RX_UE_INFORMATION_TAG)rand_r(&seed);
        nfapi_list[i]->rnti = (RNTI)rand_r(&seed);
        nfapi_list[i]->crc_indication_rel8_tag.CRCFLAG = rand_r(&seed) % 2;
    }

    // Initialize AES-256-CBC cipher
