void initialize_arrays(double** double_array, unsigned long** ulong_array, data_packet** packet_array, size_t initial_capacity) {
    *double_array = (double*)malloc(initial_capacity * sizeof(double));
    *ulong_array = (unsigned long*)malloc(initial_capacity * sizeof(unsigned long));
    *packet_array = (data_packet*)malloc(initial_capacity * sizeof(data_packet));

    if (*double_array == NULL || *ulong_array == NULL || *packet_array == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < initial_capacity; ++i) {
        (*double_array)[i] = ((double)rand() / RAND_MAX) * 1e6; // Random double between 0 and 1e6
        (*ulong_array)[i] = rand(); // Random unsigned long

        // Initialize data_packet with random values
        (*packet_array)[i].timestamp = time(NULL);
        (*packet_array)[i].status_flag = (rand() % 2 == 0) ? true : false;
        size_t data_length = rand() % 100 + 1; // Random length between 1 and 100
        (*packet_array)[i].data = (char*)malloc(data_length * sizeof(char));
        if ((*packet_array)[i].data == NULL) {
            // Handle memory allocation failure for data_packet
            exit(EXIT_FAILURE);
        }
        for (size_t j = 0; j < data_length - 1; ++j) {
            (*packet_array)[i].data[j] = 'a' + rand() % 26; // Random lowercase letter
        }
        (*packet_array)[i].data[data_length - 1] = '\0'; // Null-terminate string
    }
}

void free_arrays(double* double_array, unsigned long* ulong_array, data_packet* packet_array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        free(packet_array[i].data); // Free dynamically allocated string in each data_packet
    }
    free(double_array);
    free(ulong_array);
    free(packet_array);
}
