    array->capacity = initial_capacity;
    array->size = 0;
    array->pdus = (NFAPI_RRC_CU_TRANSPORT_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
    pthread_mutex_init(&array->mutex, NULL);
}

void free_pdu_array(PDU_Array *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->pdus);
    array->pdus = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

void add_pdu(PDU_Array *array, NFAPI_RRC_CU_TRANSPORT_PDU_T pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        array->pdus = (NFAPI_RRC_CU_TRANSPORT_PDU_T *)realloc(array->pdus, new_capacity * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        array->capacity = new_capacity;
    }
    array->pdus[array->size++] = pdu;
    pthread_mutex_unlock(&array->mutex);
}

void update_timestamp(PDU_Array *array, int cell_id, time_t new_timestamp) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->pdus[i].cell_id == cell_id) {
            array->pdus[i].timestamp = new_timestamp;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void filter_outdated_pdus(PDU_Array *array, time_t threshold_time) {
    pthread_mutex_lock(&array->mutex);
    size_t i = 0;
    while (i < array->size) {
        if (difftime(array->pdus[i].timestamp, threshold_time) > 0) {
            for (size_t j = i; j < array->size - 1; ++j) {
                array->pdus[j] = array->pdus[j + 1];
            }
            --array->size;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}
