    size_t capacity;
    size_t size;
    pthread_rwlock_t lock;
} PDU_Manager;

PDU_Manager* create_pdu_manager(size_t initial_capacity) {
    PDU_Manager *manager = (PDU_Manager*)malloc(sizeof(PDU_Manager));
    manager->pdus = (NFAPI_RRC_CU_TRANSPORT_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_rwlock_init(&manager->lock, NULL);
    return manager;
}

void destroy_pdu_manager(PDU_Manager *manager) {
    free(manager->pdus);
    pthread_rwlock_destroy(&manager->lock);
    free(manager);
}

int add_pdu(PDU_Manager *manager, NFAPI_RRC_CU_TRANSPORT_PDU_T pdu, int priority) {
    pthread_rwlock_wrlock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->pdus = (NFAPI_RRC_CU_TRANSPORT_PDU_T*)realloc(manager->pdus, new_capacity * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        manager->capacity = new_capacity;
    }
    size_t i = manager->size - 1;
    while (i >= 0 && priority > manager->pdus[i].sequence_number) {
        manager->pdus[i + 1] = manager->pdus[i];
        i--;
    }
    manager->pdus[i + 1] = pdu;
    manager->size++;
    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

void remove_outdated_pdus(PDU_Manager *manager, time_t threshold) {
    pthread_rwlock_wrlock(&manager->lock);
    size_t i = 0;
    while (i < manager->size && manager->pdus[i].timestamp < threshold) {
        i++;
    }
    if (i > 0) {
        memmove(manager->pdus, &manager->pdus[i], (manager->size - i) * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        manager->size -= i;
    }
    pthread_rwlock_unlock(&manager->lock);
}

void clear_old_pdus(PDU_Manager *manager, time_t threshold) {
    pthread_rwlock_wrlock(&manager->lock);
    size_t i = 0;
    while (i < manager->size && manager->pdus[i].timestamp < threshold) {
        i++;
    }
    if (i > 0) {
        memmove(manager->pdus, &manager->pdus[i], (manager->size - i) * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        manager->size -= i;
        for (size_t j = 0; j < manager->size; j++) {
            manager->pdus[j].sequence_number -= i;
        }
    }
    pthread_rwlock_unlock(&manager->lock);
}

size_t get_pdu_count(PDU_Manager *manager) {
    size_t count;
    pthread_rwlock_rdlock(&manager->lock);
    count = manager->size;
    pthread_rwlock_unlock(&manager->lock);
    return count;
}

time_t get_oldest_timestamp(PDU_Manager *manager) {
    time_t timestamp;
    pthread_rwlock_rdlock(&manager->lock);
    if (manager->size > 0) {
        timestamp = manager->pdus[0].timestamp;
    } else {
        timestamp = 0; // or some error value
    }
    pthread_rwlock_unlock(&manager->lock);
    return timestamp;
}

int get_highest_sequence_number(PDU_Manager *manager) {
