### Java Code for `countDisjointPairs`

```java
import java.util.Arrays;

public class DisjointPairCounter {

    public static int countDisjointPairs(int[] array) {
        if (array == null || array.length <= 1) {
            return 0;
        }

        UnionFind uf = new UnionFind(array.length);
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!uf.find(array[i], array[j])) {
                    uf.union(array[i], array[j]);
                }
            }
        }

        return uf.countDisjointSets();
    }

    static class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public boolean find(int x, int y) {
            return findParent(x) == findParent(y);
        }

        public void union(int x, int y) {
            int rootX = findParent(x);
            int rootY = findParent(y);

            if (rootX != rootY) {
                if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
        }

        private int findParent(int x) {
            if (parent[x] != x) {
                parent[x] = findParent(parent[x]);
            }
            return parent[x];
        }

        public int countDisjointSets() {
            int count = 0;
            for (int i = 0; i < parent.length; i++) {
                if (parent[i] == i) {
                    count++;
                }
            }
            return count;
        }
    }

    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5};
        long startTime = System.currentTimeMillis();
        int result = countDisjointPairs(array);
        long endTime = System.currentTimeMillis();

        System.out.println("Number of disjoint pairs: " + result);
        System.out.println("Time taken to compute the count: " + (endTime - startTime) + " ms");
    }
}
```

