#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct node {
    Record data;
    struct node* next;
} Node;

typedef struct entry {
    Record key;
    Node* list_head;
    pthread_mutex_t lock;
} Entry;

typedef struct hash_table {
    Entry** entries;
    size_t size;
    pthread_mutex_t global_lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->entries = (Entry**)calloc(size, sizeof(Entry*));
    if (!table->entries) {
        free(table);
        return NULL;
    }
    table->size = size;
    pthread_mutex_init(&table->global_lock, NULL);
    for (size_t i = 0; i < size; ++i) {
        table->entries[i] = (Entry*)malloc(sizeof(Entry));
        if (!table->entries[i]) {
            for (size_t j = 0; j < i; ++j) free(table->entries[j]);
            free(table->entries);
            free(table);
            return NULL;
        }
        pthread_mutex_init(&table->entries[i]->lock, NULL);
    }
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->entries[i]->list_head;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&table->entries[i]->lock);
        free(table->entries[i]);
    }
    free(table->entries);
    pthread_mutex_destroy(&table->global_lock);
    free(table);
}

void insert_record(HashTable* table, Record record) {
    size_t index = hash_function(record.value, table->size); // Assume a hash function is defined
    pthread_mutex_lock(&table->global_lock);
    pthread_mutex_lock(&table->entries[index]->lock);

    Node** current = &table->entries[index]->list_head;
    while (*current && (*current)->data.value < record.value) {
        current = &(*current)->next;
    }

    if (*current && (*current)->data.value == record.value) {
        pthread_mutex_unlock(&table->entries[index]->lock);
        pthread_mutex_unlock(&table->global_lock);
        return; // Duplicate value, do not insert
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->entries[index]->lock);
        pthread_mutex_unlock(&table->global_lock);
        handle_out_of_memory(); // Assume a function to handle OOM conditions is defined
        return;
    }
    new_node->data = record;
    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&table->entries[index]->lock);
    pthread_mutex_unlock(&table->global_lock);
}

// Additional functions for linked list and array management would be implemented here
```

