typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} LinkedList;

int createNFAPICRCIndicationPDUs(LinkedList* list, int N) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < N; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        newNode->data.RX_UE_INFORMATION_TAG = rand() % 1000;
        newNode->data.RNTI = rand() % 1000;
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 1000;
        newNode->data.CRCFLAG = rand() % 2;
        newNode->prev = list->tail;
        newNode->next = NULL;
        if (list->tail) {
            list->tail->next = newNode;
        } else {
            list->head = newNode;
        }
        list->tail = newNode;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void initializeLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void finalizeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
