        if (current->data.CRC_INDICATION_REL8_TAG == CRCFLAG) {
            // Perform filtering action
        }
        current = current->next;
    }
}

void pruneInactivePackets(DynamicArray* array, int inactiveThreshold) {
    PacketNode* current = array->head;
    PacketNode* prev = NULL;
    while (current != NULL) {
        if (current->data.CRC_INDICATION_REL8_TAG == 0 && time(NULL) - current->data.RX_UE_INFORMATION_TAG > inactiveThreshold) {
            if (prev == NULL) {
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            PacketNode* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void destroyDynamicArray(DynamicArray* array) {
    PacketNode* current = array->head;
    while (current != NULL) {
        PacketNode* temp = current;
        current = current->next;
        free(temp);
    }
    free(array);
}
