        return NULL; // Handle invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < num_entries; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }

    *total_entries += num_entries;
    return array;
}

void merge_arrays(NFAPI_CRC_INDICATION_PDU_T** dest, int* dest_size, NFAPI_CRC_INDICATION_PDU_T** src, int src_size) {
    if (src_size + *dest_size > MAX_ENTRIES) {
        // Handle overflow
        return;
    }

    for (int i = 0; i < src_size; i++) {
        int found = 0;
        for (int j = 0; j < *dest_size; j++) {
            if (src[i].tag == dest[j]->tag && src[i].identifier == dest[j]->identifier) {
                found = 1;
                break;
            }
        }
        if (!found) {
            dest[*dest_size] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (dest[*dest_size]) {
                memcpy(dest[*dest_size], src[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                (*dest_size)++;
            }
        }
    }
}

void free_entries(NFAPI_CRC_INDICATION_PDU_T** array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i]);
    }
    free(array);
