#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
}

NFAPI_CRC_INDICATION_PDU_T* crc_indication_list = NULL;
int list_size = 0;
pthread_mutex_t mutex;

void* populate_crc_indications(void* arg) {
    pthread_mutex_lock(&mutex);
    // Simulate network latency and data transmission errors
    if (rand() % 10 == 0) {
        printf("Network error occurred\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    int N = rand() % 10 + 1; // Random number of elements to add
    for (int i = 0; i < N; i++) {
        if (list_size == 0) {
            list_size = 10;
            crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else if (list_size % 10 == 0) {
            list_size *= 2;
            crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_indication_list, list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        NFAPI_CRC_INDICATION_PDU_T new_entry;
        new_entry.RX_UE_INFORMATION_TAG = rand() % 1000;
        new_entry.RNTI = rand() % 1000;
        new_entry.CRC_INDICATION_REL8_TAG = rand() % 1000;
        new_entry.CRCFLAG = rand() % 2;

        crc_indication_list[list_size - 1] = new_entry;
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void verify_crc_flags() {
    int total = 0, correct = 0;
    for (int i = 0; i < list_size; i++) {
        if (crc_indication_list[i].CRCFLAG == rand() % 2) {
            correct++;
        }
        total++;
    }

    double percentage_correct = ((double)correct / total) * 100;
    printf("CRC verification: %.2f%% correct\n", percentage_correct);
}

int main() {
    pthread_t threads[10];
    srand(time(NULL));

    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, populate_crc_indications, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    verify_crc_flags();

    free(crc_indication_list);
    pthread_mutex_destroy(&mutex);

    return 0;
}
