typedef struct {
    MAC_RX_MESSAGE_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MAC_RX_BUFFER_T;

MAC_RX_BUFFER_T* mac_rx_buffer_create(size_t initial_capacity) {
    MAC_RX_BUFFER_T *buffer = (MAC_RX_BUFFER_T*)malloc(sizeof(MAC_RX_BUFFER_T));
    if (!buffer) return NULL;

    buffer->messages = (MAC_RX_MESSAGE_T*)calloc(initial_capacity, sizeof(MAC_RX_MESSAGE_T));
    if (!buffer->messages) {
        free(buffer);
        return NULL;
    }

    buffer->capacity = initial_capacity;
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);

    return buffer;
}

void mac_rx_buffer_destroy(MAC_RX_BUFFER_T *buffer) {
    if (buffer) {
        free(buffer->messages);
        pthread_mutex_destroy(&buffer->lock);
        free(buffer);
    }
}

int mac_rx_buffer_add(MAC_RX_BUFFER_T *buffer, MAC_RX_MESSAGE_T message) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->count >= buffer->capacity) {
        size_t new_capacity = buffer->capacity ? buffer->capacity * 2 : 1;
        MAC_RX_MESSAGE_T *new_messages = (MAC_RX_MESSAGE_T*)realloc(buffer->messages, new_capacity * sizeof(MAC_RX_MESSAGE_T));
        if (!new_messages) {
            pthread_mutex_unlock(&buffer->lock);
            return -1; // Allocation failure
        }
        buffer->messages = new_messages;
        buffer->capacity = new_capacity;
    }

    buffer->messages[buffer->count++] = message;

    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

size_t mac_rx_buffer_count(const MAC_RX_BUFFER_T *buffer) {
    return buffer ? buffer->count : 0;
}
