#include <string.h>
#include <pthread.h>

typedef struct PacketHeader {
    char src_ip[16];
    char dest_ip[16];
    size_t payload_size;
} PacketHeader;

typedef struct PacketArray {
    PacketHeader *headers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->headers = (PacketHeader *)malloc(initial_capacity * sizeof(PacketHeader));
    if (!array->headers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

void destroy_packet_array(PacketArray *array) {
    free(array->headers);
    pthread_mutex_destroy(&array->lock);
}

int validate_packet_header(const PacketHeader *header) {
    // Add validation logic here
    return 1; // Return 0 for invalid, 1 for valid
}

int add_packet_header(PacketArray *array, const PacketHeader *header) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        PacketHeader *new_headers = (PacketHeader *)realloc(array->headers, new_capacity * sizeof(PacketHeader));
        if (!new_headers) {
            pthread_mutex_unlock(&array->lock);
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        array->headers = new_headers;
        array->capacity = new_capacity;
    }
    if (validate_packet_header(header)) {
        memcpy(&array->headers[array->count], header, sizeof(PacketHeader));
        array->count++;
        pthread_mutex_unlock(&array->lock);
        return 0;
    } else {
        pthread_mutex_unlock(&array->lock);
        return -1; // Invalid packet header
    }
}

int remove_packet_header(PacketArray *array, size_t index) {
    pthread_mutex_lock(&array->lock);
    if (index >= array->count) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    memmove(&array->headers[index], &array->headers[index + 1], (array->count - index - 1) * sizeof(PacketHeader));
    array->count--;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void iterate_packet_array(const PacketArray *array, void (*callback)(const PacketHeader *)) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; i++) {
        callback(&array->headers[i]);
    }
    pthread_mutex_unlock(&array->lock);
}

void print_packet_header(const PacketHeader *header) {
    printf("Source IP: %s, Destination IP: %s, Payload Size: %zu\n", header->src_ip, header->dest_ip, header->payload_size);
}
