#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 1000
#define TIMEOUT_THRESHOLD 3600 // 1 hour in seconds

typedef struct {
    int user_id;
    time_t start_time;
    time_t last_active_time;
    time_t duration;
} Session;

Session sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(int user_id) {
    pthread_mutex_lock(&session_lock);
    if (session_count < MAX_SESSIONS) {
        sessions[session_count].user_id = user_id;
        sessions[session_count].start_time = time(NULL);
        sessions[session_count].last_active_time = time(NULL);
        sessions[session_count].duration = 0;
        session_count++;
    } else {
        printf("Session limit reached.\n");
    }
    pthread_mutex_unlock(&session_lock);
}

void update_session(int user_id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].user_id == user_id) {
            sessions[i].last_active_time = time(NULL);
            sessions[i].duration += difftime(sessions[i].last_active_time, sessions[i].start_time);
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void terminate_session(int user_id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].user_id == user_id) {
            sessions[i].duration += difftime(time(NULL), sessions[i].last_active_time);
            printf("Session terminated for user %d. Duration: %ld seconds\n", user_id, sessions[i].duration);
            // Log session termination event
            // ...
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void check_inactive_sessions() {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (difftime(time(NULL), sessions[i].last_active_time) > TIMEOUT_THRESHOLD) {
            terminate_session(sessions[i].user_id);
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void batch_process_sessions() {
    // Aggregate session statistics
    // ...
}

int main() {
    // Example usage
    add_session(101);
    update_session(101);
    sleep(2); // Simulate time passing
    update_session(101);
    check_inactive_sessions();
    batch_process_sessions();

    return 0;
}
