        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }
        fclose(fp);
        curl_easy_cleanup(curl);
    }

    // Check file size and other conditions
    struct stat st;
    if (stat("downloaded_resource", &st) != 0 || st.st_size > max_size) {
        remove("downloaded_resource");
        return -2;
    }

    return 0;
}

void freeDynamicPacketBundle(DynamicPacketBundle *bundle) {
    pthread_mutex_destroy(&bundle->lock);
    free(bundle->headers);
    free(bundle);
}
