typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 0.75

NFAPI_CRC_INDICATION_PDU_T** create_dynamic_array(int* capacity) {
    *capacity = INITIAL_CAPACITY;
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(*capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        // Fallback strategy: use a smaller capacity
        *capacity = 5;
        array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(*capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!array) {
            return NULL; // Resource allocation failed
        }
    }
    return array;
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T** array, int* size, int capacity, int seed) {
    srand(time(NULL) + seed);
    for (int i = 0; i < *size; i++) {
        if (i >= capacity) {
            // Resize the array
            NFAPI_CRC_INDICATION_PDU_T** new_array = create_dynamic_array(&capacity);
            if (!new_array) {
                return; // Resource allocation failed
            }
            for (int j = 0; j < *size; j++) {
                new_array[j] = array[j];
            }
            free(array);
            array = new_array;
        }
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            return; // Resource allocation failed
        }
        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rand() % 1000; // Example unique RNTI generation
        pdu->CRC_INDICATION_REL8_TAG = i;
        pdu->CRCFLAG = (rand() % 2) ? 1 : 0; // Pseudo-random CRCFLAG
        array[*size] = pdu;
        (*size)++;
    }
}

void free_array(NFAPI_CRC_INDICATION_PDU_T** array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i]);
    }
    free(array);
}

int validate_rnti_uniqueness(NFAPI_CRC_INDICATION_PDU_T** array, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (array[i]->RNTI == array[j]->RNTI) {
                // Duplicate RNTI found
                return -1;
            }
        }
    }
    return 0;
}

void resize_array(NFAPI_CRC_INDICATION_PDU_T** array, int* size, int* capacity) {
    if ((double)*size / *capacity > RESIZE_THRESHOLD) {
        NFAPI_CRC_INDICATION_PDU_T** new_array = create_dynamic_array(capacity);
        if (!new_array) {
            return; // Resource allocation failed
        }
        for (int i = 0; i < *size; i++) {
            new_array[i] = array[i];
        }
        free(array);
        array = new_array;
    }
}
