    struct UE_Session *next;
} UE_Session;

typedef struct {
    UE_Session *head;
    pthread_mutex_t lock;
} SessionList;

void init_session_list(SessionList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int add_session(SessionList *list, int ue_id, float rf_rx_power, int QoS_Class_ID) {
    pthread_mutex_lock(&list->lock);
    UE_Session *new_session = (UE_Session *)malloc(sizeof(UE_Session));
    if (!new_session) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_session->ue_id = ue_id;
    new_session->rf_rx_power = rf_rx_power;
    new_session->QoS_Class_ID = QoS_Class_ID;
    new_session->avg_rf_rx_power = 0.0f;
    new_session->next = list->head;
    list->head = new_session;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void calculate_avg_rf_rx_power(SessionList *list) {
    pthread_mutex_lock(&list->lock);
    UE_Session *current = list->head;
    while (current != NULL) {
        current->avg_rf_rx_power = current->rf_rx_power; // Simplified for example
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_session_list(SessionList *list) {
    pthread_mutex_lock(&list->lock);
    UE_Session *current = list->head;
    while (current != NULL) {
        UE_Session *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}
