void populate_packet_buffer() {
    for (int i = 0; i < MAX_PACKETS; i++) {
        packet_buffer[i].rnti = i % 256; // Simulate RNTI values
        packet_buffer[i].crc_flag = (i % 2 == 0) ? 1 : 0; // Alternate valid and invalid CRC flags
    }
