void* process_packets(void* arg) {
    for (int i = 0; i < MAX_PACKETS; i++) {
        pthread_mutex_lock(&mutex);
        if (packet_buffer[i].crc_flag == 1 && packet_buffer[i].rnti > largest_valid_rnti) {
            largest_valid_rnti = packet_buffer[i].rnti;
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

