#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RNTI;
    uint8_t CRCFLAG;
    uint32_t unique_id;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N, int min_rnti, int max_rnti) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL;
    uint16_t last_rnti = 0;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            return head;
        }

        do {
            new_node->RNTI = rand() % (max_rnti - min_rnti + 1) + min_rnti;
        } while (new_node->RNTI == last_rnti);

        last_rnti = new_node->RNTI;
        new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        new_node->unique_id = (new_node->RNTI << 8) | new_node->CRCFLAG;

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }

        if (i % 1024 == 0 && i != 0) {
            // Dynamically allocate memory for the next chunk
            NFAPI_CRC_INDICATION_PDU_T *temp = head;
            while (temp->next) temp = temp->next;
            temp->next = NULL; // Break the current list
            new_node->next = head;
            head = new_node;
        }
    }

    return head;
}
