} EventType;

typedef struct {
    int ue_id;
    int sequence_number;
    EventType status_flag;
} NetworkEvent;

NetworkEvent* network_event_list[MAX_EVENTS];
int event_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initialize_network_events(int list_size, int max_ue_id) {
    if (list_size > MAX_EVENTS || list_size <= 0) {
        fprintf(stderr, "Invalid list size\n");
        return -1;
    }

    for (int i = 0; i < list_size; i++) {
        NetworkEvent* event = malloc(sizeof(NetworkEvent));
        if (!event) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        event->ue_id = rand() % max_ue_id + 1;
        event->sequence_number = i + 1;
        event->status_flag = (EventType)(rand() % (EVENT_TYPE_C + 1));
        network_event_list[i] = event;
    }

    pthread_mutex_lock(&mutex);
    event_count = list_size;
    pthread_mutex_unlock(&mutex);

    return 0;
}

void free_network_events() {
    for (int i = 0; i < event_count; i++) {
        free(network_event_list[i]);
    }
    event_count = 0;
}

void* thread_function(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < event_count) {
        NetworkEvent* event = network_event_list[index];
        printf("Thread %d: UE ID = %d, Sequence Number = %d, Status Flag = %d\n",
               index, event->ue_id, event->sequence_number, event->status_flag);
    } else {
        fprintf(stderr, "Invalid index for thread %d\n", index);
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    int list_size = 500;
    int max_ue_id = 100;

    if (initialize_network_events(list_size, max_ue_id) != 0) {
        fprintf(stderr, "Failed to initialize network events\n");
        return -1;
    }

    pthread_t threads[list_size];
    int indices[list_size];

    for (int i = 0; i < list_size; i++) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &indices[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return -1;
        }
    }

    for (int i = 0; i < list_size; i++) {
        pthread_join(threads[i], NULL);
    }

    free_network_events();

    return 0;
}
