// Function to generate a unique identifier based on RNTI and CRCFLAG
uint64_t GenerateUniqueId(uint16_t rnti, bool crcflag) {
    return (static_cast<uint64_t>(rnti) << 1) | static_cast<uint64_t>(crcflag);
}

// Function to check if two consecutive structures have the same RNTI
bool CheckConsecutiveRNTIs(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& list, size_t index) {
    if (index == 0 || index >= list.size() - 1) return false;
    return list[index].RNTI == list[index + 1].RNTI;
}

// Function to ensure RNTI values are within the specified range
bool ValidateRNTI(uint16_t rnti, uint16_t min_rnti, uint16_t max_rnti) {
    return rnti >= min_rnti && rnti <= max_rnti;
}

// Function to generate a random RNTI value within the specified range
uint16_t GenerateRandomRNTI(uint16_t min_rnti, uint16_t max_rnti) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min_rnti, max_rnti);
    return dis(gen);
}

// Function to add a new structure to the linked list
void AddToLinkedList(std::vector<NFAPI_CRC_INDICATION_PDU_T>& list, uint16_t min_rnti, uint16_t max_rnti) {
    static std::unordered_map<uint64_t, bool> used_ids;
    static std::mutex mtx;
    static std::condition_variable cv;

    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, []{ return list.size() < 1024; });

    uint16_t rnti;
    do {
        rnti = GenerateRandomRNTI(min_rnti, max_rnti);
    } while (CheckConsecutiveRNTIs(list, list.size()) || used_ids.find(GenerateUniqueId(rnti, true)) != used_ids.end());

