    new_pdu.RNTI = rnti;
    new_pdu.CRCFLAG = true; // Randomly set CRCFLAG

    used_ids[GenerateUniqueId(rnti, new_pdu.CRCFLAG)] = true;
    list.push_back(new_pdu);

    cv.notify_one();
