typedef enum { SUCCESS, FAILURE } TransactionStatus;

typedef struct {
    int id;
    char username[50];
    double amount;
    time_t timestamp;
    TransactionStatus status;
} Transaction;

typedef struct Node {
    Transaction data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} TransactionList;

void initTransactionList(TransactionList* list) {
    list->head = NULL;
    list->count = 0;
}

Node* createNode(const Transaction* transaction) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    memcpy(&newNode->data, transaction, sizeof(Transaction));
    newNode->next = NULL;
    return newNode;
}

void addTransaction(TransactionList* list, const Transaction* transaction) {
    Node* newNode = createNode(transaction);
    if (newNode == NULL) {
        return; // Handle memory allocation failure
    }
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

void updateTransaction(TransactionList* list, int id, const Transaction* newTransaction) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.id == id) {
            memcpy(&current->data, newTransaction, sizeof(Transaction));
            return;
        }
        current = current->next;
    }
}

double calculateTotalAmount(const TransactionList* list) {
    double total = 0.0;
    Node* current = list->head;
    while (current != NULL) {
        total += current->data.amount;
        current = current->next;
    }
    return total;
}

Node* filterTransactionsByUserAndTimeRange(const TransactionList* list, const char* username, time_t startTime, time_t endTime) {
    Node* filteredHead = NULL;
    Node** tail = &filteredHead;
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->data.username, username) == 0 && current->data.timestamp >= startTime && current->data.timestamp <= endTime) {
            *tail = createNode(&current->data);
            if (*tail == NULL) {
                return filteredHead; // Handle memory allocation failure
            }
            tail = &(*tail)->next;
        }
        current = current->next;
    }
    *tail = NULL;
    return filteredHead;
}

void freeTransactionList(TransactionList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}
