function assembleBuffer(chunks, startOffsets, maxBytes) {
    let totalBytes = 0;
    const resultBuffer = Buffer.alloc(maxBytes);

    for (let i = 0; i < chunks.length && totalBytes < maxBytes; i++) {
        const chunk = chunks[i];
        const startOffset = startOffsets[i] || 0;
        const bytesToCopy = Math.min(chunk.length - startOffset, maxBytes - totalBytes);

        if (bytesToCopy > 0) {
            chunk.copy(resultBuffer, totalBytes, startOffset, startOffset + bytesToCopy);
            totalBytes += bytesToCopy;
        }
    }

    return resultBuffer.slice(0, totalBytes);
}
