typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T *nfaapi_crc_pool_init(size_t initial_size) {
    NFAPI_CRC_POOL_T *pool = (NFAPI_CRC_POOL_T *)malloc(sizeof(NFAPI_CRC_POOL_T));
    if (!pool) return NULL;

    pool->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->array) {
        free(pool);
        return NULL;
    }

    pool->allocated_size = initial_size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void nfaapi_crc_pool_free(NFAPI_CRC_POOL_T *pool) {
    if (pool) {
        free(pool->array);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_get(NFAPI_CRC_POOL_T *pool, size_t N) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_size + N > pool->allocated_size) {
        size_t new_size = pool->allocated_size ? pool->allocated_size * 2 : 1;
        while (new_size < pool->used_size + N) new_size *= 2;

        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        pool->array = new_array;
        pool->allocated_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = &pool->array[pool->used_size];
    for (size_t i = 0; i < N; ++i) {
        result[i].RX_UE_INFORMATION_TAG = rand();
        result[i].RNTI = rand();
        result[i].CRC_INDICATION_REL8_TAG = rand();
        result[i].CRCFLAG = rand() % 2;
    }

    pool->used_size += N;

    pthread_mutex_unlock(&pool->lock);
    return result;
}

void nfaapi_crc_release(NFAPI_CRC_POOL_T *pool, size_t N) {
    pthread_mutex_lock(&pool->lock);

    if (N > pool->used_size) {
        pthread_mutex_unlock(&pool->lock);
        return; // Error: Trying to release more than used
    }

    pool->used_size -= N;

    pthread_mutex_unlock(&pool->lock);
}
