class NetworkEvent {
    long timestamp;
    String sourceIP;
    String eventType;
    int payloadSize;
}

public class NetworkAnomalyDetector {

    private ConcurrentHashMap<String, EventWindow> eventWindows = new ConcurrentHashMap<>();
    private AtomicInteger totalEventsProcessed = new AtomicInteger(0);
    private long timeWindow = 60000; // Default time window in milliseconds (1 minute)
    private double bandwidthThreshold = 1000000; // Default bandwidth threshold in bytes

    public void processEvent(NetworkEvent event) {
        String sourceIP = event.sourceIP;
        EventWindow window = eventWindows.computeIfAbsent(sourceIP, k -> new EventWindow(timeWindow));

        if (window.canAccept(event)) {
            window.addEvent(event);
            totalEventsProcessed.incrementAndGet();
        }
    }

    public List<String> getTopThreeActiveSources() {
        List<EventWindow> windows = new ArrayList<>(eventWindows.values());
        windows.sort(Comparator.comparingInt(EventWindow::getTotalVolume).reversed());

        List<String> topSources = new ArrayList<>();
        for (int i = 0; i < Math.min(windows.size(), 3); i++) {
            topSources.add(windows.get(i).getSourceIP());
        }

        return topSources;
    }

    public void adjustTimeWindow(double averageBandwidth) {
        if (averageBandwidth > bandwidthThreshold * 2) {
            timeWindow *= 1.5; // Increase time window for higher bandwidth
        } else if (averageBandwidth < bandwidthThreshold / 2) {
            timeWindow /= 1.5; // Decrease time window for lower bandwidth
        }
    }

    private static class EventWindow {
        private long startTime;
        private int eventCount = 0;
        private int totalVolume = 0;

        public EventWindow(long timeWindow) {
            this.startTime = System.currentTimeMillis();
        }

        public boolean canAccept(NetworkEvent event) {
            return (System.currentTimeMillis() - startTime) < timeWindow && totalVolume + event.payloadSize <= bandwidthThreshold;
        }

        public void addEvent(NetworkEvent event) {
            eventCount++;
            totalVolume += event.payloadSize;
        }

        public String getSourceIP() {
            return "Source IP"; // Replace with actual source IP retrieval logic
        }

        public int getTotalVolume() {
            return totalVolume;
        }
    }
}
