    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_LIST_NODE_T {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct NFAPI_CRC_LIST_NODE_T *next;
} NFAPI_CRC_LIST_NODE_T;

typedef struct NFAPI_CRC_LIBRARY_T {
    NFAPI_CRC_LIST_NODE_T *head;
    pthread_mutex_t lock;
} NFAPI_CRC_LIBRARY_T;

NFAPI_CRC_LIBRARY_T* nfapi_crc_library_init() {
    NFAPI_CRC_LIBRARY_T *library = (NFAPI_CRC_LIBRARY_T*)malloc(sizeof(NFAPI_CRC_LIBRARY_T));
    if (!library) return NULL;
    library->head = NULL;
    pthread_mutex_init(&library->lock, NULL);
    return library;
}

void nfapi_crc_library_add(NFAPI_CRC_LIBRARY_T *library, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&library->lock);
    NFAPI_CRC_LIST_NODE_T *new_node = (NFAPI_CRC_LIST_NODE_T*)malloc(sizeof(NFAPI_CRC_LIST_NODE_T));
    if (!new_node) {
        pthread_mutex_unlock(&library->lock);
        return;
    }
    new_node->pdu = pdu;
    new_node->next = library->head;
    library->head = new_node;
    pthread_mutex_unlock(&library->lock);
}

void nfapi_crc_library_remove(NFAPI_CRC_LIBRARY_T *library, RX_UE_INFORMATION_TAG ue_info_tag) {
    pthread_mutex_lock(&library->lock);
    NFAPI_CRC_LIST_NODE_T *current = library->head;
    NFAPI_CRC_LIST_NODE_T *prev = NULL;
    while (current != NULL) {
        if (current->pdu.ue_info_tag == ue_info_tag) {
            if (prev == NULL) {
                library->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&library->lock);
}

void nfapi_crc_library_iterate(NFAPI_CRC_LIBRARY_T *library, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&library->lock);
    NFAPI_CRC_LIST_NODE_T *current = library->head;
    while (current != NULL) {
        callback(current->pdu);
        current = current->next;
    }
    pthread_mutex_unlock(&library->lock);
}

void nfapi_crc_library_free(NFAPI_CRC_LIBRARY_T *library) {
    pthread_mutex_lock(&library->lock);
    NFAPI_CRC_LIST_NODE_T *current = library->head;
    while (current != NULL) {
        NFAPI_CRC_LIST_NODE_T *next = current->next;
        free(current);
        current = next;
    }
    library->head = NULL;
    pthread_mutex_unlock(&library->lock);
