#define MAX_LIST_SIZE 1024

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    size_t count;
    size_t capacity;
} NFAPI_CRC_INDICATION_LIST_T;

void initialize_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->count = 0;
    list->capacity = MAX_LIST_SIZE;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(RX_UE_INFORMATION_TAG rx_ue_info_tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->rx_ue_info_tag = rx_ue_info_tag;
    pdu->rnti = rnti;

    // Generate CRCFLAG based on cryptographic hash
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)&rx_ue_info_tag, sizeof(rx_ue_info_tag), hash);
    MD5((unsigned char*)&rnti, sizeof(rnti), hash + MD5_DIGEST_LENGTH / 2);
    pdu->crc_indication_rel8_tag.CRCFLAG = *(int*)hash;

    return pdu;
}

void add_to_list(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (list->count >= list->capacity) {
        // Reset the list to reuse memory
        for (size_t i = 0; i < list->count; ++i) {
            free(list->list[i]);
        }
        list->count = 0;
    }

    list->list[list->count++] = pdu;
}

void log_creation(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Asynchronous logging or buffered writes
    printf("Created CRC Indication PDU with RX_UE_INFO_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
