        NFAPI_CRC_INDICATION_PDU_T *pdu = list->list[i];
        log_creation(pdu);
        // Process each PDU
    }
}

void free_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->list[i]);
    }
