        if (memory_pool.memory == NULL || memory_pool.size < N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            free(memory_pool.memory);
            memory_pool.memory = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memory_pool.size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
        pthread_mutex_unlock(&memory_pool.lock);
