#define MAX_SESSIONS 10000

typedef struct {
    int client_id;
    time_t request_timestamp;
    char *data_buffer;
    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
} SessionContext;

SessionContext session_pool[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t pool_lock;

void initialize_session_pool() {
    pthread_mutex_init(&pool_lock, NULL);
}

int allocate_session(int client_id) {
    pthread_mutex_lock(&pool_lock);
    if (session_count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&pool_lock);
        return -1; // Pool is full
    }
    for (int i = 0; i < session_count; i++) {
        if (session_pool[i].client_id == client_id) {
            pthread_mutex_unlock(&pool_lock);
            return -2; // Duplicate client ID
        }
    }
    session_pool[session_count].client_id = client_id;
    session_pool[session_count].request_timestamp = time(NULL);
    session_pool[session_count].data_buffer = (char *)malloc(1024); // Example buffer size
    memset(session_pool[session_count].data_buffer, 0, 1024);
    generate_crc_pdu(&session_pool[session_count].crc_pdu);
    session_count++;
    pthread_mutex_unlock(&pool_lock);
    return session_count - 1;
}

void deallocate_session(int client_id) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < session_count; i++) {
        if (session_pool[i].client_id == client_id) {
            free(session_pool[i].data_buffer);
            memmove(&session_pool[i], &session_pool[i + 1], sizeof(SessionContext) * (session_count - i - 1));
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
