        printf("DEBUG: %s\n", message);
    } else if (level == LOG_ERROR) {
        fprintf(stderr, "ERROR: %s\n", message);
    }
}

int main() {
    initialize_session_pool();
    srand(time(NULL)); // Seed for random number generation

    int client_id = 12345;
    int session_index = allocate_session(client_id);
    if (session_index == -1) {
