#include <pthread.h>

typedef struct {
    time_t timestamp;
    char* event_type;
    char* message;
} NetworkEventLogEntry;

typedef struct {
    NetworkEventLogEntry** entries;
    size_t capacity;
    size_t count;
    size_t max_message_length;
    size_t daily_event_quota;
    pthread_mutex_t lock;
} EventLogger;

EventLogger* create_logger(size_t initial_capacity, size_t max_message_length, size_t daily_event_quota) {
    EventLogger* logger = (EventLogger*)malloc(sizeof(EventLogger));
    if (!logger) return NULL;

    logger->entries = (NetworkEventLogEntry**)malloc(initial_capacity * sizeof(NetworkEventLogEntry*));
    if (!logger->entries) {
        free(logger);
        return NULL;
    }

    logger->capacity = initial_capacity;
    logger->count = 0;
    logger->max_message_length = max_message_length;
    logger->daily_event_quota = daily_event_quota;
    pthread_mutex_init(&logger->lock, NULL);

    return logger;
}

void destroy_logger(EventLogger* logger) {
    for (size_t i = 0; i < logger->count; ++i) {
        free(logger->entries[i]->event_type);
        free(logger->entries[i]->message);
        free(logger->entries[i]);
    }
    free(logger->entries);
    pthread_mutex_destroy(&logger->lock);
    free(logger);
}

int log_event(EventLogger* logger, const char* event_type, const char* message) {
    pthread_mutex_lock(&logger->lock);

    if (logger->count >= logger->daily_event_quota) {
        pthread_mutex_unlock(&logger->lock);
        return -1; // Daily quota exceeded
    }

    if (logger->count == logger->capacity) {
        size_t new_capacity = logger->capacity * 2;
        NetworkEventLogEntry** new_entries = (NetworkEventLogEntry**)realloc(logger->entries, new_capacity * sizeof(NetworkEventLogEntry*));
        if (!new_entries) {
            pthread_mutex_unlock(&logger->lock);
            return -1; // Memory allocation failed
        }
        logger->entries = new_entries;
        logger->capacity = new_capacity;
    }

    NetworkEventLogEntry* entry = (NetworkEventLogEntry*)malloc(sizeof(NetworkEventLogEntry));
    if (!entry) {
        pthread_mutex_unlock(&logger->lock);
        return -1; // Memory allocation failed
    }

    entry->timestamp = time(NULL);
    entry->event_type = strdup(event_type);
    entry->message = strndup(message, logger->max_message_length);

    logger->entries[logger->count++] = entry;

    pthread_mutex_unlock(&logger->lock);
    return 0;
}
