#include <stdlib.h>
#include <pthread.h>

#define MAX_POOL_SIZE 1024

typedef struct LTE_RRC_CapabilityInformationItem_t {
    lte_rrc_cell_t cell;
    lte_rrc_rach_cfg_t rach_cfg;
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} LTE_RRC_CapabilityInformationItem;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PoolNode {
    LTE_RRC_CapabilityInformationItem item;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PoolNode* next;
} PoolNode;

typedef struct {
    PoolNode* head;
    PoolNode* tail;
    int size;
    pthread_mutex_t mutex;
} Pool;

Pool* create_pool() {
    Pool* pool = (Pool*)malloc(sizeof(Pool));
    if (!pool) return NULL;
    pool->head = pool->tail = NULL;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

int insert_item(Pool* pool, LTE_RRC_CapabilityInformationItem item, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pool->mutex);
    PoolNode* new_node = (PoolNode*)malloc(sizeof(PoolNode));
    if (!new_node) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Memory allocation failed
    }
    new_node->item = item;
    new_node->pdu = pdu;
    new_node->next = NULL;

    if (pool->tail) {
        pool->tail->next = new_node;
    } else {
        pool->head = new_node;
    }
    pool->tail = new_node;
    pool->size++;
    pthread_mutex_unlock(&pool->mutex);
    return 0; // Success
}

LTE_RRC_CapabilityInformationItem* get_item(Pool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (!pool->head) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL; // Pool is empty
    }
    LTE_RRC_CapabilityInformationItem* item = &pool->head->item;
    PoolNode* temp = pool->head;
    pool->head = pool->head->next;
    if (!pool->head) {
        pool->tail = NULL;
    }
    free(temp);
    pool->size--;
    pthread_mutex_unlock(&pool->mutex);
    return item;
}

void destroy_pool(Pool* pool) {
    pthread_mutex_lock(&pool->mutex);
    PoolNode* current = pool->head;
    while (current) {
        PoolNode* next = current->next;
        free(current);
        current = next;
    }
    pool->head = pool->tail = NULL;
    pool->size = 0;
    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}
