#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int PDU_TYPE;
    TX_PDU_T *tx_pdu_array;
    int tx_pdu_count;
} NFAPI_MESSAGE_T;

typedef struct {
    // Define the structure for TX_PDU_T
} TX_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *crc_indication_list[MAX_STRUCTURES];
int crc_indication_count = 0;
pthread_mutex_t crc_indication_lock;

NFAPI_MESSAGE_T message_array[MAX_STRUCTURES];
int message_count = 0;
pthread_mutex_t message_lock;

int add_crc_indication(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&crc_indication_lock);
    if (crc_indication_count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&crc_indication_lock);
        return -1; // Error: Maximum structures reached
    }
    NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        pthread_mutex_unlock(&crc_indication_lock);
        return -2; // Error: Memory allocation failed
    }
    new_struct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_struct->RNTI = RNTI;
    new_struct->CRCFLAG = CRCFLAG;
    crc_indication_list[crc_indication_count++] = new_struct;
    pthread_mutex_unlock(&crc_indication_lock);
    return 0; // Success
}

int add_message(int PDU_TYPE, int payload_size) {
    pthread_mutex_lock(&message_lock);
    if (message_count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&message_lock);
        return -1; // Error: Maximum structures reached
    }
    NFAPI_MESSAGE_T *new_struct = malloc(sizeof(NFAPI_MESSAGE_T));
    if (!new_struct) {
        pthread_mutex_unlock(&message_lock);
        return -2; // Error: Memory allocation failed
    }
    new_struct->PDU_TYPE = PDU_TYPE;
    new_struct->tx_pdu_array = malloc(payload_size * sizeof(TX_PDU_T));
    if (!new_struct->tx_pdu_array) {
        free(new_struct);
        pthread_mutex_unlock(&message_lock);
        return -3; // Error: Memory allocation failed
    }
    new_struct->tx_pdu_count = payload_size;
    message_array[message_count++] = *new_struct;
    pthread_mutex_unlock(&message_lock);
    return 0; // Success
}

int export_to_binary_file(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return -1; // Error: Failed to open file
    }
    fwrite(crc_indication_list, sizeof(NFAPI_CRC_INDICATION_PDU_T *), crc_indication_count, file);
    fwrite(message_array, sizeof(NFAPI_MESSAGE_T), message_count, file);
    fclose(file);
    return 0; // Success
}

int main() {
    // Example usage
    if (add_crc_indication(12345, 67890, 1) != 0) {
        printf("Failed to add CRC indication\n");
    }
    if (add_message(1, MAX_PAYLOAD_SIZE) != 0) {
        printf("Failed to add message\n");
    }
    if (export_to_binary_file("output.bin") != 0) {
        printf("Failed to export data to binary file\n");
    }
    return 0;
}
