    int status_code;
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD *records = NULL;
int record_count = 0;

void free_records() {
    if (records != NULL) {
        free(records);
        records = NULL;
        record_count = 0;
    }
}

int validate_connection_id(int id) {
    // Implement validation logic for CONNECTION_ID
    return id >= 1 && id <= 9999999; // Example range
}

int validate_ip(const char *ip) {
    // Implement validation logic for IP addresses
    return strlen(ip) == MAX_IP_LENGTH - 1; // Example length check
}

void populate_record(int connection_id, const char *source_ip, const char *destination_ip, long bytes_transferred, int status_code) {
    if (record_count >= MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records reached.\n");
        return;
    }

    if (!validate_connection_id(connection_id)) {
        fprintf(stderr, "Error: Invalid CONNECTION_ID.\n");
        return;
    }

    if (!validate_ip(source_ip) || !validate_ip(destination_ip)) {
        fprintf(stderr, "Error: Invalid IP address.\n");
        return;
    }

    records[record_count].connection_id = connection_id;
    strcpy(records[record_count].source_ip, source_ip);
    strcpy(records[record_count].destination_ip, destination_ip);
    records[record_count].bytes_transferred = bytes_transferred;
    records[record_count].status_code = status_code;

    record_count++;
}

void export_to_csv(const char *filename) {
