    for (int i = 0; i < record_count; i++) {
        fprintf(file, "%d,%s,%s,%ld,%d\n",
                records[i].connection_id,
                records[i].source_ip,
                records[i].destination_ip,
                records[i].bytes_transferred,
                records[i].status_code);
    }

    fclose(file);
}

int main() {
    // Initialize memory for records
    records = (TCP_CONNECTION_RECORD *)malloc(MAX_RECORDS * sizeof(TCP_CONNECTION_RECORD));
    if (records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return 1;
    }

    // Example usage of the function
