    // Define the structure fields here
} LTE_RRC_Scell_t;

typedef struct LTE_RRC_ConfigurationArray_t {
    LTE_RRC_ConfigurationItem_t** items;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} LTE_RRC_ConfigurationArray_t;

LTE_RRC_ConfigurationArray_t* lte_rrc_config_array_create(size_t initial_capacity) {
    LTE_RRC_ConfigurationArray_t* array = (LTE_RRC_ConfigurationArray_t*)malloc(sizeof(LTE_RRC_ConfigurationArray_t));
    if (!array) return NULL;

    array->items = (LTE_RRC_ConfigurationItem_t**)calloc(initial_capacity, sizeof(LTE_RRC_ConfigurationItem_t*));
    if (!array->items) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void lte_rrc_config_array_destroy(LTE_RRC_ConfigurationArray_t* array) {
    if (!array) return;

    for (size_t i = 0; i < array->size; ++i) {
        free(array->items[i]);
    }
    free(array->items);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int lte_rrc_config_array_insert(LTE_RRC_ConfigurationArray_t* array, LTE_RRC_ConfigurationItem_t* item) {
    if (!array || !item) return -1;

    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        LTE_RRC_ConfigurationItem_t** new_items = (LTE_RRC_ConfigurationItem_t**)realloc(array->items, new_capacity * sizeof(LTE_RRC_ConfigurationItem_t*));
        if (!new_items) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->items = new_items;
        array->capacity = new_capacity;
    }

    array->items[array->size++] = item;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

LTE_RRC_ConfigurationItem_t* lte_rrc_config_array_get(LTE_RRC_ConfigurationArray_t* array, size_t index) {
    if (!array || index >= array->size) return NULL;

    pthread_mutex_lock(&array->mutex);
    LTE_RRC_ConfigurationItem_t* item = array->items[index];
    pthread_mutex_unlock(&array->mutex);

    return item;
}
