#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char *data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node *next;
} Node;

Node* createNode(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->pdu = pdu;
    newNode->next = NULL;
    return newNode;
}

void processNfaPduList(Node** head, int numPDUs) {
    for (int i = 0; i < numPDUs; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Initialize pdu fields
        pdu.RX_UE_INFORMATION_TAG = i + 1;
        pdu.RNTI = i * 2;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 2;

        Node* newNode = createNode(pdu);
        if (*head == NULL) {
            *head = newNode;
        } else {
            Node* temp = *head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }
}

unsigned char* decryptAES(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* key, const unsigned char* iv) {
    unsigned char *plaintext = (unsigned char*)malloc(ciphertext_len);
    if (plaintext == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    AES_KEY enc_key;
    if (AES_set_decrypt_key(key, 256, &enc_key) < 0) {
        fprintf(stderr, "Failed to set decryption key\n");
        free(plaintext);
        return NULL;
    }

    int decrypted_len = 0;
    if (AES_cbc_encrypt(ciphertext, plaintext, ciphertext_len, &enc_key, iv, AES_DECRYPT) != 0) {
        fprintf(stderr, "Decryption failed\n");
        free(plaintext);
        return NULL;
    }

    // Remove padding
    int padding_length = plaintext[decrypted_len - 1];
    if (padding_length > decrypted_len || padding_length == 0) {
        fprintf(stderr, "Invalid padding length\n");
        free(plaintext);
        return NULL;
    }

    unsigned char *decrypted_text = (unsigned char*)realloc(plaintext, decrypted_len - padding_length);
    if (decrypted_text == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(plaintext);
        return NULL;
    }

    memcpy(decrypted_text, plaintext, decrypted_len - padding_length);
    free(plaintext);
    return decrypted_text;
}

