        if (decrypted_data != NULL) {
            printf("Decrypted data: %s\n", decrypted_data);
            free(decrypted_data);
        }
        temp = temp->next;
    }

    // Free linked list
    temp = head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }

    return 0;
