    Node* head = createNode((NFAPI_CRC_INDICATION_PDU_T){0, 0, 0, 0});
    Node* current = head;

    for (int i = 1; i < 10000; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {i, i * 2, rand() % 2, i * 3};
        current->next = createNode(data);
        current = current->next;
