}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

void add_to_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        size_t new_capacity = (da->capacity == 0) ? 1 : da->capacity * 2;
        da->array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        da->capacity = new_capacity;
    }
    da->array[da->size++] = item;
    pthread_mutex_unlock(&da->mutex);
}

void serialize_array(DynamicArray *da, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->size, file);
    fclose(file);
}

void deserialize_array(DynamicArray *da, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    da->size = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (da->size > da->capacity) {
        da->array = realloc(da->array, da->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        da->capacity = da->size;
    }
    fread(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->size, file);
    fclose(file);
}

void log_operation(const char *operation) {
    printf("Operation: %s\n", operation);
}
