int add_crc_record(CRC_RECORD_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T record) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= MAX_NF_API_CRC_INDICATION_PDU_T) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Array is full
    }
    array->crc_records[array->count++] = record;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

