#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LogEntry {
    int timestamp;
    int userID;
    char actionType[50];
    int resourceID;
    int status;
    struct LogEntry* next;
} LogEntry;

typedef struct LinkedList {
    LogEntry* head;
    LogEntry* tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->capacity = 10; // Initial capacity
    pthread_mutex_init(&list->lock, NULL);
}

void addLogEntry(LinkedList* list, LogEntry* entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity * 0.75) {
        // Resize logic here
    }
    if (list->head == NULL) {
        list->head = entry;
        list->tail = entry;
    } else {
        list->tail->next = entry;
        list->tail = entry;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void updateLogEntry(LinkedList* list, int userID, LogEntry* newEntry) {
    pthread_mutex_lock(&list->lock);
    LogEntry* current = list->head;
    while (current != NULL) {
        if (current->userID == userID) {
            *current = *newEntry; // Update the entry
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void deleteLogEntry(LinkedList* list, int userID) {
    pthread_mutex_lock(&list->lock);
    LogEntry* current = list->head;
    LogEntry* prev = NULL;
    while (current != NULL) {
        if (current->userID == userID) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterateLogEntries(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    LogEntry* current = list->head;
    while (current != NULL) {
        // Process each log entry
        printf("Timestamp: %d, UserID: %d, Action Type: %s, Resource ID: %d, Status: %d\n",
               current->timestamp, current->userID, current->actionType,
               current->resourceID, current->status);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void filterLogEntries(LinkedList* list, int userID) {
    pthread_mutex_lock(&list->lock);
    LogEntry* current = list->head;
    while (current != NULL) {
        if (current->userID == userID) {
            // Process filtered log entry
            printf("Filtered Entry: Timestamp: %d, UserID: %d, Action Type: %s, Resource ID: %d, Status: %d\n",
                   current->timestamp, current->userID, current->actionType,
                   current->resourceID, current->status);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroyLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    LogEntry* current = list->head;
    while (current != NULL) {
        LogEntry* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
