    if (list->head) {
        *data = &list->head->data;
    } else {
        *data = NULL;
    }
    pthread_mutex_unlock(&list->lock);
}

void reset_list(List* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}
