#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct record {
    int value;
} Record;

typedef struct hash_entry {
    int key;
    Record *record;
    struct hash_entry *next;
} HashEntry;

typedef struct hash_table {
    HashEntry **buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = size;
    table->buckets = (HashEntry**)calloc(size, sizeof(HashEntry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashEntry *entry = table->buckets[i];
        while (entry) {
            HashEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(int key, size_t size) {
    return abs(key) % size;
}

int insert_record(HashTable *table, int key, int value_range_start, int value_range_end) {
    pthread_mutex_lock(&table->lock);

    HashEntry *entry = (HashEntry*)malloc(sizeof(HashEntry));
    if (!entry) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failure
    }

    entry->key = key;
    entry->record = (Record*)malloc(sizeof(Record));
    if (!entry->record) {
        free(entry);
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failure
    }
    entry->record->value = rand() % (value_range_end - value_range_start + 1) + value_range_start;

    size_t index = hash_function(key, table->size);
    entry->next = table->buckets[index];
    table->buckets[index] = entry;

    pthread_mutex_unlock(&table->lock);
    return 0; // Success
}

int main() {
    srand(time(NULL));

    HashTable *table = create_hash_table(MAX_ENTRIES);
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return EXIT_FAILURE;
    }

    int offsets[] = {100, 200, 300};
    int keys[] = {50, 150, 250};

    for (size_t i = 0; i < sizeof(offsets) / sizeof(offsets[0]); ++i) {
        if (insert_record(table, keys[i], -100, 100) != 0) {
            fprintf(stderr, "Failed to insert record with key %d\n", keys[i]);
        }
    }

    destroy_hash_table(table);
    return EXIT_SUCCESS;
}
