#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initializeLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Fallback strategy: retry allocation
        newNode = (Node*)realloc(NULL, sizeof(Node));
        if (newNode == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void verifyLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* temp = list->head;
    while (temp != NULL) {
        if (temp->data.RX_UE_INFORMATION_TAG == 0 || temp->data.RNTI == 0 || temp->data.CRC_INDICATION_REL8_TAG == 0 || temp->data.CRCFLAG == 0) {
            fprintf(stderr, "Verification failed: Node not properly initialized\n");
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}
