#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_length;
} NetworkPacket;

NetworkPacket* packet_array = NULL;
size_t array_size = 0;
size_t used_size = 0;

void initialize_packet_array(size_t initial_size) {
    packet_array = (NetworkPacket*)malloc(initial_size * sizeof(NetworkPacket));
    if (packet_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array_size = initial_size;
}

void add_packet(time_t timestamp, const char* source_ip, const char* destination_ip, size_t payload_length) {
    if (used_size >= array_size) {
        size_t new_size = array_size * 2;
        NetworkPacket* new_array = (NetworkPacket*)realloc(packet_array, new_size * sizeof(NetworkPacket));
        if (new_array == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        packet_array = new_array;
        array_size = new_size;
    }
    NetworkPacket* new_packet = &packet_array[used_size++];
    new_packet->timestamp = timestamp;
    strncpy(new_packet->source_ip, source_ip, sizeof(new_packet->source_ip) - 1);
    strncpy(new_packet->destination_ip, destination_ip, sizeof(new_packet->destination_ip) - 1);
    new_packet->payload_length = payload_length;
}

void update_packet(size_t index, time_t timestamp, const char* source_ip, const char* destination_ip, size_t payload_length) {
    if (index >= used_size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    NetworkPacket* packet = &packet_array[index];
    packet->timestamp = timestamp;
    strncpy(packet->source_ip, source_ip, sizeof(packet->source_ip) - 1);
    strncpy(packet->destination_ip, destination_ip, sizeof(packet->destination_ip) - 1);
    packet->payload_length = payload_length;
}

void iterate_packets_and_calculate_total_data() {
    size_t total_data = 0;
    for (size_t i = 0; i < used_size; ++i) {
        total_data += packet_array[i].payload_length;
    }
    printf("Total data transferred: %zu bytes\n", total_data);
}

unsigned char* calculate_md5(const char* input, size_t length) {
    unsigned char* digest = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    if (digest == NULL) {
        fprintf(stderr, "Memory allocation failed for MD5 digest\n");
        return NULL;
    }
    MD5((unsigned char*)input, length, digest);
    return digest;
}

void print_md5(const unsigned char* md5_digest) {
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", md5_digest[i]);
    }
    printf("\n");
}

int main() {
    initialize_packet_array(10);
    add_packet(time(NULL), "192.168.1.1", "10.0.0.1", 1024);
    update_packet(0, time(NULL) + 1, "192.168.1.2", "10.0.0.2", 512);
    iterate_packets_and_calculate_total_data();

    const char* input_string = "Hello, world!";
    unsigned char* md5_digest = calculate_md5(input_string, strlen(input_string));
    if (md5_digest != NULL) {
        print_md5(md5_digest);
        free(md5_digest);
    }

    for (size_t i = 0; i < used_size; ++i) {
        free(&packet_array[i]);
    }
    free(packet_array);

    return 0;
}
