#include <stdio.h>
#include <dirent.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

typedef struct {
    uint16 bitsPerSample;
    uint16 samplesPerPixel;
    uint16 compressionType;
} TIFFMetadata;

NFAPI_CRC_INDICATION_PDU_T* processTIFFDirectory(const char* directoryPath, int* reportSize) {
    DIR* dir = opendir(directoryPath);
    if (!dir) {
        perror("Failed to open directory");
        return NULL;
    }

    struct dirent* entry;
    TIFFMetadata** metadataArray = (TIFFMetadata**)malloc(100 * sizeof(TIFFMetadata*));
    int count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".tif") != NULL) {
            char filePath[256];
            snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, entry->d_name);

            TIFF* tif = TIFFOpen(filePath, "r");
            if (!tif) {
                fprintf(stderr, "Failed to open file: %s\n", filePath);
                continue;
            }

            uint16 bitsPerSample, samplesPerPixel, compressionType;
            TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
            TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
            TIFFGetField(tif, TIFFTAG_COMPRESSION, &compressionType);

            if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
                fprintf(stderr, "Unsupported bits per sample: %d in file %s\n", bitsPerSample, filePath);
                TIFFClose(tif);
                continue;
            }

            TIFFMetadata* metadata = (TIFFMetadata*)malloc(sizeof(TIFFMetadata));
            metadata->bitsPerSample = bitsPerSample;
            metadata->samplesPerPixel = samplesPerPixel;
            metadata->compressionType = compressionType;

            metadataArray[count++] = metadata;

            if (count >= 100) {
                metadataArray = (TIFFMetadata**)realloc(metadataArray, (count + 50) * sizeof(TIFFMetadata*));
            }

            TIFFClose(tif);
        }
    }

    closedir(dir);

    NFAPI_CRC_INDICATION_PDU_T* report = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < count; i++) {
        report[i].bitsPerSample = metadataArray[i]->bitsPerSample;
        report[i].samplesPerPixel = metadataArray[i]->samplesPerPixel;
        report[i].compressionType = metadataArray[i]->compressionType;
        free(metadataArray[i]);
    }
    free(metadataArray);

    *reportSize = count;
    return report;
}
