#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RSSI 49
#define MIN_RSSI -50
#define MAX_SNR 9
#define MIN_SNR -10
#define MAX_RNTI 1000

typedef struct {
    int rssi;
    int snr;
} RSSI_SNR;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} CRC_LIST;

void init_crc_list(CRC_LIST *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_crc_entry(CRC_LIST *list, RX_UE_INFORMATION_TAG ue_info, RNTI rnti, CRC_INDICATION_REL8_TAG crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *new_entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        fprintf(stderr, "Out of memory\n");
        return;
    }
    new_entry->ue_info = ue_info;
    new_entry->rnti = rnti;
    new_entry->crc_flag = crc_flag;
    new_entry->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_entry;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_entry;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_crc_entry(CRC_LIST *list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current != NULL) {
        if (current->rnti == rnti) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_crc_list(CRC_LIST *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        // Process each entry
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_crc_list(CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        // Serialize each entry
        fwrite(&current->ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&current->rnti, sizeof(RNTI), 1, file);
        fwrite(&current->crc_flag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserialize_crc_list(CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        // Deserialize each entry
        fread(&current->ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fread(&current->rnti, sizeof(RNTI), 1, file);
        fread(&current->crc_flag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        current = current->next;
    }

    fclose(file);
}
