NFAPI_CRC_INDICATION_PDU_T** manage_crc_indications(int* rnti_values, int n_rntis, int max_entries) {
    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T** crc_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!crc_list) {
        return NULL; // Memory allocation failed
    }

    // Initialize the list with NULL pointers
    for (int i = 0; i < max_entries; i++) {
        crc_list[i] = NULL;
    }

    // Sort RNTI values to handle duplicates efficiently
    qsort(rnti_values, n_rntis, sizeof(int), compare_ints);

    // Process each RNTI value
    for (int i = 0; i < n_rntis; i++) {
        int rnti = rnti_values[i];
        int index = find_or_allocate_index(crc_list, max_entries, rnti);
        if (index == -1) {
            // Handle memory allocation failure
            free_crl_list(crc_list, max_entries);
            return NULL;
        }

        // Populate the structure with random CRCFLAG and valid tags
        crc_list[index]->RX_UE_INFORMATION_TAG = generate_tag();
        crc_list[index]->RNTI = rnti;
        crc_list[index]->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    return crc_list;
}

int compare_ints(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

int find_or_allocate_index(NFAPI_CRC_INDICATION_PDU_T** list, int max_entries, int rnti) {
    for (int i = 0; i < max_entries; i++) {
        if (!list[i] || list[i]->RNTI == rnti) {
            return i;
        }
    }

    // Allocate new memory for the structure
    NFAPI_CRC_INDICATION_PDU_T* new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        return -1; // Memory allocation failed
    }

    list[max_entries] = new_entry;
    return max_entries;
}

int generate_tag() {
    // Generate a valid RX_UE_INFORMATION_TAG
    return rand();
}

void free_crl_list(NFAPI_CRC_INDICATION_PDU_T** list, int max_entries) {
    for (int i = 0; i < max_entries; i++) {
        if (list[i]) {
            free(list[i]);
        }
    }
    free(list);
}
