#include <stdio.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int rx_tag, int rnti, int crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, int rx_tag, int rnti, int crc_flag) {
    Node* new_node = create_node(rx_tag, rnti, crc_flag);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

int find_largest_integer(Node* head) {
    if (head == NULL) {
        fprintf(stderr, "List is empty\n");
        exit(1);
    }
    int max_value = head->data.RX_UE_INFORMATION_TAG;
    Node* current = head->next;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG > max_value) {
            max_value = current->data.RX_UE_INFORMATION_TAG;
        }
        current = current->next;
    }
    return max_value;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    Node* head = NULL;
    int rx_tag, rnti, crc_flag;

    printf("Enter integers (enter -1 to stop):\n");
    while (1) {
        scanf("%d", &rx_tag);
        if (rx_tag == -1) break;
        scanf("%d %d", &rnti, &crc_flag);
        insert_node(&head, rx_tag, rnti, crc_flag);
    }

    int largest_integer = find_largest_integer(head);
    printf("Largest integer: %d\n", largest_integer);

    free_list(head);
    return 0;
}
