#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI_ENTRIES 1000
#define MEMORY_THRESHOLD 500000 // in bytes

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_RNTI_ENTRIES];
    int count;
    pthread_mutex_t lock;
} NetworkManager;

NetworkManager network_manager;

void init_network_manager() {
    memset(&network_manager, 0, sizeof(network_manager));
    pthread_mutex_init(&network_manager.lock, NULL);
}

int add_rnti_entry(int RNTI) {
    pthread_mutex_lock(&network_manager.lock);
    if (network_manager.count >= MAX_RNTI_ENTRIES) {
        pthread_mutex_unlock(&network_manager.lock);
        return -1; // Error: Maximum entries reached
    }
    for (int i = 0; i < network_manager.count; i++) {
        if (network_manager.entries[i].RNTI == RNTI) {
            pthread_mutex_unlock(&network_manager.lock);
            return -2; // Error: Duplicate entry
        }
    }
    network_manager.entries[network_manager.count].RNTI = RNTI;
    network_manager.entries[network_manager.count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    network_manager.count++;
    pthread_mutex_unlock(&network_manager.lock);
    return 0; // Success
}

void free_network_manager() {
    pthread_mutex_destroy(&network_manager.lock);
}
