#include <stdint.h>
#include <string.h>

#define MAX_STRUCTS 10000
#define POOL_SIZE (MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T))
#define ALIGNMENT 64

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void *pool;
    size_t pool_size;
    size_t used_size;
    void *free_list;
} MemoryPool;

NFAPI_CRC_INDICATION_PDU_T* allocate_struct(MemoryPool *pool) {
    if (pool->used_size + sizeof(NFAPI_CRC_INDICATION_PDU_T) > pool->pool_size) {
        return NULL; // Out of memory
    }
    void *ptr = pool->free_list;
    if (ptr == NULL) {
        ptr = pool->pool + pool->used_size;
        pool->used_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    } else {
        pool->free_list = *(void**)ptr;
    }
    return (NFAPI_CRC_INDICATION_PDU_T*)ptr;
}

void free_struct(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *node) {
    *(void**)(node) = pool->free_list;
    pool->free_list = node;
}

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;
    pool->pool = aligned_alloc(ALIGNMENT, size);
    if (pool->pool == NULL) {
        free(pool);
        return NULL;
    }
    pool->pool_size = size;
    pool->used_size = 0;
    pool->free_list = NULL;
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    aligned_free(pool->pool);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* create_doubly_linked_list(int N, MemoryPool *pool) {
    if (N > MAX_STRUCTS) return NULL; // Exceeds maximum allowed structures
    NFAPI_CRC_INDICATION_PDU_T *head = allocate_struct(pool);
    if (head == NULL) return NULL;
    head->prev = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    for (int i = 1; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = allocate_struct(pool);
        if (new_node == NULL) {
            // Clean up allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free_struct(pool, temp);
            }
            return NULL; // Memory allocation failed
        }
        new_node->prev = current;
        current->next = new_node;
        current = new_node;
    }

    current->next = NULL;

    for (NFAPI_CRC_INDICATION_PDU_T *node = head; node != NULL; node = node->next) {
        // Populate the structure with random values
        node->RX_UE_INFORMATION_TAG = rand();
        node->RNTI = (uint16_t)(rand() % 0xFFFF);
        node->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);
        node->CRCFLAG = (uint8_t)(rand() % 2); // Randomly set CRCFLAG
    }

    return head;
}

void destroy_doubly_linked_list(NFAPI_CRC_INDICATION_PDU_T *head, MemoryPool *pool) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free_struct(pool, temp);
    }
}
