using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Linq;
using System.Text;

public class DynamicSqlExecutor
{
    private readonly DbProviderFactory _factory;
    private readonly string _connectionString;

    public DynamicSqlExecutor(DbProviderFactory factory, string connectionString)
    {
        _factory = factory;
        _connectionString = connectionString;
    }

    public IDataReader ExecuteQuery(string queryTemplate, Dictionary<string, object> parameters)
    {
        using (var connection = _factory.CreateConnection())
        {
            connection.ConnectionString = _connectionString;

            try
            {
                connection.Open();
                var command = connection.CreateCommand();
                command.CommandText = ConstructQuery(queryTemplate, parameters);

                foreach (var param in parameters)
                {
                    AddParameter(command, param.Key, param.Value);
                }

                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (Exception ex)
            {
                LogError(ex);
                throw;
            }
        }
    }

    private string ConstructQuery(string queryTemplate, Dictionary<string, object> parameters)
    {
        var sb = new StringBuilder(queryTemplate);

        foreach (var param in parameters)
        {
            var placeholder = $"@{param.Key}";
            if (sb.Contains(placeholder))
            {
                sb.Replace(placeholder, ConvertParameter(param.Value));
            }
        }

        return sb.ToString();
    }

    private void AddParameter(DbCommand command, string name, object value)
    {
        var parameter = command.CreateParameter();
        parameter.ParameterName = $"@{name}";
        parameter.Value = value ?? DBNull.Value;
        command.Parameters.Add(parameter);
    }

    private string ConvertParameter(object value)
    {
        if (value == null) return "NULL";

        switch (Type.GetTypeCode(value.GetType()))
        {
            case TypeCode.String:
                return $"'{value}'";
            case TypeCode.DateTime:
                return $"'{((DateTime)value).ToString("yyyy-MM-dd HH:mm:ss")}'";
            default:
                return value.ToString();
        }
    }

    private void LogError(Exception ex)
    {
        // Implement logging logic here
        Console.WriteLine($"Error: {ex.Message}");
    }
}
