using System;
using System.Collections.Concurrent;
using UnityEngine;

public class ValueGenerator : IDisposable
{
    private readonly ConcurrentDictionary<string, object> _boundsLocks = new ConcurrentDictionary<string, object>();
    private float _minValue;
    private float _maxValue;

    public ValueGenerator(float minValue, float maxValue)
    {
        SetBounds(minValue, maxValue);
    }

    public void SetBounds(float minValue, float maxValue)
    {
        lock (_boundsLocks.GetOrAdd("SetBounds", new object()))
        {
            _minValue = minValue;
            _maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return (float)GetRandomDouble();
    }

    public int GetRandomInt()
    {
        lock (_boundsLocks.GetOrAdd("GetRandomInt", new object()))
        {
            return (int)Math.Round(GetRandomDouble() * (_maxValue - _minValue + 1)) + (int)_minValue;
        }
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(
            GetRandomFloat(),
            GetRandomFloat(),
            GetRandomFloat()
        );
    }

    public Color GetRandomColor()
    {
        return new Color(
            GetRandomFloat(),
            GetRandomFloat(),
            GetRandomFloat()
        );
    }

    private double GetRandomDouble()
    {
        lock (_boundsLocks.GetOrAdd("GetRandomDouble", new object()))
        {
            Random random = new Random();
            return _minValue + (random.NextDouble() * (_maxValue - _minValue));
        }
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
