    list->capacity = initial_capacity;
    list->size = 0;
    list->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
}

void destroy_crc_indication_list(CRC_Indication_List *list) {
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
}

bool add_crc_indication(CRC_Indication_List *list, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity && list->capacity < MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
