#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->next = NULL;
    return new_node;
}

int is_unique_rnti(Node* head, int RNTI) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return 0; // Duplicate RNTI found
        }
        current = current->next;
    }
    return 1; // Unique RNTI
}

Node* add_node(Node** head, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (!is_unique_rnti(*head, RNTI)) {
        // Generate a new unique RNTI
        do {
            RNTI = rand() % 65536; // Assuming RNTI is a 16-bit unsigned integer
        } while (!is_unique_rnti(*head, RNTI));
    }
    Node* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (new_node == NULL) {
        // Handle memory allocation failure
        return *head;
    }
    new_node->next = *head;
    *head = new_node;
    return *head;
}

void prune_old_entries(Node** head, int max_size) {
    Node* current = *head;
    Node* previous = NULL;
    while (current != NULL && current->next != NULL) {
        if (/* condition to determine if the entry is old or unused */) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            previous = current;
            current = current->next;
        }
    }
}

void manage_linked_list(Node** head, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    add_node(head, RX_UE_INFORMATION_TAG, rand() % 65536, CRC_INDICATION_REL8_TAG);
    if (/* condition to check list size */) {
        prune_old_entries(head, 50000);
    }
}
```

