#define MAX_TEST_REQUESTS 1000
#define MIN_BUFFER_SIZE 1024

typedef struct {
    int TestRequestID;
    int ConfigurationProfileIndex;
} LTE_PHY_TEST_REQUEST_T;

typedef struct {
    void* buffer;
    size_t bufferSize;
    size_t usedSize;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memoryPool;

void initializeMemoryPool(size_t initialSize) {
    memoryPool.buffer = malloc(initialSize);
    if (memoryPool.buffer == NULL) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        exit(EXIT_FAILURE);
    }
    memoryPool.bufferSize = initialSize;
    memoryPool.usedSize = 0;
    pthread_mutex_init(&memoryPool.lock, NULL);
}

void* allocateFromMemoryPool(size_t size) {
    pthread_mutex_lock(&memoryPool.lock);
    if (memoryPool.usedSize + size > memoryPool.bufferSize) {
        // Double the buffer size and reallocate
        size_t newSize = memoryPool.bufferSize * 2;
        void* newBuffer = realloc(memoryPool.buffer, newSize);
        if (newBuffer == NULL) {
            fprintf(stderr, "Failed to reallocate memory pool\n");
            pthread_mutex_unlock(&memoryPool.lock);
            return NULL;
        }
        memoryPool.buffer = newBuffer;
        memoryPool.bufferSize = newSize;
    }
    void* ptr = (char*)memoryPool.buffer + memoryPool.usedSize;
    memoryPool.usedSize += size;
    pthread_mutex_unlock(&memoryPool.lock);
    return ptr;
}

LTE_PHY_TEST_REQUEST_T* initializeTestRequests(int numRequests, int configProfileIndex) {
    if (numRequests > MAX_TEST_REQUESTS) {
        fprintf(stderr, "Too many test requests\n");
        return NULL;
    }

    LTE_PHY_TEST_REQUEST_T* testRequests = allocateFromMemoryPool(numRequests * sizeof(LTE_PHY_TEST_REQUEST_T));
    if (testRequests == NULL) {
        fprintf(stderr, "Failed to allocate memory for test requests\n");
        return NULL;
    }

    for (int i = 0; i < numRequests; i++) {
        testRequests[i].TestRequestID = i + 1;
        testRequests[i].ConfigurationProfileIndex = configProfileIndex;
    }

    return testRequests;
}

void freeTestRequests(LTE_PHY_TEST_REQUEST_T* testRequests, int numRequests) {
    pthread_mutex_lock(&memoryPool.lock);
    memoryPool.usedSize -= numRequests * sizeof(LTE_PHY_TEST_REQUEST_T);
    pthread_mutex_unlock(&memoryPool.lock);

    // Optionally, shrink the memory pool if it's significantly larger than needed
}

int main() {
    initializeMemoryPool(MIN_BUFFER_SIZE);

    int numRequests = 500;
    LTE_PHY_TEST_REQUEST_T* testRequests = initializeTestRequests(numRequests, 1);
    if (testRequests != NULL) {
        printf("Successfully initialized %d test requests\n", numRequests);
        freeTestRequests(testRequests, numRequests);
    }

    return 0;
}
