            requests[i].test_data_payload = NULL;
        }
    }

    return requests;
}

void cleanup_test_requests(LTE_PHY_TEST_REQUEST_T* requests, int num_requests) {
    for (int i = 0; i < num_requests; i++) {
        if (requests[i].test_data_payload != NULL) {
            free(requests[i].test_data_payload);
        }
    }
    free(requests);
}

int main() {
    init_memory_pool(DEFAULT_BUFFER_SIZE * MAX_TEST_REQUESTS);

    LTE_PHY_TEST_REQUEST_T* requests = initialize_test_requests(10, 1);
    if (requests == NULL) {
        printf("Failed to initialize test requests\n");
        return 1;
    }

    // Use the initialized test requests here

    cleanup_test_requests(requests, 10);
    free_memory_pool();

    return 0;
}
