typedef struct {
    int userID;
    time_t loginTime;
    time_t logoutTime;
    time_t sessionDuration;
    time_t lastActiveTimestamp;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t capacity;
    size_t size;
} SessionManager;

void initSessionManager(SessionManager *manager, size_t initialCapacity) {
    manager->sessions = (UserSession *)malloc(initialCapacity * sizeof(UserSession));
    if (manager->sessions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initialCapacity;
    manager->size = 0;
}

void addOrUpdateSession(SessionManager *manager, UserSession session) {
    if (manager->size >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        UserSession *newSessions = (UserSession *)realloc(manager->sessions, newCapacity * sizeof(UserSession));
        if (newSessions == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    }
    manager->sessions[manager->size++] = session;
}

void removeInactiveSessions(SessionManager *manager, time_t idleTimeout) {
    size_t i = 0, j = 0;
    for (; i < manager->size; ++i) {
        if (time(NULL) - manager->sessions[i].lastActiveTimestamp > idleTimeout) {
            continue;
        }
        manager->sessions[j++] = manager->sessions[i];
    }
    manager->size = j;
}

time_t calculateTotalActiveTime(SessionManager *manager) {
    time_t totalActiveTime = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        totalActiveTime += manager->sessions[i].sessionDuration;
    }
    return totalActiveTime;
}

void fetchRealTimeUpdates(SessionManager *manager) {
    // Placeholder for fetching real-time updates from an external data source
    // This function should update the sessions in the manager accordingly
}

int main() {
    SessionManager manager;
    initSessionManager(&manager, 10);

    UserSession session1 = {1, time(NULL), time(NULL) + 3600, 3600, time(NULL)};
    addOrUpdateSession(&manager, session1);

    fetchRealTimeUpdates(&manager);
    removeInactiveSessions(&manager, 7200); // Remove sessions inactive for more than 2 hours

    printf("Total active time: %ld seconds\n", calculateTotalActiveTime(&manager));

    free(manager.sessions);
    return 0;
}
