#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_EVM_RSRP_MEASUREMENT {
    int cell_id;
    double evm;
    int rsrp;
    long timestamp;
} LTE_EVM_RSRP_MEASUREMENT;

typedef struct DynamicArray {
    LTE_EVM_RSRP_MEASUREMENT* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        free(array->data);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int add_measurement(DynamicArray* array, LTE_EVM_RSRP_MEASUREMENT measurement) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        LTE_EVM_RSRP_MEASUREMENT* new_data = realloc(array->data, new_capacity * sizeof(LTE_EVM_RSRP_MEASUREMENT));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = measurement;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_measurement(DynamicArray* array, int cell_id, long timestamp, LTE_EVM_RSRP_MEASUREMENT new_measurement) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].cell_id == cell_id && array->data[i].timestamp == timestamp) {
            array->data[i] = new_measurement;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Measurement not found
}

int get_measurements_by_cell_id(DynamicArray* array, int cell_id, LTE_EVM_RSRP_MEASUREMENT** measurements, size_t* count) {
    pthread_mutex_lock(&array->lock);
    *count = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].cell_id == cell_id) {
            (*measurements)[(*count)++] = array->data[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int get_measurements_by_time_range(DynamicArray* array, long start_time, long end_time, LTE_EVM_RSRP_MEASUREMENT** measurements, size_t* count) {
    pthread_mutex_lock(&array->lock);
    *count = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].timestamp >= start_time && array->data[i].timestamp <= end_time) {
            (*measurements)[(*count)++] = array->data[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return 0;
}
