#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct TCI {
    int modulation;
    int codingScheme;
    int rankIndicator;
    int precodingMatrixIndex;
    int channelQualityIndicator;
    struct TCI *next;
} TCI;

TCI* createTCI(int modulation, int codingScheme, int rankIndicator, int precodingMatrixIndex, int channelQualityIndicator) {
    TCI *newTCI = (TCI *)malloc(sizeof(TCI));
    if (newTCI == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newTCI->modulation = modulation;
    newTCI->codingScheme = codingScheme;
    newTCI->rankIndicator = rankIndicator;
    newTCI->precodingMatrixIndex = precodingMatrixIndex;
    newTCI->channelQualityIndicator = channelQualityIndicator;
    newTCI->next = NULL;
    return newTCI;
}

void insertTCI(TCI **head, int modulation, int codingScheme, int rankIndicator, int precodingMatrixIndex, int channelQualityIndicator) {
    TCI *newTCI = createTCI(modulation, codingScheme, rankIndicator, precodingMatrixIndex, channelQualityIndicator);
    newTCI->next = *head;
    *head = newTCI;
}

void adjustTCI(TCI **head, int modulation, int codingScheme, int rankIndicator, int precodingMatrixIndex, int channelQualityIndicator) {
    TCI *current = *head;
    while (current != NULL) {
        if (current->modulation == modulation && current->codingScheme == codingScheme &&
            current->rankIndicator == rankIndicator && current->precodingMatrixIndex == precodingMatrixIndex &&
            current->channelQualityIndicator == channelQualityIndicator) {
            current->modulation = modulation;
            current->codingScheme = codingScheme;
            current->rankIndicator = rankIndicator;
            current->precodingMatrixIndex = precodingMatrixIndex;
            current->channelQualityIndicator = channelQualityIndicator;
            return;
        }
        current = current->next;
    }
}

void freeTCI(TCI *head) {
    TCI *current = head;
    while (current != NULL) {
        TCI *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    TCI *head = NULL;

    insertTCI(&head, 1, 2, 3, 4, 5);
    adjustTCI(&head, 1, 2, 3, 4, 6);

    freeTCI(head);

    return 0;
}
