int add_crc_indication(NFAPI_CRC_INDICATION_PDU_T **array, size_t *size, size_t *capacity, int RX_UE_INFORMATION_TAG, int RNTI, int seed) {
    if (seed != -1) {
        srand(seed);
    }

    if (*size >= *capacity) {
        *capacity = (*capacity == 0) ? 1 : *capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, *capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            return -1; // Memory allocation failed
        }
        *array = new_array;
    }

    for (size_t i = 0; i < *size; ++i) {
        if ((*array)[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            return -2; // Duplicate entry
        }
    }

    (*array)[*size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    (*array)[*size].RNTI = RNTI;
    (*array)[*size].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    ++(*size);

    return 0; // Success
}

void free_crc_indication(NFAPI_CRC_INDICATION_PDU_T *array) {
    free(array);
}
