typedef struct LTE_DL_FRAME_STRUCT {
    // Define members as per your requirements
} LTE_DL_FRAME_STRUCT;

typedef struct LTE_TransformInfo {
    // Define members as per your requirements
} LTE_TransformInfo;

typedef struct LTE_PHY_DownlinkChannelConfig {
    // Define members as per your requirements
} LTE_PHY_DownlinkChannelConfig;

typedef struct LTEPHY_TransformConfig {
    LTE_DL_FRAME_STRUCT frame;
    LTE_TransformInfo transformInfo;
    LTE_PHY_DownlinkChannelConfig channelConfig;
    struct LTEPHY_TransformConfig *prev, *next;
} LTEPHY_TransformConfig;

typedef struct {
    pthread_mutex_t lock;
    LTEPHY_TransformConfig *head, *tail;
} DoublyLinkedList;

void initializeList(DoublyLinkedList *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int addNode(DoublyLinkedList *list, LTE_DL_FRAME_STRUCT frame, LTE_TransformInfo transformInfo, LTE_PHY_DownlinkChannelConfig channelConfig) {
    pthread_mutex_lock(&list->lock);
    LTEPHY_TransformConfig *newNode = (LTEPHY_TransformConfig *)malloc(sizeof(LTEPHY_TransformConfig));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    newNode->frame = frame;
    newNode->transformInfo = transformInfo;
    newNode->channelConfig = channelConfig;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void iterateList(DoublyLinkedList *list, void (*processNode)(LTEPHY_TransformConfig *)) {
    pthread_mutex_lock(&list->lock);
    LTEPHY_TransformConfig *current = list->head;
    while (current) {
        processNode(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeList(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    LTEPHY_TransformConfig *current = list->head, *temp;
    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }
    list->head = list->tail = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
