    LTE_Frame_Descriptor* descriptors = (LTE_Frame_Descriptor*)malloc(num_frames * sizeof(LTE_Frame_Descriptor));
    if (!descriptors) return NULL;

    for (int i = 0; i < num_frames; i++) {
        descriptors[i].pci = i + 1; // Unique PCI
        descriptors[i].rsrp = -110 + (i % 20); // Configured RSRP
        pthread_mutex_init(&descriptors[i].bsr_lock, NULL);
        descriptors[i].bsr_buffer = (unsigned char*)calloc(BSR_SIZE, sizeof(unsigned char));
        if (!descriptors[i].bsr_buffer) {
            for (int j = 0; j < i; j++) {
                free(descriptors[j].bsr_buffer);
                pthread_mutex_destroy(&descriptors[j].bsr_lock);
            }
            free(descriptors);
            return NULL;
        }
    }

    return descriptors;
}

void destroy_lte_frame_descriptors(LTE_Frame_Descriptor* descriptors, int num_frames) {
    for (int i = 0; i < num_frames; i++) {
        free(descriptors[i].bsr_buffer);
        pthread_mutex_destroy(&descriptors[i].bsr_lock);
    }
    free(descriptors);
}

void update_bsr(LTE_Frame_Descriptor* descriptor, int ue_id, unsigned char* data, size_t size) {
    if (size > BSR_SIZE) return; // Handle buffer overflow

    pthread_mutex_lock(&descriptor->bsr_lock);
    memcpy(descriptor->bsr_buffer + ue_id * BSR_SIZE / MAX_UE, data, size);
    pthread_mutex_unlock(&descriptor->bsr_lock);
}
