    for (size_t i = 0; i < N; ++i) {
        if (i % (*allocated_size) == 0 && *allocated_size > 1) {
            // Double the allocation size
            *allocated_size *= 2;
        }

        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = i + 1; // Unique tag for each structure
        data.RNTI = (rand() % MAX_RNTI) + 1; // Random RNTI within valid range
        data.CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRCFLAG

        Node* new_node = create_node(data);
        if (new_node == NULL) {
            // Handle memory allocation error
            free_list(&head);
            return NULL;
        }

        *current = new_node;
        current = &(*current)->next;

        // Log memory usage and errors
        fprintf(log_file, "Allocated %zu bytes for structure %zu\n", sizeof(Node), i + 1);
    }

    return head;
}

int main() {
    srand(time(NULL));
    FILE* log_file = fopen("memory_usage.log", "w");
    if (log_file == NULL) {
        // Handle error: Unable to open log file
        return 1;
    }

    size_t allocated_size = INITIAL_ALLOC_SIZE;
    Node* head = allocate_and_populate_array(500000, &allocated_size, log_file);
    if (head != NULL) {
        free_list(&head);
    }

    fclose(log_file);
    return 0;
}
