const cloudinary = require('cloudinary').v2;
const axios = require('axios');
const fs = require('fs');

cloudinary.config({
  cloud_name: 'your_cloud_name',
  api_key: 'your_api_key',
  api_secret: 'your_api_secret'
});

async function uploadFile(fileSource, fileType, fileSize) {
  let fileBuffer;

  if (fileType === 'local') {
    fileBuffer = fs.readFileSync(fileSource);
  } else if (fileType === 'api') {
    const response = await axios.get(fileSource, { responseType: 'arraybuffer' });
    fileBuffer = Buffer.from(response.data, 'binary');
  }

  return new Promise((resolve, reject) => {
    cloudinary.uploader.upload_stream(
      {
        resource_type: fileType,
        folder: 'uploads',
        tags: ['uploaded_by_api'],
        transformation: [{ width: 500, height: 300, crop: 'scale' }]
      },
      (error, result) => {
        if (error) {
          console.error('Upload failed:', error);
          reject(error);
        } else {
          console.log('File uploaded successfully:', result.url);
          resolve({ url: result.url, metadata: result });
        }
      }
    ).end(fileBuffer);
  });
}

// Example usage:
uploadFile('/path/to/local/file.jpg', 'image', fs.statSync('/path/to/local/file.jpg').size)
  .then(result => {
    console.log('Upload result:', result);
  })
  .catch(error => {
    console.error('Error uploading file:', error);
  });

uploadFile('https://api.example.com/files/image.jpg', 'image', 1024 * 1024 * 5)
  .then(result => {
    console.log('Upload result:', result);
  })
  .catch(error => {
    console.error('Error uploading file:', error);
  });
