#define MAX_CONFIGS 1024

typedef struct LTE_DL_FRAME_STRUCT {
    // Define fields for DL frame structure
} LTE_DL_FRAME_STRUCT;

typedef struct LTE_TransformInfo {
    // Define fields for transform information
} LTE_TransformInfo;

typedef struct LTE_PHY_DownlinkChannelConfig {
    // Define fields for downlink channel configuration
} LTE_PHY_DownlinkChannelConfig;

typedef struct LTEPHY_TransformConfig {
    LTE_DL_FRAME_STRUCT dl_frame;
    LTE_TransformInfo transform_info;
    LTE_PHY_DownlinkChannelConfig channel_config;
    struct LTEPHY_TransformConfig *prev, *next;
} LTEPHY_TransformConfig;

typedef struct {
    LTEPHY_TransformConfig *head, *tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

void init_list(DoublyLinkedList *list) {
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_config(DoublyLinkedList *list, LTE_DL_FRAME_STRUCT dl_frame, LTE_TransformInfo transform_info, LTE_PHY_DownlinkChannelConfig channel_config) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_CONFIGS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: List is full
    }
    LTEPHY_TransformConfig *new_config = malloc(sizeof(LTEPHY_TransformConfig));
    if (!new_config) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Error: Memory allocation failed
    }
    new_config->dl_frame = dl_frame;
    new_config->transform_info = transform_info;
    new_config->channel_config = channel_config;
    new_config->prev = list->tail;
    new_config->next = NULL;
    if (list->tail) {
        list->tail->next = new_config;
    } else {
        list->head = new_config;
    }
    list->tail = new_config;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void iterate_list(DoublyLinkedList *list, void (*callback)(LTEPHY_TransformConfig *)) {
    pthread_mutex_lock(&list->lock);
    for (LTEPHY_TransformConfig *current = list->head; current != NULL; current = current->next) {
        callback(current);
    }
    pthread_mutex_unlock(&list->lock);
}

void free_list(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    while (list->head) {
        LTEPHY_TransformConfig *temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

