#include <stdlib.h>
#include <pthread.h>

typedef struct LTEPHY_TransformConfig {
    LTE_DL_FRAME_STRUCT frame;
    LTE_TransformInfo transformInfo;
    LTE_PHY_DownlinkChannelConfig channelConfig;
} LTEPHY_TransformConfig;

typedef struct Node {
    LTEPHY_TransformConfig data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initDoublyLinkedList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(LTEPHY_TransformConfig data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void insertAtEnd(DoublyLinkedList* list, LTEPHY_TransformConfig data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);
    if (newNode == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->tail == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeDoublyLinkedList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    DoublyLinkedList list;
    initDoublyLinkedList(&list);

    LTEPHY_TransformConfig config1, config2; // Initialize with valid data
    insertAtEnd(&list, config1);
    insertAtEnd(&list, config2);

    freeDoublyLinkedList(&list);
    return 0;
}
