#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000
#define DYNAMIC_ALLOCATIONS 950

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ThreadSafeQueue;

void init_queue(ThreadSafeQueue *queue) {
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

int enqueue(ThreadSafeQueue *queue, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == MAX_STRUCTURES) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->pool[queue->count++] = item;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *dequeue(ThreadSafeQueue *queue) {
    NFAPI_CRC_INDICATION_PDU_T *item = NULL;
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    item = queue->pool[--queue->count];
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return item;
}

void *populate_structures(void *arg) {
    ThreadSafeQueue *queue = (ThreadSafeQueue *)arg;
    for (int i = 0; i < DYNAMIC_ALLOCATIONS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_item = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_item->RX_UE_INFORMATION_TAG = rand() % 100;
        new_item->RNTI = rand() % 256;
        new_item->CRC_INDICATION_REL8_TAG = rand() % 10;
        new_item->CRCFLAG = rand() % 2;
        enqueue(queue, new_item);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    ThreadSafeQueue queue;
    init_queue(&queue);

    pthread_t thread;
    pthread_create(&thread, NULL, populate_structures, &queue);

    // Simulate concurrent access and monitoring
    for (int i = 0; i < DYNAMIC_ALLOCATIONS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *item = dequeue(&queue);
        printf("Dequeued item: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               item->RX_UE_INFORMATION_TAG, item->RNTI, item->CRC_INDICATION_REL8_TAG, item->CRCFLAG);
        free(item);
    }

    pthread_join(thread, NULL);

    return 0;
}
