#define MAX_SESSIONS 1000
#define MEMORY_BUDGET 50 * 1024

typedef struct {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T sessions[MAX_SESSIONS];
    pthread_mutex_t mutex;
    size_t used_memory;
} SessionManager;

SessionManager* create_session_manager() {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->used_memory = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_session_manager(SessionManager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_session(SessionManager* manager, int RNTI) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->used_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MEMORY_BUDGET) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Memory limit exceeded
    }

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (!manager->sessions[i].RNTI) {
            manager->sessions[i].RNTI = RNTI;
            manager->used_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
            pthread_mutex_unlock(&manager->mutex);
            return 0; // Session added successfully
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // No available slot for new session
}

int remove_session(SessionManager* manager, int RNTI) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i].RNTI == RNTI) {
            manager->sessions[i].RNTI = 0;
            manager->used_memory -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            pthread_mutex_unlock(&manager->mutex);
            return 0; // Session removed successfully
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Session not found
}
