#define MAX_USER_AGENT_LENGTH 256
#define MAX_ACTIVE_SESSIONS_PER_USER 5
#define SESSION_LOG_MAX_TIME_MS 500

typedef struct UserSession {
    int sessionID;
    time_t lastActiveTimestamp;
    int activeStatus;
    char userAgent[MAX_USER_AGENT_LENGTH];
} UserSession;

typedef struct SessionNode {
    UserSession session;
    struct SessionNode* next;
} SessionNode;

typedef struct UserSessions {
    SessionNode** sessions;
    int userCount;
    pthread_mutex_t lock;
} UserSessions;

UserSessions* initUserSessions(int maxUsers) {
    UserSessions* us = (UserSessions*)malloc(sizeof(UserSessions));
    if (!us) return NULL;

    us->sessions = (SessionNode**)calloc(maxUsers, sizeof(SessionNode*));
    if (!us->sessions) {
        free(us);
        return NULL;
    }

    us->userCount = 0;
    pthread_mutex_init(&us->lock, NULL);

    return us;
}

void destroyUserSessions(UserSessions* us) {
    for (int i = 0; i < us->userCount; i++) {
        SessionNode* node = us->sessions[i];
        while (node) {
            SessionNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(us->sessions);
    pthread_mutex_destroy(&us->lock);
    free(us);
}

void addUserSession(UserSessions* us, int userID, UserSession session) {
    pthread_mutex_lock(&us->lock);

    if (us->userCount >= MAX_ACTIVE_SESSIONS_PER_USER) {
        printf("User %d has reached the maximum number of active sessions.\n", userID);
        pthread_mutex_unlock(&us->lock);
        return;
    }

    SessionNode* newNode = (SessionNode*)malloc(sizeof(SessionNode));
    if (!newNode) {
        printf("Failed to allocate memory for new session node.\n");
        pthread_mutex_unlock(&us->lock);
        return;
    }

    newNode->session = session;
    newNode->next = us->sessions[userID];
    us->sessions[userID] = newNode;
    us->userCount++;

    pthread_mutex_unlock(&us->lock);
}

void logSession(UserSessions* us, int userID) {
    SessionNode* node = us->sessions[userID];
    while (node) {
        // Simulate logging operation
        printf("Logging session ID: %d\n", node->session.sessionID);

        // Simulate asynchronous I/O operation with a delay
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = SESSION_LOG_MAX_TIME_MS * 1000 * 1000; // Convert ms to ns
        nanosleep(&ts, NULL);

        node = node->next;
    }
}

int main() {
    UserSessions* us = initUserSessions(100);
    if (!us) return 1;

    srand(time(NULL));

    for (int i = 0; i < 50; i++) {
        UserSession session;
        session.sessionID = i + 1;
        session.lastActiveTimestamp = time(NULL);
        session.activeStatus = 1;
        snprintf(session.userAgent, MAX_USER_AGENT_LENGTH, "UserAgent-%d", rand() % 1000);

        addUserSession(us, i % 10, session);
    }

    for (int i = 0; i < 10; i++) {
        logSession(us, i);
    }

    destroyUserSessions(us);

    return 0;
}
