#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define N 100 // Number of elements in the linked list

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void *pool;
    size_t block_size;
    size_t pool_size;
    size_t free_count;
    pthread_mutex_t lock;
} MemoryPool;

NFAPI_CRC_INDICATION_PDU_T* create_node(MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *node = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_count > 0) {
        node = pool->pool + ((pool->pool_size - pool->free_count) * pool->block_size);
        pool->free_count--;
    }
    pthread_mutex_unlock(&pool->lock);
    return node;
}

void free_node(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&pool->lock);
    size_t index = ((char*)node - (char*)pool->pool) / pool->block_size;
    if (index >= pool->pool_size - pool->free_count) {
        pool->pool[index] = 1; // Mark as free
        pool->free_count++;
    }
    pthread_mutex_unlock(&pool->lock);
}

MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->block_size = block_size;
    pool->pool_size = pool_size;
    pool->free_count = pool_size;
    pool->pool = malloc(pool_size * block_size);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N, MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *node = create_node(pool);
        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            return head;
        }
        node->RX_UE_INFORMATION_TAG = rand() % 1000;
        node->RNTI = rand() % 1000;
        node->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        if (i == 0) {
            head = node;
        } else {
            current->next = node;
        }
        current = node;
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *head, MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free_node(pool, current);
        current = next;
    }
}

void* thread_function(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;
    NFAPI_CRC_INDICATION_PDU_T *list = create_linked_list(N, pool);
    if (!list) {
        fprintf(stderr, "Failed to create linked list\n");
        return NULL;
    }
    // Process the list
    free_linked_list(list, pool);
    return NULL;
}

int main() {
    srand(time(NULL));
    MemoryPool *pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), N);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, pool) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool(pool);
    return 0;
}
