#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_crc_indication(NFAPI_CRC_LIST_T *list, uint16_t RNTI, uint8_t CRCFLAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate RNTI
        }
    }

    list->list[list->count].RNTI = RNTI;
    list->list[list->count].CRCFLAG = CRCFLAG;
    ++list->count;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void serialize_crc_list(NFAPI_CRC_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return; // File opening failed
    }

    fwrite(&list->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->count; ++i) {
        fwrite(&list->list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

int deserialize_crc_list(NFAPI_CRC_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return -1; // File opening failed
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            fclose(file);
            return -2; // Memory allocation failed
        }
        list->list = new_list;
        list->capacity = count;
    }

    for (size_t i = 0; i < count; ++i) {
        fread(&list->list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    list->count = count;
    fclose(file);
    return 0;
}

int main() {
    NFAPI_CRC_LIST_T *crc_list = create_crc_list(1024);

    srand(time(NULL));
    for (size_t i = 0; i < 10000; ++i) {
        uint16_t RNTI = rand() % MAX_RNTI;
        uint8_t CRCFLAG = rand() % 2;
        insert_crc_indication(crc_list, RNTI, CRCFLAG);
    }

    serialize_crc_list(crc_list, "crc_list.bin");

    NFAPI_CRC_LIST_T *new_crc_list = create_crc_list(1024);
    deserialize_crc_list(new_crc_list, "crc_list.bin");

    destroy_crc_list(crc_list);
    destroy_crc_list(new_crc_list);

    return 0;
}
