typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    sem_t lock;
} CRC_LIST;

CRC_LIST* create_crc_list(size_t initial_capacity) {
    CRC_LIST *list = (CRC_LIST*)malloc(sizeof(CRC_LIST));
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initial_capacity;
    sem_init(&list->lock, 0, 1);
    return list;
}

void destroy_crc_list(CRC_LIST *list) {
    free(list->entries);
    sem_destroy(&list->lock);
    free(list);
}

int insert_crc_entry(CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    sem_wait(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            sem_post(&list->lock);
            return -1; // Memory allocation failed
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rx_ue_info.RNTI == entry.rx_ue_info.RNTI) {
            sem_post(&list->lock);
            return -2; // Duplicate RNTI
        }
    }

    list->entries[list->count++] = entry;
    sem_post(&list->lock);
    return 0;
}

int serialize_crc_list(CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return -1; // File open failed
    }

    sem_wait(&list->lock);
    size_t written = fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    sem_post(&list->lock);

    fclose(file);
    if (written != list->count) {
        return -2; // Write failed
    }

    return 0;
}

void* async_serialize_crc_list(void *arg) {
    CRC_LIST *list = (CRC_LIST*)arg;
    char filename[256];
    snprintf(filename, sizeof(filename), "crc_list_%d.dat", getpid());

    serialize_crc_list(list, filename);

    return NULL;
}
