    unsigned long userId;
    time_t timestamp;
    SessionStatus status;
} Session;

typedef struct {
    Session* sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* createSessionManager(size_t initialCapacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = (Session*)calloc(initialCapacity, sizeof(Session));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroySessionManager(SessionManager* manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        free(manager->sessions);
        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int addSession(SessionManager* manager, unsigned long userId, SessionStatus status) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        Session* newSessions = (Session*)realloc(manager->sessions, newCapacity * sizeof(Session));
        if (!newSessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    }

    manager->sessions[manager->count].userId = userId;
    manager->sessions[manager->count].timestamp = time(NULL);
    manager->sessions[manager->count].status = status;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void updateSessionStatus(SessionManager* manager, unsigned long userId, SessionStatus newStatus) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; i++) {
        if (manager->sessions[i].userId == userId) {
            manager->sessions[i].status = newStatus;

            // Notify external systems about the status change
            notifyExternalSystems(userId, newStatus);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void removeSession(SessionManager* manager, unsigned long userId) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; i++) {
        if (manager->sessions[i].userId == userId) {
            // Reclaim memory by moving the last session to this position
            manager->sessions[i] = manager->sessions[manager->count - 1];
            manager->count--;

            // Notify external systems about the removal
            notifyExternalSystems(userId, INACTIVE);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

