    fprintf(log_file, "%s: UE_INDEX=%d\n", event, UE_INDEX);
    pthread_mutex_unlock(&mutex);
}

void scan_and_free_unused_frames() {
    for (int i = 0; i < frame_count; i++) {
        if (frames[i] && /* condition to check if the frame is unused */) {
            destroy_frame(frames[i]);
            frames[i] = NULL;
            log_frame_event("Destroyed", frames[i]->UE_INDEX);
        }
    }
}

void* process_bursts(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        // Process bursts for the current thread
        scan_and_free_unused_frames();
        // Sleep or yield to other threads
        pthread_yield();
    }
    return NULL;
}

void initialize_system() {
    log_file = fopen("log.txt", "w");
    for (int i = 0; i < MAX_FRAMES; i++) {
        frames[i] = NULL;
    }
    pthread_t threads[MAX_FRAMES];
    int thread_ids[MAX_FRAMES];
    for (int i = 0; i < MAX_FRAMES; i++) {
        frames[i] = malloc(sizeof(LTE_PHY_RX_FRAME_INFO_T));
        initialize_frame(frames[i], i, i % 10);
        log_frame_event("Created", frames[i]->UE_INDEX);
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, process_bursts, &thread_ids[i]);
    }
}

void cleanup_system() {
    for (int i = 0; i < MAX_FRAMES; i++) {
        if (frames[i]) {
            destroy_frame(frames[i]);
            frames[i] = NULL;
            log_frame_event("Destroyed", frames[i]->UE_INDEX);
        }
    }
    fclose(log_file);
}

void export_data_to_csv() {
    FILE* csv_file = fopen("data.csv", "w");
    for (int i = 0; i < frame_count; i++) {
        if (frames[i]) {
            fprintf(csv_file, "%d,%d,", frames[i]->UE_INDEX, frames[i]->RF_CHANNEL);
            for (int j = 0; j < MAX_BURSTS_PER_FRAME; j++) {
                if (frames[i]->bursts[j]) {
                    fprintf(csv_file, "%d,%d,", frames[i]->bursts[j]->burst_length, frames[i]->bursts[j]->signal_strength);
                } else {
                    fprintf(csv_file, "0,0,");
                }
            }
            fprintf(csv_file, "\n");
        }
    }
    fclose(csv_file);
}

int main() {
    initialize_system();
    // Simulate burst processing
    export_data_to_csv();
    cleanup_system();
    return 0;
}
