#include <time.h>

#define MAX_UE_INDEX 10000
#define MAX_BURST_COUNT 100

typedef struct {
    int length;
    float signal_strength;
} BURST_INFO_T;

typedef struct {
    int UE_INDEX;
    int RF_CHANNEL;
    BURST_INFO_T* bursts[MAX_BURST_COUNT];
} LTE_PHY_RX_FRAME_INFO_T;

LTE_PHY_RX_FRAME_INFO_T** frames = NULL;
int frame_count = 0;
int max_frames = 10000;
int memory_limit = 1024 * 1024 * 10; // 10 MB
int logging_level = 1; // 1: Error, 2: Warning, 3: Info

void initialize_frame(LTE_PHY_RX_FRAME_INFO_T* frame) {
    frame->UE_INDEX = rand() % MAX_UE_INDEX;
    frame->RF_CHANNEL = rand() % 100;
    for (int i = 0; i < MAX_BURST_COUNT; i++) {
        frame->bursts[i] = malloc(sizeof(BURST_INFO_T));
        if (!frame->bursts[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        frame->bursts[i]->length = rand() % 100;
        frame->bursts[i]->signal_strength = (float)rand() / RAND_MAX * 100.0f;
    }
}

void cleanup_frame(LTE_PHY_RX_FRAME_INFO_T* frame) {
    for (int i = 0; i < MAX_BURST_COUNT; i++) {
        free(frame->bursts[i]);
    }
}

void add_frame() {
    if (frame_count >= max_frames) {
        fprintf(stderr, "Maximum number of frames reached\n");
        return;
    }
    LTE_PHY_RX_FRAME_INFO_T* new_frame = malloc(sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (!new_frame) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    initialize_frame(new_frame);
    frames[frame_count++] = new_frame;
}

void remove_frame(int index) {
    if (index < 0 || index >= frame_count) {
        fprintf(stderr, "Invalid frame index\n");
        return;
    }
    cleanup_frame(frames[index]);
    free(frames[index]);
    for (int i = index; i < frame_count - 1; i++) {
        frames[i] = frames[i + 1];
    }
    frame_count--;
}

void configure_memory_limit(int limit) {
    memory_limit = limit;
}

void configure_logging_level(int level) {
    logging_level = level;
}

void print_frame_info(LTE_PHY_RX_FRAME_INFO_T* frame) {
    printf("UE_INDEX: %d, RF_CHANNEL: %d\n", frame->UE_INDEX, frame->RF_CHANNEL);
    for (int i = 0; i < MAX_BURST_COUNT; i++) {
        if (frame->bursts[i]) {
            printf("  Burst %d: Length=%d, Signal Strength=%.2f\n", i, frame->bursts[i]->length, frame->bursts[i]->signal_strength);
        }
    }
}

void print_all_frames() {
    for (int i = 0; i < frame_count; i++) {
        printf("Frame %d:\n", i);
        print_frame_info(frames[i]);
    }
}

int main() {
    srand(time(NULL));
    frames = malloc(max_frames * sizeof(LTE_PHY_RX_FRAME_INFO_T*));
    if (!frames) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < 1000; i++) {
        add_frame();
    }

    print_all_frames();

    for (int i = 0; i < frame_count; i++) {
        remove_frame(i);
    }

    free(frames);

    return 0;
}
