#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    int rnti;
    // Other fields from ueInformation structure
} UEInformation;

typedef struct {
    int crcIndicationRel15;
    // Other fields from NRUEInformationTag structure
} NRUEInformationTag;

typedef struct {
    NRUEInformationTag *tags;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for dynamic array");
        return NULL;
    }
    array->tags = (NRUEInformationTag*)calloc(INITIAL_CAPACITY, sizeof(NRUEInformationTag));
    if (!array->tags) {
        free(array);
        perror("Failed to allocate memory for tags in dynamic array");
        return NULL;
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array) {
        free(array->tags);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_tag_to_array(DynamicArray *array, int rnti, UEInformation *ueInfo) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        NRUEInformationTag *new_tags = (NRUEInformationTag*)realloc(array->tags, new_capacity * sizeof(NRUEInformationTag));
        if (!new_tags) {
            pthread_mutex_unlock(&array->mutex);
            perror("Failed to reallocate memory for dynamic array");
            return -1;
        }
        array->tags = new_tags;
        array->capacity = new_capacity;
    }

    // Populate the tag with data
    array->tags[array->size].crcIndicationRel15 = rand() % 2; // Random CRC flag
    // Copy ueInfo fields to tag
    // ...

    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Example usage
int main() {
    srand(time(NULL));
    DynamicArray *array = create_dynamic_array();
    if (array) {
        UEInformation ueInfo; // Populate with actual data from external source
        add_tag_to_array(array, 12345, &ueInfo);
        destroy_dynamic_array(array);
    }
    return 0;
}
