#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    NFAPI_CRC_INDICATION_PDU_T *cache[1000];
    int cache_size;
    pthread_mutex_t lock;
} CRC_LIST;

CRC_LIST* create_crc_list() {
    CRC_LIST* list = (CRC_LIST*)aligned_alloc(64, sizeof(CRC_LIST));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->cache_size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRC_LIST* list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand();
    pdu->CRCFLAG = rand() % 2;
    pdu->prev = pdu->next = NULL;
    return pdu;
}

int add_to_crc_list(CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = list->tail = pdu;
    } else {
        list->tail->next = pdu;
        pdu->prev = list->tail;
        list->tail = pdu;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* find_in_crc_list(CRC_LIST* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->cache_size; i++) {
        if (list->cache[i]->RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return list->cache[i];
        }
    }
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->RNTI == RNTI) {
            if (list->cache_size < 1000) {
                list->cache[list->cache_size++] = current;
            }
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int remove_from_crc_list(CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);
    if (pdu->prev) {
        pdu->prev->next = pdu->next;
    } else {
        list->head = pdu->next;
    }
    if (pdu->next) {
        pdu->next->prev = pdu->prev;
    } else {
        list->tail = pdu->prev;
    }
    pthread_mutex_unlock(&list->lock);
    free(pdu);
    return 0;
}

int populate_crc_list(CRC_LIST* list, int N) {
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_crc_pdu();
        if (!pdu) {
            destroy_crc_list(list);
            return -1;
        }
        if (add_to_crc_list(list, pdu)) {
            destroy_crc_list(list);
            free(pdu);
            return -1;
        }
    }
    return 0;
}
