#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 5000
#define SUPPORTED_QOS_PROFILES 10

typedef struct {
    int ueid;
    int rnti;
    int qos_profile_index;
} LTE_UE_Context;

LTE_UE_Context *ue_context_list = NULL;
int current_size = 0;
int max_size = MAX_UE_CONTEXTS;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int most_frequently_used_ueid = -1;
int qos_profile_cache[SUPPORTED_QOS_PROFILES] = {0};

LTE_UE_Context* custom_realloc(LTE_UE_Context *ptr, size_t new_size) {
    LTE_UE_Context *new_ptr = realloc(ptr, new_size);
    if (new_ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

void validate_qos_profile(int qos_index) {
    if (qos_index < 0 || qos_index >= SUPPORTED_QOS_PROFILES) {
        fprintf(stderr, "Invalid QoS profile index: %d\n", qos_index);
    } else {
        qos_profile_cache[qos_index]++;
    }
}

void update_most_frequently_used_ueid(int ueid) {
    if (ueid != most_frequently_used_ueid) {
        int old_count = 0;
        for (int i = 0; i < current_size; i++) {
            if (ue_context_list[i].ueid == most_frequently_used_ueid) {
                old_count++;
                break;
            }
        }
        int new_count = 0;
        for (int i = 0; i < current_size; i++) {
            if (ue_context_list[i].ueid == ueid) {
                new_count++;
                break;
            }
        }
        if (new_count > old_count) {
            most_frequently_used_ueid = ueid;
        }
    }
}

void insert_UE_context(int ueid, int rnti, int qos_index) {
    pthread_mutex_lock(&list_mutex);
    if (current_size >= max_size) {
        max_size *= 2;
        ue_context_list = custom_realloc(ue_context_list, max_size * sizeof(LTE_UE_Context));
    }
    validate_qos_profile(qos_index);
    update_most_frequently_used_ueid(ueid);
    ue_context_list[current_size].ueid = ueid;
    ue_context_list[current_size].rnti = rnti;
    ue_context_list[current_size].qos_profile_index = qos_index;
    current_size++;
    pthread_mutex_unlock(&list_mutex);
}

int get_total_elements() {
    return current_size;
}

int find_qos_profile(int ueid) {
    for (int i = 0; i < current_size; i++) {
        if (ue_context_list[i].ueid == ueid) {
            return ue_context_list[i].qos_profile_index;
        }
    }
    return -1;
}
