#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Packet {
    int id;
    time_t timestamp;
    char *payload;
    size_t payload_size;
} Packet;

typedef struct PacketList {
    Packet **packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketList;

PacketList* create_packet_list() {
    PacketList *list = (PacketList*)malloc(sizeof(PacketList));
    list->packets = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_packet_list(PacketList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->packets[i]->payload);
        free(list->packets[i]);
    }
    free(list->packets);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_packet(PacketList *list, Packet *packet) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        Packet **new_packets = (Packet**)realloc(list->packets, new_capacity * sizeof(Packet*));
        if (!new_packets) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle memory allocation failure
        }
        list->packets = new_packets;
        list->capacity = new_capacity;
    }
    list->packets[list->count++] = packet;
    pthread_mutex_unlock(&list->lock);
}

Packet* get_packet(PacketList *list, int id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->packets[i]->id == id) {
            pthread_mutex_unlock(&list->lock);
            return list->packets[i];
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void update_packet(PacketList *list, Packet *packet) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->packets[i]->id == packet->id) {
            free(list->packets[i]->payload);
            list->packets[i] = packet;
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    PacketList *packet_list = create_packet_list();

    // Simulate adding packets
    Packet *new_packet = (Packet*)malloc(sizeof(Packet));
    new_packet->id = 1;
    new_packet->timestamp = time(NULL);
    new_packet->payload_size = 1024;
    new_packet->payload = (char*)malloc(new_packet->payload_size);
    // Populate payload...
    add_packet(packet_list, new_packet);

    // Simulate retrieving a packet
    Packet *retrieved_packet = get_packet(packet_list, 1);
    if (retrieved_packet) {
        printf("Packet ID: %d\n", retrieved_packet->id);
        free(retrieved_packet->payload);
        free(retrieved_packet);
    }

    destroy_packet_list(packet_list);
    return 0;
}
```

This code provides a basic structure for managing a list of custom packet structures in C, including thread safety and dynamic memory management. It includes functions to add, retrieve, and update packets by their ID. The example usage demonstrates how to create a packet list, add a packet, retrieve it, and clean up resources.']

