typedef struct {
    char path[256];
    time_t mod_time;
    char owner[32];
    char permissions[10];
    size_t size;
} FileMetadata;

typedef struct Node {
    FileMetadata data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} MetadataList;

void initMetadataList(MetadataList* list) {
    list->head = NULL;
    list->count = 0;
}

Node* createNode(const FileMetadata* metadata) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    memcpy(&newNode->data, metadata, sizeof(FileMetadata));
    newNode->next = NULL;
    return newNode;
}

void addEntry(MetadataList* list, const FileMetadata* metadata) {
    Node* newNode = createNode(metadata);
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

void updateEntry(MetadataList* list, const char* path, const FileMetadata* newMetadata) {
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->data.path, path) == 0) {
            memcpy(&current->data, newMetadata, sizeof(FileMetadata));
            return;
        }
        current = current->next;
    }
}

void iterateList(MetadataList* list, void (*callback)(const FileMetadata*)) {
    Node* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
}

size_t calculateTotalSize(MetadataList* list) {
    size_t totalSize = 0;
    iterateList(list, (void (*)(const FileMetadata*))&totalSize += data.size);
    return totalSize;
}

void findFilesByOwner(MetadataList* list, const char* owner, void (*callback)(const FileMetadata*)) {
    iterateList(list, (void (*)(const FileMetadata*))&{
        if (strcmp(data.owner, owner) == 0) {
            callback(data);
        }
    });
}

void freeMetadataList(MetadataList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}
