#include <stdlib.h>
#include <string.h>

typedef struct emm_procedure {
    // Define the structure for EPS Mobility Management Entity procedures
} emm_procedure_t;

typedef struct session_context {
    uint16_t rnti; // Unique UE identifier (RNTI)
    char *nas_buffer; // Dynamically allocated buffer for NAS messages
    size_t nas_size; // Size of the NAS message buffer
    emm_procedure_t *emm_head; // Linked list head for EPS Mobility Management Entity procedures
    struct session_context *next; // Pointer to the next session context in the pool
} session_context_t;

typedef struct session_pool {
    session_context_t *head; // Head of the linked list of session contexts
    size_t total_nas_size; // Total size of all NAS message buffers
    size_t max_sessions; // Maximum number of sessions allowed in the pool
    size_t current_sessions; // Current number of sessions in the pool
} session_pool_t;

session_context_t* create_session_context(uint16_t rnti, size_t nas_size) {
    session_context_t *ctx = (session_context_t*)malloc(sizeof(session_context_t));
    if (ctx == NULL) return NULL;

    ctx->rnti = rnti;
    ctx->nas_buffer = (char*)malloc(nas_size);
    if (ctx->nas_buffer == NULL) {
        free(ctx);
        return NULL;
    }
    ctx->nas_size = nas_size;
    ctx->emm_head = NULL;
    ctx->next = NULL;

    return ctx;
}

void destroy_session_context(session_context_t *ctx) {
    if (ctx != NULL) {
        free(ctx->nas_buffer);
        free(ctx);
    }
}

session_pool_t* create_session_pool(size_t max_sessions) {
    session_pool_t *pool = (session_pool_t*)malloc(sizeof(session_pool_t));
    if (pool == NULL) return NULL;

    pool->head = NULL;
    pool->total_nas_size = 0;
    pool->max_sessions = max_sessions;
    pool->current_sessions = 0;

    return pool;
}

void destroy_session_pool(session_pool_t *pool) {
    if (pool != NULL) {
        session_context_t *ctx = pool->head;
        while (ctx != NULL) {
            session_context_t *next = ctx->next;
            destroy_session_context(ctx);
            ctx = next;
        }
        free(pool);
    }
}

int add_session_to_pool(session_pool_t *pool, uint16_t rnti, size_t nas_size) {
    if (pool->current_sessions >= pool->max_sessions) return -1; // Pool is full

    session_context_t *ctx = create_session_context(rnti, nas_size);
    if (ctx == NULL) return -2; // Memory allocation failed

    ctx->next = pool->head;
    pool->head = ctx;
    pool->total_nas_size += nas_size;
    pool->current_sessions++;

    return 0; // Success
}

int remove_session_from_pool(session_pool_t *pool, uint16_t rnti) {
    session_context_t **prev = &pool->head;
    while (*prev != NULL) {
        if ((*prev)->rnti == rnti) {
            session_context_t *ctx = *prev;
            *prev = ctx->next;
            pool->total_nas_size -= ctx->nas_size;
            destroy_session_context(ctx);
            pool->current_sessions--;
            return 0; // Success
        }
        prev = &(*prev)->next;
    }
    return -1; // Session not found
}

session_context_t* get_session_from_pool(session_pool_t *pool, uint16_t rnti) {
    session_context_t *ctx = pool->head;
    while (ctx != NULL) {
        if (ctx->rnti == rnti) return ctx;
        ctx = ctx->next;
    }
    return NULL; // Session not found
}
