#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

long* offsets = NULL;
int* keys = NULL;
record* records = NULL;
size_t num_offsets = 0, num_keys = 0, num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void allocate_memory(size_t new_num_offsets, size_t new_num_keys, size_t new_num_records) {
    pthread_mutex_lock(&mutex);
    if (new_num_offsets != num_offsets) {
        free(offsets);
        offsets = malloc(new_num_offsets * sizeof(long));
        if (!offsets) {
            perror("Failed to allocate memory for offsets");
            exit(EXIT_FAILURE);
        }
        num_offsets = new_num_offsets;
    }

    if (new_num_keys != num_keys) {
        free(keys);
        keys = calloc(new_num_keys, sizeof(int));
        if (!keys) {
            perror("Failed to allocate memory for keys");
            exit(EXIT_FAILURE);
        }
        num_keys = new_num_keys;
    }

    if (new_num_records != num_records) {
        free(records);
        records = malloc(new_num_records * sizeof(record));
        if (!records) {
            perror("Failed to allocate memory for records");
            exit(EXIT_FAILURE);
        }
        num_records = new_num_records;
    }
    pthread_mutex_unlock(&mutex);
}

void initialize_data() {
    srand(time(NULL));
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = 0;
    }
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 101;
    }
}

void free_memory() {
    pthread_mutex_lock(&mutex);
    free(offsets);
    offsets = NULL;
    free(keys);
    keys = NULL;
    free(records);
    records = NULL;
    num_offsets = num_keys = num_records = 0;
    pthread_mutex_unlock(&mutex);
}
