    char source_ip[16];
    char destination_ip[16];
    int payload_length;
} NetworkPacket;

NetworkPacket* packet_array[MAX_PACKETS];
int packet_count = 0;

void add_packet(int timestamp, const char* source_ip, const char* destination_ip, int payload_length) {
    if (packet_count >= MAX_PACKETS) {
        printf("Error: Packet array is full.\n");
        return;
    }
    NetworkPacket* new_packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (!new_packet) {
        printf("Error: Memory allocation failed for packet.\n");
        return;
    }
    new_packet->timestamp = timestamp;
    strncpy(new_packet->source_ip, source_ip, 16);
    strncpy(new_packet->destination_ip, destination_ip, 16);
    new_packet->payload_length = payload_length;
    packet_array[packet_count++] = new_packet;
}

void update_packet(int index, int timestamp, const char* source_ip, const char* destination_ip, int payload_length) {
    if (index < 0 || index >= packet_count) {
        printf("Error: Invalid packet index.\n");
        return;
    }
    NetworkPacket* packet = packet_array[index];
    packet->timestamp = timestamp;
    strncpy(packet->source_ip, source_ip, 16);
    strncpy(packet->destination_ip, destination_ip, 16);
    packet->payload_length = payload_length;
}

int calculate_total_data_transferred() {
    int total = 0;
    for (int i = 0; i < packet_count; i++) {
        total += packet_array[i]->payload_length;
    }
    return total;
}

