NFAPI_CRC_INDICATION_PDU_T* manage_array(int *size, int new_elements) {
    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* array = realloc(*array, (*size + new_elements) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    // Populate new elements with random data and valid tags
    for (int i = 0; i < new_elements; i++) {
        array[*size + i].RX_UE_INFORMATION_TAG = rand();
        array[*size + i].RNTI = rand() % 1000; // Assuming RNTI is a small integer for simplicity
        array[*size + i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    *size += new_elements;

    return array;
}

void sort_array(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    // Sort by RNTI first
    qsort(array, size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    if (array[0].RNTI == array[1].RNTI) { // Fallback to RX_UE_INFORMATION_TAG if RNTIs are the same
        qsort(array, size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rx_tag);
    }
}

