#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

void init_crc_array(NFAPI_CRC_ARRAY_T *array, size_t initial_capacity) {
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void add_crc_element(NFAPI_CRC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&array->mutex);
            exit(EXIT_FAILURE);
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
}

void sort_crc_array(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->mutex);
    if (array->size > 1) {
        qsort(array->array, array->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);
        if (array->array[0].RNTI == array->array[1].RNTI) {
            qsort(array->array, array->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rx_ue_information_tag);
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

int compare_rnti(const void *a, const void *b) {
    return ((NFAPI_CRC_INDICATION_PDU_T *)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T *)b)->RNTI;
}

int compare_rx_ue_information_tag(const void *a, const void *b) {
    return ((NFAPI_CRC_INDICATION_PDU_T *)a)->RX_UE_INFORMATION_TAG - ((NFAPI_CRC_INDICATION_PDU_T *)b)->RX_UE_INFORMATION_TAG;
}

void free_crc_array(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}
