    char MESSAGE_TYPE[100];
} LTE_ENB_RRC_MESSAGE_PDU_T;

typedef struct ListNode {
    LTE_ENB_RRC_MESSAGE_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct List {
    ListNode* head;
    size_t size;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    return list;
}

void destroy_list(List* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int add_to_list(List* list, LTE_ENB_RRC_MESSAGE_PDU_T data) {
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) return -1; // Memory allocation failed
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    return 0;
}

int compare_sequence_number(const void* a, const void* b) {
    LTE_ENB_RRC_MESSAGE_PDU_T* pa = (LTE_ENB_RRC_MESSAGE_PDU_T*)a;
    LTE_ENB_RRC_MESSAGE_PDU_T* pb = (LTE_ENB_RRC_MESSAGE_PDU_T*)b;
    return pa->SEQUENCE_NUMBER - pb->SEQUENCE_NUMBER;
}

int compare_pdu_session_id(const void* a, const void* b) {
    LTE_ENB_RRC_MESSAGE_PDU_T* pa = (LTE_ENB_RRC_MESSAGE_PDU_T*)a;
    LTE_ENB_RRC_MESSAGE_PDU_T* pb = (LTE_ENB_RRC_MESSAGE_PDU_T*)b;
    return pa->PDU_SESSION_ID - pb->PDU_SESSION_ID;
}

int sort_list(List* list) {
    if (!list || !list->head) return 0; // Empty list

    ListNode* current = list->head;
    LTE_ENB_RRC_MESSAGE_PDU_T* array[list->size];
    int i = 0;

    while (current) {
        array[i++] = &current->data;
        current = current->next;
    }

    qsort(array, list->size, sizeof(LTE_ENB_RRC_MESSAGE_PDU_T*), compare_sequence_number);

    if (array[0]->SEQUENCE_NUMBER == array[1]->SEQUENCE_NUMBER) {
        qsort(array, list->size, sizeof(LTE_ENB_RRC_MESSAGE_PDU_T*), compare_pdu_session_id);
    }

    ListNode* new_head = NULL;
    for (int j = 0; j < list->size; j++) {
        ListNode* node = (ListNode*)malloc(sizeof(ListNode));
        if (!node) return -1; // Memory allocation failed
        node->data = *array[j];
        node->next = new_head;
        new_head = node;
    }

    destroy_list(list);
    list->head = new_head;
    list->size = list->size;

    return 0;
}
