    Session_Context *head;
    size_t total_nas_size;
    pthread_mutex_t lock;
} Session_Manager;

void init_session_manager(Session_Manager *manager) {
    manager->head = NULL;
    manager->total_nas_size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_session_context(Session_Manager *manager, int rnti, NAS_Message *nas_buffer, EMM_Procedure *emm_procedures) {
    pthread_mutex_lock(&manager->lock);
    Session_Context *new_context = (Session_Context *)malloc(sizeof(Session_Context));
    new_context->rnti = rnti;
    new_context->nas_buffer = nas_buffer;
    new_context->emm_procedures = emm_procedures;
    new_context->next = manager->head;
    manager->head = new_context;
    manager->total_nas_size += nas_buffer->length;
    pthread_mutex_unlock(&manager->lock);
}

void remove_session_context(Session_Manager *manager, int rnti) {
    pthread_mutex_lock(&manager->lock);
    Session_Context *current = manager->head;
    Session_Context *previous = NULL;

    while (current != NULL) {
        if (current->rnti == rnti) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            manager->total_nas_size -= current->nas_buffer->length;
            free(current->nas_buffer->data);
            free(current->nas_buffer);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

