    Session_Context *current = manager->head;

    while (current != NULL) {
        if (current->rnti == rnti) {
            NAS_Message *nas_buffer = current->nas_buffer;
            pthread_mutex_unlock(&manager->lock);
            return nas_buffer;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

