#include <stdlib.h>
#include <string.h>

#define MAX_SESSIONS 50000
#define MEMORY_BUDGET 2 * 1024 * 1024 // 2 MB
#define ALIGNMENT 32

typedef struct {
    unsigned int SessionID;
    char ClientIP[16];
    time_t RequestTimestamp;
} SessionEntry;

typedef struct {
    SessionEntry entries[MAX_SESSIONS];
    size_t count;
} HashTable;

HashTable* createHashTable() {
    HashTable* table = (HashTable*)aligned_alloc(ALIGNMENT, sizeof(HashTable));
    if (!table) return NULL; // Memory allocation failed
    memset(table, 0, sizeof(HashTable));
    return table;
}

int addSession(HashTable* table, unsigned int SessionID, const char* ClientIP, time_t RequestTimestamp) {
    if (table->count >= MAX_SESSIONS) return -1; // Hash table is full

    size_t index = SessionID % MAX_SESSIONS;
    while (table->entries[index].SessionID != 0 && table->entries[index].SessionID != UINT_MAX) {
        index = (index + 1) % MAX_SESSIONS; // Linear probing
    }

    if (table->count >= MEMORY_BUDGET / sizeof(SessionEntry)) return -2; // Memory budget exceeded

    table->entries[index].SessionID = SessionID;
    strncpy(table->entries[index].ClientIP, ClientIP, sizeof(table->entries[index].ClientIP) - 1);
    table->entries[index].RequestTimestamp = RequestTimestamp;
    table->count++;
    return 0; // Success
}

void destroyHashTable(HashTable* table) {
    free(table);
}
