    if (!session->message_buffer) {
        free(session->connections);
        free(session);
        return NULL;
    }

    memset(session->connections, 0, max_connections * sizeof(ConnectionParams));
    memset(session->message_buffer, 0, buffer_size);

    for (size_t i = 0; i < max_connections; ++i) {
        session->connections[i].timeout = 5000; // Default timeout value
    }

    return session;
}

