#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_SIZE 1024 * 1024 // Maximum size for memory allocation
#define INITIAL_CAPACITY 1000 // Initial capacity of arrays

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} data_structures;

data_structures* create_data_structures(size_t initial_capacity) {
    data_structures* ds = (data_structures*)malloc(sizeof(data_structures));
    if (!ds) return NULL;

    ds->offsets = (long*)calloc(initial_capacity, sizeof(long));
    ds->keys = (int*)calloc(initial_capacity, sizeof(int));
    ds->records = (record**)calloc(initial_capacity, sizeof(record*));
    ds->capacity = initial_capacity;
    ds->size = 0;
    pthread_mutex_init(&ds->mutex, NULL);

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds);
        return NULL;
    }

    return ds;
}

void destroy_data_structures(data_structures* ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

void* resize_data_structures(void* arg) {
    data_structures* ds = (data_structures*)arg;
    size_t new_capacity = ds->capacity * 2;

    if (new_capacity > MAX_SIZE) return NULL;

    long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    record** new_records = (record**)realloc(ds->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_records) return NULL;

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;

    return NULL;
}

void add_record(data_structures* ds, int key, int value) {
    pthread_mutex_lock(&ds->mutex);
    if (ds->size == ds->capacity) {
        resize_data_structures(ds);
    }
    ds->offsets[ds->size] = 0; // Placeholder for offset
    ds->keys[ds->size] = key;
    ds->records[ds->size] = (record*)malloc(sizeof(record));
    if (!ds->records[ds->size]) {
        pthread_mutex_unlock(&ds->mutex);
        return;
    }
    ds->records[ds->size]->value = value;
    ++ds->size;
    pthread_mutex_unlock(&ds->mutex);
}

void serialize_data_structures(data_structures* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(ds->offsets, sizeof(long), ds->size, file);
    fwrite(ds->keys, sizeof(int), ds->size, file);
    for (size_t i = 0; i < ds->size; ++i) {
        fwrite(&ds->records[i]->value, sizeof(int), 1, file);
    }

    fclose(file);
}

void deserialize_data_structures(data_structures* ds, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    resize_data_structures(ds);
    ds->size = new_size;

    fread(ds->offsets, sizeof(long), ds->size, file);
    fread(ds->keys, sizeof(int), ds->size, file);
    for (size_t i = 0; i < ds->size; ++i) {
        ds->records[i] = (record*)malloc(sizeof(record));
        fread(&ds->records[i]->value, sizeof(int), 1, file);
    }

    fclose(file);
}

int main() {
    data_structures* ds = create_data_structures(INITIAL_CAPACITY);
    if (!ds) return -1;

    srand(time(NULL));
    for (size_t i = 0; i < 5000; ++i) {
        add_record(ds, i, rand());
    }

    serialize_data_structures(ds, "data.bin");
    destroy_data_structures(ds);

    ds = create_data_structures(INITIAL_CAPACITY);
    if (!ds) return -1;

    deserialize_data_structures(ds, "data.bin");

    for (size_t i = 0; i < ds->size; ++i) {
        printf("Key: %d, Value: %d\n", ds->keys[i], ds->records[i]->value);
    }

    destroy_data_structures(ds);

    return 0;
}
