#define ALIGNMENT 64

typedef struct {
    int id;
    char* payload;
} CUSTOM_EVENT_RECORD;

int allocate_event_pipeline(int num_records, int payload_length) {
    if (num_records <= 0 || payload_length <= 0) {
        return -1; // Invalid input
    }

    size_t aligned_size = ((payload_length + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;
    char* memory_block = malloc(num_records * sizeof(CUSTOM_EVENT_RECORD) + num_records * aligned_size);
    if (!memory_block) {
        return -2; // Memory allocation failed
    }

    CUSTOM_EVENT_RECORD* records = (CUSTOM_EVENT_RECORD*)memory_block;
    char* payload_buffers = (char*)(records + num_records);

    for (int i = 0; i < num_records; ++i) {
        records[i].id = i + 1;
        records[i].payload = payload_buffers + i * aligned_size;
        memset(records[i].payload, 0, aligned_size); // Initialize payload buffer
    }

    return 0; // Success
}

void free_event_pipeline(CUSTOM_EVENT_RECORD* records, int num_records) {
    if (records) {
        free(records);
    }
}
