#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTS_PER_FILE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

void init_nfaip_crc_array(NFAPI_CRC_ARRAY *arr, size_t initial_capacity) {
    arr->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr->array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    arr->count = 0;
    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->mutex, NULL);
}

void free_nfaip_crc_array(NFAPI_CRC_ARRAY *arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->array);
    arr->array = NULL;
    arr->count = 0;
    arr->capacity = 0;
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

void add_nfaip_crc_to_array(NFAPI_CRC_ARRAY *arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity == 0 ? 1 : arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        arr->array = new_array;
        arr->capacity = new_capacity;
    }
    arr->array[arr->count++] = pdu;
    pthread_mutex_unlock(&arr->mutex);
}

void serialize_nfaip_crc_array(NFAPI_CRC_ARRAY *arr, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    pthread_mutex_lock(&arr->mutex);
    size_t written = fwrite(arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), arr->count, file);
    if (written != arr->count) {
        fprintf(stderr, "Error during serialization\n");
    }
    pthread_mutex_unlock(&arr->mutex);
    fclose(file);
}

int deserialize_nfaip_crc_array(NFAPI_CRC_ARRAY *arr, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return -1;
    }
    pthread_mutex_lock(&arr->mutex);
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    size_t count = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (count > MAX_STRUCTS_PER_FILE) {
        fprintf(stderr, "Too many structures in the file\n");
        pthread_mutex_unlock(&arr->mutex);
        fclose(file);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        pthread_mutex_unlock(&arr->mutex);
        fclose(file);
        return -1;
    }
    arr->array = new_array;
    arr->count = count;
    size_t read = fread(arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    if (read != count) {
        fprintf(stderr, "Error during deserialization\n");
        pthread_mutex_unlock(&arr->mutex);
        fclose(file);
        return -1;
    }
    pthread_mutex_unlock(&arr->mutex);
    fclose(file);
    return 0;
}
