    ArrayElement* elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

typedef struct {
    char buffer[MAX_LOG_SIZE];
    size_t head;
    size_t tail;
    pthread_mutex_t logMutex;
} LogBuffer;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->elements = (ArrayElement*)calloc(initial_capacity, sizeof(ArrayElement));
    if (!array->elements) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->elements);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

LogBuffer* create_log_buffer() {
    LogBuffer* buffer = (LogBuffer*)malloc(sizeof(LogBuffer));
    if (!buffer) return NULL;

    pthread_mutex_init(&buffer->logMutex, NULL);
    buffer->head = 0;
    buffer->tail = 0;

    return buffer;
}

void destroy_log_buffer(LogBuffer* buffer) {
    pthread_mutex_lock(&buffer->logMutex);
    buffer->head = 0;
    buffer->tail = 0;
    pthread_mutex_unlock(&buffer->logMutex);
    pthread_mutex_destroy(&buffer->logMutex);
    free(buffer);
}

