    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        ArrayElement* new_elements = (ArrayElement*)realloc(array->elements, new_capacity * sizeof(ArrayElement));
        if (!new_elements) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->elements = new_elements;
        array->capacity = new_capacity;
    }

    array->elements[array->size].data = data;
    array->elements[array->size].index = array->size;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return 0; // Success
}

int remove_element_by_index(DynamicArray* array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->size) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Index out of bounds
    }

    for (size_t i = index; i < array->size - 1; i++) {
        array->elements[i] = array->elements[i + 1];
    }
    array->size--;
    pthread_mutex_unlock(&array->mutex);
    return 0; // Success
}

int remove_element_by_tag(DynamicArray* array, RX_UE_INFORMATION_TAG tag) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        if (array->elements[i].data.RX_UE_INFORMATION_TAG == tag) {
            remove_element_by_index(array, i);
            pthread_mutex_unlock(&array->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Tag not found
}

void iterate_array(DynamicArray* array, void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        operation(&array->elements[i].data);
    }
    pthread_mutex_unlock(&array->mutex);
}

void log_operation(LogBuffer* buffer, const char* operation, size_t index, RX_UE_INFORMATION_TAG tag) {
    pthread_mutex_lock(&buffer->logMutex);
    size_t next_tail = (buffer->tail + 1) % MAX_LOG_SIZE;
    if (next_tail != buffer->head) {
        snprintf(buffer->buffer + buffer->tail * sizeof(char), sizeof(char), "%s, Index: %zu, Tag: %d\n", operation, index, tag);
        buffer->tail = next_tail;
    }
    pthread_mutex_unlock(&buffer->logMutex);
}

void clear_array_and_log(DynamicArray* array, LogBuffer* log) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        log_operation(log, "Remove", array->elements[i].index, array->elements[i].data.RX_UE_INFORMATION_TAG);
    }
    free(array->elements);
    array->elements = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}
