NFAPI_CRC_COLLECTION_T* create_collection(size_t initial_capacity) {
    NFAPI_CRC_COLLECTION_T *collection = (NFAPI_CRC_COLLECTION_T*)malloc(sizeof(NFAPI_CRC_COLLECTION_T));
    collection->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_to_collection(NFAPI_CRC_COLLECTION_T *collection, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        collection->capacity *= 2;
        collection->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->data, collection->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    collection->data[collection->size++] = item;
    pthread_mutex_unlock(&collection->lock);
}

void remove_from_collection(NFAPI_CRC_COLLECTION_T *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    if (index < collection->size) {
        for (size_t i = index; i < collection->size - 1; ++i) {
            collection->data[i] = collection->data[i + 1];
        }
        --collection->size;
    }
    pthread_mutex_unlock(&collection->lock);
}

void iterate_collection(NFAPI_CRC_COLLECTION_T *collection, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&collection->lock);
