        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    list->messages = new_messages;

    LTE_RRC_CU_MSG* msg = (LTE_RRC_CU_MSG*)malloc(sizeof(LTE_RRC_CU_MSG));
    if (!msg) {
