    strncpy(ue_context->RRC_CONNECTION_ESTABLISHMENT_REQUEST, "Establishment REQUEST", sizeof(ue_context->RRC_CONNECTION_ESTABLISHMENT_REQUEST));

    msg->ue_context = ue_context;

    list->messages[list->count++] = msg;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

