}

void add_request(DynamicList *list, HttpRequest request) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity > 0 ? list->capacity * 2 : 1;
        list->requests = realloc(list->requests, new_capacity * sizeof(HttpRequest));
        list->capacity = new_capacity;
    }
    memcpy(&list->requests[list->count], &request, sizeof(HttpRequest));
    ++list->count;
    pthread_mutex_unlock(&list->lock);
}

