int parse_json_config(const char* filename, Record** records, int* num_records) {
    struct json_object *parsed_json;
    struct json_object *array_obj;
    struct json_object *record_obj;
    struct json_object *value_obj, *offset_obj, *key_obj;

    parsed_json = json_tokener_parse_file(filename);
    if (!parsed_json) {
        fprintf(stderr, "Failed to parse JSON file\n");
        return -1;
    }

    array_obj = json_object_object_get_ex(parsed_json, "records", &record_obj) ? record_obj : NULL;
    if (!array_obj || !json_object_is_type(array_obj, json_type_array)) {
        fprintf(stderr, "Invalid JSON format: 'records' field is missing or not an array\n");
        json_object_put(parsed_json);
        return -1;
    }

    *num_records = json_object_array_length(array_obj);
    if (*num_records > MAX_ENTRIES) {
        fprintf(stderr, "Too many records in the configuration file\n");
        json_object_put(parsed_json);
        return -1;
    }

    *records = (Record*)malloc(*num_records * sizeof(Record));
    if (!*records) {
        perror("Failed to allocate memory for records");
        json_object_put(parsed_json);
        return -1;
    }

    for (int i = 0; i < *num_records; i++) {
        record_obj = json_object_array_get_idx(array_obj, i);
        value_obj = json_object_object_get_ex(record_obj, "value", &key_obj) ? key_obj : NULL;
        offset_obj = json_object_object_get_ex(record_obj, "offset", &key_obj) ? key_obj : NULL;
        key_obj = json_object_object_get_ex(record_obj, "key", &key_obj) ? key_obj : NULL;

        if (!value_obj || !json_object_is_type(value_obj, json_type_int) ||
            !offset_obj || !json_object_is_type(offset_obj, json_type_int) ||
            !key_obj || !json_object_is_type(key_obj, json_type_int)) {
            fprintf(stderr, "Invalid JSON format: record %d is missing or has invalid fields\n", i);
            free(*records);
            json_object_put(parsed_json);
            return -1;
        }

        (*records)[i].value = json_object_get_int(value_obj);
        (*records)[i].offset = json_object_get_int(offset_obj);
        (*records)[i].key = json_object_get_int(key_obj);
    }

    json_object_put(parsed_json);
    return 0;
}

int main() {
    Record* records;
    int num_records;

    if (parse_json_config("config.json", &records, &num_records) != 0) {
        fprintf(stderr, "Failed to parse JSON configuration file\n");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_nfaapi_crc_indication_pdu(records[i].value, records[i].offset, records[i].key);
        if (!pdu) {
            fprintf(stderr, "Failed to create NFAPI_CRC_INDICATION_PDU_T for record %d\n", i);
            continue;
        }
        // Use the pdu as needed
        free_nfaapi_crc_indication_pdu(pdu);
    }

    free(records);
    return 0;
}
