['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1024

typedef struct {
    int RNTI;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == entry.RNTI) {
            printf("Error: Duplicate RNTI detected.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }
    if (list->count >= MAX_ENTRIES) {
        printf("Error: List is full.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == RNTI) {
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    printf("Error: RNTI not found.\n");
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_RNTI(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return &list->entries[i];
        }
    }
    pthread_mutex_unlock(&list->lock);
    printf("Error: RNTI not found.\n");
    return NULL;
}

void cleanup_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (time(NULL) - list->entries[i].timestamp > 5) {
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
            i--;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void print_statistics(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    int unique_RNTI = 0;
    for (int i = 0; i < list->count; i++) {
        if (i == 0 || list->entries[i].RNTI != list->entries[i - 1].RNTI) {
            unique_RNTI++;
        }
    }
    time_t total_age = 0;
    for (int i = 0; i < list->count; i++) {
        total_age += time(NULL) - list->entries[i].timestamp;
    }
    double average_age = (list->count > 0) ? (double)total_age / list->count : 0;
    printf("Active entries: %d\n", list->count);
    printf("Unique RNTI values: %d\n", unique_RNTI);
    printf("Average age of entries: %.2f seconds\n", average_age);
    pthread_mutex_unlock(&list->lock);
}

void* periodic_cleanup(void *arg) {
    DynamicList *list = (DynamicList *)arg;
    while (1) {
        cleanup_list(list);
        sleep(5); // Cleanup every 5 seconds
    }
    return NULL;
}
