int compare_rnti(const void *a, const void *b) {
    return ((NFAPI_CRC_INDICATION_PDU_T *)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T *)b)->RNTI;
}

void* generate_and_sort_structs(void *arg) {
    int *N = (int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *structs = malloc(*N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structs) {
        perror("Memory allocation failed");
        return NULL;
