    for (int i = 0; i < *N; i++) {
        structs[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structs[i].RNTI = rand() % 500;
        structs[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        structs[i].CRCFLAG = rand() % 2;
    }

    qsort(structs, *N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    // Simulate external API processing
    int unique_rntis = 0;
    for (int i = 0; i < *N; i++) {
        if (i == 0 || structs[i].RNTI != structs[i - 1].RNTI) {
            unique_rntis++;
        }
    }

    free(structs);
    return (void *)(long)unique_rntis;
}

