#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ThreadSafeList;

void initialize_list(ThreadSafeList *list, size_t initial_capacity) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void resize_list(ThreadSafeList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

void add_to_list(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        resize_list(list);
    }
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
}

void generate_and_populate(ThreadSafeList *list, size_t N) {
    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T item;
        // Simulate dynamic tag retrieval and validation
        item.RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        item.RNTI = rand() % 256;
        item.CRCFLAG = rand() % 2;
        add_to_list(list, item);
    }
}

int main() {
    ThreadSafeList list;
    initialize_list(&list, 1000);

    clock_t start_time = clock();
    generate_and_populate(&list, MAX_STRUCTURES);
    clock_t end_time = clock();

    double elapsed_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("Time taken: %f seconds\n", elapsed_time);

    pthread_mutex_destroy(&list.lock);
    free(list.data);
    return 0;
}
