DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->pdus);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_pdu(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }
    array->pdus[array->size++] = pdu;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void update_pdu(DynamicArray *array, int index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        array->pdus[index] = pdu;
    }
    pthread_mutex_unlock(&array->lock);
}

void mark_active(DynamicArray *array, int index) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        array->pdus[index].active = 1;
    }
    pthread_mutex_unlock(&array->lock);
}

void mark_inactive(DynamicArray *array, int index) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        array->pdus[index].active = 0;
    }
    pthread_mutex_unlock(&array->lock);
}

int prune_inactive_pdus(DynamicArray *array) {
    int pruned_count = 0;
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ) {
        if (!array->pdus[i].active) {
            for (size_t j = i + 1; j < array->size; ++j) {
                array->pdus[j - 1] = array->pdus[j];
            }
            --array->size;
            ++pruned_count;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return pruned_count;
}

