InterfaceConfig configs[MAX_CONFIGS];
int config_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* load_configs(void* arg) {
    // Simulate loading configurations from a networked storage service
    for (int i = 0; i < MAX_CONFIGS; i++) {
        snprintf(configs[i].ip, sizeof(configs[i].ip), "192.168.%d.%d", i / 256, i % 256);
        snprintf(configs[i].subnet_mask, sizeof(configs[i].subnet_mask), "255.255.255.0");
        snprintf(configs[i].gateway, sizeof(configs[i].gateway), "192.168.%d.1", i / 256);
        configs[i].id = i;
        configs[i].flags = rand();
    }
    config_count = MAX_CONFIGS;
    return NULL;
}

void save_configs() {
    // Simulate saving configurations back to a remote database
    for (int i = 0; i < config_count; i++) {
        printf("Saving config %d: IP=%s, Subnet=%s, Gateway=%s, Flags=0x%lx\n",
               configs[i].id, configs[i].ip, configs[i].subnet_mask, configs[i].gateway, configs[i].flags);
    }
}

void add_config(InterfaceConfig* new_config) {
    pthread_mutex_lock(&mutex);
    if (config_count < MAX_CONFIGS) {
        memcpy(&configs[config_count], new_config, sizeof(InterfaceConfig));
        config_count++;
    } else {
        printf("Error: Maximum number of configurations reached.\n");
    }
    pthread_mutex_unlock(&mutex);
}

void remove_config(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < config_count; i++) {
        if (configs[i].id == id) {
            memmove(&configs[i], &configs[i + 1], sizeof(InterfaceConfig) * (config_count - i - 1));
            config_count--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void modify_config(int id, InterfaceConfig* new_config) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < config_count; i++) {
        if (configs[i].id == id) {
            memcpy(&configs[i], new_config, sizeof(InterfaceConfig));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void validate_config(InterfaceConfig* config) {
    // Simple validation for demonstration purposes
    if (strlen(config->ip) != 15 || strlen(config->subnet_mask) != 15 || strlen(config->gateway) != 15) {
        printf("Error: Invalid IP, subnet mask, or gateway format.\n");
        exit(1);
    }
}

int main() {
    srand(time(NULL));
    pthread_t load_thread;
    pthread_create(&load_thread, NULL, load_configs, NULL);
    pthread_join(load_thread, NULL);

    InterfaceConfig new_config = {0};
    strcpy(new_config.ip, "192.168.1.1");
    strcpy(new_config.subnet_mask, "255.255.255.0");
    strcpy(new_config.gateway, "192.168.1.254");
