<?php

class PasswordService {
    private $db;
    private $cache;
    private $logger;

    public function __construct($db, $cache, $logger) {
        $this->db = $db;
        $this->cache = $cache;
        $this->logger = $logger;
    }

    public function updatePassword($userId, $newPassword, $historyPeriod) {
        $maxRetries = 3;
        for ($retryCount = 0; $retryCount <= $maxRetries; $retryCount++) {
            try {
                if (!$this->isPasswordComplex($newPassword)) {
                    throw new Exception("Password does not meet complexity requirements.");
                }

                if ($this->isPasswordSimilarToHistory($userId, $newPassword, $historyPeriod)) {
                    throw new Exception("Password is too similar to previous passwords.");
                }

                $this->db->beginTransaction();
                $this->cache->delete("password_history:$userId");
                $this->db->updateUserPassword($userId, password_hash($newPassword, PASSWORD_DEFAULT));
                $this->db->commit();

                $this->logger->logSuccess("Password updated successfully for user ID: $userId");

                return true;
            } catch (Exception $e) {
                if ($retryCount == $maxRetries) {
                    $this->logger->logFailure("Failed to update password for user ID: $userId. Reason: " . $e->getMessage());
                    throw $e;
                }

                $this->db->rollBack();
                sleep(1); // Exponential backoff
            }
        }
    }

    private function isPasswordComplex($password) {
        return preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $password);
    }

    private function isPasswordSimilarToHistory($userId, $newPassword, $historyPeriod) {
        $history = $this->cache->get("password_history:$userId");
        if ($history === false) {
            $history = [];
        } else {
            $history = json_decode($history, true);
        }

        foreach ($history as $oldPassword) {
            if (similar_text($newPassword, $oldPassword, $percent)) {
                return true;
            }
        }

        $history[] = $newPassword;
        if (count($history) > $historyPeriod) {
            array_shift($history);
        }

        $this->cache->set("password_history:$userId", json_encode($history), 3600); // Cache for 1 hour

        return false;
    }
}
