    if (!array) {
        fprintf(stderr, "Memory allocation failed for MAC_RX_UE_CONTEXT_ARRAY_T\n");
        return NULL;
    }

    array->allocated_size = max_ues + ALLOC_OVERHEAD;
    array->used_size = 0;

    array->contexts = (MAC_RX_UE_CONTEXT_T*)malloc(array->allocated_size * sizeof(MAC_RX_UE_CONTEXT_T));
    if (!array->contexts) {
        fprintf(stderr, "Memory allocation failed for MAC_RX_UE_CONTEXT_T array\n");
        free(array);
        return NULL;
    }

    return array;
}

void destroy_mac_rx_ue_context_array(MAC_RX_UE_CONTEXT_ARRAY_T *array) {
