        free(array->contexts);
    }
    free(array);
}

int add_mac_rx_ue_context(MAC_RX_UE_CONTEXT_ARRAY_T *array, int ue_id, int rnti, int cqi_config) {
    if (array->used_size >= array->allocated_size) {
        fprintf(stderr, "Array is full\n");
        return -1;
    }

    MAC_RX_UE_CONTEXT_T *new_context = &array->contexts[array->used_size];
    new_context->MAC_RX_UE_ID = ue_id;
    new_context->MAC_RNTI = rnti;
    new_context->CQI_Reporting_Configuration = cqi_config;

    array->used_size++;
    return 0;
}

