#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

// Define constants
#define MAX_DEVICES 100
#define MAX_DATA_POINTS 1000

// Define structures
typedef struct {
    int id;
    double data[MAX_DATA_POINTS];
    int count;
} SensorData;

typedef struct {
    double threshold;
    double variance;
    double correlation;
} AnomalyThresholds;

typedef struct {
    SensorData devices[MAX_DEVICES];
    AnomalyThresholds thresholds[MAX_DEVICES];
    time_t last_update;
} SensorLibrary;

// Function prototypes
void init_library(SensorLibrary *lib);
void process_data(SensorLibrary *lib, int device_id, double data_point);
double get_max_anomaly_score(SensorLibrary *lib);
void log_anomaly(SensorLibrary *lib, int device_id, double data_point, double score);

// Initialize the library
void init_library(SensorLibrary *lib) {
    memset(lib->devices, 0, sizeof(lib->devices));
    memset(lib->thresholds, 0, sizeof(lib->thresholds));
    lib->last_update = time(NULL);
}

// Process sensor data
void process_data(SensorLibrary *lib, int device_id, double data_point) {
    if (device_id >= MAX_DEVICES || device_id < 0) return;

    SensorData *dev = &lib->devices[device_id];
    AnomalyThresholds *thresh = &lib->thresholds[device_id];

    // Update data
    dev->data[dev->count++] = data_point;
    if (dev->count >= MAX_DATA_POINTS) {
        memmove(dev->data, dev->data + 1, sizeof(double) * (MAX_DATA_POINTS - 1));
        dev->count--;
    }

    // Calculate variance and correlation
    double sum = 0, mean = 0, var = 0, corr = 0;
    for (int i = 0; i < dev->count; i++) {
        sum += dev->data[i];
    }
    mean = sum / dev->count;

    for (int i = 0; i < dev->count; i++) {
        var += pow(dev->data[i] - mean, 2);
    }
    var /= dev->count;

    if (dev->count > 1) {
        double sum_corr = 0;
        for (int i = 0; i < dev->count; i++) {
            for (int j = i + 1; j < dev->count; j++) {
                sum_corr += (dev->data[i] - mean) * (dev->data[j] - mean);
            }
        }
        corr = sum_corr / ((dev->count - 1) * sqrt(var));
    }

    // Update thresholds
    thresh->variance = var;
    thresh->correlation = corr;

    // Detect anomaly
    double score = fabs(data_point - mean) / sqrt(var);
    if (score > thresh->threshold) {
        log_anomaly(lib, device_id, data_point, score);
    }
}

// Get the maximum anomaly score
double get_max_anomaly_score(SensorLibrary *lib) {
    double max_score = 0;
    for (int i = 0; i < MAX_DEVICES; i++) {
        if (lib->devices[i].count > 0) {
            double score = fabs(lib->devices[i].data[lib->devices[i].count - 1] -
                               lib->thresholds[i].variance) /
                           sqrt(lib->thresholds[i].variance);
            if (score > max_score) {
                max_score = score;
            }
        }
    }
    return max_score;
}

// Log an anomaly
void log_anomaly(SensorLibrary *lib, int device_id, double data_point, double score) {
    printf("Anomaly detected: Device ID %d, Data Point %.2f, Score %.2f\n", device_id, data_point, score);
}
