typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int hash_function(int rnti, time_t timestamp, const char* config_data) {
    // Implement a simple hash function
    return (rnti * timestamp + strlen(config_data)) % 1000000;
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T** array, int N, int seed, const char* config_path) {
    srand(seed);
    FILE* config_file = fopen(config_path, "r");
    if (!config_file) {
        perror("Failed to open configuration file");
        return;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        perror("Memory allocation failed");
        fclose(config_file);
        return;
    }

    char config_data[1024];
    time_t timestamp = time(NULL);

    for (int i = 0; i < N; i++) {
        int rnti = rand() % 65536; // Random RNTI
        (*array)[i].RNTI = rnti;
        (*array)[i].RX_UE_INFORMATION_TAG = hash_function(rnti, timestamp, config_data);
        if (fgets(config_data, sizeof(config_data), config_file) == NULL) {
            perror("Failed to read configuration data");
            free(*array);
            fclose(config_file);
            return;
        }
        (*array)[i].CRC_INDICATION_REL8_TAG = i; // Example CRC tag
        (*array)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    fclose(config_file);
}

void validate_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    for (int i = 0; i < N; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == 0 || array[i].CRCFLAG > 1) {
            fprintf(stderr, "Validation failed at index %d\n", i);
        }
    }
}

void cleanup_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    free(array);
}

int main() {
    int N = 10;
    int seed = time(NULL);
    const char* config_path = "config.txt";

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    populate_array(&array, N, seed, config_path);

    if (array != NULL) {
        validate_array(array, N);
        cleanup_array(array, N);
    }

    return 0;
}
