#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 10000
#define INACTIVITY_THRESHOLD 300 // 5 minutes in seconds

typedef struct {
    char session_id[256];
    char user_agent[256];
    time_t last_active;
    int request_count;
} Session;

Session sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(const char* session_id, const char* user_agent) {
    pthread_mutex_lock(&session_lock);
    if (session_count < MAX_SESSIONS) {
        strcpy(sessions[session_count].session_id, session_id);
        strcpy(sessions[session_count].user_agent, user_agent);
        sessions[session_count].last_active = time(NULL);
        sessions[session_count].request_count = 0;
        session_count++;
    }
    pthread_mutex_unlock(&session_lock);
}

void update_session(const char* session_id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].session_id, session_id) == 0) {
            sessions[i].last_active = time(NULL);
            sessions[i].request_count++;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void remove_expired_sessions() {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; ) {
        if (time(NULL) - sessions[i].last_active > INACTIVITY_THRESHOLD) {
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            session_count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void* manage_sessions(void* arg) {
    while (1) {
        remove_expired_sessions();
        // Simulate periodic computation of average request rate
        sleep(60); // Every minute
    }
    return NULL;
}

int main() {
    pthread_t session_manager_thread;
    pthread_create(&session_manager_thread, NULL, manage_sessions, NULL);

    add_session("12345", "Mozilla/5.0");
    update_session("12345");

    pthread_join(session_manager_thread, NULL);
    return 0;
}
```

This code provides a basic structure for managing user sessions in a C-based service module. It includes functions to add, update, and remove sessions, as well as a thread that periodically removes expired sessions based on an inactivity threshold. The use of mutexes ensures thread safety when accessing the session data. This example can be expanded with additional features such as persistence, logging, and more sophisticated session management strategies.']

