#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char hwid[50];
    char software_version[20];
    int operational_state;
} DeviceConfig;

typedef struct Node {
    DeviceConfig data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ConfigList;

void init_config_list(ConfigList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_config_list(ConfigList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int add_device_config(ConfigList* list, DeviceConfig config) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data = config;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_device_config(ConfigList* list, char* hwid) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (strcmp(current->data.hwid, hwid) == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Configuration removed successfully
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Configuration not found
}

int validate_config(DeviceConfig config) {
