#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    char source_ip[16];
    char destination_ip[16];
    int payload_length;
    // Additional metadata fields here
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PacketManager;

void init_packet_manager(PacketManager *manager, size_t initial_capacity) {
    manager->packets = (NetworkPacket *)malloc(initial_capacity * sizeof(NetworkPacket));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->mutex, NULL);
}

void add_packet(PacketManager *manager, NetworkPacket packet) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->packets = (NetworkPacket *)realloc(manager->packets, new_capacity * sizeof(NetworkPacket));
        manager->capacity = new_capacity;
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->mutex);
}

void update_packet(PacketManager *manager, size_t index, NetworkPacket packet) {
    pthread_mutex_lock(&manager->mutex);
    if (index < manager->count) {
        manager->packets[index] = packet;
    }
    pthread_mutex_unlock(&manager->mutex);
}

int calculate_total_data_transferred(PacketManager *manager) {
    int total_data = 0;
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        total_data += manager->packets[i].payload_length;
    }
    pthread_mutex_unlock(&manager->mutex);
    return total_data;
}

void destroy_packet_manager(PacketManager *manager) {
    free(manager->packets);
    pthread_mutex_destroy(&manager->mutex);
}
