#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024

typedef struct {
    uint64_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_length;
    NFAPI_CRC_INDICATION_PDU_T metadata;
} NetworkPacket;

typedef struct {
    NetworkPacket packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_packet(PacketManager *manager, NetworkPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Packet manager is full
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_packet(PacketManager *manager, int index, NetworkPacket new_packet) {
    pthread_mutex_lock(&manager->lock);
    if (index < 0 || index >= manager->count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Invalid packet index
    }
    manager->packets[index] = new_packet;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

size_t calculate_total_data_transferred(PacketManager *manager) {
    size_t total = 0;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        total += manager->packets[i].payload_length;
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}

