void destroy_dynamic_array(DynamicArray *array) {
    free(array->messages);
    free(array);
}

int insert_message(DynamicArray *array, LTE_RRC_CU_UP_MESSAGE message) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_RRC_CU_UP_MESSAGE *new_messages = (LTE_RRC_CU_UP_MESSAGE*)realloc(array->messages, new_capacity * sizeof(LTE_RRC_CU_UP_MESSAGE));
        if (!new_messages) return -1;
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    size_t i;
    for (i = array->count; i > 0 && array->messages[i-1].PDCP_SN > message.PDCP_SN; --i) {
        array->messages[i] = array->messages[i-1];
    }
    array->messages[i] = message;
    ++array->count;
    return 0;
}

int delete_message(DynamicArray *array, uint32_t PDCP_SN) {
    size_t i;
    for (i = 0; i < array->count && array->messages[i].PDCP_SN != PDCP_SN; ++i);
    if (i == array->count) return -1;
    memmove(&array->messages[i], &array->messages[i+1], (array->count-i-1) * sizeof(LTE_RRC_CU_UP_MESSAGE));
    --array->count;
    return 0;
}

LTE_RRC_CU_UP_MESSAGE* get_message(DynamicArray *array, uint32_t PDCP_SN) {
    size_t i;
    for (i = 0; i < array->count && array->messages[i].PDCP_SN != PDCP_SN; ++i);
    if (i == array->count) return NULL;
    return &array->messages[i];
}

