#include <time.h>

#define MAX_SESSIONS 10000

typedef struct {
    int session_id;
    char user_ip[16];
    time_t start_time;
    void* data_buffer;
    size_t data_size;
} SessionContext;

SessionContext* session_pool[MAX_SESSIONS];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_session(const char* user_ip, size_t data_size) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (session_pool[i] == NULL) {
            session_pool[i] = malloc(sizeof(SessionContext));
            if (session_pool[i] == NULL) {
                pthread_mutex_unlock(&pool_lock);
                return -1; // Memory allocation failed
            }
            session_pool[i]->session_id = i;
            strncpy(session_pool[i]->user_ip, user_ip, 15);
            session_pool[i]->user_ip[15] = '\0';
            session_pool[i]->start_time = time(NULL);
            session_pool[i]->data_buffer = malloc(data_size);
            if (session_pool[i]->data_buffer == NULL) {
                free(session_pool[i]);
                session_pool[i] = NULL;
                pthread_mutex_unlock(&pool_lock);
                return -1; // Memory allocation failed
            }
            session_pool[i]->data_size = data_size;
            pthread_mutex_unlock(&pool_lock);
            return i; // Successfully allocated session
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return -1; // No available sessions
}

void free_session(int session_id) {
    if (session_id >= 0 && session_id < MAX_SESSIONS) {
        pthread_mutex_lock(&pool_lock);
        if (session_pool[session_id] != NULL) {
            free(session_pool[session_id]->data_buffer);
            free(session_pool[session_id]);
            session_pool[session_id] = NULL;
        }
        pthread_mutex_unlock(&pool_lock);
    }
}
