} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->messages = (LTE_RRC_CU_UP_MESSAGE*)malloc(10 * sizeof(LTE_RRC_CU_UP_MESSAGE));
    if (!array->messages) {
        free(array);
        return NULL;
    }
    array->count = 0;
    array->capacity = 10;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->messages);
    pthread_mutex_unlock(&array->lock);
    free(array);
}

int insert_message(DynamicArray *array, LTE_RRC_CU_UP_MESSAGE message) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_RRC_CU_UP_MESSAGE *new_messages = (LTE_RRC_CU_UP_MESSAGE*)realloc(array->messages, new_capacity * sizeof(LTE_RRC_CU_UP_MESSAGE));
        if (!new_messages) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    size_t i;
    for (i = array->count; i > 0 && array->messages[i-1].PDCP_SN > message.PDCP_SN; --i) {
        array->messages[i] = array->messages[i-1];
    }
    array->messages[i] = message;
    ++array->count;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int delete_message(DynamicArray *array, uint32_t PDCP_SN) {
    pthread_mutex_lock(&array->lock);
    size_t i;
    for (i = 0; i < array->count && array->messages[i].PDCP_SN != PDCP_SN; ++i);
    if (i == array->count) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Message not found
    }
    for (; i < array->count - 1; ++i) {
        array->messages[i] = array->messages[i+1];
    }
    --array->count;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

LTE_RRC_CU_UP_MESSAGE* retrieve_message(DynamicArray *array, uint32_t PDCP_SN) {
    pthread_mutex_lock(&array->lock);
    size_t i;
    for (i = 0; i < array->count && array->messages[i].PDCP_SN != PDCP_SN; ++i);
    if (i == array->count) {
        pthread_mutex_unlock(&array->lock);
        return NULL; // Message not found
    }
    LTE_RRC_CU_UP_MESSAGE *message = &array->messages[i];
    pthread_mutex_unlock(&array->lock);
    return message;
}

