#include <time.h>
#include <pthread.h>

#define CACHE_ALIGN 64

typedef struct {
    char** keys;
    void** data;
    size_t max_entries;
    size_t entry_count;
    pthread_rwlock_t lock;
} Cache;

Cache* cache_create(size_t max_entries) {
    Cache* cache = (Cache*)aligned_alloc(CACHE_ALIGN, sizeof(Cache));
    if (!cache) return NULL;

    cache->keys = (char**)aligned_alloc(CACHE_ALIGN, max_entries * sizeof(char*));
    cache->data = (void**)aligned_alloc(CACHE_ALIGN, max_entries * sizeof(void*));
    if (!cache->keys || !cache->data) {
        free(cache);
        return NULL;
    }

    cache->max_entries = max_entries;
    cache->entry_count = 0;
    pthread_rwlock_init(&cache->lock, NULL);

    return cache;
}

void cache_destroy(Cache* cache) {
    if (cache) {
        for (size_t i = 0; i < cache->entry_count; ++i) {
            free(cache->keys[i]);
            // Free data if necessary
        }
        free(cache->keys);
        free(cache->data);
        pthread_rwlock_destroy(&cache->lock);
        free(cache);
    }
}

void* cache_get(Cache* cache, const char* key) {
    pthread_rwlock_rdlock(&cache->lock);
    for (size_t i = 0; i < cache->entry_count; ++i) {
        if (strcmp(cache->keys[i], key) == 0) {
            void* data = cache->data[i];
            pthread_rwlock_unlock(&cache->lock);
            return data;
        }
    }
    pthread_rwlock_unlock(&cache->lock);
    return NULL;
}

int cache_set(Cache* cache, const char* key, void* data) {
    pthread_rwlock_wrlock(&cache->lock);
    if (cache->entry_count >= cache->max_entries) {
        pthread_rwlock_unlock(&cache->lock);
        return -1; // Cache full
    }

    char* new_key = strdup(key);
    if (!new_key) {
        pthread_rwlock_unlock(&cache->lock);
        return -2; // Memory allocation failed
    }

    cache->keys[cache->entry_count] = new_key;
    cache->data[cache->entry_count++] = data;
    pthread_rwlock_unlock(&cache->lock);

    return 0;
}

