typedef struct {
    int key;
    char *user_id;
    pthread_mutex_t lock;
} HashEntry;

typedef struct {
    HashEntry **entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t table_lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->size = 0;
    table->entries = (HashEntry**)calloc(initial_capacity, sizeof(HashEntry*));
    if (!table->entries) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->table_lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        table->entries[i] = (HashEntry*)malloc(sizeof(HashEntry));
        if (!table->entries[i]) {
            for (size_t j = 0; j < i; ++j) free(table->entries[j]);
            free(table->entries);
            free(table);
            return NULL;
        }
        table->entries[i]->key = -1;
        table->entries[i]->user_id = NULL;
        pthread_mutex_init(&table->entries[i]->lock, NULL);
    }

    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->entries[i]->key != -1) {
            free(table->entries[i]->user_id);
        }
        pthread_mutex_destroy(&table->entries[i]->lock);
        free(table->entries[i]);
    }
    free(table->entries);
    pthread_mutex_destroy(&table->table_lock);
    free(table);
}

