            // Handle memory allocation failure for data buffer
            free(packets); // Free previously allocated memory
            return NULL;
        }
    }

    return packets;
}

void destroy_packets(DataPacket *packets, size_t num_packets) {
    for (size_t i = 0; i < num_packets; ++i) {
        free(packets[i].data);
    }
    free(packets);
}
