typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_crc_array(size_t initial_capacity) {
    NFAPI_CRC_ARRAY *array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY *array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->array);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_crc_entry(NFAPI_CRC_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!array || !array->array) return -1;

    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->size++] = entry;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

int update_crc_entry(NFAPI_CRC_ARRAY *array, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    if (!array || !array->array) return -1;

    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RNTI == rnti) {
            array->array[i] = new_entry;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);

    return -1;
}

int remove_crc_entry(NFAPI_CRC_ARRAY *array, uint16_t rnti) {
    if (!array || !array->array) return -1;

    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RNTI == rnti) {
            memmove(&array->array[i], &array->array[i + 1], (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array->size--;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);

    return -1;
}
