#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define RECORD_SIZE 32
#define DEFAULT_CHAR_VALUE 'A'
#define COMPRESSION_THRESHOLD 0.5

typedef struct {
    int value;
    char buffer[16];
} record;

void* aligned_malloc(size_t size, size_t alignment) {
    void* ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

void initialize_records(record** records, long* offsets, int* keys, size_t num_records, int value_range, char default_char) {
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * RECORD_SIZE;
        keys[i] = i % value_range;
        records[i]->value = keys[i];
        memset(records[i]->buffer, default_char, sizeof(records[i]->buffer));
    }
}

void compress_buffers(record** records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        int new_size = strlen(records[i]->buffer);
        if (new_size < sizeof(records[i]->buffer)) {
            memmove(records[i]->buffer, records[i]->buffer, new_size);
            memset(records[i]->buffer + new_size, '\0', sizeof(records[i]->buffer) - new_size);
        }
    }
}

void* allocate_memory(size_t num_records, size_t alignment) {
    long* offsets = aligned_malloc(num_records * sizeof(long), alignment);
    int* keys = aligned_malloc(num_records * sizeof(int), alignment);
    record** records = aligned_malloc(num_records * sizeof(record*), alignment);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i] = aligned_malloc(RECORD_SIZE, alignment);
        if (!records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    initialize_records(records, offsets, keys, num_records, value_range, DEFAULT_CHAR_VALUE);

    return records;
}

void deallocate_memory(void* memory, size_t num_records) {
    record** records = (record**)memory;

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }

    free(records);
}

int main() {
    size_t num_records = 100;
    void* memory = allocate_memory(num_records, 16);

    if (!memory) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    compress_buffers(memory, num_records);

    deallocate_memory(memory, num_records);

    return EXIT_SUCCESS;
}
