} Packet;

typedef struct PacketCaptureRecord {
    int network_interface_id;
    time_t timestamp;
    Packet *packets;
    size_t packet_count;
    pthread_mutex_t lock;
} PacketCaptureRecord;

PacketCaptureRecord* init_packet_capture_record(int interface_id) {
    PacketCaptureRecord *record = (PacketCaptureRecord*)malloc(sizeof(PacketCaptureRecord));
    if (!record) return NULL;

    record->network_interface_id = interface_id;
    record->timestamp = time(NULL);
    record->packets = NULL;
    record->packet_count = 0;
    pthread_mutex_init(&record->lock, NULL);

    return record;
}

void add_packet_to_record(PacketCaptureRecord *record, Packet packet) {
    pthread_mutex_lock(&record->lock);
    record->packets = (Packet*)realloc(record->packets, (record->packet_count + 1) * sizeof(Packet));
    if (!record->packets) {
        pthread_mutex_unlock(&record->lock);
        return;
    }
    record->packets[record->packet_count++] = packet;
    pthread_mutex_unlock(&record->lock);
}

void free_packet_capture_record(PacketCaptureRecord *record) {
    if (record->packets) free(record->packets);
    pthread_mutex_destroy(&record->lock);
    free(record);
}
