#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SIZE 10000
#define SYSTEM_LIMIT (5 * 1024 * 1024) // 5 MB

typedef struct {
    int value;
} record;

record* initialize_data_structures(int n, pthread_mutex_t* mutex) {
    if (n > MAX_SIZE) {
        fprintf(stderr, "Error: Input size exceeds maximum allowed.\n");
        return NULL;
    }

    size_t total_size = sizeof(long) * n + sizeof(int) * n + sizeof(record) * 2 * n;
    if (total_size > SYSTEM_LIMIT) {
        fprintf(stderr, "Error: Total memory consumption exceeds system limit.\n");
        return NULL;
    }

    record* records = (record*)malloc(2 * n * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        return NULL;
    }

    long* long_array = (long*)malloc(n * sizeof(long));
    if (!long_array) {
        free(records);
        fprintf(stderr, "Error: Failed to allocate memory for long array.\n");
        return NULL;
    }

    int* int_array = (int*)malloc(n * sizeof(int));
    if (!int_array) {
        free(long_array);
        free(records);
        fprintf(stderr, "Error: Failed to allocate memory for int array.\n");
        return NULL;
    }

    pthread_mutex_lock(mutex);

    // Initialize arrays
    for (int i = 0; i < n; i++) {
        long_array[i] = 0;
        int_array[i] = 0;
        records[i].value = 0;
    }

    pthread_mutex_unlock(mutex);

    return records;
}

void cleanup(record* records, long* long_array, int* int_array) {
    free(records);
