#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CAPACITY 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = MAX_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void add_entry(DynamicList *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->size].RNTI = RNTI;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(DynamicList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    fwrite(&list->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; i++) {
        fwrite(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(DynamicList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);
    if (new_size > MAX_CAPACITY) {
        fprintf(stderr, "Deserialized list exceeds maximum capacity\n");
        exit(EXIT_FAILURE);
    }
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->size = new_size;
    for (size_t i = 0; i < list->size; i++) {
        fread(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->lock);
}

void filter_list(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    size_t new_size = 0;
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            list->data[new_size++] = list->data[i];
        }
    }
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->size = new_size;
    pthread_mutex_unlock(&list->lock);
}

void log_operation(DynamicList *list, const char *operation) {
