typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int data;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t mutex;
} CRC_LIST;

void init_crc_list(CRC_LIST *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(int data) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(CRC_LIST *list, int data) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(data);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(CRC_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

void validate_list(CRC_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->next != NULL && current->data > current->next->data) {
            fprintf(stderr, "List corruption detected\n");
            exit(1);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void* update_list(void *arg) {
    CRC_LIST *list = (CRC_LIST*)arg;
    // Simulate data update from external source
    for (int i = 0; i < 10; i++) {
        add_to_list(list, rand() % 100);
        validate_list(list);
        sleep(1); // Simulate periodic updates
    }
    return NULL;
}

int main() {
    CRC_LIST list;
    init_crc_list(&list);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, update_list, &list) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        exit(1);
    }

    pthread_join(thread_id, NULL);

    free_list(&list);

    return 0;
}
