#include <pthread.h>
#include <string.h>

#define MAX_UE_CONTEXTS 1000

typedef struct {
    char imsi[16];
    int rnti;
    int servingCellId;
} UEContext;

typedef struct {
    UEContext contexts[MAX_UE_CONTEXTS];
    int count;
    pthread_mutex_t lock;
} UEModule;

void initUEModule(UEModule *module) {
    memset(module, 0, sizeof(UEModule));
    pthread_mutex_init(&module->lock, NULL);
}

int addOrUpdateUEContext(UEModule *module, const char *imsi, int rnti, int servingCellId) {
    pthread_mutex_lock(&module->lock);
    for (int i = 0; i < module->count; ++i) {
        if (strcmp(module->contexts[i].imsi, imsi) == 0) {
            module->contexts[i].rnti = rnti;
            module->contexts[i].servingCellId = servingCellId;
            pthread_mutex_unlock(&module->lock);
            return 1; // Updated
        }
    }
    if (module->count < MAX_UE_CONTEXTS) {
        strcpy(module->contexts[module->count].imsi, imsi);
        module->contexts[module->count].rnti = rnti;
        module->contexts[module->count].servingCellId = servingCellId;
        ++module->count;
        pthread_mutex_unlock(&module->lock);
        return 0; // Added
    }
    pthread_mutex_unlock(&module->lock);
    return -1; // Full
}

int removeUEContext(UEModule *module, const char *imsi) {
    pthread_mutex_lock(&module->lock);
    for (int i = 0; i < module->count; ++i) {
        if (strcmp(module->contexts[i].imsi, imsi) == 0) {
            for (int j = i; j < module->count - 1; ++j) {
                module->contexts[j] = module->contexts[j + 1];
            }
            --module->count;
            pthread_mutex_unlock(&module->lock);
            return 1; // Removed
        }
    }
    pthread_mutex_unlock(&module->lock);
    return 0; // Not found
}

void garbageCollectUEContexts(UEModule *module) {
    pthread_mutex_lock(&module->lock);
    for (int i = module->count - 1; i >= 0; --i) {
        if (/* condition to determine if context is stale */) {
            for (int j = i; j < module->count - 1; ++j) {
                module->contexts[j] = module->contexts[j + 1];
            }
            --module->count;
        }
    }
    pthread_mutex_unlock(&module->lock);
}

void logUEOperation(const char *operation, const char *imsi) {
    printf("%s: IMSI %s\n", operation, imsi);
}
