typedef enum {
    PENDING,
    RUNNING,
    COMPLETED
} task_status;

typedef struct {
    int priority;
    char* name;
    double progress;
    struct timeval timestamp;
    task_status status;
} Task;

Task* create_task(int min_priority, int max_priority, const char* prefix, double min_progress, double max_progress) {
    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) {
        perror("Memory allocation failed");
        return NULL;
    }

    task->priority = rand() % (max_priority - min_priority + 1) + min_priority;
    task->name = (char*)malloc(20 * sizeof(char));
    snprintf(task->name, 20, "%s%d", prefix, task->priority);
    task->progress = ((double)rand() / RAND_MAX) * (max_progress - min_progress) + min_progress;

    gettimeofday(&task->timestamp, NULL);

    int status_index = rand() % 3;
    switch (status_index) {
        case 0:
            task->status = PENDING;
            break;
        case 1:
            task->status = RUNNING;
            break;
        default:
            task->status = COMPLETED;
            break;
    }

    return task;
}

void free_task(Task* task) {
    if (task) {
        free(task->name);
        free(task);
    }
}

