#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char username[100];
    int id;
} UserDetails;

typedef enum {
    ACTIVE,
    INACTIVE,
    EXPIRED
} SessionState;

typedef struct UserSession {
    char token[50];
    UserDetails user;
    SessionState state;
    time_t loginTime;
    time_t lastActivity;
} UserSession;

typedef struct {
    UserSession** sessions;
    size_t capacity;
    size_t size;
} SessionManager;

void initSessionManager(SessionManager* manager, size_t initialCapacity) {
    manager->sessions = (UserSession**)malloc(initialCapacity * sizeof(UserSession*));
    manager->capacity = initialCapacity;
    manager->size = 0;
}

void freeSessionManager(SessionManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->sessions[i]);
    }
    free(manager->sessions);
}

UserSession* findSessionByToken(SessionManager* manager, const char* token) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->sessions[i]->token, token) == 0) {
            return manager->sessions[i];
        }
    }
    return NULL;
}

void addSession(SessionManager* manager, const char* token, UserDetails user) {
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = (UserSession**)realloc(manager->sessions, manager->capacity * sizeof(UserSession*));
    }
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    strcpy(session->token, token);
    session->user = user;
    session->state = ACTIVE;
    time(&session->loginTime);
    time(&session->lastActivity);
    manager->sessions[manager->size++] = session;
}

void updateSession(SessionManager* manager, const char* token) {
    UserSession* session = findSessionByToken(manager, token);
    if (session != NULL) {
        time(&session->lastActivity);
    }
}

void invalidateSessions(SessionManager* manager, time_t now, time_t inactivityThreshold) {
    for (size_t i = 0; i < manager->size; ++i) {
        UserSession* session = manager->sessions[i];
        if ((now - session->lastActivity > inactivityThreshold) && session->state != EXPIRED) {
            session->state = EXPIRED;
            time_t logoutTime;
            time(&logoutTime);
            printf("User %s logged out at %s\n", session->user.username, ctime(&logoutTime));
        }
    }
}

int main() {
    SessionManager manager;
    initSessionManager(&manager, 10);

    UserDetails user1 = {"john_doe", 1};
    addSession(&manager, "token123", user1);
    updateSession(&manager, "token123");

    time_t now;
    time(&now);
    invalidateSessions(&manager, now, 60 * 60); // Invalidate sessions inactive for more than an hour

    freeSessionManager(&manager);

    return 0;
}
