#include <string.h>
#include <pthread.h>

#define MAX_MESSAGES 10000

typedef struct {
    time_t timestamp;
    int priority;
    char *message_body;
} Message;

typedef struct {
    Message messages[MAX_MESSAGES];
    int count;
    pthread_mutex_t lock;
    FILE *log_file;
} MessageList;

void init_message_list(MessageList *list, const char *log_filename) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    if (log_filename != NULL) {
        list->log_file = fopen(log_filename, "w");
    } else {
        list->log_file = NULL;
    }
}

void destroy_message_list(MessageList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->messages[i].message_body);
    }
    pthread_mutex_destroy(&list->lock);
    if (list->log_file != NULL) {
        fclose(list->log_file);
    }
}

void append_message(MessageList *list, time_t timestamp, int priority, const char *message_body, size_t body_length) {
    pthread_mutex_lock(&list->lock);
    if (list->count < MAX_MESSAGES) {
        list->messages[list->count].timestamp = timestamp;
        list->messages[list->count].priority = priority;
        list->messages[list->count].message_body = malloc(body_length + 1);
        strncpy(list->messages[list->count].message_body, message_body, body_length);
        list->messages[list->count].message_body[body_length] = '\0';
        list->count++;
        if (list->log_file != NULL) {
            fprintf(list->log_file, "Inserted message at index %d\n", list->count - 1);
        }
    } else {
        printf("Message list is full.\n");
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_messages(MessageList *list, void (*callback)(const Message *)) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        callback(&list->messages[i]);
    }
    pthread_mutex_unlock(&list->lock);
}

int search_message_by_priority(MessageList *list, int priority) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->messages[i].priority == priority) {
            pthread_mutex_unlock(&list->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

void log_operation(MessageList *list, const char *operation) {
    if (list->log_file != NULL) {
        fprintf(list->log_file, "%s\n", operation);
    }
}
