// Custom memory management module functions
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void safe_free(void* ptr) {
    free(ptr);
}

// Function to initialize protocol configuration
ProtocolConfig* initialize_protocol_config(int timeout, size_t bufferSize, const char* encryptionKey, int versionNumber) {
    ProtocolConfig* config = (ProtocolConfig*)safe_malloc(sizeof(ProtocolConfig));

    // Validate and set parameters
    if (timeout < 0 || timeout > 600) {
        fprintf(stderr, "Invalid timeout value\n");
        safe_free(config);
        return NULL;
    }
    config->timeout = timeout;

    if (bufferSize < 1024 || bufferSize > 1024 * 1024) {
        fprintf(stderr, "Invalid buffer size\n");
        safe_free(config);
        return NULL;
    }
    config->bufferSize = bufferSize;

    if (encryptionKey == NULL || strlen(encryptionKey) < 8) {
        fprintf(stderr, "Invalid encryption key\n");
        safe_free(config);
        return NULL;
    }
    config->encryptionKey = strdup(encryptionKey);

    if (versionNumber < 1 || versionNumber > 99) {
        fprintf(stderr, "Invalid version number\n");
        free(config->encryptionKey);
        safe_free(config);
        return NULL;
    }
    config->versionNumber = versionNumber;

    return config;
}

// Function to load configuration from an external API or local database
ProtocolConfig* load_configuration_from_api() {
    // Simulate loading configuration from an API
    ProtocolConfig* config = initialize_protocol_config(30, 16 * 1024, "secureKey123", 1);
    return config;
}

// Function to handle hot-reload of configuration
void reload_configuration(ProtocolConfig** currentConfig) {
    ProtocolConfig* newConfig = load_configuration_from_api();
    if (newConfig != NULL) {
        // Safely update the current configuration without interfering with ongoing connections
        free((*currentConfig)->encryptionKey);
        safe_free(*currentConfig);
        *currentConfig = newConfig;
    }
}

// Function to log configuration load events
void log_configuration_event(ProtocolConfig* config, int success) {
    time_t now = time(NULL);
    if (success) {
        printf("Configuration loaded successfully at %s\n", ctime(&now));
    } else {
        printf("Failed to load configuration at %s\n", ctime(&now));
    }
}

// Main function for demonstration
int main() {
    ProtocolConfig* config = initialize_protocol_config(30, 16 * 1024, "secureKey123", 1);
    if (config != NULL) {
        log_configuration_event(config, 1);
        reload_configuration(&config);
        log_configuration_event(config, 1);
        free(config->encryptionKey);
        safe_free(config);
    }
    return 0;
}
