typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRC_Indication_Buffer;

void init_crc_indication_buffer(CRC_Indication_Buffer *buffer, size_t initial_capacity) {
    buffer->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (buffer->data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    buffer->capacity = initial_capacity;
    buffer->size = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

void free_crc_indication_buffer(CRC_Indication_Buffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    free(buffer->data);
    buffer->data = NULL;
    buffer->capacity = 0;
    buffer->size = 0;
    pthread_mutex_unlock(&buffer->mutex);
    pthread_mutex_destroy(&buffer->mutex);
}

void expand_crc_indication_buffer(CRC_Indication_Buffer *buffer) {
    size_t new_capacity = buffer->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(buffer->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    buffer->data = new_data;
    buffer->capacity = new_capacity;
}

void populate_crc_indications(CRC_Indication_Buffer *buffer, NFAPI_CRC_INDICATION_PDU_T *new_data, size_t count) {
    pthread_mutex_lock(&buffer->mutex);
    while (buffer->size + count > buffer->capacity) {
        expand_crc_indication_buffer(buffer);
    }
    for (size_t i = 0; i < count; ++i) {
        buffer->data[buffer->size++] = new_data[i];
    }
    pthread_mutex_unlock(&buffer->mutex);
}

int main() {
    CRC_Indication_Buffer buffer;
    init_crc_indication_buffer(&buffer, 1024);

    // Simulate data processing
    NFAPI_CRC_INDICATION_PDU_T new_data[1000];
    for (size_t i = 0; i < 1000; ++i) {
        populate_crc_indications(&buffer, &new_data[i], 1);
    }

    free_crc_indication_buffer(&buffer);
    return 0;
}
