#define MAX_JOB_QUEUE_SIZE 1000

typedef struct {
    char input_image_path[256];
    char output_pdf_path[256];
    int priority;
    double estimated_processing_time;
    int resource_requirements;
} Job;

typedef struct {
    Job jobs[MAX_JOB_QUEUE_SIZE];
    int front, rear;
} JobQueue;

void initialize_job_queue(JobQueue *queue) {
    queue->front = queue->rear = -1;
}

int is_full(JobQueue *queue) {
    return (queue->rear + 1) % MAX_JOB_QUEUE_SIZE == queue->front;
}

int is_empty(JobQueue *queue) {
    return queue->front == -1;
}

void enqueue_job(JobQueue *queue, Job job) {
    if (is_full(queue)) {
        printf("Job queue is full!\n");
        return;
    }
    if (is_empty(queue)) {
        queue->front = queue->rear = 0;
    } else {
        queue->rear = (queue->rear + 1) % MAX_JOB_QUEUE_SIZE;
    }
    queue->jobs[queue->rear] = job;
}

Job dequeue_job(JobQueue *queue) {
    Job job;
    if (is_empty(queue)) {
        printf("Job queue is empty!\n");
        job.priority = -1; // Error value
        return job;
    }
    job = queue->jobs[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % MAX_JOB_QUEUE_SIZE;
    }
    return job;
}

int process_jobs(JobQueue *queue) {
    while (!is_empty(queue)) {
        Job current_job = dequeue_job(queue);
        if (current_job.priority == -1) {
            printf("Error processing job.\n");
            return 1;
        }
        // Simulate job processing
        printf("Processing job with priority %d\n", current_job.priority);
    }
    return 0;
}

int main() {
    JobQueue job_queue;
    initialize_job_queue(&job_queue);

    // Example jobs
    Job job1 = {"input1.jpg", "output1.pdf", 3, 5.0, 2};
    Job job2 = {"input2.jpg", "output2.pdf", 1, 2.0, 1};

    enqueue_job(&job_queue, job1);
    enqueue_job(&job_queue, job2);

    return process_jobs(&job_queue);
}
