        free(*keys);
        free(*records);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand() % (1024 * 1024); // Random offset value
        (*keys)[i] = i;
        (*records)[i].value = rand() % 1000; // Random value within range [0, 999]
    }

    return 0; // Success
}

