#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct RecordCollection {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->records);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int insert_record(RecordCollection* collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

int delete_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            for (size_t j = i; j < collection->count - 1; ++j) {
                collection->records[j] = collection->records[j + 1];
            }
            collection->count--;
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Key not found
}

int serialize_record_collection(RecordCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(&collection->records[i].key, sizeof(int), 1, file);
        fwrite(&collection->records[i].offset, sizeof(long), 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize_record_collection(RecordCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&collection->lock);
    if (count > collection->capacity) {
        Record* new_records = (Record*)realloc(collection->records, count * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            fclose(file);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = count;
    }

    for (size_t i = 0; i < count; ++i) {
        fread(&collection->records[i].key, sizeof(int), 1, file);
        fread(&collection->records[i].offset, sizeof(long), 1, file);
    }
    collection->count = count;

    pthread_mutex_unlock(&collection->lock);
    fclose(file);
    return 0;
}

// Example usage
int main() {
    RecordCollection* collection = create_record_collection(10);

    insert_record(collection, 1, 123456789L);
    insert_record(collection, 2, 987654321L);

    serialize_record_collection(collection, "records.dat");

    destroy_record_collection(collection);

    collection = create_record_collection(10);
    deserialize_record_collection(collection, "records.dat");

    delete_record(collection, 1);

    destroy_record_collection(collection);

    return 0;
}
