typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDU_SIZE];
    int size;
    pthread_mutex_t lock;
} DistributedList;

DistributedList list[MAX_DATA_CENTERS];

void init_list(int data_center_id) {
    list[data_center_id].size = 0;
    pthread_mutex_init(&list[data_center_id].lock, NULL);
}

int add_pdu(int data_center_id, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list[data_center_id].lock);
    if (list[data_center_id].size >= MAX_PDU_SIZE) {
        pthread_mutex_unlock(&list[data_center_id].lock);
        return -1; // List is full
    }
    list[data_center_id].pdus[list[data_center_id].size++] = pdu;
    pthread_mutex_unlock(&list[data_center_id].lock);
    return 0;
}

int process_pdus(int data_center_id) {
    int processed_count = 0;
    pthread_mutex_lock(&list[data_center_id].lock);
    for (int i = 0; i < list[data_center_id].size; i++) {
        // Process each PDU here
        processed_count++;
    }
    list[data_center_id].size = 0; // Clear the list after processing
    pthread_mutex_unlock(&list[data_center_id].lock);
    return processed_count;
}

void* data_center_thread(void* arg) {
    int data_center_id = *(int*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Simulate receiving PDU from network
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 1000;
        pdu.CRCFLAG = rand() % 2;

        if (add_pdu(data_center_id, pdu) == 0) {
            int processed_count = process_pdus(data_center_id);
            printf("Data Center %d: Processed %d PDUs\n", data_center_id, processed_count);
        } else {
            printf("Data Center %d: List is full\n", data_center_id);
        }
    }
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < MAX_DATA_CENTERS; i++) {
        init_list(i);
        pthread_t thread;
        int* id = malloc(sizeof(int));
        *id = i;
        pthread_create(&thread, NULL, data_center_thread, id);
    }

    // Simulate running for a while
    sleep(10);

    return 0;
}
