typedef struct {
    int SAPI;
    int PDCP_SN;
    int SDU_LENGTH;
} MAC_LTE_PDU_T;

typedef struct {
    MAC_LTE_PDU_T *list;
    size_t count;
    size_t max_count;
    pthread_mutex_t mutex;
} DynamicList_T;

DynamicList_T* dynamic_list_init(size_t max_count) {
    DynamicList_T *list = (DynamicList_T*)malloc(sizeof(DynamicList_T));
    if (!list) return NULL;

    list->max_count = max_count;
    list->count = 0;
    list->list = (MAC_LTE_PDU_T*)calloc(max_count, sizeof(MAC_LTE_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_free(DynamicList_T *list) {
    if (list) {
        pthread_mutex_destroy(&list->mutex);
        free(list->list);
        free(list);
    }
}

int dynamic_list_add(DynamicList_T *list, int SAPI, int PDCP_SN, int SDU_LENGTH) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }

    MAC_LTE_PDU_T *entry = &list->list[list->count];
    entry->SAPI = SAPI;
    entry->PDCP_SN = PDCP_SN;
    entry->SDU_LENGTH = SDU_LENGTH;

    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

int dynamic_list_get(DynamicList_T *list, size_t index, MAC_LTE_PDU_T *entry) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Index out of bounds
    }

    *entry = list->list[index];
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}
