    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t nodeCount;
    size_t totalBytes;
    size_t maxSizeNodes;
    size_t maxTotalBytes;
    int overflowStrategy; // 0 for truncation, 1 for error logging
