    if (list == NULL) return NULL;
    list->head = NULL;
    list->nodeCount = 0;
    list->totalBytes = 0;
    list->maxSizeNodes = maxSizeNodes;
    list->maxTotalBytes = maxTotalBytes;
    list->overflowStrategy = overflowStrategy;
    return list;
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) return NULL;
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

