    if (list->nodeCount >= list->maxSizeNodes || list->totalBytes + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->maxTotalBytes) {
        if (list->overflowStrategy == 0) {
            // Truncate excess data
            freeLinkedList(list);
            list->head = NULL;
            list->nodeCount = 0;
            list->totalBytes = 0;
        } else {
            // Log error message
            printf("Overflow detected. Current node count: %zu, max nodes: %zu\n", list->nodeCount, list->maxSizeNodes);
            return;
        }
    }

    Node* newNode = createNode(data);
    if (newNode == NULL) return;

    newNode->next = list->head;
    list->head = newNode;
    list->nodeCount++;
    list->totalBytes += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Validate and update CRC flags
    if (data.CRC_INDICATION_REL8_TAG != 0 && data.CRC_INDICATION_REL8_TAG != 1) {
        data.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set to 0 or 1
    }
}

void periodicOperation(LinkedList* list, int interval) {
    for (int i = 0; i < interval; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 1000; // Random value
        data.RNTI = rand() % 1000; // Random value
        data.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set to 0 or 1

        addNode(list, data);
    }
}

int main() {
    srand(time(NULL));
    LinkedList* list = createLinkedList(100, 1024 * 1024, 0); // Max 100 nodes and 1MB total bytes
    if (list == NULL) return -1;

    periodicOperation(list, 10); // Trigger operation every 10 units of time

    freeLinkedList(list);
    return 0;
}
