void execute_command(const char *command) {
    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("Failed to execute command");
        return;
    }

    char buffer[MAX_OUTPUT_SIZE];
    while (fgets(buffer, sizeof(buffer), fp)) {
        printf("%s", buffer);
    }

    int status = pclose(fp);
    if (status == -1) {
        perror("Error reading from command output");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Command exited with non-zero status: %d\n", WEXITSTATUS(status));
    }
}

void setup_environment() {
    struct stat st;
    if (stat(CONFIG_FILE, &st) == 0) {
        if (remove(CONFIG_FILE) != 0) {
            perror("Failed to remove configuration file");
        } else {
            printf("Configuration file removed successfully\n");
        }
    }

    // Implement robust logging mechanism here
}

void perform_operations(int offset_count, int key_count, int min_value, int max_value, const char *command) {
    setup_environment();

    long *offsets = (long *)malloc(offset_count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return;
    }

    int *keys = (int *)malloc(key_count * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return;
    }

    record *records = (record *)malloc(record_count * RECORD_SIZE);
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return;
    }

    initialize_records(records, record_count, min_value, max_value);

    execute_command(command);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

