typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t node_count;
    size_t total_bytes;
    size_t max_nodes;
    size_t max_bytes;
    int overflow_policy; // 0 for truncation, 1 for error logging
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list(size_t max_nodes, size_t max_bytes, int overflow_policy) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->node_count = 0;
    list->total_bytes = 0;
    list->max_nodes = max_nodes;
    list->max_bytes = max_bytes;
    list->overflow_policy = overflow_policy;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (list->node_count >= list->max_nodes || list->total_bytes + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->max_bytes) {
        if (list->overflow_policy == 0) {
            // Truncate excess data
            pthread_mutex_unlock(&list->lock);
            return -1;
        } else {
            // Log error message
            printf("Overflow detected. Error logged.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;
    list->total_bytes += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Additional functions for updating CRC flags, validating data, and integrating with network interface can be added here.
