    NFAPI_CRC_INDICATION_PDU_T* newElement = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newElement) {
        printf("Error: Memory allocation failed\n");
        return;
    }
    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    srand(time(NULL));
    newElement->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    array[count++] = newElement;
}

void removeElement(unsigned short RNTI) {
    for (int i = 0; i < count; i++) {
        if (array[i]->RNTI == RNTI) {
            free(array[i]);
            for (int j = i; j < count - 1; j++) {
                array[j] = array[j + 1];
            }
            count--;
            return;
        }
    }
    printf("Error: Element not found\n");
}

void updateElement(unsigned short RNTI, int newRX_UE_INFORMATION_TAG) {
