#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->entries);
        free(list);
    }
}

int add_crc_entry(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    if (RNTI < 0 || RNTI > 65535) return -1; // Assuming valid RNTI range is 0-65535

    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T entry = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG};
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void* populate_crc_list(void *arg) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)arg;
    int N = 1000; // Example number of entries
    int RNTI_start = 100;
    int RNTI_end = 500;
    unsigned int seed = time(NULL);

    srand(seed);
    for (int i = 0; i < N; i++) {
        int RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        int RNTI = rand() % (RNTI_end - RNTI_start + 1) + RNTI_start;
        int CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;
        int CRCFLAG = rand() % 2;

        add_crc_entry(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG);
    }

    return NULL;
}

int main() {
    NFAPI_CRC_LIST_T *list = create_crc_list(100);
    if (!list) return -1;

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, populate_crc_list, list) != 0) {
            destroy_crc_list(list);
            return -1;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Total entries: %zu\n", list->count);

    destroy_crc_list(list);
    return 0;
}
