#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1000
#define RNTI_RANGE_MIN 1
#define RNTI_RANGE_MAX 4095

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t mutex;
} PDU_Manager;

PDU_Manager pdu_manager = {0, PTHREAD_MUTEX_INITIALIZER};

int validate_rnti(int rnti) {
    return (rnti >= RNTI_RANGE_MIN && rnti <= RNTI_RANGE_MAX);
}

void log_pdu_creation(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    time_t now = time(NULL);
    printf("PDU created at %s with tag: %d, RNTI: %d, CRCFLAG: %d\n", ctime(&now), pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
}

int allocate_pdu(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&pdu_manager.mutex);
    if (pdu_manager.count >= MAX_ENTRIES) {
        printf("Error: Maximum entries reached.\n");
        pthread_mutex_unlock(&pdu_manager.mutex);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &pdu_manager.entries[pdu_manager.count];
    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    if (!validate_rnti(new_pdu->RNTI)) {
        printf("Error: Invalid RNTI value.\n");
        pthread_mutex_unlock(&pdu_manager.mutex);
        return -1;
    }
    log_pdu_creation(new_pdu);
    pdu_manager.count++;
    pthread_mutex_unlock(&pdu_manager.mutex);
    return 0;
}

void merge_pdu_arrays(PDU_Manager *dest, PDU_Manager *src) {
    pthread_mutex_lock(&dest->mutex);
    pthread_mutex_lock(&src->mutex);
    for (int i = 0; i < src->count; i++) {
        if (!validate_rnti(src->entries[i].RNTI)) {
            printf("Error: Invalid RNTI value in source array.\n");
            continue;
        }
        int found = 0;
        for (int j = 0; j < dest->count; j++) {
            if (dest->entries[j].RX_UE_INFORMATION_TAG == src->entries[i].RX_UE_INFORMATION_TAG &&
                dest->entries[j].RNTI == src->entries[i].RNTI &&
                dest->entries[j].CRC_INDICATION_REL8_TAG == src->entries[i].CRC_INDICATION_REL8_TAG) {
                found = 1;
                break;
            }
        }
        if (!found && dest->count < MAX_ENTRIES) {
            NFAPI_CRC_INDICATION_PDU_T *new_pdu = &dest->entries[dest->count];
            new_pdu->RX_UE_INFORMATION_TAG = src->entries[i].RX_UE_INFORMATION_TAG;
            new_pdu->RNTI = src->entries[i].RNTI;
            new_pdu->CRC_INDICATION_REL8_TAG = src->entries[i].CRC_INDICATION_REL8_TAG;
            new_pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            log_pdu_creation(new_pdu);
            dest->count++;
        }
    }
    pthread_mutex_unlock(&src->mutex);
    pthread_mutex_unlock(&dest->mutex);
}

void free_pdu_manager(PDU_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);
}
