#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct LTE_UARFCN_T {
    int TAC;
    int ECM_SSI;
    int quality_value;
} LTE_UARFCN_T;

typedef struct LTE_Collection_T {
    LTE_UARFCN_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    int unique_elements_enabled;
} LTE_Collection_T;

LTE_Collection_T* initialize_collection(size_t initial_capacity, int enable_unique_elements) {
    LTE_Collection_T* collection = (LTE_Collection_T*)malloc(sizeof(LTE_Collection_T));
    if (!collection) {
        perror("Failed to allocate memory for LTE_Collection_T");
        return NULL;
    }

    collection->data = (LTE_UARFCN_T*)calloc(initial_capacity, sizeof(LTE_UARFCN_T));
    if (!collection->data) {
        perror("Failed to allocate memory for LTE_UARFCN_T array");
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    collection->unique_elements_enabled = enable_unique_elements;

    // Log initialization details
    printf("Collection initialized with capacity: %zu\n", initial_capacity);

    return collection;
}

void resize_collection(LTE_Collection_T* collection) {
    size_t new_capacity = collection->capacity * 2;
    LTE_UARFCN_T* new_data = (LTE_UARFCN_T*)realloc(collection->data, new_capacity * sizeof(LTE_UARFCN_T));
    if (!new_data) {
        perror("Failed to reallocate memory for LTE_UARFCN_T array");
        return;
    }

    collection->data = new_data;
    collection->capacity = new_capacity;

    // Log resize details
    printf("Collection resized to capacity: %zu\n", new_capacity);
}

void add_element(LTE_Collection_T* collection, int TAC, int ECM_SSI, int quality_value) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        resize_collection(collection);
    }

    LTE_UARFCN_T new_element = {TAC, ECM_SSI, quality_value};
    if (!collection->unique_elements_enabled || !element_exists(collection, TAC)) {
        collection->data[collection->size++] = new_element;
    } else {
        printf("Element with TAC %d already exists. Skipping.\n", TAC);
    }

    pthread_mutex_unlock(&collection->mutex);
}

int element_exists(LTE_Collection_T* collection, int TAC) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->data[i].TAC == TAC) {
            return 1;
        }
    }
    return 0;
}

void update_collection(LTE_Collection_T* collection, int new_capacity) {
    pthread_mutex_lock(&collection->mutex);

    if (new_capacity > collection->capacity) {
        resize_collection(collection);
    }

    pthread_mutex_unlock(&collection->mutex);
}

void free_collection(LTE_Collection_T* collection) {
    pthread_mutex_destroy(&collection->mutex);
    free(collection->data);
    free(collection);
}
