#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Entry* next;
} Entry;

typedef struct {
    Entry** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConcurrentHashMap;

ConcurrentHashMap* create_concurrent_hashmap(size_t initial_capacity) {
    ConcurrentHashMap* map = (ConcurrentHashMap*)malloc(sizeof(ConcurrentHashMap));
    if (!map) return NULL;

    map->buckets = (Entry**)calloc(initial_capacity, sizeof(Entry*));
    if (!map->buckets) {
        free(map);
        return NULL;
    }

    map->capacity = initial_capacity;
    map->size = 0;
    pthread_mutex_init(&map->lock, NULL);

    return map;
}

void destroy_concurrent_hashmap(ConcurrentHashMap* map) {
    for (size_t i = 0; i < map->capacity; ++i) {
        Entry* entry = map->buckets[i];
        while (entry) {
            Entry* next = entry->next;
            free(entry);
            entry = next;
        }
    }

    pthread_mutex_destroy(&map->lock);
    free(map->buckets);
    free(map);
}

size_t hash_function(int rnti, size_t capacity) {
    return (rnti * 31) % capacity;
}

int add_entry(ConcurrentHashMap* map, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&map->lock);

    size_t index = hash_function(data.RNTI, map->capacity);
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&map->lock);
        return -1; // Memory allocation failure
    }

    new_entry->data = data;
    new_entry->next = map->buckets[index];
    map->buckets[index] = new_entry;
    ++map->size;

    pthread_mutex_unlock(&map->lock);
    return 0;
}

int remove_entry(ConcurrentHashMap* map, int rnti) {
    pthread_mutex_lock(&map->lock);

    size_t index = hash_function(rnti, map->capacity);
    Entry** current = &map->buckets[index];
    while (*current) {
        if ((*current)->data.RNTI == rnti) {
            Entry* to_remove = *current;
            *current = to_remove->next;
            free(to_remove);
            --map->size;
            pthread_mutex_unlock(&map->lock);
            return 0; // Success
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&map->lock);
    return -1; // Entry not found
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(ConcurrentHashMap* map, int rnti) {
    pthread_mutex_lock(&map->lock);

    size_t index = hash_function(rnti, map->capacity);
    Entry* entry = map->buckets[index];
    while (entry) {
        if (entry->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* result = &entry->data;
            pthread_mutex_unlock(&map->lock);
            return result; // Found
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&map->lock);
    return NULL; // Entry not found
}
