    snprintf(file_path, sizeof(file_path), "%s/crc_indications.bin", directory);

    int fd = open(file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Failed to create file");
        return NULL;
    }

    if (write(fd, crc_indications, num_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T)) != num_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        perror("Failed to write to file");
        close(fd);
        return NULL;
    }

    close(fd);
    return NULL;
}

void* save_to_directory(void* arg) {
    char* directory = (char*)arg;
    char dir_path[256];
    snprintf(dir_path, sizeof(dir_path), "%s/crc_indications", directory);

    if (mkdir(dir_path, 0755) == -1 && errno != EEXIST) {
        perror("Failed to create directory");
        return NULL;
    }

    char file_path[256];
    snprintf(file_path, sizeof(file_path), "%s/crc_indications/data.json", dir_path);

    FILE* fp = fopen(file_path, "w");
    if (fp == NULL) {
        perror("Failed to open file for writing");
        return NULL;
    }

    // Write JSON data here

    fclose(fp);
    return NULL;
}

void save_crc_indications() {
    pthread_mutex_lock(&storage_lock);

    char* storage_type = getenv("NFIX_STORAGE_TYPE");
    if (storage_type == NULL) {
        fprintf(stderr, "NFIX_STORAGE_TYPE environment variable not set\n");
        pthread_mutex_unlock(&storage_lock);
        return;
    }

    char directory[256];
    if (strcmp(storage_type, "FILE") == 0) {
        // Get user-specified directory or create using template
        snprintf(directory, sizeof(directory), "%s", getenv("HOME"));
        strcat(directory, "/nfix_storage/");
        mkdir(directory, 0755);
    } else if (strcmp(storage_type, "DIR") == 0) {
        // Get user-specified directory or create using template
        snprintf(directory, sizeof(directory), "%s", getenv("HOME"));
        strcat(directory, "/nfix_storage/");
        mkdir(directory, 0755);
    } else {
        fprintf(stderr, "Invalid NFIX_STORAGE_TYPE value\n");
        pthread_mutex_unlock(&storage_lock);
        return;
    }

    if (strcmp(storage_type, "FILE") == 0) {
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, save_to_file, directory) != 0) {
            perror("Failed to create thread for file saving");
        }
        pthread_join(thread_id, NULL);
    } else if (strcmp(storage_type, "DIR") == 0) {
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, save_to_directory, directory) != 0) {
            perror("Failed to create thread for directory saving");
        }
        pthread_join(thread_id, NULL);
    }

    pthread_mutex_unlock(&storage_lock);
}
