#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct SubscriptionInfo {
    char userId[50];
    char status[20];
    double billingAmount;
} SubscriptionInfo;

typedef struct TreeNode {
    SubscriptionInfo data;
    struct TreeNode *left, *right;
} TreeNode;

TreeNode* createNode(SubscriptionInfo info) {
    TreeNode* newNode = (TreeNode*)malloc(sizeof(TreeNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = info;
    newNode->left = newNode->right = NULL;
    return newNode;
}

TreeNode* insertNode(TreeNode* root, SubscriptionInfo info) {
    if (root == NULL)
        return createNode(info);

    if (strcmp(info.userId, root->data.userId) < 0)
        root->left = insertNode(root->left, info);
    else
        root->right = insertNode(root->right, info);

    return root;
}

TreeNode* searchNode(TreeNode* root, char* userId) {
    if (root == NULL || strcmp(userId, root->data.userId) == 0)
        return root;

    if (strcmp(userId, root->data.userId) < 0)
        return searchNode(root->left, userId);

    return searchNode(root->right, userId);
}

void freeTree(TreeNode* node) {
    if (node != NULL) {
        freeTree(node->left);
        freeTree(node->right);
        free(node);
    }
}

int main() {
    TreeNode* root = NULL;
    SubscriptionInfo info1 = {"user1", "active", 50.0};
    SubscriptionInfo info2 = {"user2", "inactive", 30.0};

    root = insertNode(root, info1);
    root = insertNode(root, info2);

    TreeNode* result = searchNode(root, "user1");
    if (result != NULL) {
        printf("User ID: %s, Status: %s, Billing Amount: %.2f\n", 
               result->data.userId, result->data.status, result->data.billingAmount);
    }

    freeTree(root);

    return 0;
}
