        array[i] = (LTE_PHY_RX_FRAME_PDU_T*)malloc(sizeof(LTE_PHY_RX_FRAME_PDU_T));
        if (!array[i]) {
            perror("Failed to allocate memory for frame PDU");
            // Clean up previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }
    return array;
}

void resize_dynamic_array(LTE_PHY_RX_FRAME_PDU_T*** array, size_t new_size) {
    LTE_PHY_RX_FRAME_PDU_T** new_array = (LTE_PHY_RX_FRAME_PDU_T**)realloc(*array, new_size * sizeof(LTE_PHY_RX_FRAME_PDU_T*));
    if (!new_array) {
        perror("Failed to reallocate memory for dynamic array");
        return;
    }
    *array = new_array;
