#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_length;
    int protocol_type;
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t count;
    size_t capacity;
} PacketArray;

void init_packet_array(PacketArray *array) {
    array->packets = (NetworkPacket *)malloc(INITIAL_CAPACITY * sizeof(NetworkPacket));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
}

void add_packet(PacketArray *array, NetworkPacket packet) {
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        NetworkPacket *new_packets = (NetworkPacket *)realloc(array->packets, new_capacity * sizeof(NetworkPacket));
        if (!new_packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->count++] = packet;
}

void update_packet(PacketArray *array, size_t index, NetworkPacket packet) {
    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    array->packets[index] = packet;
}

void delete_packet(PacketArray *array, size_t index) {
    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    for (size_t i = index; i < array->count - 1; ++i) {
        array->packets[i] = array->packets[i + 1];
    }
    --array->count;
}

void prune_old_packets(PacketArray *array, time_t threshold) {
    size_t new_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (difftime(time(NULL), array->packets[i].timestamp) > threshold) {
            continue;
        }
        array->packets[new_count++] = array->packets[i];
    }
    array->count = new_count;
}

size_t calculate_total_data_transferred(PacketArray *array, int protocol_type) {
    size_t total_length = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i].protocol_type == protocol_type) {
            total_length += array->packets[i].payload_length;
        }
    }
    return total_length;
}

void free_packet_array(PacketArray *array) {
    free(array->packets);
}
