using System;
using System.Threading.Tasks;

public class DynamicRangeGenerator
{
    private double minValue;
    private double maxValue;
    private static Random random = new Random();

    public DynamicRangeGenerator(double min, double max)
    {
        SetRange(min, max);
    }

    public double GetRandomFloat()
    {
        return random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GetRandomInt()
    {
        return random.Next((int)Math.Ceiling(minValue), (int)Math.Floor(maxValue) + 1);
    }

    public override string ToString()
    {
        return $"Range[{minValue}, {maxValue}]";
    }

    public static void InitializeRandomSeed(int seed)
    {
        random = new Random(seed);
    }

    public void SetRange(double min, double max)
    {
        if (min > max)
        {
            double temp = min;
            min = max;
            max = temp;
        }
        minValue = min;
        maxValue = max;
    }

    public async Task RefreshRangeAsync(IConfigurationService configService)
    {
        try
        {
            var newRange = await configService.GetRangeAsync();
            SetRange(newRange.Min, newRange.Max);
        }
        catch (Exception ex)
        {
            // Handle exception gracefully, e.g., log it or use a default range
            Console.WriteLine($"Failed to refresh range: {ex.Message}");
        }
    }

    public static void Main(string[] args)
    {
        var configService = new ConfigurationService();
        InitializeRandomSeed(42);
        var generator = new DynamicRangeGenerator(configService.GetInitialMin(), configService.GetInitialMax());

        // Example usage
        Console.WriteLine(generator.ToString());
        Console.WriteLine(generator.GetRandomFloat());
        Console.WriteLine(generator.GetRandomInt());

        // Periodically refresh the range
        Task.Run(async () =>
        {
            while (true)
            {
                await generator.RefreshRangeAsync(configService);
                await Task.Delay(60000); // Refresh every minute
            }
        });
    }
}

public interface IConfigurationService
{
    double GetInitialMin();
    double GetInitialMax();
    Task<Range> GetRangeAsync();
}

public class ConfigurationService : IConfigurationService
{
    public double GetInitialMin()
    {
        return 1.0;
    }

    public double GetInitialMax()
    {
        return 100.0;
    }

    public async Task<Range> GetRangeAsync()
    {
        // Simulate network delay and potential failure
        await Task.Delay(500);
        if (DateTime.Now.Hour < 8 || DateTime.Now.Hour > 20)
        {
            throw new Exception("Configuration service is unavailable during off-peak hours.");
        }
        return new Range { Min = 1.0, Max = 100.0 };
    }
}

public class Range
{
    public double Min { get; set; }
    public double Max { get; set; }
}
