void load_crypto_algorithms() {
    // Initialize OpenSSL environment
    if (!OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CONFIG | OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS, NULL)) {
        fprintf(stderr, "Failed to initialize OpenSSL\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    // Dynamically load AES algorithm
    EVP_add_cipher(EVP_aes_256_cbc());

    // Dynamically load Camellia algorithm
    EVP_add_cipher(EVP_camellia_256_cbc());

    // Dynamically load MD5 digest
    EVP_add_digest(EVP_md5());

    // Dynamically load SHA-256 digest
    EVP_add_digest(EVP_sha256());

    // Dynamically load RSA with SHA-256 signature algorithm
    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, NULL);
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create RSA context\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    if (EVP_PKEY_keygen_init(ctx) <= 0) {
        fprintf(stderr, "Failed to initialize RSA key generation\n");
        ERR_print_errors_fp(stderr);
        EVP_PKEY_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    if (EVP_PKEY_CTX_set_rsa_keygen_bits(ctx, 2048) <= 0) {
        fprintf(stderr, "Failed to set RSA key size\n");
        ERR_print_errors_fp(stderr);
        EVP_PKEY_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    if (EVP_PKEY_CTX_set_signature_md(ctx, EVP_sha256()) <= 0) {
        fprintf(stderr, "Failed to set signature digest algorithm\n");
        ERR_print_errors_fp(stderr);
        EVP_PKEY_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Clean up
    EVP_PKEY_CTX_free(ctx);

    printf("All cryptographic algorithms loaded successfully.\n");
}

int main() {
    load_crypto_algorithms();
    return 0;
}
