#define MAX_PACKETS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char source_ip[16];
    char destination_ip[16];
    int payload_size;
} PacketHeader;

typedef struct {
    PacketHeader *headers[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_packet(PacketManager *manager, PacketHeader *header) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Array is full
    }
    manager->headers[manager->count++] = header;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_packet(PacketManager *manager, int index) {
    pthread_mutex_lock(&manager->lock);
    if (index < 0 || index >= manager->count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid index
    }
    for (int i = index; i < manager->count - 1; i++) {
        manager->headers[i] = manager->headers[i + 1];
    }
    manager->count--;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void iterate_packets(PacketManager *manager, void (*callback)(PacketHeader *)) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        callback(manager->headers[i]);
    }
    pthread_mutex_unlock(&manager->lock);
}

void validate_packet_header(PacketHeader *header) {
