    init_packet_manager(&manager);

    // Example usage
    PacketHeader *header = (PacketHeader *)malloc(sizeof(PacketHeader));
    header->RX_UE_INFORMATION_TAG = 123;
    header->RNTI = 456;
    strcpy(header->source_ip, "192.168.1.1");
    strcpy(header->destination_ip, "10.0.0.1");
    header->payload_size = 1024;

    validate_packet_header(header);
    if (add_packet(&manager, header) == 0) {
        printf("Packet added successfully\n");
    } else {
        printf("Failed to add packet\n");
    }

    iterate_packets(&manager, [](PacketHeader *header) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, Payload Size: %d\n",
               header->RX_UE_INFORMATION_TAG, header->RNTI, header->payload_size);
    });

    remove_packet(&manager, 0);

