}

int add_phy_downlink_shared_channel(NFAPI_RRC_PDU_T *pdu, char *channel_data) {
    if (strlen(channel_data) >= pdu->buffer_size) {
        // Handle overflow by reallocating buffer
        pdu->PHY_DOWNLINK_CONTROLS = (char *)realloc(pdu->PHY_DOWNLINK_CONTROLS, strlen(channel_data) + 1);
        if (!pdu->PHY_DOWNLINK_CONTROLS) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        pdu->buffer_size = strlen(channel_data) + 1;
    }
    strcpy(pdu->PHY_DOWNLINK_CONTROLS, channel_data);
    return 0;
}

int main() {
    PacketArray packet_array;
    init_packet_array(&packet_array);

    NFAPI_RRC_PDU_T pdu;
    init_nfaapi_rrc_pdu(&pdu, BUFFER_SIZE);

    // Example usage
    PacketHeader header = {12345, 67890, 1, "192.168.1.1", "192.168.1.2", 1024};
    add_packet(&packet_array, header);

    char channel_data[] = "PHY_DOWNLINK_SHARED_CHANNEL_DATA";
    add_phy_downlink_shared_channel(&pdu, channel_data);

    // Clean up
    free_nfaapi_rrc_pdu(&pdu);
    return 0;
}
