#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    char* data;
    int priority;
    struct Node* next;
} Node;

typedef struct Task {
    Node* node;
    time_t start_time;
    time_t end_time;
} Task;

Node* create_node(const char* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        exit(1);
    }
    new_node->data = strdup(data);
    new_node->priority = rand() % 100; // Random priority between 0 and 99
    new_node->next = NULL;
    return new_node;
}

Task* create_task(Node* node) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (new_task == NULL) {
        fprintf(stderr, "Memory allocation failed for task\n");
        exit(1);
    }
    new_task->node = node;
    new_task->start_time = time(NULL);
    new_task->end_time = new_task->start_time + 60; // Duration of 1 minute
    return new_task;
}

void add_node(Node** head, const char* data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void add_task(Task** tasks, int* task_count, Node* node) {
    Task* new_task = create_task(node);
    (*tasks)[(*task_count)] = *new_task;
    (*task_count)++;
}

void remove_node(Node** head, const char* data) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->data, data) == 0) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->data);
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void remove_task(Task** tasks, int* task_count, Node* node) {
    for (int i = 0; i < *task_count; i++) {
        if (tasks[i]->node == node) {
            free(tasks[i]);
            for (int j = i; j < *task_count - 1; j++) {
                tasks[j] = tasks[j + 1];
            }
            (*task_count)--;
            return;
        }
    }
}

void free_nodes(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}

void free_tasks(Task** tasks, int task_count) {
    for (int i = 0; i < task_count; i++) {
        free(tasks[i]);
    }
    free(tasks);
}
