    event_pool.pool_size = pool_size;
    event_pool.used_count = 0;
    pthread_mutex_init(&event_pool.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_event() {
    NFAPI_CRC_INDICATION_PDU_T *event = NULL;
    pthread_mutex_lock(&event_pool.lock);
    if (event_pool.used_count < event_pool.pool_size) {
        event = &event_pool.pool[event_pool.used_count++];
