MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->pool = malloc(initial_size);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pool->size = initial_size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
    free(pool);
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used + size > pool->size) {
        // Resize the pool
        void* new_pool = realloc(pool->pool, pool->size * 2);
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->pool = new_pool;
        pool->size *= 2;
    }
    void* ptr = (char*)pool->pool + pool->used;
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

