    if (pool->used + sizeof(LTE_PHY_TX_PDU) > pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full
    }
    memcpy((char*)pool->pool + pool->used, pdu, sizeof(LTE_PHY_TX_PDU));
    pool->used += sizeof(LTE_PHY_TX_PDU);
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void serialize_to_file(MemoryPool* pool, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;
    fwrite(pool->pool, 1, pool->used, file);
    fclose(file);
}

void deserialize_from_file(MemoryPool* pool, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    if (file_size > pool->size) {
        void* new_pool = realloc(pool->pool, file_size);
        if (!new_pool) {
            fclose(file);
            return;
        }
        pool->pool = new_pool;
        pool->size = file_size;
    }
    fread(pool->pool, 1, file_size, file);
    pool->used = file_size;
    fclose(file);
}

