    NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_crc_pdu(12345, 67890);
    if (new_pdu != NULL) {
        *list = realloc(*list, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*list == NULL) {
