#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_CONCURRENT_QUERIES 5
#define CACHE_EXPIRY_SECONDS 10

typedef struct {
    char hostname[256];
    struct in_addr ipv4;
    struct in6_addr ipv6;
    time_t expiry_time;
} DNSCacheEntry;

DNSCacheEntry dns_cache[MAX_CONCURRENT_QUERIES];

int resolve_dns(const char *hostname, struct sockaddr_in *ipv4, struct sockaddr_in6 *ipv6) {
    // Check cache
    for (int i = 0; i < MAX_CONCURRENT_QUERIES; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && time(NULL) < dns_cache[i].expiry_time) {
            memcpy(ipv4, &dns_cache[i].ipv4, sizeof(struct in_addr));
            memcpy(ipv6, &dns_cache[i].ipv6, sizeof(struct in6_addr));
            return 0; // Success from cache
        }
    }

    // Perform DNS query
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1; // DNS query failed
    }

    // Store result in cache
    for (int i = 0; i < MAX_CONCURRENT_QUERIES; i++) {
        if (dns_cache[i].expiry_time == 0) {
            strcpy(dns_cache[i].hostname, hostname);
            dns_cache[i].expiry_time = time(NULL) + CACHE_EXPIRY_SECONDS;
            memcpy(&dns_cache[i].ipv4, &((struct sockaddr_in *)res->ai_addr)->sin_addr, sizeof(struct in_addr));
            memcpy(&dns_cache[i].ipv6, &((struct sockaddr_in6 *)res->ai_addr)->sin6_addr, sizeof(struct in6_addr));
            freeaddrinfo(res);
            return 0; // Success
        }
    }

    freeaddrinfo(res);
    return -1; // Cache full
}

int main() {
    struct sockaddr_in ipv4;
    struct sockaddr_in6 ipv6;

    int result = resolve_dns("example.com", &ipv4, &ipv6);
    if (result == 0) {
        printf("IPv4: %s\n", inet_ntoa(ipv4.sin_addr));
        printf("IPv6: %s\n", inet_ntop(AF_INET6, &ipv6.sin6_addr, NULL, INET6_ADDRSTRLEN));
    } else {
        printf("DNS resolution failed.\n");
    }

    return 0;
}
