#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    char* data;
} Record;

typedef struct RecordCollection {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]->data);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int insert_record(RecordCollection* collection, int key, long offset, const char* data) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }

    record->key = key;
    record->offset = offset;
    record->data = strdup(data);
    if (!record->data) {
        free(record);
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }

    collection->records[collection->size++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int delete_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]->data);
            free(collection->records[i]);
            for (size_t j = i; j < collection->size - 1; ++j) {
                collection->records[j] = collection->records[j + 1];
            }
            --collection->size;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Record not found
}

void iterate_records(RecordCollection* collection, void (*callback)(int, long, const char*)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        callback(collection->records[i]->key, collection->records[i]->offset, collection->records[i]->data);
    }

    pthread_mutex_unlock(&collection->lock);
}
