#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t size;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_at_index(List* list, size_t index, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || index > list->size) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (index == 0) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        for (size_t i = 0; i < index - 1; ++i) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_at_index(List* list, size_t index) {
    if (!list || index >= list->size) return -1;

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    if (index == 0) {
        list->head = current->next;
    } else {
        for (size_t i = 0; i < index - 1; ++i) {
            current = current->next;
        }
        Node* temp = current->next;
        current->next = temp->next;
    }
    free(current);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void update_crcflag(List* list, int (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        if (callback(&current->data)) {
            // Update CRCFLAG based on callback
            current->data.CRCFLAG = 1; // Example update
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void iterate_list(List* list, void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !operation) return;

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        operation(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

size_t get_size(List* list) {
    if (!list) return 0;
    return list->size;
}
