#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define LOG_FILE "crc_operations.log"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T crc_list[MAX_ENTRIES];
int entry_count = 0;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

void log_operation(const char* operation, int rnti) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) return;
    time_t now = time(NULL);
    pthread_t thread_id = pthread_self();
    fprintf(log_file, "%s [%ld] %s RNTI: %d\n", ctime(&now), (long)thread_id, operation, rnti);
    fclose(log_file);
}

int add_crc_entry(int rx_tag, int crc_flag) {
    pthread_rwlock_wrlock(&rwlock);
    if (entry_count >= MAX_ENTRIES) {
        pthread_rwlock_unlock(&rwlock);
        return -1;
    }
    for (int i = 0; i < entry_count; i++) {
        if (crc_list[i].RNTI == rx_tag) {
            pthread_rwlock_unlock(&rwlock);
            return -2;
        }
    }
    crc_list[entry_count].RX_UE_INFORMATION_TAG = rx_tag;
    crc_list[entry_count].RNTI = rx_tag;
    crc_list[entry_count].CRC_INDICATION_REL8_TAG = 0; // Assuming this is set elsewhere
    crc_list[entry_count].CRCFLAG = crc_flag;
    entry_count++;
    pthread_rwlock_unlock(&rwlock);
    log_operation("Added CRC Entry", rx_tag);
    return 0;
}

int delete_crc_entry(int rnti) {
    pthread_rwlock_wrlock(&rwlock);
    for (int i = 0; i < entry_count; i++) {
        if (crc_list[i].RNTI == rnti) {
            memmove(&crc_list[i], &crc_list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (entry_count - i - 1));
            entry_count--;
            pthread_rwlock_unlock(&rwlock);
            log_operation("Deleted CRC Entry", rnti);
            return 0;
        }
    }
    pthread_rwlock_unlock(&rwlock);
    return -1;
}

void* handle_request(void* arg) {
    int request_type = *(int*)arg; // Assuming 0 for PUT, 1 for DELETE
    int rnti = rand() % MAX_ENTRIES; // Simulating RNTI generation

    if (request_type == 0) {
        add_crc_entry(rnti, rand() % 2); // Random CRCFLAG
    } else if (request_type == 1) {
        delete_crc_entry(rnti);
    }

    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[10];
    srand(time(NULL));

    for (int i = 0; i < 10; i++) {
        int* request_type = malloc(sizeof(int));
        *request_type = rand() % 2; // Randomly choose PUT or DELETE
        pthread_create(&threads[i], NULL, handle_request, request_type);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
