#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 0.75

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    int userID;
    int sessionID;
    char action[50];
    int responseCode;
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t count;
    size_t capacity;
} LogArray;

void initLogArray(LogArray *logArray) {
    logArray->entries = (LogEntry *)malloc(INITIAL_CAPACITY * sizeof(LogEntry));
    if (!logArray->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    logArray->count = 0;
    logArray->capacity = INITIAL_CAPACITY;
}

void resizeLogArray(LogArray *logArray) {
    size_t newCapacity = logArray->capacity * 2;
    LogEntry *newEntries = (LogEntry *)realloc(logArray->entries, newCapacity * sizeof(LogEntry));
    if (!newEntries) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    logArray->entries = newEntries;
    logArray->capacity = newCapacity;
}

void addLogEntry(LogArray *logArray, LogEntry entry) {
    if (logArray->count >= logArray->capacity * RESIZE_THRESHOLD) {
        resizeLogArray(logArray);
    }
    logArray->entries[logArray->count++] = entry;
}

void updateLogEntry(LogArray *logArray, int userID, LogEntry newEntry) {
    for (size_t i = 0; i < logArray->count; ++i) {
        if (logArray->entries[i].userID == userID) {
            logArray->entries[i] = newEntry;
            return;
        }
    }
}

void deleteLogEntry(LogArray *logArray, int userID) {
    for (size_t i = 0; i < logArray->count; ++i) {
        if (logArray->entries[i].userID == userID) {
            memmove(&logArray->entries[i], &logArray->entries[i + 1], (logArray->count - i - 1) * sizeof(LogEntry));
            --logArray->count;
            return;
        }
    }
}

void iterateLogArray(LogArray *logArray, int (*filter)(const LogEntry *)) {
    size_t totalActions = 0;
    double totalResponseTime = 0.0;

    for (size_t i = 0; i < logArray->count; ++i) {
        if (filter(&logArray->entries[i])) {
            totalActions++;
            totalResponseTime += difftime(time(NULL), logArray->entries[i].timestamp);
        }
    }

    printf("Total Actions: %zu\n", totalActions);
    if (totalActions > 0) {
        printf("Average Response Time: %.2f seconds\n", totalResponseTime / totalActions);
    } else {
        printf("No actions to calculate average response time.\n");
    }
}

int filterByUserID(const LogEntry *entry, int userID) {
    return entry->userID == userID;
}

int filterByActionType(const LogEntry *entry, const char *actionType) {
    return strcmp(entry->action, actionType) == 0;
}

void freeLogArray(LogArray *logArray) {
    free(logArray->entries);
}
