        list->capacity = newCapacity;
    }
    list->configs[list->count++] = config;
    pthread_mutex_unlock(&list->mutex);
}

LTEConfig *getConfigByBandwidth(ConfigList *list, int bandwidth) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->configs[i].bandwidth == bandwidth) {
            pthread_mutex_unlock(&list->mutex);
            return &list->configs[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

int main() {
    ConfigList configList;
    initConfigList(&configList, 10);

    LTEConfig config1 = {20, 15e3, 1};
    addConfig(&configList, config1);

    LTEConfig *config = getConfigByBandwidth(&configList, 20);
    if (config) {
        printf("Found config: Bandwidth=%d, Subcarrier Spacing=%.2f, Cell Identity=%d\n",
               config->bandwidth, config->subcarrierSpacing, config->cellIdentity);
    } else {
        printf("Config not found\n");
    }

    freeConfigList(&configList);

    return 0;
}
