typedef enum {
    CIPHER_NULL,
    CIPHER_DES_ECB,
    CIPHER_DES_EDE,
    CIPHER_DES_EDE3,
    CIPHER_DES_CFB
} CipherMode;

EVP_CIPHER* get_cipher(CipherMode mode, int key_size) {
    EVP_CIPHER* cipher = NULL;
    switch (mode) {
        case CIPHER_NULL:
            cipher = EVP_enc_null();
            break;
        case CIPHER_DES_ECB:
            if (key_size == 64)
                cipher = EVP_des_ecb();
            else
                return NULL; // Unsupported key size for ECB
            break;
        case CIPHER_DES_EDE:
            if (key_size == 128)
                cipher = EVP_des_ede3_cbc();
            else
                return NULL; // Unsupported key size for EDE
            break;
        case CIPHER_DES_EDE3:
            if (key_size == 192)
                cipher = EVP_des_ede3_cbc();
            else
                return NULL; // Unsupported key size for EDE3
            break;
        case CIPHER_DES_CFB:
            if (key_size == 64)
                cipher = EVP_des_cfb8();
            else
                return NULL; // Unsupported key size for CFB
            break;
        default:
            return NULL; // Invalid mode
    }
    return cipher;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <mode> <key_size>\n", argv[0]);
        return 1;
    }

    CipherMode mode = CIPHER_NULL;
    int key_size = 64;

    if (strcmp(argv[1], "ECB") == 0)
        mode = CIPHER_DES_ECB;
    else if (strcmp(argv[1], "EDE") == 0)
        mode = CIPHER_DES_EDE;
    else if (strcmp(argv[1], "EDE3") == 0)
        mode = CIPHER_DES_EDE3;
    else if (strcmp(argv[1], "CFB") == 0)
        mode = CIPHER_DES_CFB;

    key_size = atoi(argv[2]);

    EVP_CIPHER* cipher = get_cipher(mode, key_size);
    if (!cipher) {
        fprintf(stderr, "Invalid cipher mode or key size\n");
        return 1;
    }

    printf("Cipher selected: %s with key size %d\n", EVP_CIPHER_name(cipher), key_size);

    // Additional code for encryption/decryption and error handling can be added here

    return 0;
}
```

