#define MAX_SESSIONS 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pthread_mutex_t lock;
} SessionData;

SessionData session_pool[MAX_SESSIONS];
int pool_size = 0;
pthread_mutex_t pool_lock;

void init_session_pool() {
    pthread_mutex_init(&pool_lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_session(int rnti) {
    pthread_mutex_lock(&pool_lock);
    if (pool_size >= MAX_SESSIONS) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Out of memory
    }
    SessionData *session = &session_pool[pool_size++];
    session->pdu.RNTI = rnti;
    session->pdu.CRC_INDICATION_REL8_TAG.crc_flag = rand() % 2; // Random CRC flag
    pthread_mutex_init(&session->lock, NULL);
    pthread_mutex_unlock(&pool_lock);
    return &session->pdu;
}

void free_session(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    for (int i = 0; i < pool_size; i++) {
        if (&session_pool[i].pdu == pdu) {
            pthread_mutex_destroy(&session_pool[i].lock);
            pthread_mutex_lock(&pool_lock);
            session_pool[i] = session_pool[--pool_size];
            pthread_mutex_unlock(&pool_lock);
            return;
        }
    }
}

void resize_session_pool(int new_size) {
    if (new_size > MAX_SESSIONS) {
        new_size = MAX_SESSIONS; // Cap at maximum size
    }
    pthread_mutex_lock(&pool_lock);
    while (pool_size > new_size) {
        free_session(&session_pool[--pool_size].pdu);
    }
    pthread_mutex_unlock(&pool_lock);
}
