typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *da) {
    da->count = 0;
    pthread_mutex_init(&da->mutex, NULL);
}

int addElement(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (da->count >= MAX_ELEMENTS) return -1; // Error: Array is full
    pthread_mutex_lock(&da->mutex);
    da->array[da->count++] = element;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int removeElement(DynamicArray *da, unsigned short RNTI) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i]->RNTI == RNTI) {
            free(da->array[i]);
            for (; i + 1 < da->count; ++i) {
                da->array[i] = da->array[i + 1];
            }
            da->count--;
            pthread_mutex_unlock(&da->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->mutex);
    return -1; // Error: Element not found
}

int updateElement(DynamicArray *da, unsigned short RNTI, NFAPI_CRC_INDICATION_PDU_T *newElement) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i]->RNTI == RNTI) {
            free(da->array[i]);
            da->array[i] = newElement;
            pthread_mutex_unlock(&da->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->mutex);
    return -1; // Error: Element not found
}

void destroyDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->count; ++i) {
        free(da->array[i]);
    }
    da->count = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

