int load_config(const char *filename, int *max_structures, int *retry_interval, int *resource_threshold) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    fscanf(file, "%d %d %d", max_structures, retry_interval, resource_threshold);
    fclose(file);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_structures(int max_structures, int retry_interval, int resource_threshold) {
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    int attempts = 0;

    while (attempts < retry_interval) {
        structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (structures) break;
        attempts++;
        sleep(1); // Wait before retrying
    }

    if (!structures) {
        fprintf(stderr, "Failed to allocate memory after %d attempts\n", retry_interval);
        return NULL;
    }

    for (int i = 0; i < max_structures; i++) {
        structures[i].RX_UE_INFORMATION_TAG = i * 100;
        structures[i].RNTI = i * 200;
        structures[i].CRC_INDICATION_REL8_TAG = i * 300;
        structures[i].CRCFLAG = (i % 2 == 0) ? 1 : 0; // Non-trivial condition
    }

    return structures;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T *structures, int max_structures) {
    if (structures) {
        free(structures);
    }
}

int main() {
    int max_structures, retry_interval, resource_threshold;
    if (load_config("config.txt", &max_structures, &retry_interval, &resource_threshold) != 0) {
        fprintf(stderr, "Failed to load configuration\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *structures = initialize_structures(max_structures, retry_interval, resource_threshold);
    if (!structures) {
        return -1;
    }

    // Use the structures...

    free_structures(structures, max_structures);

    return 0;
}
