} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_pdu(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }
    list->pdus[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->pdus[list->size].RNTI = RNTI;
    list->pdus[list->size].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void* crc_list_thread_func(void *arg) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)arg;
    for (int i = 0; i < 1000; i++) {
        add_crc_pdu(list, rand() % 100, rand() % 100);
    }
    return NULL;
}

void test_crc_list() {
    NFAPI_CRC_LIST_T *list = create_crc_list(10);
    pthread_t threads[10];
    srand(time(NULL));

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, crc_list_thread_func, list);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Total PDUs added: %zu\n", list->size);

    destroy_crc_list(list);
}
