#include <algorithm>

// Define NFAPI_CRC_INDICATION_PDU_T structure for demonstration purposes
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    } crc_indication_rel8_tag;
};

// Function to generate NFAPI_CRC_INDICATION_PDU_T structures
std::vector<NFAPI_CRC_INDICATION_PDU_T*> generateNfarcrcIndications(int N) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> indications(N);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    for (int i = 0; i < N; ++i) {
        indications[i] = new NFAPI_CRC_INDICATION_PDU_T();
        auto start = std::chrono::high_resolution_clock::now();
        indications[i]->RX_UE_INFORMATION_TAG = i;
        indications[i]->RNTI = i * 100;
        indications[i]->crc_indication_rel8_tag.CRCFLAG = dis(gen);
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "Allocation and initialization time for element " << i << ": "
                  << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms" << std::endl;
    }

    return indications;
}

// Function to count disjoint pairs using Union-Find
int countDisjointPairs(const std::vector<int>& array) {
    int n = array.size();
    std::unordered_set<int> parent(n);
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
    }

    auto find = [&](int u) {
        if (parent[u] != u) {
            parent[u] = find(parent[u]);
        }
        return parent[u];
    };

    auto unionSet = [&](int u, int v) {
        int pu = find(u);
        int pv = find(v);
        if (pu != pv) {
            parent[pu] = pv;
        }
    };

    std::vector<std::pair<int, int>> pairs(n * (n - 1) / 2);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            pairs[i * (n - 1) / 2 + j - i - 1] = {array[i], array[j]};
        }
    }

    auto start = std::chrono::high_resolution_clock::now();
    for (const auto& pair : pairs) {
        unionSet(pair.first, pair.second);
    }
    auto end = std::chrono::high_resolution_clock::now();

    std::cout << "Disjoint pairs count computation time: "
              << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms" << std::endl;

    return pairs.size();
}

int main() {
    int N = 1000;
    auto indications = generateNfarcrcIndications(N);
    for (auto& indication : indications) {
        delete indication;
    }

    std::vector<int> array = {1, 2, 3, 4, 5};
    countDisjointPairs(array);

    return 0;
}
