#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define POOL_SIZE 1000

typedef struct {
    int value;
    char* userID;
} Record;

typedef struct {
    int key;
    Record* record;
} HashTableEntry;

typedef struct {
    HashTableEntry** entries;
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    Record records[POOL_SIZE];
    int nextFreeIndex;
    pthread_mutex_t poolLock;
} RecordPool;

NFAPI_CRC_INDICATION_PDU_T* crc_indication_list[MAX_ELEMENTS];
int crc_count = 0;
pthread_mutex_t crc_lock;

RecordPool record_pool;
HashTable hash_table;

void custom_realloc(void** ptr, size_t new_size) {
    void* new_ptr = realloc(*ptr, new_size);
    if (new_ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *ptr = new_ptr;
}

int validate_rnti(int rnti, int* whitelist, int whitelist_size) {
    for (int i = 0; i < whitelist_size; i++) {
        if (rnti == whitelist[i]) {
            return 1;
        }
    }
    return 0;
}

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu, int* whitelist, int whitelist_size) {
    pthread_mutex_lock(&crc_lock);
    if (crc_count >= MAX_ELEMENTS) {
        fprintf(stderr, "CRC indication list is full\n");
        pthread_mutex_unlock(&crc_lock);
        return;
    }
    if (!validate_rnti(pdu->rnti, whitelist, whitelist_size)) {
        fprintf(stderr, "Invalid RNTI value: %d\n", pdu->rnti);
        pthread_mutex_unlock(&crc_lock);
        return;
    }
    crc_indication_list[crc_count] = pdu;
    crc_count++;
    pthread_mutex_unlock(&crc_lock);
}

int get_crc_count() {
    return crc_count;
}

void* hash_table_get(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    HashTableEntry* entry = table->entries[key % MAX_ELEMENTS];
    if (entry != NULL && entry->key == key) {
        Record* record = entry->record;
        pthread_mutex_unlock(&table->lock);
        return record;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void hash_table_put(HashTable* table, int key, Record* record) {
    pthread_mutex_lock(&table->lock);
    HashTableEntry* entry = table->entries[key % MAX_ELEMENTS];
    if (entry == NULL) {
        entry = malloc(sizeof(HashTableEntry));
        entry->key = key;
        entry->record = record;
        table->entries[key % MAX_ELEMENTS] = entry;
    } else {
        entry->record = record;
    }
    pthread_mutex_unlock(&table->lock);
}

void* record_pool_get() {
    pthread_mutex_lock(&record_pool.poolLock);
    if (record_pool.nextFreeIndex >= POOL_SIZE) {
        fprintf(stderr, "Record pool is full\n");
        pthread_mutex_unlock(&record_pool.poolLock);
        return NULL;
    }
    Record* record = &record_pool.records[record_pool.nextFreeIndex++];
    pthread_mutex_unlock(&record_pool.poolLock);
    return record;
}

void record_pool_put(Record* record) {
    pthread_mutex_lock(&record_pool.poolLock);
    record->value = rand() % 100; // Update value to a random number
    record_pool.nextFreeIndex--;
    pthread_mutex_unlock(&record_pool.poolLock);
}

void iterate_records() {
    for (int i = 0; i < crc_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = crc_indication_list[i];
        Record* record = hash_table_get(&hash_table, pdu->rnti);
        if (record != NULL) {
            printf("Value: %d, UserID: %s\n", record->value, record->userID);
        }
    }
}

int main() {
    // Initialize data structures
    custom_realloc((void**)&crc_indication_list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_ELEMENTS);
    hash_table.entries = malloc(sizeof(HashTableEntry*) * MAX_ELEMENTS);
    memset(hash_table.entries, 0, sizeof(HashTableEntry*) * MAX_ELEMENTS);
    pthread_mutex_init(&hash_table.lock, NULL);

    record_pool.nextFreeIndex = 0;
    pthread_mutex_init(&record_pool.poolLock, NULL);

    // Example usage
    int whitelist[] = {1, 2, 3};
    NFAPI_CRC_INDICATION_PDU_T pdu = {.rx_ue_information_tag = 1, .rnti = 1, .crc_indication_rel8_tag = 0};
    add_crc_indication(&pdu, whitelist, sizeof(whitelist) / sizeof(whitelist[0]));

    Record* record = (Record*)record_pool_get();
    if (record != NULL) {
        record->userID = strdup("user1");
        hash_table_put(&hash_table, pdu.rnti, record);
    }

    iterate_records();

    // Clean up
    free(crc_indication_list);
    free(hash_table.entries);
    pthread_mutex_destroy(&hash_table.lock);

    for (int i = 0; i < POOL_SIZE; i++) {
        free(record_pool.records[i].userID);
    }
    pthread_mutex_destroy(&record_pool.poolLock);

    return 0;
}
