void* manage_memory(void* arg) {
    size_t offsets_size, keys_size, records_size, pdus_size;
    size_t total_size = 0;
    long* offsets;
    int* keys;
    record* records;
    NFAPI_CRC_INDICATION_PDU_T* pdus;

    // Parse arguments and calculate sizes
    // ...

    // Check memory threshold
    if (total_size > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory usage exceeds threshold\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets array
    offsets = malloc(offsets_size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    total_size += offsets_size * sizeof(long);

    // Allocate memory for keys array
    keys = malloc(keys_size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        exit(EXIT_FAILURE);
    }
    total_size += keys_size * sizeof(int);

    // Allocate memory for records array
    records = malloc(records_size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }
    total_size += records_size * sizeof(record);

    // Allocate memory for PDUs array
    pdus = malloc(pdus_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory for PDUs");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }
    total_size += pdus_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Initialize records and populate PDUs
    // ...

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(pdus);

    return NULL;
}

int main() {
    pthread_t thread;
    int result = pthread_create(&thread, NULL, manage_memory, NULL);
    if (result != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    return 0;
}
