#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST_T;

void crc_list_init(CRC_LIST_T *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(RX_UE_INFORMATION_TAG ue_info, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(CACHE_LINE_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    pdu->ue_info = ue_info;
    pdu->RNTI = RNTI;
    pdu->crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pdu->next = NULL;
    return pdu;
}

void crc_list_insert(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = pdu;
        list->tail = pdu;
    } else {
        list->tail->next = pdu;
        list->tail = pdu;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void crc_list_delete(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (pdu == list->head) {
        list->head = pdu->next;
        if (pdu == list->tail) {
            list->tail = NULL;
        }
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current != NULL && current->next != pdu) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = pdu->next;
            if (pdu == list->tail) {
                list->tail = current;
            }
        }
    }
    free(pdu);
    list->count--;
    pthread_mutex_unlock(&list->lock);
}

void crc_list_iterate_forward(CRC_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void crc_list_iterate_backward(CRC_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->tail;
    while (current != NULL) {
        callback(current);
        current = current->next; // Assuming next points to the previous node for reverse iteration
    }
    pthread_mutex_unlock(&list->lock);
}

void crc_list_destroy(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
