#include <stdlib.h>
#include <string.h>

typedef struct {
    int version;
    void* params;
} ProtocolConfig;

typedef struct {
    size_t budget;
    size_t current_usage;
    ProtocolConfig** configs;
    int count;
} ConfigManager;

ConfigManager* init_config_manager(size_t budget) {
    ConfigManager* manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    manager->budget = budget;
    manager->current_usage = 0;
    manager->configs = (ProtocolConfig**)malloc(budget * sizeof(ProtocolConfig*));
    if (!manager->configs) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    return manager;
}

int add_protocol_config(ConfigManager* manager, int version, size_t param_size) {
    if (manager->current_usage + param_size > manager->budget) return -1; // Memory overflow

    ProtocolConfig* config = (ProtocolConfig*)malloc(sizeof(ProtocolConfig));
    if (!config) return -2; // Allocation failed

    config->version = version;
    config->params = malloc(param_size);
    if (!config->params) {
        free(config);
        return -3; // Parameter allocation failed
    }

    manager->configs[manager->count++] = config;
    manager->current_usage += param_size;
    return 0; // Success
}

void update_protocol_config(ConfigManager* manager, int version, void* new_params) {
    for (int i = 0; i < manager->count; ++i) {
        if (manager->configs[i]->version == version) {
            free(manager->configs[i]->params);
            manager->configs[i]->params = malloc(sizeof(new_params));
            memcpy(manager->configs[i]->params, new_params, sizeof(new_params));
            return;
        }
    }
}

void remove_protocol_config(ConfigManager* manager, int version) {
    for (int i = 0; i < manager->count; ++i) {
        if (manager->configs[i]->version == version) {
            free(manager->configs[i]->params);
            free(manager->configs[i]);
            for (; i < manager->count - 1; ++i) {
                manager->configs[i] = manager->configs[i + 1];
            }
            manager->count--;
            manager->current_usage -= sizeof(ProtocolConfig);
            return;
        }
    }
}

void destroy_config_manager(ConfigManager* manager) {
    for (int i = 0; i < manager->count; ++i) {
        free(manager->configs[i]->params);
        free(manager->configs[i]);
    }
    free(manager->configs);
    free(manager);
}
