#include <string.h>
#include <pthread.h>

#define MAX_MESSAGES 100

typedef enum {
    NFAPI_L1_RRC_MSG_TYPE_UE_CONTEXT_SETUP_REQUEST,
    NFAPI_L1_RRC_MSG_TYPE_UE_CONTEXT_RELEASE_REQUEST,
    // Add more message types as needed
} NFAPI_L1_RRC_MSG_TYPE;

typedef struct {
    NFAPI_L1_RRC_MSG_TYPE type;
    int rrc_ue_id;
    char *pdu_content;
    size_t pdu_length;
} NFAPI_RX_MESSAGE_T;

typedef struct {
    NFAPI_RX_MESSAGE_T messages[MAX_MESSAGES];
    int count;
    pthread_mutex_t lock;
} MessageManager;

void init_message_manager(MessageManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_or_update_message(MessageManager *manager, NFAPI_L1_RRC_MSG_TYPE type, int rrc_ue_id, const char *pdu_content, size_t pdu_length) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->messages[i].rrc_ue_id == rrc_ue_id) {
            free(manager->messages[i].pdu_content);
            manager->messages[i].type = type;
            manager->messages[i].pdu_length = pdu_length;
            manager->messages[i].pdu_content = malloc(pdu_length + 1);
            if (manager->messages[i].pdu_content == NULL) {
                pthread_mutex_unlock(&manager->lock);
                return -1; // Memory allocation failed
            }
            strncpy(manager->messages[i].pdu_content, pdu_content, pdu_length);
            manager->messages[i].pdu_content[pdu_length] = '\0';
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    if (manager->count >= MAX_MESSAGES) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Maximum messages reached
    }
    manager->messages[manager->count].type = type;
    manager->messages[manager->count].rrc_ue_id = rrc_ue_id;
    manager->messages[manager->count].pdu_length = pdu_length;
    manager->messages[manager->count].pdu_content = malloc(pdu_length + 1);
    if (manager->messages[manager->count].pdu_content == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    strncpy(manager->messages[manager->count].pdu_content, pdu_content, pdu_length);
    manager->messages[manager->count].pdu_content[pdu_length] = '\0';
    ++manager->count;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_RX_MESSAGE_T* get_message_by_rrc_ue_id(MessageManager *manager, int rrc_ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->messages[i].rrc_ue_id == rrc_ue_id) {
            NFAPI_RX_MESSAGE_T* message = &manager->messages[i];
            pthread_mutex_unlock(&manager->lock);
            return message;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Message not found
}

void free_message_manager(MessageManager *manager) {
    for (int i = 0; i < manager->count; ++i) {
        free(manager->messages[i].pdu_content);
    }
    pthread_mutex_destroy(&manager->lock);
}
