#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MAC_ID 256
#define MAX_LCG_CONFIG 10

typedef struct {
    int mac_id;
    int lcg_config[MAX_LCG_CONFIG];
    int scheduling_requests;
} MacState;

typedef struct {
    MacState *states;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MacList;

MacList* create_mac_list() {
    MacList *list = (MacList*)malloc(sizeof(MacList));
    if (!list) return NULL;

    list->states = (MacState*)calloc(MAX_MAC_ID, sizeof(MacState));
    if (!list->states) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = MAX_MAC_ID;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_mac_list(MacList *list) {
    if (list) {
        free(list->states);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_mac_state(MacList *list, int mac_id, int lcg_config[], int scheduling_requests) {
    pthread_mutex_lock(&list->lock);

    if (mac_id < 0 || mac_id >= MAX_MAC_ID) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid MAC ID
    }

    for (int i = 0; i < MAX_LCG_CONFIG; i++) {
        if (lcg_config[i] < 0 || lcg_config[i] > 1) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Invalid LCG configuration
        }
    }

    if (list->states[mac_id].scheduling_requests != 0) {
        pthread_mutex_unlock(&list->lock);
        return -3; // MAC ID already in use
    }

    for (int i = 0; i < MAX_LCG_CONFIG; i++) {
        list->states[mac_id].lcg_config[i] = lcg_config[i];
    }
    list->states[mac_id].scheduling_requests = scheduling_requests;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_mac_state(MacList *list, int mac_id) {
    pthread_mutex_lock(&list->lock);

    if (mac_id < 0 || mac_id >= MAX_MAC_ID) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid MAC ID
    }

    if (list->states[mac_id].scheduling_requests == 0) {
        pthread_mutex_unlock(&list->lock);
        return -2; // MAC ID not found
    }

    list->states[mac_id].scheduling_requests = 0;
    for (int i = 0; i < MAX_LCG_CONFIG; i++) {
        list->states[mac_id].lcg_config[i] = 0;
    }
    list->count--;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

MacState* get_mac_state(MacList *list, int mac_id) {
    if (mac_id < 0 || mac_id >= MAX_MAC_ID) return NULL; // Invalid MAC ID

    return &list->states[mac_id];
}
