    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
}

void add_pdu_to_list(PDU_List *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    list->pdus[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->pdus[list->size].RNTI = RNTI;
    list->pdus[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void populate_pdu_list(PDU_List *list, int network_config_rnti_range_start, int network_config_rnti_range_end) {
