int read_integers(int *array) {
    int count = 0;
    char buffer[MAX_INPUT_SIZE];
    fgets(buffer, sizeof(buffer), stdin);
    char *token = strtok(buffer, " ");
    while (token != NULL && count < MAX_INPUT_SIZE / sizeof(int)) {
        array[count++] = atoi(token);
        token = strtok(NULL, " ");
    }
    return count;
}

int find_largest(int *array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void print_largest(int largest) {
    printf("Largest integer: %d\n", largest);
}

int main() {
    int array[MAX_INPUT_SIZE / sizeof(int)];
    int size = read_integers(array);
    int largest = find_largest(array, size);
    print_largest(largest);
    return 0;
