#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "json-c/json.h"

#define MAX_ELEMENTS 10000
#define REALLOC_THRESHOLD 100

typedef struct {
    int RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da) {
    da->array = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (da->array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->count = 0;
    da->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&da->lock, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    da->array = NULL;
    da->count = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity + REALLOC_THRESHOLD;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&da->lock);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->count++] = element;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* find_by_rnti(DynamicArray *da, int rnti) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].rx_ue_info.RNTI == rnti && rnti > 0) {
            pthread_mutex_unlock(&da->lock);
            return &da->array[i];
        }
    }
    pthread_mutex_unlock(&da->lock);
    return NULL;
}

int load_from_json(DynamicArray *da, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open JSON file\n");
        return -1;
    }

    json_object *root = json_tokener_parse_file(file);
    fclose(file);

    if (root == NULL) {
        fprintf(stderr, "Failed to parse JSON file\n");
        return -1;
