double calculate_average(float *numbers, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

NFAPI_MESSAGE_PDU_T* create_nfaipdu(MODULATION_SCHEME scheme, unsigned char *payload) {
