#define BUFFER_SIZE 1024

typedef struct {
    int FRAME_ID;
    int SAMPLING_RATE;
    int BITRATE;
    // Other necessary metadata fields
} MEDIA_FRAME_PACKET_T;

typedef struct {
    MEDIA_FRAME_PACKET_T frames[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

void initCircularBuffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

int isCircularBufferFull(CircularBuffer *buffer) {
    return (buffer->count == BUFFER_SIZE);
}

int isCircularBufferEmpty(CircularBuffer *buffer) {
    return (buffer->count == 0);
}

void addFrameToBuffer(CircularBuffer *buffer, MEDIA_FRAME_PACKET_T frame) {
    if (!isCircularBufferFull(buffer)) {
        buffer->frames[buffer->tail] = frame;
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
        buffer->count++;
    } else {
        // Handle buffer overflow, e.g., drop the oldest frame
        buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    }
}

int removeFrameFromBuffer(CircularBuffer *buffer, MEDIA_FRAME_PACKET_T *frame) {
    if (!isCircularBufferEmpty(buffer)) {
        *frame = buffer->frames[buffer->head];
        buffer->head = (buffer->head + 1) % BUFFER_SIZE;
        buffer->count--;
        return 1; // Frame removed successfully
    }
    return 0; // Buffer is empty, no frame to remove
}

void processMediaStream(CircularBuffer *frameBuffer) {
    MEDIA_FRAME_PACKET_T newFrame;
    // Simulate receiving a new audio frame
    newFrame.FRAME_ID = generateFrameID(); // Assume this function generates a valid FRAME_ID
    newFrame.SAMPLING_RATE = getSamplingRateFromExternalService(); // Assume this function fetches the sampling rate
    newFrame.BITRATE = getBitrateFromExternalService(); // Assume this function fetches the bitrate

    addFrameToBuffer(frameBuffer, newFrame);

    MEDIA_FRAME_PACKET_T frame;
    while (removeFrameFromBuffer(frameBuffer, &frame)) {
        // Process the frame for further transmission or storage
        processFrame(&frame);
    }
}

int main() {
    CircularBuffer frameBuffer;
    initCircularBuffer(&frameBuffer);

    // Simulate processing multiple audio frames
    for (int i = 0; i < 1500; i++) {
        processMediaStream(&frameBuffer);
    }

    return 0;
}
