    size_t count;
    pthread_mutex_t lock;
} CRC_PDUBufferPool;

CRC_PDUBufferPool* allocate_and_initialize_crc_pdu_array(size_t N, size_t buffer_pool_size, int use_spin_lock) {
    if (N == 0 || buffer_pool_size == 0) {
        return NULL; // Handle invalid inputs
    }

    CRC_PDUBufferPool *pool = malloc(sizeof(CRC_PDUBufferPool));
    if (!pool) {
        perror("Failed to allocate memory for CRC PDUBufferPool");
        return NULL;
    }

    pool->array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->array) {
        perror("Failed to allocate memory for CRC PDU array");
        free(pool);
        return NULL;
    }

    pool->capacity = N;
    pool->count = 0;

    if (use_spin_lock) {
        pthread_mutexattr_t attr;
        pthread_mutexattr_init(&attr);
        pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_SPIN_NP);
        pthread_mutex_init(&pool->lock, &attr);
        pthread_mutexattr_destroy(&attr);
    } else {
        pthread_mutex_init(&pool->lock, NULL);
    }

    return pool;
}

void free_crc_pdu_array(CRC_PDUBufferPool *pool) {
    if (pool) {
        pthread_mutex_lock(&pool->lock);
        free(pool->array);
        pthread_mutex_unlock(&pool->lock);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}
