    if (!array) return NULL;

    srand(time(NULL));

    for (int i = 0; i < N; ) {
        int rnti = min_rnti + rand() % (max_rnti - min_rnti + 1);
        int found_duplicate = 0;
        for (int j = 0; j < i; j++) {
            if (array[j].RNTI == rnti) {
                found_duplicate = 1;
                break;
            }
        }
        if (!found_duplicate) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
            array[i].RNTI = rnti;
            array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
            i++;
        }
    }

    qsort(array, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    return array;
}

