        bufferPools[i].data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!bufferPools[i].data) {
            // Log error
        }
        bufferPools[i].size = initialSize;
    }
}

void* allocateBuffer(size_t N) {
    int generation = currentGeneration.load(std::memory_order_relaxed);
    BufferPool *pool = &bufferPools[generation];

    if (N > pool->size) {
        // Log error
        return NULL;
    }

    void *buffer = pool->data + (currentGeneration.fetch_add(1, std::memory_order_relaxed) % pool->size);
    // Initialize buffer with valid data
