        buffer[i].RX_UE_INFORMATION_TAG = generateRX_UE_INFORMATION_TAG();
        buffer[i].RNTI = getRNTIFromExternalDatabase();
        buffer[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return buffer;
}

void invalidateStaleData() {
    int generation = currentGeneration.load(std::memory_order_relaxed);
    for (int i = 0; i < generation; ++i) {
        // Invalidate data in pool[i]
    }
    currentGeneration.store(0, std::memory_order_relaxed);
}
