#define MAX_STRUCTURES 1000
#define MEMORY_THRESHOLD 500000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *list[MAX_STRUCTURES];
int list_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_event(int rnti, int crcflag) {
    printf("Created structure with RNTI: %d, CRCFLAG: %d\n", rnti, crcflag);
}

int create_structure(int rx_ue_info_tag, int rnti, int *crcflag) {
    if (rx_ue_info_tag < 0 || rx_ue_info_tag > 10000) return -1; // Example range check
    if (rnti < 1 || rnti > 4096) return -2; // Example range check

    pthread_mutex_lock(&mutex);
    if (list_size >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&mutex);
        return -3; // Overflow condition
    }

    NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        pthread_mutex_unlock(&mutex);
        return -4; // Out of memory
    }

    new_struct->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_struct->RNTI = rnti;
    *crcflag = rand() % 2; // Randomly set CRCFLAG

    list[list_size++] = new_struct;
    log_event(rnti, *crcflag);
    pthread_mutex_unlock(&mutex);

    return 0; // Success
}

void cleanup_list() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < list_size; i++) {
        free(list[i]);
    }
    list_size = 0;
    pthread_mutex_unlock(&mutex);
}

// Example usage
int main() {
    srand(time(NULL));
    int crcflag;
    create_structure(1234, 5678, &crcflag);
    cleanup_list();
    return 0;
