#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void freeDynamicList(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    if (list->data != NULL) {
        free(list->data);
        list->data = NULL;
    }
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void addElement(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == element.RNTI) {
            fprintf(stderr, "Error: Duplicate RNTI detected\n");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }
    list->data[list->size++] = element;
    pthread_mutex_unlock(&list->mutex);
}

void removeElement(DynamicList *list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->size) {
        fprintf(stderr, "Error: Index out of bounds\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }
    --list->size;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* getElementByRNTI(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return &list->data[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void* fetchConfig(void *arg) {
    // Simulate fetching configuration from an external HTTP API
    sleep(1); // Simulate network latency
    printf("Configuration fetched successfully\n");
    return NULL;
}

int main() {
    DynamicList list;
    initDynamicList(&list);

    NFAPI_CRC_INDICATION_PDU_T element = {0, 12345, 67890, rand() % 2};
    addElement(&list, element);

    NFAPI_CRC_INDICATION_PDU_T *retrievedElement = getElementByRNTI(&list, 12345);
    if (retrievedElement != NULL) {
        printf("Retrieved element: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               retrievedElement->RX_UE_INFORMATION_TAG,
               retrievedElement->RNTI,
               retrievedElement->CRC_INDICATION_REL8_TAG,
               retrievedElement->CRCFLAG);
    }

    removeElement(&list, 0);

    freeDynamicList(&list);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, fetchConfig, NULL) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
